		expectTrue(ML.overlapFraction({ wl, wt, wr, wb }, { nl, nt, nr, nb }) == 0, "hub clear of the board at " .. w)
	end
end })

table.insert(tests, { name = "MenuWorldLayout v2: six tiles share one baseline with equal gaps, board aligned to the row, nothing overlaps", fn = function()
	local WL = require(script.Parent.Parent.Engine.MenuWorldLayout)
	local ML = require(script.Parent.Parent.Engine.MenuLayout)
	for _, size in ipairs({ { 1920, 1080 }, { 1280, 720 } }) do
		local w, h = size[1], size[2]
		local tiles = {}
		for _, r in ipairs(WL.rects(ML, w, h)) do
			if r.kind == "landmark" and r.id ~= "play" then tiles[#tiles + 1] = r end
		end
		expectEqual(#tiles, 6, "six tiles")
		table.sort(tiles, function(a, b) return a[1] < b[1] end)
		for i = 2, 6 do
			expectTrue(math.abs(tiles[i][4] - tiles[1][4]) < 0.5, "shared baseline")
			expectTrue(math.abs((tiles[i][1] - tiles[i - 1][1]) - (tiles[2][1] - tiles[1][1])) < 0.5, "equal gaps")
			expectTrue(math.abs((tiles[i][3] - tiles[i][1]) - (tiles[1][3] - tiles[1][1])) < 0.5, "identical size")
		end
		local nl, nt, nr, nb = ML.noticeRect(w, h)
		expectTrue(math.abs(nl - tiles[1][1]) < 0.01 * w, "board left edge matches the row's left edge at " .. w)
		expectTrue(nr <= WL.hubRect(w, h), "board clear of the hub")
		local rows = {}
		for _, t in ipairs(tiles) do rows[#rows + 1] = t end
		local all = WL.rects(ML, w, h)
		for i, a in ipairs(all) do
			expectTrue(ML.overlapFraction(a, { nl, nt, nr, nb }) == 0, "clear of the board: " .. a.id)
			for j = i + 1, #all do expectTrue(ML.overlapFraction(a, all[j]) <= 0.02, "no overlap: " .. a.id .. " " .. all[j].id) end
		end
	end
	local phone = WL.tileSpots(640)
	expectEqual(#phone, 6, "six phone tiles")
	expectTrue(phone[1].y == phone[3].y and phone[4].y == phone[6].y and phone[4].y > phone[1].y, "two rows of three on phones")
	expectEqual(WL.grid.order[1], "questscroll", "Quest Scroll first")
end })

table.insert(tests, { name = "MenuWorldLayout: one rigid drift, hero walks out and back, apply moves the hotspots", fn = function()
	local WL = require(script.Parent.Parent.Engine.MenuWorldLayout)
	local D = WL.drift
	expectTrue(D.panPx <= 8 and D.zoomAmp <= 0.02 and D.period >= 40, "tiny slow drift")
	expectTrue(D.baseZoom - D.zoomAmp - 1 >= 2 * D.panPx / 1280, "zoom margin covers the pan so no edge shows")
	for t = 0, 80, 3.7 do
		local dx, dy, z = WL.driftAt(t)
		expectTrue(math.abs(dx) <= D.panPx and math.abs(dy) <= D.panPx and z >= D.baseZoom - D.zoomAmp - 1e-9 and z <= D.baseZoom + D.zoomAmp + 1e-9, "drift stays inside its budget")
	end
	local hx0, hy0 = WL.heroAt(0)
	local _, hyMid = WL.heroAt(WL.hero.period / 2)
	local _, hyEnd = WL.heroAt(WL.hero.period)
	expectEqual(hx0, WL.hero.x0, "hero walks the road")
	expectTrue(math.abs(hy0 - WL.hero.y0) < 1e-9 and math.abs(hyMid - WL.hero.y1) < 1e-9 and math.abs(hyEnd - hy0) < 1e-9, "out to the end of the road and back every period")
	-- apply works on a copy so the shared MenuLayout is left alone
	local fake = { Hotspots = { { id = "tome", x = 0, y = 0, s = 1, asp = 2 }, { id = "other", x = 7, y = 7, s = 1, asp = 1 } } }
	expectEqual(WL.apply(fake), 1, "only hotspots with a spot move")
	expectEqual(fake.Hotspots[1].x, WL.spots.tome.x, "moved to the landmark spot")
	expectEqual(fake.Hotspots[2].x, 7, "unknown hotspots untouched")
	expectTrue(fake.world == true, "world flag set")
	local f = io and io.open and io.open("src/Client/MenuWorld.lua", "r")
	if f then
		local src = f:read("*a"); f:close()
		expectTrue(src:find("Transparency = ColorSequence", 1, true) == nil, "no gradient Transparency")
		expectTrue(src:find("calm", 1, true) ~= nil, "map life honours calm mode")
		expectTrue(src:find("world.Position = UDim2.new(0.5, dx, 0.5, dy)", 1, true) ~= nil, "the whole map moves as one frame")
		expectTrue(src:find("Bayou", 1, true) == nil, "no bayou layers")
	end
end })

table.insert(tests, { name = "Menu polish 1: no corner blobs, no cloud ghosts or hard band, Notice Board fits its notes with pins on the top edge, All actions is a solid legible plate", fn = function()
	local function read(path)
		local f = io and io.open and io.open(path, "r")
		if not f then return nil end
		local s = f:read("*a"); f:close()
		return s
	end
	local world, board, hot = read("src/Client/MenuWorld.lua"), read("src/Client/MenuBoard.lua"), read("src/Client/MenuHotspots.lua")
	if not (world and board and hot) then return end
	expectTrue(world:find("menu_map_frame", 1, true) == nil and world:find("WL.frameStrips", 1, true) == nil, "the scroll frame's roller ends (the four corner blobs) are not drawn")
	expectTrue(world:find("CloudShadow", 1, true) == nil and world:find("menu_cloud_wisp", 1, true) == nil, "no cloud shadows (ghost circles and a light band)")
	expectTrue(world:find('name = "TitleScrim"', 1, true) ~= nil and world:find('"TitleScrim" .. i', 1, true) == nil, "the title backing is one gradient frame, no hard band edge")
	expectTrue(world:find("menu_fog_edge_clean", 1, true) ~= nil, "the despilled fog edge is preferred when recorded")
	expectTrue(board:find("local function fit()", 1, true) ~= nil and board:find("frame.Size = UDim2.new(N.w, 0, 0, math.max(60, math.floor(h)))", 1, true) ~= nil, "the board is only as tall as its notes")
	expectTrue(board:find("UDim2.new(0.5, 0, 0, -4)", 1, true) ~= nil, "pins sit on the note's top edge, not over its rows")
	expectTrue(hot:find("if Layout.world then object.Visible = false end", 1, true) ~= nil, "the Deal Me In block has no cut-off dark medallion on the map")
	expectTrue(hot:find("allButton.BackgroundColor3 = Color3.fromRGB(58, 38, 22)", 1, true) ~= nil and hot:find("allButton.BackgroundTransparency = 0", 1, true) ~= nil, "All actions is a solid dark wood plate")
	local ML = require(script.Parent.Parent.Engine.MenuLayout)
	local LL = require(script.Parent.Parent.Engine.LedgerLayout)
	expectTrue(LL.contrast({ 250, 235, 200 }, { 58, 38, 22 }) >= 4.5, "cream on the All actions plate is at least 4.5:1")
	expectTrue(ML.NoticeBoard.h <= 0.3, "the board's layout rect is the cap, the fit makes it shorter")
end })

table.insert(tests, { name = "MenuRoomLayout: one painted picture, hotspots map through the crop, stay on screen, 44 px, no overlaps, strip fallback", fn = function()
	local ML = require(script.Parent.Parent.Engine.MenuLayout)
	local RL = require(script.Parent.Parent.Engine.MenuRoomLayout)
	for _, action in ipairs(ML.Actions) do
		local owner = ML.hotspotOf(action.id)
		expectTrue(owner ~= nil and RL.pic[owner.id] ~= nil, "every action has a hotspot with a picture rect: " .. action.id)
	end
	for _, id in ipairs({ "play", "tome", "questscroll", "maptable", "coinjar", "rulebook", "jukebox", "noticeboard" }) do
		expectTrue(RL.pic[id] ~= nil, "picture rect for " .. id)
	end
	expectEqual(ML.hotspotOf("play").id, "play", "Deal Me In is the card table")
	expectEqual(ML.hotspotOf("road").id, "maptable", "Road Ahead is the wall map")
	expectEqual(ML.hotspotOf("collection").id, "tome", "The Tome is the lectern book")
	for _, size in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 800, 450 }, { 390, 844 } }) do
		local W, H = size[1], size[2]
		local pw, ph, ox, oy = RL.cover(W, H)
		expectTrue(pw >= W - 1e-6 and ph >= H - 1e-6, "the picture covers the screen at " .. W)
		expectTrue(math.abs(pw / ph - RL.ASPECT) < 1e-6, "never stretched at " .. W)
		expectTrue(math.abs(ox - (W - pw) / 2) < 1e-6 and math.abs(oy - (H - ph) / 2) < 1e-6, "centred at " .. W)
		local rects = RL.rects(W, H)
		expectEqual(#rects, #RL.stripOrder, "every hotspot has a rect at " .. W)
		for i, a in ipairs(rects) do
			expectTrue(a[1] >= 0 and a[3] <= W and a[2] >= 0 and a[4] <= H, a.id .. " inside the screen at " .. W .. "x" .. H)
			expectTrue(a[3] - a[1] >= RL.minTouch - 1e-6 and a[4] - a[2] >= RL.minTouch - 1e-6, "touch target 44 px or more: " .. a.id .. " " .. W)
			if W >= 800 and a.kind == "prop" then
				for j = i + 1, #rects do
					local b = rects[j]
					if b.kind == "prop" then
						expectTrue(ML.overlapFraction(a, b) <= 0.08, "overlap under 8 percent: " .. a.id .. " vs " .. b.id .. " at " .. W)
					end
				end
			end
		end
	end
	for _, r in ipairs(RL.rects(1920, 1080)) do expectEqual(r.kind, "prop", "no strip plate on desktop: " .. r.id) end
	local strips = 0
	for _, r in ipairs(RL.rects(390, 844)) do if r.kind == "strip" then strips = strips + 1 end end
	expectTrue(strips >= 2, "a phone crop moves cropped hotspots into the bottom strip")
	for _, size in ipairs({ { 1920, 1080 }, { 1280, 720 } }) do
		local W, H = size[1], size[2]
		local pw, ph, ox, oy = RL.cover(W, H)
		local r = RL.layout(W, H).play
		local p = RL.pic.play
		expectTrue(math.abs(r.l - (ox + p.l * pw)) < 1 and r.b <= oy + p.b * ph + 1, "the table keeps its picture position at " .. W)
	end
	expectTrue(RL.ambientKinds <= RL.MAX_AMBIENT, "at most 8 ambient kinds")
	local known = {}
	for _, key in ipairs(RL.artKeys) do known[key] = true end
	expectEqual(RL.SCENE_KEY, "menu_scene_a", "the room painting is read from MenuSceneArt menu_scene_a")
	for id in pairs(require(script.Parent.Parent.Engine.MenuRoomArt)) do expectTrue(known[id], "MenuRoomArt only holds known keys: " .. id) end
end })

table.insert(tests, { name = "MenuRoomLayout: apply sets picture rects, flicker and glint stay inside their budgets, calm mode has no tweens, fallback builds without the art", fn = function()
	local RL = require(script.Parent.Parent.Engine.MenuRoomLayout)
	local fake = { Hotspots = { { id = "tome", x = 0, y = 0, s = 1, asp = 2 }, { id = "other", x = 7, y = 7, s = 1, asp = 1 } } }
	expectEqual(RL.apply(fake), 1, "only hotspots with a picture rect are set")
	expectTrue(fake.Hotspots[1].pic == RL.pic.tome and fake.Hotspots[2].pic == nil, "picture rect set on the tome only")
	expectTrue(fake.world == true and fake.room == true, "world and room flags set")
	expectTrue(next(fake.WorldArt) == nil, "the old per-prop pieces are not drawn")
	local ml, mt, mr, mb = fake.picRect(fake.Hotspots[1], 1920, 1080)
	expectTrue(mr > ml and mb > mt, "picRect maps the hotspot through the crop")
	for tt = 0, 60, 0.37 do
		expectTrue(math.abs(RL.flickerAt(tt)) <= RL.flicker + 1e-9, "flicker stays at 3 percent")
		local g = RL.glintAt(tt)
		expectTrue(g >= 0 and g <= 1, "glint phase is 0 to 1")
		for i = 1, RL.motes do
			local x, y, a = RL.moteAt(i, tt)
			expectTrue(x > 0 and x < 1 and y > 0 and y < 1 and a >= 0 and a <= 1, "motes stay on the picture")
		end
	end
	expectEqual(RL.glintAt(RL.glint.length + 1), 0, "coins glint only once in a while")
	local function read(path)
		local f = io and io.open and io.open(path, "r")
		if not f then return nil end
		local text = f:read("*a"); f:close()
		return text
	end
	local room, menu, hot = read("src/Client/MenuRoom.lua"), read("src/Client/Menu.lua"), read("src/Client/MenuHotspots.lua")
	if not (room and menu and hot) then return end
	expectTrue(room:find("Transparency = ColorSequence", 1, true) == nil, "no gradient Transparency")
	expectTrue(room:find("if calm then", 1, true) ~= nil, "room life honours calm mode")
	expectTrue(room:find("TweenService", 1, true) == nil, "the room's life is driven by one update, no tweens, so calm mode has none")
	expectTrue(room:find("drawFallback", 1, true) ~= nil and room:find("if sceneArt then", 1, true) ~= nil, "without the scene art a code-drawn room builds")
	for _, old in ipairs({ "menu_room_cardtable", "menu_room_scroll", "menu_room_map", "menu_room_tome", "menu_room_rulebook", "menu_room_coinjar", "menu_room_jukebox", "menu_room_lantern", "menu_room_sign" }) do
		expectTrue(room:find(old, 1, true) == nil, "MenuRoom no longer references " .. old)
	end
	expectTrue(room:find("ScaleType.Crop", 1, true) == nil and room:find("RL.cover", 1, true) ~= nil, "the picture is cover-cropped by the layout, not stretched")
	expectTrue(menu:find('"MenuRoomLayout"', 1, true) ~= nil and menu:find("MenuRoom).build", 1, true) ~= nil, "the Menu builds the Tavern Room")
	expectTrue(hot:find('Layout.WorldArtCategory or "menu_world"', 1, true) ~= nil, "props pick their art category from the layout")
end })

table.insert(tests, { name = "HandLedger: every hand once weakest first, formulas and highlights, layout fits desktop and phone sizes", fn = function()
	local HL = require(script.Parent.Parent.Engine.HandLedger)
	local HandEvaluator = require(script.Parent.Parent.Engine.HandEvaluator)
	local Scoring = require(script.Parent.Parent.Engine.Scoring)
	local ledger = HL.build({ order = HandEvaluator.HandOrder, base = Scoring.HandBase, growth = Scoring.HandLevelGrowth,
		handStats = { Pair = 4, Flush = 1 }, handLevels = { Pair = 2 }, lastHand = "Flush", lifetimeHands = 120 })
	expectEqual(#ledger.rows, #HandEvaluator.HandOrder)
	local seen = {}
	for i, row in ipairs(ledger.rows) do
		expectEqual(row.name, HandEvaluator.HandOrder[i]) -- weakest to strongest, in Engine order
		expectFalse(seen[row.name], "each hand once")
		seen[row.name] = true
		expectTrue(HL.TIER_COLORS[row.tier] ~= nil, "tier colour")
		local c = HL.TIER_COLORS[row.tier]
		expectTrue(c[1] >= c[2] and c[2] >= c[3] - 40 and not (c[2] < 60), "tier colours are wood, brass or gold, never red")
		expectTrue(#row.tip > 0 and not row.tip:find("-", 1, true) and not row.tip:find("\226\128\148", 1, true), "tip is plain")
		expectFalse(row.tip:lower():find("balatro", 1, true) ~= nil)
		local spec = HandEvaluator.Examples[row.name]
		expectTrue(spec ~= nil and #spec >= 1, "example cards resolve for " .. row.name)
	end
	expectEqual(ledger.rows[1].tier, "wood")
	expectEqual(ledger.rows[#ledger.rows].tier, "legend")
	local pair, flush, high = ledger.rows[2], ledger.rows[6], ledger.rows[1]
	expectEqual(pair.level, 2)
	expectTrue(pair.leveled and not flush.leveled)
	expectEqual(pair.chips, Scoring.HandBase["Pair"].chips + Scoring.HandLevelGrowth["Pair"].chips * 2)
	expectTrue(pair.chipsFormula:find("Lv 2", 1, true) ~= nil and high.chipsFormula:find("Lv", 1, true) == nil)
	expectTrue(high.notPlayed and not pair.notPlayed)
	expectTrue(flush.justPlayed and not pair.justPlayed)
	expectEqual(ledger.lifetimeHands, 120)
	expectEqual(ledger.topHand, pair.points >= flush.points and "Pair" or "Flush") -- most points this run (estimate)
	local count = 0
	for _, row in ipairs(ledger.rows) do if row.isTop then count = count + 1 end end
	expectEqual(count, 1)
	expectEqual(HL.defaultSelection(ledger, "Straight"), "Straight")
	expectEqual(HL.defaultSelection(ledger, nil), "Flush") -- the hand just played
	expectEqual(HL.defaultSelection(HL.build({ order = HandEvaluator.HandOrder, base = Scoring.HandBase, growth = Scoring.HandLevelGrowth }), nil), "High Card")
	-- layout: panel inside the screen, list and detail inside the panel and never overlapping
	for _, size in ipairs({ { 1920, 1080 }, { 1366, 768 }, { 1280, 720 }, { 800, 600 }, { 360, 640 }, { 412, 915 } }) do
		local w, h = size[1], size[2]
		local L = HL.layout(w, h, #ledger.rows)
		expectTrue(L.panel.w <= w and L.panel.h <= h, "panel fits " .. w .. "x" .. h)
		expectEqual(L.phone, w < 700)
		for _, r in ipairs({ L.list, L.detail }) do
			expectTrue(r.x >= 0 and r.y >= 50 and r.x + r.w <= L.panel.w and r.y + r.h <= L.panel.h, "section inside the panel " .. w)
			expectTrue(r.w > 100 and r.h > 100, "section has room")
		end
		local a, b = L.list, L.detail
		local apart = a.x + a.w <= b.x or b.x + b.w <= a.x or a.y + a.h <= b.y or b.y + b.h <= a.y
		expectTrue(apart, "list and detail do not overlap at " .. w)
		expectTrue(L.rowH >= 40, "rows are tall enough to tap")
		if not L.phone then expectTrue(L.panel.h <= h * 0.9 + 1, "panel clears the top strip") end
	end
	local f = io and io.open and io.open("src/Client/PokerHandsReference.lua", "r")
	if not f then return end
	local src = f:read("*a"); f:close()
	expectTrue(src:find('registerOpener("pokerHandsReference"', 1, true) ~= nil and src:find("handRefButton.MouseButton1Click", 1, true) ~= nil, "existing openers kept")
	expectFalse(src:find("SkinArt", 1, true) ~= nil, "old ornate frame art is gone")
end })

