table.insert(tests, { name = "PanelBorder: no border piece overlaps the content rect or the Close button at 1920x1080, 1280x720 and phone", fn = function()
	local PB = require(script.Parent.Parent.Engine.PanelBorder)
	local function hit(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	for _, size in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 360, 640 } }) do
		local w, h = size[1], size[2]
		local c = PB.content(w, h)
		local l = PB.layout(w, h)
		-- Close sits in the content area, top right, inset 8 px from the content edge
		local close = { x = c.x + c.w - 8 - 90, y = c.y + 8, w = 90, h = 36 }
		for i, b in ipairs(l.brackets) do
			expectTrue(not hit(b, c), "bracket " .. i .. " stays out of the content rect at " .. w .. "x" .. h)
			expectTrue(not hit(b, close), "bracket " .. i .. " stays off Close at " .. w .. "x" .. h)
		end
	end
end })

table.insert(tests, { name = "ShadowFit: shadow bounds equal panel bounds plus padding on both axes, clamped or not", fn = function()
	local SF = require(script.Parent.Parent.Engine.ShadowFit)
	for _, screen in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 360, 640 }, { 3840, 2160 } }) do
		local pw = SF.panelAxis(screen[1], 0.8, 0, 640, 980)
		local ph = SF.panelAxis(screen[2], 0.88, 0, 520, 640)
		local sw = SF.shadowAxis(screen[1], 0.8, 0, 640, 980)
		local sh = SF.shadowAxis(screen[2], 0.88, 0, 520, 640)
		expectEqual(sw, pw + SF.PAD, "shadow width = panel + pad at " .. screen[1] .. "x" .. screen[2])
		expectEqual(sh, ph + SF.PAD, "shadow height = panel + pad at " .. screen[1] .. "x" .. screen[2])
	end
	local a, b, c, d = SF.limits(640, 520, 980, 640)
	expectTrue(a == 654 and b == 534 and c == 994 and d == 654, "constraint grown by pad")
end })

table.insert(tests, { name = "LedgerPages: stats map to story, hall and records content; empty state; beaten records; count-up", fn = function()
	local LP = require(script.Parent.Parent.Engine.LedgerPages)
	expectEqual(#LP.PAGES, 3, "three pages")
	expectEqual(LP.isEmpty(nil), true, "no stats is empty")
	expectEqual(LP.isEmpty({ runs = 0, recent = {} }), true, "no runs is empty")
	expectEqual(LP.isEmpty({ runs = 2, recent = {} }), false, "runs written")
	expectEqual(LP.EMPTY_NOTE, "Nothing written yet. Go lose gracefully.", "empty note text")
	expectEqual(LP.EMPTY_NOTE:find("\226\128\148", 1, true), nil, "no em dash")
	expectEqual(LP.winRate({ runs = 4, wins = 1 }), 0.25, "win rate")
	expectEqual(LP.winRate({ runs = 0, wins = 0 }), 0, "no runs, no rate")
	expectEqual(LP.winRate({ runs = 1, wins = 5 }), 1, "rate capped at 1")
	local t = LP.tally(13)
	expectEqual(t.fives, 2, "two full tally groups")
	expectEqual(t.loose, 3, "three loose strokes")
	expectEqual(LP.tally(99).capped, true, "tally caps")
	expectEqual(LP.tally(99).fives * 5 + LP.tally(99).loose, LP.TALLY_MAX, "capped tally shows the max marks")
	local story = LP.story({ wins = 3, runs = 9, bestNight = 6 })
	expectEqual(story.wins, 3, "story wins")
	expectEqual(story.tally.fives, 1, "best Night 6 is one group plus one stroke")
	local recent = {
		{ night = 5, won = false, score = 900 }, { night = 8, won = true, score = 500 },
		{ night = 8, won = false, score = 9000 }, { night = 8, won = true, score = 700 }, { night = 2, won = false, score = 1 },
	}
	local bests = LP.bests(recent, 3)
	expectEqual(#bests, 3, "three bests")
	expectEqual(bests[1].score, 700, "a win beats a loss on the same Night, then the higher score")
	expectEqual(bests[2].score, 500, "second best")
	expectEqual(bests[3].score, 9000, "the Night 8 loss is third")
	local hall = LP.hall({ favoritePatron = { id = "x", wins = 4 }, recent = recent, hands = 12345, bestHandScore = 777, tipsEarned = 20 }, "Regular")
	expectEqual(hall.favorite.wins, 4, "favourite Patron wins")
	expectEqual(hall.life[1].value, "Regular", "title line")
	expectEqual(hall.life[2].value, "12.3K", "hands played formatted")
	expectEqual(hall.life[3].label, "Best hand score", "best hand score line")
	expectEqual(LP.hall({}, nil).life[1].value, "None", "no title")
	local rec = LP.records({ recent = recent })
	expectEqual(#rec.rows, 5, "rows")
	expectEqual(rec.bars[1].night, 2, "oldest run is the first bar")
	expectEqual(rec.bars[#rec.bars].night, 5, "newest run is the last bar")
	expectEqual(rec.bars[1].height, 0.25, "bar height is Night over the best Night")
	local many = {}
	for i = 1, 30 do many[i] = { night = 3, won = true, score = i } end
	expectEqual(#LP.records({ recent = many }).rows, LP.RUNS_SHOWN, "ten runs listed")
	expectEqual(#LP.records({ recent = many }).bars, LP.SPARK_SLOTS, "twenty bars")
	expectEqual(#LP.beaten(nil, { wins = 1 }), 0, "first look stamps nothing")
	expectEqual(LP.beaten({ wins = 1, bestNight = 3, bestHandScore = 10 }, { wins = 2, bestNight = 3, bestHandScore = 12 })[1], "wins", "a new win is a beaten record")
	expectEqual(#LP.beaten({ wins = 1 }, { wins = 1 }), 0, "nothing new")
	expectEqual(LP.countUp(100, 0), 0, "count starts at zero")
	expectEqual(LP.countUp(100, 1), 100, "count ends on the target")
	expectEqual(LP.countUp(100, 0.5) > 50 and LP.countUp(100, 0.5) < 100, true, "eased in between")
	expectEqual(LP.step(1, -1), 1, "no page before the first")
	expectEqual(LP.step(3, 1), 3, "no page after the last")
	expectEqual(LP.step(1, 1), 2, "next page")
end })

table.insert(tests, { name = "LedgerPages: layout keeps pages inside the book, tabs outside it, everything inside the panel (1920x1080 and compact)", fn = function()
	local LP = require(script.Parent.Parent.Engine.LedgerPages)
	for _, size in ipairs({ { 1574, 972 }, { 1000, 600 }, { 524, 576 } }) do
		local r = LP.rects(size[1], size[2])
		local function inside(a, b) return a.x >= b.x - 0.001 and a.y >= b.y - 0.001 and a.x + a.w <= b.x + b.w + 0.001 and a.y + a.h <= b.y + b.h + 0.001 end
		local panel = { x = 0, y = 0, w = size[1], h = size[2] }
		expectTrue(inside(r.book, panel) and inside(r.title, panel), "book and title inside the panel")
		expectTrue(inside(r.left, r.book) and inside(r.right, r.book), "pages inside the book")
		expectTrue(r.left.x + r.left.w <= r.right.x, "left page ends before the right page starts")
		expectTrue(r.title.y + r.title.h <= r.book.y + 0.001, "title clears the book")
		-- the ribbon tabs hang off the right edge of the book, level with the top of the pages, and stay in the panel
		local T = require(script.Parent.Parent.Engine.LedgerLayout).TABS
		local bookW = r.book.w
		local tabsRight = r.book.x + (T.x + T.w) * bookW
		expectTrue(tabsRight <= size[1] + 0.001, "tabs inside the panel")
		expectTrue(T.x >= 0.95 and T.w <= 0.1, "slim tabs on the right edge of the book")
		expectTrue(math.abs(T.y - require(script.Parent.Parent.Engine.LedgerLayout).pageBox("right").y) < 0.01, "tabs level with the page top")
	end
end })

table.insert(tests, { name = "Ledger v3: book rests on the table line, ink stays inside the page margins, desk clears the sidebar, no stickers or stray square", fn = function()
	local LP = require(script.Parent.Parent.Engine.LedgerPages)
	for _, size in ipairs({ { 1574, 972 }, { 1000, 600 }, { 524, 576 } }) do
		local r = LP.rects(size[1], size[2])
		expectTrue(math.abs(r.book.y + r.book.h - r.tableY) < 0.01, "book bottom sits on the table line")
		expectTrue(r.tableY <= size[2] * (1 - LP.LAYOUT.close.h) + 0.001, "table line leaves the Close button row clear")
		for _, side in ipairs({ "left", "right" }) do
			local page = r[side]
			local ink = LP.inkRect(page, side)
			expectTrue(ink.x >= page.x and ink.y >= page.y and ink.x + ink.w <= page.x + page.w + 0.001 and ink.y + ink.h <= page.y + page.h + 0.001, "ink inside the page rect")
			local outer = (side == "left") and (ink.x - page.x) or (page.x + page.w - ink.x - ink.w)
			local inner = (side == "left") and (page.x + page.w - ink.x - ink.w) or (ink.x - page.x)
			expectTrue(outer / page.w >= 0.06 and outer / page.w <= 0.08, "outer margin is 6 to 8 percent")
			expectTrue(inner >= outer, "spine side clears the binding rings")
		end
	end
	for _, vp in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1000, 600 } }) do
		local p = LP.panelRect(vp[1], vp[2])
		expectTrue(p.x >= 260 and p.x + p.w <= vp[1], "desk starts right of the 240 px sidebar and its gap")
	end
	local c = LP.panelRect(600, 800)
	expectTrue(c.x == 12 and c.x + c.w <= 600, "compact desk has no sidebar margin")
	local f = io and io.open and io.open("src/Client/LedgerBook.lua", "r")
	if not f then return end
	local src = f:read("*a"); f:close()
	for _, gone in ipairs({ "ledger_chalkboard", "ledger_photo_frame", "ledger_wax_seal", "ledger_coffee_ring", "drawRing", "drawTally", "ledger_paper_note" }) do
		expectTrue(src:find(gone, 1, true) == nil, "no leftover: " .. gone)
	end
	expectTrue(src:find('Name = "ContactShadow"', 1, true) ~= nil, "soft contact shadow under the book")
	expectTrue(src:find('Name = "PatronVignette"', 1, true) ~= nil, "patron is an inked vignette")
end })

table.insert(tests, { name = "BadgeWallLayout: every tab has its badges, nothing overlaps or leaves the board (wide and compact), lines, next up, fresh, progress", fn = function()
	local W = require(script.Parent.Parent.Engine.BadgeWallLayout)
	local B = require(script.Parent.Parent.Engine.Badges)
	expectEqual(#B.Definitions, 32, "32 badges")
	expectEqual(#W.members("All"), 32, "All holds every badge")
	local seen, total = {}, 0
	for _, chip in ipairs({ "Roads", "Masters", "Night", "Special" }) do
		for _, d in ipairs(W.members(chip)) do
			expectFalse(seen[d.id], d.id .. " is on exactly one tab")
			seen[d.id] = true
			total = total + 1
		end
	end
	expectEqual(total, 32, "the four tabs together hold every badge once")
	expectEqual(#W.members("Roads"), 8, "eight road badges")
	expectEqual(W.members("Roads")[1].region, "meadow", "road order starts at the meadow")
	expectEqual(W.members("Roads")[8].region, "tavern", "road order ends at the tavern")
	expectEqual(#W.members("Masters"), 8, "eight master badges")
	expectEqual(#W.members("Night"), 4, "four Night badges")
	for _, chip in ipairs(B.Chips) do
		expectTrue(W.FURNITURE[chip] ~= nil and W.FURNITURE_ART[W.FURNITURE[chip]] ~= nil, chip .. " has its own furniture and art key")
	end
	for _, size in ipairs({ { 1000, 560 }, { 1400, 700 }, { 520, 300 } }) do
		for _, chip in ipairs(B.Chips) do
			local lay = W.layout(chip, nil, size[1], size[2])
			expectEqual(#lay.items, #W.members(chip), chip .. " lays out every badge")
			for i, a in ipairs(lay.items) do
				local fa = W.footprint(a)
				expectTrue(fa.x >= 0 and fa.y >= 0 and fa.x + fa.w <= size[1] and fa.y + fa.h <= size[2], chip .. " item " .. a.id .. " stays on the board at " .. size[1] .. "x" .. size[2])
				for j = i + 1, #lay.items do
					local fb = W.footprint(lay.items[j])
					local apart = fa.x + fa.w <= fb.x or fb.x + fb.w <= fa.x or fa.y + fa.h <= fb.y or fb.y + fb.h <= fa.y
					expectTrue(apart, chip .. " items " .. a.id .. " and " .. lay.items[j].id .. " do not overlap at " .. size[1] .. "x" .. size[2])
				end
			end
		end
	end
	-- Masters: the Master Tavern badge is larger and centred
	local m = W.layout("Masters", nil, 1000, 560)
	local bigItem
	for _, it in ipairs(m.items) do if it.big then bigItem = it end end
	expectTrue(bigItem ~= nil and bigItem.id == "master_tavern", "Master Tavern is the big one")
	expectTrue(math.abs(bigItem.x + bigItem.size / 2 - 500) <= 1, "Master Tavern is centred")
	for _, it in ipairs(m.items) do if not it.big then expectTrue(it.size < bigItem.size, "seven masters are smaller than the centre badge") end end
	-- lines
	expectEqual(#W.lines("Roads", nil, {}), 7, "seven strings between eight road badges")
	expectEqual(#W.lines("Night", nil, {}), 3, "three constellation lines between four stars")
	expectEqual(#W.lines("All", nil, {}), 0, "no lines on the cabinet")
	local have = { biome_meadow = true, biome_river = true, biome_peaks = false }
	local lines = W.lines("Roads", nil, have)
	expectEqual(lines[1].lit, true, "meadow to river is lit")
	expectEqual(lines[2].lit, false, "river to peaks is not")
	-- next up and fresh
	expectEqual(W.nextUp("Night", nil, {}), "night_3", "the easiest locked Night badge is next")
	expectEqual(W.nextUp("Night", nil, { night_3 = true }), "night_5", "then the next one")
	local allNight = { night_3 = true, night_5 = true, night_8 = true, night_10 = true }
	expectEqual(W.nextUp("Night", nil, allNight), nil, "nothing left to nudge")
	expectEqual(#W.fresh(nil, { wins_1 = true }), 0, "first view sparkles nothing")
	expectEqual(W.fresh({ wins_1 = true }, { wins_1 = true, wins_5 = true })[1], "wins_5", "a newly earned badge sparkles")
	local e, t, f = W.progress({ wins_1 = true, wins_5 = true })
	expectEqual(e, 2, "earned count")
	expectEqual(t, 32, "total count")
	expectEqual(f, 2 / 32, "progress fraction")
	local d1 = B.getById("wins_1")
	expectEqual(W.plateText(d1, true), "First Win", "earned nameplate shows the name")
	expectEqual(W.plateText(d1, false), "First Win", "locked nameplate shows the full name too (the requirement is in the tooltip)")
	local seg = W.segment(0, 0, 3, 4)
	expectEqual(seg.length, 5, "segment length")
	expectEqual(seg.x, 1.5, "segment midpoint")
end })

