		return src
	end
	local life = read("src/Client/AmbientLife.lua")
	if not life then return end
	expectTrue(select(2, life:gsub("Heartbeat:Connect", "")) == 1, "a single Heartbeat connection")
	expectTrue(life:find("TICK", 1, true) ~= nil, "capped by the 30 Hz tick")
	expectTrue(life:find("reduceShake", 1, true) ~= nil and life:find("clearObjects", 1, true) ~= nil, "calm mode destroys the objects")
	expectTrue(life:find("Visible", 1, true) ~= nil and life:find("covered", 1, true) ~= nil, "stops while hidden or covered by a popup")
	expectTrue(life:find("Instance.new%("), "frames are created")
	local step = life:match("local function step%(dt%).-\nend\n") or ""
	expectTrue(step:find("Instance.new", 1, true) == nil, "no frames are created inside the per-frame step")
	local bs = read("src/Client/BackdropStyles.lua")
	expectTrue(bs:find("setAmbient", 1, true) ~= nil and bs:find("AmbientLife", 1, true) ~= nil, "BackdropStyles hosts the ambient scene")
	local view = read("src/Client/CosmeticSetsView.lua")
	expectTrue(view:find("setAmbient", 1, true) ~= nil, "the set view starts it on every equip")
	local art = read("src/Shared/Engine/ContentArt.lua")
	expectTrue(art:find("AmbientArt", 1, true) ~= nil, "ambient art is registered")
end })

table.insert(tests, { name = "HudStyle: pile look is stable per set and different for every set; HUD wiring is present", fn = function()
	local HS = require(script.Parent.Parent.Engine.HudStyle)
	local CS = require(script.Parent.Parent.Engine.CosmeticSets)
	local seen, count = {}, 0
	for _, set in ipairs(CS.Definitions) do
		local a, b = HS.pileLook(set.id), HS.pileLook(set.id)
		expectEqual(#a, 3, "three cards behind the pile")
		local sig = {}
		for i = 1, 3 do
			expectEqual(a[i].rot, b[i].rot, "stable tilt")
			expectTrue(a[i].rot ~= 0 and math.abs(a[i].rot) <= 6, "tilt within 6 degrees and never flat")
			sig[#sig + 1] = a[i].rot .. "," .. a[i].dx .. "," .. a[i].dy
		end
		local key = table.concat(sig, "|")
		expectFalse(seen[key], set.id .. " has its own pile look")
		seen[key] = true
		count = count + 1
	end
	expectTrue(count >= 15, "all sets covered")
	local function read(path)
		local f = io and io.open and io.open(path, "r")
		if not f then return nil end
		local text = f:read("*a")
		f:close()
		return text
	end
	local hub = read("src/Client/init.client.lua")
	if hub then
		expectTrue(hub:find("HudTheme", 1, true) ~= nil and hub:find("SortToggle", 1, true) ~= nil, "hub uses the themed action buttons and the sort toggle")
		expectFalse(hub:find("makeSortButton", 1, true) ~= nil, "the old Sort Rank and Suit buttons are gone")
	end
	local skin = read("src/Client/SetSkin.lua")
	if skin then
		expectTrue(skin:find("ClassicCardFrame", 1, true) ~= nil and skin:find("HudTheme", 1, true) ~= nil, "SetSkin drives the Classic frame and the HUD theme")
	end
	local deck = read("src/Client/DeckWidget.lua")
	if deck then expectTrue(deck:find("DeckWidgetSkin", 1, true) ~= nil, "the draw pile is skinned per set") end
end })

table.insert(tests, { name = "HudTheme: every palette colour is a 3-number table and every Color3 assignment in the HUD skin modules goes through c3", fn = function()
	local HS = require(script.Parent.Parent.Engine.HudStyle)
	local CS = require(script.Parent.Parent.Engine.CosmeticSets)
	local function isRgb(t)
		if type(t) ~= "table" or #t < 3 then return false end
		for i = 1, 3 do if type(t[i]) ~= "number" then return false end end
		return true
	end
	local function checkAll(pal, label)
		for k, v in pairs(pal) do
			if type(v) == "table" and k ~= "gradient" then expectTrue(isRgb(v), label .. "." .. tostring(k) .. " is an rgb table") end
		end
	end
	local sets = 0
	for _, set in ipairs(CS.Definitions) do
		sets = sets + 1
		local skin = CS.skinOf(set)
		local colors = skin.colors
		for _, role in ipairs({ "play", "discard", "sort" }) do
			checkAll(HS.buttonPalette(colors, role), set.id .. "/" .. role)
		end
		checkAll(HS.iconPalette(colors), set.id .. "/icon")
		checkAll(HS.deckPalette(colors), set.id .. "/deck")
	end
	expectTrue(sets >= 15, "all sets checked")
	checkAll(HS.buttonPalette(nil, "play"), "neutral/play")
	local f = io and io.open and io.open("src/Client/HudTheme.lua", "r")
	if f then
		local src = f:read("*a"); f:close()
		for line in src:gmatch("[^\n]+") do
			if line:find("BackgroundColor3%s*=") or line:find("TextColor3%s*=") then
				expectTrue(line:find("c3%(") ~= nil or line:find("Color3%.") ~= nil, "HudTheme colour assignment uses c3: " .. line)
			end
		end
	end
end })

table.insert(tests, { name = "FlairRoomLayout: drawers map every Flair slot, locked/owned/equipped states, unlock progress, one equipped slot per category, detail actions", fn = function()
	local Flair = require(script.Parent.Parent.Engine.Flair)
	local L = require(script.Parent.Parent.Engine.FlairRoomLayout)
	local profile = { tavernRank = 6, highestStakeUnlocked = 1, questsDone = 0 }
	local view = Flair.view(profile)
	local drawers = L.drawers(view)
	expectEqual(#drawers, #Flair.Slots, "one drawer per Flair category")
	for i, d in ipairs(drawers) do
		expectEqual(d.id, Flair.Slots[i].id, "drawer order follows the registry")
		expectEqual(d.total, #Flair.optionsFor(d.id), d.id .. " holds every option")
		local equipped, owned = 0, 0
		for _, item in ipairs(d.items) do
			if item.state == "equipped" then equipped = equipped + 1 end
			if item.state ~= "locked" then owned = owned + 1 end
			if item.state == "locked" then
				expectTrue(type(item.tag) == "string" and item.tag ~= "", item.id .. " has a brass tag")
				expectTrue(item.ratio == nil or (item.ratio >= 0 and item.ratio <= 1), "progress rail is 0 to 1")
			else
				expectTrue(item.tag == nil, "unlocked pieces have no tag")
			end
		end
		expectEqual(equipped, 1, d.id .. " has exactly one equipped piece")
		expectEqual(d.ownedCount, owned, d.id .. " counts unlocked pieces")
	end
	-- unlock progress: Ember Numbers needs rank 5 (owned at rank 6), Frost Numbers rank 10 shows 6 of 10
	local function find(id) for _, d in ipairs(drawers) do for _, it in ipairs(d.items) do if it.id == id then return it end end end end
	expectEqual(find("ember_numbers").state, "owned", "rank 6 unlocks the rank 5 piece")
	local frost = find("frost_numbers")
	expectEqual(frost.state, "locked", "rank 10 piece is locked at rank 6")
	expectEqual(frost.tag, "Rank 6 of 10", "tag shows progress toward the goal")
	expectTrue(math.abs(frost.ratio - 0.6) < 0.001, "progress rail ratio")
	local store = find("rainbow_numbers")
	expectEqual(store.tag, "Tavern Store", "store pieces say so")
	expectTrue(store.ratio == nil, "store pieces have no rail")
	expectTrue(find("leaf_numbers").tag == "Achievement", "achievement pieces name their kind")
	-- detail card
	local dFrost, dStore, dOwned, dEquipped = L.detail(frost), L.detail(store), L.detail(find("ember_numbers")), L.detail(find("classic_numbers"))
	expectFalse(dFrost.canEquip or dFrost.canBuy, "a locked free piece cannot be equipped or bought")
	expectTrue(dFrost.canPreview and dFrost.status == "Locked", "a locked piece can be previewed and shows a Locked label")
	expectTrue(dFrost.how:find("Rank 6 of 10", 1, true) ~= nil, "locked piece names its unlock progress")
	expectTrue(dFrost.how:find("Tavern Rank 10", 1, true) ~= nil, "locked piece says how to get it")
	expectTrue(dStore.canBuy and not dStore.canEquip and dStore.canPreview, "store piece offers Buy and Preview")
	expectTrue(dOwned.canEquip and dOwned.canPreview and not dOwned.canBuy, "owned piece offers Equip and Preview")
	expectTrue(not dEquipped.canEquip and dEquipped.canPreview, "equipped piece offers Preview only")
	expectFalse(L.detail(nil).canEquip, "empty detail offers nothing")
	-- equipped slots: one per category, showing the default when nothing else is equipped
	local eq = L.equippedSlots(view)
	expectEqual(#eq, #Flair.Slots, "one equipped slot per category")
	for i, e in ipairs(eq) do
		expectEqual(e.optionId, Flair.defaultFor(Flair.Slots[i].id), "default is equipped at first")
	end
	local ok = Flair.equip(profile, "scoreNumbers", "ember_numbers")
	expectTrue(ok ~= false, "equip works")
	expectEqual(L.equippedSlots(Flair.view(profile))[1].optionId, "ember_numbers", "slot follows the equipped piece")
	expectEqual(#L.drawers(nil), 0, "no view means no drawers")
end })

table.insert(tests, { name = "Flair preview: every Flair id previews without touching equip or ownership; grid fills the width; panel clears the sidebar", fn = function()
	local L = require(script.Parent.Parent.Engine.FlairRoomLayout)
	local Flair = require(script.Parent.Parent.Engine.Flair)
	local profile = Flair.newProfile and Flair.newProfile() or nil
	local view = Flair.view(profile or {})
	local before = {}
	for _, slot in ipairs(view.slots) do
		for _, o in ipairs(slot.options) do before[o.id] = { o.owned, o.equipped } end
	end
	local n = 0
	for _, d in ipairs(L.drawers(view)) do
		for _, it in ipairs(d.items) do
			n = n + 1
			expectTrue(L.detail(it).canPreview, it.id .. " can be previewed in any state")
		end
	end
	expectTrue(n > 0, "there are Flair ids")
	for _, slot in ipairs(Flair.view(profile or {}).slots) do
		for _, o in ipairs(slot.options) do
			expectEqual(o.owned, before[o.id][1], o.id .. " ownership unchanged")
			expectEqual(o.equipped, before[o.id][2], o.id .. " equip unchanged")
		end
	end
	for _, W in ipairs({ 1920, 1280 }) do
		local H = W == 1920 and 1080 or 720
		local pr = L.panelRect(W, H)
		expectTrue(pr.x >= 260 and pr.x + pr.w <= W, "panel clears the 240 px sidebar at " .. W)
		local R = L.rects(pr.w, pr.h)
		local cell = L.cell(R.compact)
		local g = L.grid(R.grid.w - 8, 11, cell)
		local last = g.cells[math.min(g.cols, 11)]
		expectEqual(g.cells[1].x, 8, "grid is left aligned to its padding")
		expectTrue((R.grid.w - 8) - (last.x + last.w) <= 8 + g.cols, "first row fills the grid width")
		for _, c in ipairs(g.cells) do expectEqual(c.w, g.cells[1].w, "tiles share one width") end
	end
end })

table.insert(tests, { name = "FlairSceneLayout: painted Flair room maps tabs, 12 cubbies, mirror, plaque and detail card inside the area without overlaps, falls back when small", fn = function()
	local L = require(script.Parent.Parent.Engine.FlairSceneLayout)
	local Flair = require(script.Parent.Parent.Engine.Flair)
	local function inside(a, b) return a.x >= b.x - 0.001 and a.y >= b.y - 0.001 and a.x + a.w <= b.x + b.w + 0.001 and a.y + a.h <= b.y + b.h + 0.001 end
	local function hit(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	-- panel areas of 1920x1080, 1280x720 (compact), 1100x700
	local fitted = 0
	for _, size in ipairs({ { 1640, 850 }, { 1000, 544 }, { 1000, 600 } }) do
		local W, H = size[1], size[2]
		local p = L.place(W, H)
		local area = { x = 0, y = 0, w = W, h = H }
		expectTrue(p.ok, "painted scene fits at " .. W .. "x" .. H)
		if p.ok then
			fitted = fitted + 1
			expectEqual(#p.cubbies, L.CUBBIES, "twelve cubbies")
			expectEqual(#p.tabs, 6, "six tab plates")
			local all = { p.mirror, p.plaque, p.detail }
			for _, t in ipairs(p.tabs) do all[#all + 1] = t end
			for _, c in ipairs(p.cubbies) do all[#all + 1] = c end
			for i, r in ipairs(all) do
				expectTrue(inside(r, area), "slot " .. i .. " inside the area at " .. W .. "x" .. H)
				for j = i + 1, #all do expectFalse(hit(r, all[j]), "slots " .. i .. " and " .. j .. " overlap at " .. W .. "x" .. H) end
			end
			expectTrue(p.tabs[1].w >= 130 and p.tabs[1].h >= 40, "tab plates big enough to read")
			expectTrue(p.cubbies[1].w >= 80 and p.cubbies[1].h >= 88, "cubbies big enough to read")
			expectTrue(p.detail.w >= 272 and p.detail.h >= 110, "detail card fits its three buttons")
			expectTrue(inside(p.bounds, area), "cubby block inside the area")
			-- never stretched: the picture keeps its aspect
			expectTrue(math.abs(p.image.w / p.image.h - L.IMAGE_W / L.IMAGE_H) < 0.001, "picture is not stretched")
			local cell = L.cell(p.cubbies[1].w, p.cubbies[1].h)
			expectTrue(cell.med >= 28 and 6 + cell.med + 4 + cell.nameH + (cell.showTag and cell.tagH + 2 or 0) <= p.cubbies[1].h, "tile content fits the cubby")
		end
	end
	expectEqual(fitted, 3, "all three desktop sizes use the painted room")
	expectFalse(L.place(776, 301).ok, "a tiny panel keeps the plain layout")
	-- every Flair category fits the twelve cubbies and the tab plates
	local view = Flair.view({})
	expectTrue(#view.slots <= 6, "no more categories than tab plates")
	for _, slot in ipairs(view.slots) do
		expectTrue(#slot.options <= L.CUBBIES, slot.id .. " has no more pieces than cubbies")
	end
end })

table.insert(tests, { name = "FlairSceneLayout: the picture is never stretched, uncovered edges melt into a vignette (no picture slices), names get two full lines (1920x1080, 1280x720)", fn = function()
	local L = require(script.Parent.Parent.Engine.FlairSceneLayout)
	for _, size in ipairs({ { 1410, 680 }, { 1000, 544 }, { 1640, 850 } }) do
		local W, H = size[1], size[2]
		local p = L.place(W, H)
		expectTrue(p.ok, "painted room at " .. W .. "x" .. H)
		local strips = L.feather(p, W, H)
		local uncovered = p.image.x > 0.5 or p.image.x + p.image.w < W - 0.5 or p.image.y > 0.5 or p.image.y + p.image.h < H - 0.5
		expectEqual(#strips > 0, uncovered, "a vignette exactly when the picture leaves an edge uncovered at " .. W .. "x" .. H)
		for _, st in ipairs(strips) do
			expectTrue(st.transparency >= 0 and st.transparency <= 1, "vignette transparency is a fraction")
			expectTrue(st.rect.x >= -1 and st.rect.y >= -1 and st.rect.x + st.rect.w <= W + 2 and st.rect.y + st.rect.h <= H + 2, st.name .. " stays inside the body")
			expectTrue(st.src == nil, "no stretched picture slice")
		end
		-- the cubby tile: two 14 px lines never cut (Roblox needs at least 36 px for them), content inside the cubby
		local c = p.cubbies[1]
		local cell = L.cell(c.w, c.h)
		expectTrue(cell.lines == 2 and cell.nameH >= 36, "two full name lines at " .. W .. "x" .. H)
		expectTrue(cell.med >= 28 and 6 + cell.med + 4 + cell.nameH + (cell.showTag and cell.tagH + 2 or 0) <= c.h, "tile fits the cubby at " .. W .. "x" .. H)
	end
end })

table.insert(tests, { name = "FlairDressingRoom: painted room source keeps the polish (parchment card, labels on the plaque, fitted sample, scaled tab names, vignette, intact spare plates, [FlairRoom] line)", fn = function()
	local f = io and io.open and io.open("src/Client/FlairDressingRoom.lua", "r")
	if not f then return end
