table.insert(tests, { name = "BadgeWallLayout: grid tabs share columns and rows; the Roads row is straight; nameplates stay inside their cell (three sizes)", fn = function()
	local W = require(script.Parent.Parent.Engine.BadgeWallLayout)
	for _, size in ipairs({ { 1400, 700 }, { 1000, 560 }, { 330, 300 } }) do
		for _, chip in ipairs({ "All", "Special" }) do
			local lay = W.layout(chip, nil, size[1], size[2])
			local cols, rowsY = {}, {}
			for _, it in ipairs(lay.items) do
				cols[it.x] = true
				rowsY[it.y] = true
				expectEqual(it.size, lay.items[1].size, chip .. " badges share one size")
			end
			local nCols, nRows = 0, 0
			for _ in pairs(cols) do nCols = nCols + 1 end
			for _ in pairs(rowsY) do nRows = nRows + 1 end
			local rows = chip == "All" and 3 or 2
			expectTrue(nRows <= rows, chip .. " uses at most " .. rows .. " aligned rows at " .. size[1] .. "x" .. size[2])
			expectTrue(nCols <= math.ceil(#lay.items / rows), chip .. " rows share the same columns at " .. size[1] .. "x" .. size[2])
		end
		-- Roads: every medal hangs ON the map at its stop (Wall.ROAD_STOPS, fractions of the board), along one road left to right
		local roads = W.layout("Roads", nil, size[1], size[2])
		local list = W.members("Roads")
		for i, it in ipairs(roads.items) do
			expectEqual(it.size, roads.items[1].size, "Roads badges share one size")
			local stop = W.ROAD_STOPS[list[i].region]
			expectTrue(stop ~= nil, list[i].region .. " has a stop on the map")
			expectTrue(math.abs(it.x + it.size / 2 - stop[1] * size[1]) <= 1 and math.abs(it.y + it.size / 2 - stop[2] * size[2]) <= 1,
				list[i].id .. " is centred on its stop at " .. size[1] .. "x" .. size[2])
			if i > 1 then
				expectTrue(it.x > roads.items[i - 1].x, "Roads badges follow one path left to right")
				expectTrue(it.y ~= roads.items[i - 1].y, "...zigzagging between an upper and a lower row, so plates never touch a neighbour")
			end
		end
	end
end })

table.insert(tests, { name = "Badge sockets: concentric with every badge, no overlaps, inside the board, shelf planks under rows, trimmed lines and dots", fn = function()
	local W = require(script.Parent.Parent.Engine.BadgeWallLayout)
	local B = require(script.Parent.Parent.Engine.Badges)
	for _, size in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 600, 330 } }) do
		for _, chip in ipairs(B.Chips) do
			local lay = W.layout(chip, nil, size[1], size[2])
			local tag = chip .. " at " .. size[1] .. "x" .. size[2]
			for i, it in ipairs(lay.items) do
				local s = W.socketRect(it)
				expectEqual(s.x + s.w / 2, it.x + it.size / 2, tag .. ": socket x is concentric")
				expectEqual(s.y + s.h / 2, it.y + it.size / 2, tag .. ": socket y is concentric")
				expectTrue(s.w > it.size and s.w <= it.size * 1.3, tag .. ": the rim sticks out a little past the badge")
				expectEqual(it.socket, W.SOCKET_KIND[chip], tag .. ": socket kind follows the tab")
				expectTrue(W.SOCKET_ART[it.socket] ~= nil, tag .. ": socket has an art key")
				local f = W.footprint(it)
				expectTrue(f.x >= 0 and f.y >= 0 and f.x + f.w <= size[1] and f.y + f.h <= size[2], tag .. ": socket and plate inside the board")
				expectTrue(W.plateY(it) >= it.size + (s.w - it.size) / 2, tag .. ": nameplate hangs below the socket, never over it")
				for j = i + 1, #lay.items do
					local a, b = W.socketRect(it), W.socketRect(lay.items[j])
					local apart = a.x + a.w <= b.x or b.x + b.w <= a.x or a.y + a.h <= b.y or b.y + b.h <= a.y
					expectTrue(apart, tag .. ": sockets do not overlap")
				end
			end
			if chip == "All" or chip == "Special" then
				expectTrue(#lay.shelves >= 1, tag .. ": a plank under each row")
				for _, y in ipairs(lay.shelves) do
					expectTrue(y + W.PLANK_H <= size[2], tag .. ": plank inside the board")
				end
				for _, it in ipairs(lay.items) do
					local bottom = it.y + it.size + W.pad(it.size)
					local rests = false
					for _, y in ipairs(lay.shelves) do
						if math.abs(y + 3 - bottom) <= 1 then rests = true end
					end
					expectTrue(rests, tag .. ": every socket rests on a plank")
				end
			end
		end
	end
	-- trimmed lines start and end on the socket edges
	local t = W.trim(0, 0, 100, 0, 20, 20)
	expectTrue(t.x1 == 20 and t.x2 == 80 and t.y1 == 0, "trim cuts back to the socket edge")
	expectTrue(W.trim(0, 0, 30, 0, 20, 20) == nil, "overlapping sockets leave no line")
	local dots = W.dots(0, 0, 200, 0, 20, 20, 20)
	expectTrue(#dots >= 3 and dots[1].x == 20 and dots[#dots].x == 180, "dots run from socket edge to socket edge")
	if io then
		local f = io.open("src/Client/BadgeWall.lua", "r")
		if f then
			local src = f:read("*a")
			f:close()
			expectTrue(src:find("Wall.socketRect", 1, true) ~= nil and src:find("BadgeSocketArt", 1, true) ~= nil, "the wall draws sockets from the layout, with art hooks")
			expectTrue(src:find('"badge_hook_pin"', 1, true) == nil, "no floating pins or hooks above the badges")
		end
	end
	local Art = require(script.Parent.Parent.Engine.BadgeSocketArt)
	expectEqual(type(Art), "table", "BadgeSocketArt is a table (empty until Image ids are recorded)")
end })

table.insert(tests, { name = "Popup sounds: scroll_open and scroll_close cues exist, the shared gate debounces, and PopupShield plays them", fn = function()
	local S = require(script.Parent.Parent.Engine.SoundIds)
	local R = require(script.Parent.Parent.Engine.PopupRules)
	expectEqual(S.Cues.scroll_open.id, "rbxassetid://9118835650", "scroll_open id")
	expectEqual(S.Cues.scroll_open.volume, 0.45, "scroll_open volume")
	expectEqual(S.Cues.scroll_open.maxLength, 1.9, "scroll_open length")
	expectEqual(S.Cues.scroll_close.id, "rbxassetid://9118838541", "scroll_close id")
	expectEqual(S.Cues.scroll_close.volume, 0.35, "scroll_close volume")
	expectEqual(S.Cues.scroll_close.maxLength, 0.7, "scroll_close length")
	local listed = {}
	for _, n in ipairs(S.CueOrder) do listed[n] = true end
	expectTrue(listed.scroll_open and listed.scroll_close, "both cues are in CueOrder")
	local gate = R.newCueGate()
	expectEqual(gate(true, 10), "scroll_open", "first open plays")
	expectEqual(gate(false, 10.05), nil, "a close inside 0.15 s is silent (no open and close together)")
	expectEqual(gate(false, 10.2), "scroll_close", "a close after the gap plays")
	expectEqual(gate(true, 10.25), nil, "rapid toggle does not stack")
	expectEqual(gate(true, 10.5), "scroll_open", "later open plays")
	expectTrue(R.makesSound("SettingsBackdrop") and R.makesSound("Scroll_questscroll") and R.makesSound("AllActions"), "popups make sound")
	expectFalse(R.makesSound("DeckTrackerBackdrop") or R.makesSound("FanCatcher") or R.makesSound("NoticeBoard"), "toggles and catchers stay silent")
	local f = io and io.open and io.open("src/Client/PopupShield.lua", "r")
	if f then
		local src = f:read("*a"); f:close()
		expectTrue(src:find('"scroll_open"', 1, true) ~= nil or src:find("newCueGate", 1, true) ~= nil, "PopupShield uses the shared gate")
		expectTrue(src:find("Cue.play(cue)", 1, true) ~= nil, "PopupShield plays the cue")
		expectTrue(src:find("page_turn", 1, true) == nil, "ledger page turns are not popup sounds")
	end
	local h = io and io.open and io.open("src/Client/MenuHotspots.lua", "r")
	if h then
		local src = h:read("*a"); h:close()
		local _, n = src:gsub("watchSound", "")
		expectEqual(n, 2, "Menu scrolls and the All actions list register with the popup sound path")
	end
end })

table.insert(tests, { name = "Classic card border: wraps the full card edge, centre transparent, the Card Sets chip is a mini card, other sets untouched", fn = function()
	local HS = require(script.Parent.Parent.Engine.HudStyle)
	for _, size in ipairs({ { 38, 52 }, { 100, 140 }, { 200, 280 } }) do
		local w, h = size[1], size[2]
		local l = HS.classicFrame(w, h)
		expectTrue(l.band.top.x == 0 and l.band.top.y == 0 and l.band.top.w == w, "top band spans the card width")
		expectTrue(l.band.bottom.y + l.band.bottom.h == h and l.band.right.x + l.band.right.w == w, "bands end on the card rect")
		expectTrue(l.band.left.h == h and l.band.right.h == h, "side bands span the card height")
		expectTrue(l.t / w >= 0.06 - 0.02, "band about 6 to 8 percent of the width at " .. w)
		expectTrue(w - 2 * l.t > w * 0.7 and h - 2 * l.t > h * 0.7, "the centre window stays open at " .. w)
	end
	if io and io.open then
		local f = io.open("src/Client/ClassicCardFrame.lua", "r")
		local src = f:read("*a"); f:close()
		expectTrue(src:find("holder.BackgroundTransparency = 1", 1, true) ~= nil, "frame holder (the centre) is transparent")
		expectTrue(src:find("Oak_", 1, true) == nil and src:find("Cap\" ..", 1, true) == nil and src:find("stroke.Thickness = 1", 1, true) ~= nil, "card edge is one 1 px stroke: no oak band, no corner caps")
		expectTrue(src:find("FindFirstChildOfClass", 1, true) ~= nil, "frame corner radius follows the card")
		local g = io.open("src/Client/CosmeticSetsPanel.lua", "r")
		local panel = g:read("*a"); g:close()
		expectTrue(panel:find("MiniCard", 1, true) == nil and panel:find("SampleCardChip", 1, true) == nil and panel:find("Card border", 1, true) == nil, "no Classic-only mini card chip; every set shows the Panel border chip through SetSkin.sample")
		expectTrue(panel:find("SampleButton", 1, true) == nil and panel:find("SamplePanel", 1, true) == nil and panel:find("SetSkin.sample", 1, true) == nil and panel:find("bdStroke.Color", 1, true) ~= nil, "set rows draw no empty sample bars; the set tint rides the thumbnail stroke")
		local nonAscii = false
		for _, codepoint in utf8.codes(panel) do
			if codepoint > 0x2000 then nonAscii = true end
		end
		expectTrue(not nonAscii, "CosmeticSetsPanel has no emoji (set names, lock badge)")
		expectTrue(panel:find("set.icon", 1, true) == nil, "set names do not carry the emoji icon")
		expectTrue(panel:find("192, 192, 192", 1, true) ~= nil and panel:find("130, 130, 130) -- never", 1, true) == nil, "locked thumbnails dim at most 25 percent")
		local h = io.open("src/Client/MenuHotspots.lua", "r")
		local hot = h:read("*a"); h:close()
		expectTrue(hot:find('register("menuActions"', 1, true) ~= nil, "All actions list closes when any panel opens")
		local k = io.open("src/Client/SetSkin.lua", "r")
		local skin = k:read("*a"); k:close()
		local _, n = skin:gsub("ClassicCardFrame", "")
		expectEqual(n, 1, "SetSkin still draws the Classic frame in one place only")
	end
end })

