table.insert(tests, { name = "Ledger page turn: the page_turn cue exists with its id, volume and length, and the ledger plays it on a page or tab change", fn = function()
	local S = require(script.Parent.Parent.Engine.SoundIds)
	local cue = S.Cues.page_turn
	expectTrue(cue ~= nil, "page_turn is a named cue")
	expectEqual(cue.id, "rbxassetid://9118835414", "page_turn id")
	expectEqual(cue.volume, 0.5, "page_turn volume")
	expectEqual(cue.maxLength, 1.0, "page_turn max length")
	expectTrue(cue.startAt ~= nil and cue.startAt >= 0 and cue.fade ~= nil and cue.fade > 0, "page_turn skips the lead-in and fades its tail")
	expectEqual(S.cueId("page_turn"), "rbxassetid://9118835414", "page_turn is playable")
	local f = io and io.open and io.open("src/Client/LedgerBook.lua", "r")
	if not f then return end
	local src = f:read("*a"); f:close()
	expectTrue(src:find('local Cue = require(script.Parent.Cue)', 1, true) ~= nil, "plays through the Cue bridge to Sound.playCue")
	local quick = src:match("local function quickTurn%(target%)(.-)\n\tend\n")
	expectTrue(quick ~= nil and quick:find('cueOnce("page_turn", 1)', 1, true) ~= nil, "every section jump plays page_turn")
	local cuePos = quick:find('cueOnce("page_turn", 1)', 1, true)
	local sheetPos = quick:find("beginTurn(", 1, true)
	expectTrue(cuePos ~= nil and sheetPos ~= nil and cuePos < sheetPos, "the cue starts as the sheet leaves the page, not after it lands")
	expectTrue(src:find('Name = "PageFlip"', 1, true) ~= nil and src:find("PageSweep", 1, true) == nil, "one paper sheet, no grey sweep")
	expectTrue(src:find("animate(t, 0, 1, 0.22,", 1, true) ~= nil and src:find("Layout.TURN_TIME", 1, true) ~= nil, "a quick turn takes 0.22 s, a released drag 0.25 s")
	expectTrue(src:find('Name = "PageVeil"', 1, true) ~= nil and src:find("TweenInfo.new(0.12)", 1, true) ~= nil, "calm mode crossfades in 0.12 s")
	expectTrue(src:find("PopupRules.newCueGate(0.15)", 1, true) ~= nil, "never more than one sound per 0.15 s")
end })

