table.insert(tests, { name = "Ledger v5: text rows sit on the book's own sloped lines, inside the page quads, in readable ink; the flip sheet is cut from the page", fn = function()
	local LL = require(script.Parent.Parent.Engine.LedgerLayout)
	local LP = require(script.Parent.Parent.Engine.LedgerPages)
	expectEqual(#LL.lines("left"), 9, "nine ruled lines on the left page")
	expectEqual(#LL.lines("right"), 9, "nine ruled lines on the right page")
	expectTrue(LL.pageAngle("left") < 0 and LL.pageAngle("right") > -0.5, "the pages are tilted differently (left rises toward the gutter)")
	for _, vp in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 600, 800 } }) do
		local pr = LP.panelRect(vp[1], vp[2])
		local r = (pr.w < 700) and LP.LAYOUT.bookCompact or LP.LAYOUT.book
		local bw = math.min(pr.w * r.w, pr.h * r.h * LL.ASPECT)
		local bh = bw / LL.ASPECT
		local sz = LL.sizes(bh)
		expectTrue(sz.body >= 14, "body text never below 14 px")
		if vp[1] == 1920 then expectTrue(sz.body >= 20 and sz.head >= 24, "20 px body and 24+ px headings at 1920x1080") end
		for _, side in ipairs({ "left", "right" }) do
			local box = LL.pageBox(side)
			for i = 1, LL.LINE_COUNT do
				for _, t in ipairs({ 0, 0.5, 1 }) do
					local lift = LL.liftPx(side, i, t, bw, bh)
					expectTrue(math.abs(lift - LL.UP_PX) <= 0.01, "baseline lifted 3 px off its line (" .. side .. i .. ")")
					local ax, ay, lx, ly = LL.anchorPx(side, i, t, bw, bh)
					expectTrue(math.abs(ax - lx) <= 3.01 and math.abs(ay - ly) <= 3.01, "anchor within 3 px of the line point")
					local x, y = LL.point(side, i, t)
					expectTrue(LL.insideQuad(side, x, y, 0.05 * box.w), "row end inside the page quad with a margin (" .. side .. i .. ")")
				end
			end
		end
	end
	expectTrue(LL.liftPx("left", 3, 0.5, 951, 634) > 0, "text sits above the line")
	for _, side in ipairs({ "left", "right" }) do
		local paper = LL.paperRgb(side)
		expectTrue(LL.contrast(LL.INK, paper) >= 7, "ink contrast 7:1 on the " .. side .. " paper")
		expectTrue(LL.contrast(LL.INK_DIM, paper) >= 7, "soft ink contrast 7:1 on the " .. side .. " paper")
	end
	-- page box = the quad's bounding box, the sheet is cut from it, and the tabs sit level with the page top
	for _, side in ipairs({ "left", "right" }) do
		local box = LL.pageBox(side)
		for _, c in ipairs(LL.quad(side)) do
			expectTrue(c[1] >= box.x - 1e-9 and c[1] <= box.x + box.w + 1e-9 and c[2] >= box.y - 1e-9 and c[2] <= box.y + box.h + 1e-9, "quad corner inside its page box")
		end
	end
	expectTrue(LL.pageBox("left").x + LL.pageBox("left").w < LL.GEOMETRY.gutterX and LL.pageBox("right").x > LL.GEOMETRY.gutterX, "the pages sit either side of the gutter")
	local f = io and io.open and io.open("src/Client/LedgerBook.lua", "r")
	if not f then return end
	local src = f:read("*a"); f:close()
	expectTrue(src:find("TextTransparency = 0.", 1, true) == nil and src:find("TextTransparency = 1", 1, true) == nil, "no see-through ledger text")
	expectTrue(src:find("UIAspectRatioConstraint", 1, true) ~= nil and src:find("ar.AspectRatio = Layout.ASPECT", 1, true) ~= nil, "the book keeps the art's aspect so the measured angles hold")
	expectTrue(src:find("Rotation = p.angle", 1, true) ~= nil, "text rows are rotated to the measured line angle")
	expectTrue(src:find("sheet.Rotation", 1, true) == nil and src:find("img.Size = UDim2.fromScale(1 / sb.w, 1 / sb.h)", 1, true) ~= nil, "the flip sheet is a crop of the page art and is never rotated (a rotated frame ignores clipping)")
	expectTrue(src:find("Fold", 1, true) == nil and src:find("(1 - (1 - u) * (1 - u))", 1, true) ~= nil, "no stray cream rectangle, Quad out easing")
	expectTrue(src:find("tab.Parent = book", 1, true) ~= nil, "the ribbon tabs hang off the book edge")
end })

table.insert(tests, { name = "Ledger v6: one sheet turns about the spine (cos width, lift, shade), drag progress and release thresholds, first and last page, tab jump, calm mode, only the sheet changes", fn = function()
	local LL = require(script.Parent.Parent.Engine.LedgerLayout)
	-- sheet progress math
	local s0, s25, s5, s75, s1 = LL.sheetState(0, true), LL.sheetState(0.25, true), LL.sheetState(0.5, true), LL.sheetState(0.75, true), LL.sheetState(1, true)
	expectTrue(math.abs(s0.width - 1) < 1e-9 and s0.side == "right" and s0.face == "front" and s0.lift == 0, "starts flat on the right page, front face")
	expectTrue(math.abs(s25.width - math.cos(math.pi * 0.25)) < 1e-9 and s25.side == "right" and s25.face == "front", "width follows cos(p pi)")
	expectTrue(s5.width < 1e-9 and math.abs(s5.lift - LL.LIFT_PX) < 1e-9, "edge on at the middle, free edge lifted 6 px")
	expectTrue(s75.side == "left" and s75.face == "back" and math.abs(s75.width - math.abs(math.cos(math.pi * 0.75))) < 1e-9, "past the middle it grows on the left page showing the back")
	expectTrue(math.abs(s1.width - 1) < 1e-9 and s1.side == "left" and s1.lift < 1e-9 and s1.shade < 1e-9 and s1.shadow < 1e-9, "lands flat, shade and shadow gone")
	expectTrue(s5.shade > 0.3 and s5.shadow > 0.25, "shade and cast shadow peak at the middle")
	local back0, back1 = LL.sheetState(0.1, false), LL.sheetState(0.9, false)
	expectTrue(back0.side == "left" and back1.side == "right", "a backward turn goes left to right")
	for i = 0, 20 do
		local st = LL.sheetState(i / 20, i % 2 == 0)
		expectTrue(st.width >= 0 and st.width <= 1 and st.lift >= 0 and st.lift <= LL.LIFT_PX + 1e-9, "width and lift stay in range")
	end
	-- drag: progress follows pointer travel over the page width, release thresholds
	expectEqual(LL.dragProgress(-20, 300), 0, "dragging the wrong way does nothing")
	expectTrue(math.abs(LL.dragProgress(150, 300) - 0.5) < 1e-9 and LL.dragProgress(900, 300) == 1, "progress is travel over page width, clamped")
	expectEqual(LL.release(0.5, 0), "complete", "past 0.4 completes")
	expectEqual(LL.release(0.39, 0), "back", "under 0.4 springs back")
	expectEqual(LL.release(0.1, LL.FAST_PX_PER_S + 1), "complete", "a fast flick completes")
	expectTrue(LL.TURN_TIME == 0.25 and LL.DRAG_START_PX == 8, "0.25 s settle, the sheet leaves after 8 px")
	-- first and last page
	local ok1 = LL.canTurn(1, -1, 3)
	local ok2 = LL.canTurn(3, 1, 3)
	local ok3, target = LL.canTurn(2, 1, 3)
	expectFalse(ok1, "no turning back from the first section")
	expectFalse(ok2, "no turning forward from the last section")
	expectTrue(ok3 and target == 3, "a middle section turns")
	expectTrue(LL.maxProgress(false) == LL.END_LIFT and LL.END_LIFT <= 0.15 and LL.maxProgress(true) == 1, "at the ends the sheet only lifts a little")
	-- grab hotspots: outer edge strip of at least 12 percent plus the bottom corner, inside the page
	for _, side in ipairs({ "left", "right" }) do
		local h = LL.hotspots(side)
		expectTrue(h.edge.w >= 0.12 and h.edge.h == 1 and h.corner.y + h.corner.h <= 1.0001, "edge strip and corner of the " .. side .. " page")
		if side == "right" then expectTrue(h.edge.x + h.edge.w >= 0.9999, "right page grabs at its outer (right) edge") else expectTrue(h.edge.x == 0, "left page grabs at its outer (left) edge") end
	end
	local f = io and io.open and io.open("src/Client/LedgerBook.lua", "r")
	if not f then return end
	local src = f:read("*a"); f:close()
	-- only the sheet changes: the turn code touches the sheet, its faces, shade and cast shadow, never the book frame
	local turnCode = src:match("local function setSheet%(t, p%)(.-)\n\tend\n")
	expectTrue(turnCode ~= nil and turnCode:find("book.Size", 1, true) == nil and turnCode:find("book.Position", 1, true) == nil and turnCode:find("desk.", 1, true) == nil, "setSheet never touches the book or the desk")
	expectTrue(src:find("quickTurn(i) -- one sheet to that section", 1, true) ~= nil, "a tab jump is one quick sheet turn")
	expectTrue(src:find("Enum.KeyCode.Right then step(1)", 1, true) ~= nil and src:find("Enum.KeyCode.Left then step(-1)", 1, true) ~= nil, "Left and Right arrow keys turn pages")
	expectTrue(src:find("if not d.started then -- a plain click or tap on the corner turns the page", 1, true) ~= nil, "a click on the corner turns the page")
	local quick = src:match("local function quickTurn%(target%)(.-)\n\tend\n")
	local calmBranch = quick and quick:match("if calm%(%) then(.-)return\n\t\tend")
	expectTrue(calmBranch ~= nil and calmBranch:find("crossfade(", 1, true) ~= nil and calmBranch:find("beginTurn", 1, true) == nil and calmBranch:find("Create(", 1, true) == nil, "calm mode crossfades and builds no sheet or tween")
	expectTrue(src:find("if calm() then return end\n\t\tlocal t = beginTurn(forward, nil)", 1, true) ~= nil, "calm mode does not lift the sheet at the ends either")
	expectTrue(src:find("ScrollBarThickness = 4", 1, true) ~= nil and src:find("ScrollBarImageTransparency = 0.5", 1, true) ~= nil, "the run list scroll bar is thin and low contrast")
	expectTrue(src:find("book:GetPropertyChangedSignal(\"AbsoluteSize\")", 1, true) ~= nil, "pages repaint once the book is laid out or resized")
end })

table.insert(tests, { name = "Art hooks: paper notes, ribbon banner and shelf rails use their art ids and keep the drawn fallback", fn = function()
	local LedgerArt = require(script.Parent.Parent.Engine.LedgerArt)
