table.insert(tests, { name = "Badge sockets fit: diameter is the medal times 1.18, Night sockets never overlap, Roads pins sit above every medal, tiny stars stay clear of sockets", fn = function()
	local W = require(script.Parent.Parent.Engine.BadgeWallLayout)
	for _, size in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 600, 330 }, { 330, 300 } }) do
		for _, chip in ipairs({ "Night", "Roads", "All", "Masters", "Special" }) do
			local lay = W.layout(chip, nil, size[1], size[2])
			for i, it in ipairs(lay.items) do
				local d = W.socketRect(it).w
				expectTrue(math.abs(d - it.size * 1.18) <= 1.5, chip .. ": socket is the medal times 1.18 (within a pixel)")
				expectEqual(d, W.socketDiameter(it.size))
				for j = i + 1, #lay.items do
					local a, b = W.socketRect(it), W.socketRect(lay.items[j])
					expectTrue(a.x + a.w <= b.x or b.x + b.w <= a.x or a.y + a.h <= b.y or b.y + b.h <= a.y, chip .. ": sockets never overlap")
				end
				if chip == "Roads" then
					local p = W.pinFor(it)
					expectEqual(p.x, it.x + it.size / 2, "pin directly above the medal")
					expectTrue(p.y >= 4 and p.y < p.y2 and p.y2 == it.y - W.pad(it.size), "pin and string end at the socket top, inside the board")
				end
			end
			if chip == "Night" then
				for _, st in ipairs(W.tinyStars(lay.items)) do
					expectTrue(st.x >= 0 and st.y >= 0 and st.x <= size[1] and st.y <= size[2], "tiny star inside the board")
					for _, it in ipairs(lay.items) do
						local r = W.socketRect(it)
						local dx, dy = st.x - (r.x + r.w / 2), st.y - (r.y + r.h / 2)
						expectTrue(dx * dx + dy * dy >= (r.w / 2) ^ 2, "tiny star clear of every socket")
					end
				end
			end
			if chip == "All" or chip == "Special" then
				for _, it in ipairs(lay.items) do
					local bottom = it.y + it.size + W.pad(it.size)
					local rests = false
					for _, y in ipairs(lay.shelves) do if math.abs(y + 3 - bottom) <= 1 then rests = true end end
					expectTrue(rests, chip .. ": every medal sits on a shelf plank")
				end
			end
		end
	end
end })

table.insert(tests, { name = "Daily reward plate: queued above toasts, auto closes after 12s, no emoji in the login files", fn = function()
	local R = require(script.Parent.Parent.Engine.OverlayQueueRules)
	local LS = require(script.Parent.Parent.Engine.LoginStreak)
	expectTrue(R.PRIORITY.daily > R.PRIORITY.unlock and R.PRIORITY.daily < R.PRIORITY.rank and R.PRIORITY.rank < R.PRIORITY.other, "daily sits above rank and other toasts")
	expectEqual(R.autoSeconds({ button = "Claim", autoAfter = R.DAILY_AUTO_SECONDS }), 12, "the daily plate closes itself after 12s")
	expectEqual(R.autoSeconds({ button = "Continue" }), nil, "other button plates still wait for a click")
	local q = R.new()
	q:enqueue({ id = "toast", priority = R.PRIORITY.other })
	q:enqueue({ id = "daily:1", priority = R.PRIORITY.daily, custom = function() end })
	local first = q:advance()
	expectEqual(first.id, "daily:1", "the daily plate goes before toasts")
	expectTrue(type(first.custom) == "function", "custom content survives the queue")
	local function noEmoji(text, what)
		local i = 1
		while i <= #text do
			local cp = utf8.codepoint(text, i)
			expectTrue(cp < 0x2000 or (cp >= 0x2000 and cp <= 0x206F), what .. " has a glyph above U+2000 (codepoint " .. cp .. ")")
			i = utf8.offset(text, 2, i)
		end
	end
	for _, r in ipairs(LS.Rewards) do
		expectTrue(r.icon == nil, "day " .. r.day .. " has no emoji icon")
		expectTrue(r.art == "tips" or r.art == "xp" or r.art == "cardBack", "day " .. r.day .. " names a painted piece")
		noEmoji(r.label, "day " .. r.day .. " label")
	end
	for _, path in ipairs({ "src/Client/LoginStreakUI.lua", "src/Shared/Engine/LoginStreak.lua" }) do
		local f = io and io.open and io.open(path, "r")
		if f then
			local src = f:read("*a")
			f:close()
			noEmoji(src, path)
		end
	end
end })

