		expectTrue(sv:find("UIGradient", 1, true) ~= nil and sv:find("g.Parent = f", 1, true) ~= nil, "every vignette frame gets a UIGradient")
		for _, file in ipairs({ "BossFight", "BackdropStyles", "ShopBackdrop", "TableLook", "PanelArt", "TravelTransition" }) do
			local src = read("src/Client/" .. file .. ".lua")
			expectTrue(src ~= nil and src:find("SmoothVignette", 1, true) ~= nil, file .. " builds its vignette with SmoothVignette")
			expectTrue(src:find("VIGNETTE_STEPS", 1, true) == nil, file .. " has no stepped vignette constant")
			expectTrue(src:find("\"Vignette\" .. i", 1, true) == nil and src:find("strip(Vector2", 1, true) == nil, file .. " stacks no strips")
		end
	end
end })

table.insert(tests, { name = "Counter v2 stage: card scales fit the rects, rows sit on the counter at four sizes, stage keeps handlers and gates on the art", fn = function()
	local L = require(script.Parent.Parent.Engine.ShopSceneLayout)
	local CardShape = require(script.Parent.Parent.Engine.CardShape)
	local sizes = { { 1660, 1080 }, { 1020, 720 }, { 800, 450 }, { 360, 640 } }
	for _, sz in ipairs(sizes) do
		local W, H = sz[1], sz[2]
		for _, counts in ipairs({ { offers = 3, packs = 2 }, { offers = 5, packs = 3 }, { offers = 2, packs = 0 } }) do
			local tag = W .. "x" .. H .. " " .. counts.offers .. "/" .. counts.packs
			local r = L.rects(W, H, counts)
			local sc = L.cardScales(r)
			expectTrue(sc.patron >= L.SCALE_MIN and sc.patron <= L.SCALE_MAX, "patron scale in range " .. tag)
			local ps = CardShape.shape("patron", sc.patron)
			if sc.patron > L.SCALE_MIN + 1e-9 then
				expectTrue(ps.w <= r.offers[1].w + 1, "patron card fits its rect width " .. tag)
				expectTrue(ps.h <= r.offers[1].h + 1, "patron card fits its rect height " .. tag)
			end
			local rows = L.rows(r, CardShape.shape("patron", sc.patron).h + 32, CardShape.shape("pack", sc.pack).h + 32)
			expectTrue(rows.patron.x >= 0 and rows.patron.x + rows.patron.w <= W, "patron row inside horizontally " .. tag)
			if not r.phone then
				expectEqual(rows.patron.y + 16, r.offers[1].y, "the Patron row's cards start where the table layout put them " .. tag)
				expectTrue(r.bandX0 > r.marlo.x + r.marlo.w * 0.5, "card band starts right of Marlo " .. tag)
			end
			if counts.packs > 0 then expectTrue(rows.pack ~= nil, "pack row " .. tag) end
		end
	end
	local function read(path)
		local f = io and io.open and io.open(path, "r")
		if not f then return nil end
		local src = f:read("*a"); f:close()
		return src
	end
	local stage = read("src/Client/ShopStage.lua")
	if stage then
		expectTrue(stage:find("if not backdrop then", 1, true) ~= nil, "no art, no stage: the old Shop shows unchanged")
		expectTrue(stage:find("FireServer", 1, true) == nil and stage:find("MouseButton1Click", 1, true) == nil, "the stage adds no handlers and fires no remotes")
		expectTrue(stage:find("calm()", 1, true) ~= nil and stage:find("reduceShake", 1, true) ~= nil, "calm mode never lights the prop glow")
		expectTrue(stage:find("TweenService", 1, true) == nil and stage:find("task.spawn", 1, true) == nil and stage:find("Layout.bob", 1, true) == nil,
			"the stage runs no loops and no tweens: cards lie on the table, they do not float")
	end
	local shop = read("src/Client/Shop.lua")
	if shop then
		expectTrue(shop:find("ShopStage", 1, true) ~= nil and shop:find("shopStage.arrange", 1, true) ~= nil, "Shop mounts the stage and arranges after each rebuild")
		for _, h in ipairs({ "RerollShopRemote:FireServer", "BuyPatronRemote:FireServer", "BuyPackRemote:FireServer", "BuyHousePassRemote:FireServer" }) do
			expectTrue(shop:find(h, 1, true) ~= nil, "handler kept: " .. h)
		end
		expectTrue(shop:find("shopStage.setTab", 1, true) ~= nil, "My Patrons / My Recipes tabs switch the plate")
	end
	local scene = read("src/Client/ShopScene.lua")
	if scene then
		expectTrue(scene:find("painted", 1, true) ~= nil and scene:find("placeBubble", 1, true) ~= nil, "ShopScene hides its flat dressing under the painted scene")
		expectTrue(scene:find("if not marlo or calm() then return end", 1, true) ~= nil, "Marlo reactions are skipped in calm mode")
	end
	local haggle = read("src/Client/ShopHaggle.lua")
	if haggle then
		expectTrue(haggle:find("b.TextStrokeTransparency = 1", 1, true) ~= nil, "Haggle label has no squeezing text stroke")
	end
	local bd = read("src/Client/ShopBackdrop.lua")
	if bd then
		expectTrue(bd:find("shop_marlo_behind", 1, true) ~= nil and bd:find("shop_light_pool", 1, true) ~= nil, "backdrop draws Marlo and the light pool from the scene art")
	end
end })

table.insert(tests, { name = "RegionTiles.maskStops: smootherstep masks with at least 8 keypoints per faded side, valid for a NumberSequence", fn = function()
	local RegionTiles = require(script.Parent.Parent.Engine.RegionTiles)
	for _, c in ipairs({ { 800, 200, 0 }, { 800, 0, 200 }, { 800, 300, 300 }, { 100, 400, 400 }, { 1, 1, 0 }, { 500, 0, 0 } }) do
		local pts = RegionTiles.maskStops(c[1], c[2], c[3], 10)
		expectEqual(0, pts[1].t, "starts at 0")
		expectEqual(1, pts[#pts].t, "ends at 1")
		for k = 2, #pts do
			expectTrue(pts[k].t >= pts[k - 1].t, "times never decrease")
			expectTrue(pts[k].transparency >= 0 and pts[k].transparency <= 1, "transparency in range")
		end
		if c[2] > 0 then
			expectEqual(1, pts[1].transparency, "a faded left edge starts clear")
		end
		if c[3] > 0 then
			expectEqual(1, pts[#pts].transparency, "a faded right edge ends clear")
		end
		local want = ((c[2] > 0) and 11 or 1) + ((c[3] > 0) and 11 or 1)
		if c[2] > 0 and c[3] > 0 then want = 20 end -- both sides faded: capped so the NumberSequence stays within Roblox's 20 keypoints
		expectEqual(want, #pts, "keypoint count")
	end
end })

table.insert(tests, { name = "RegionTiles.maskStops: never more than 20 keypoints for any width, fade or perSide, and a stub NumberSequence accepts every result", fn = function()
	local RegionTiles = require(script.Parent.Parent.Engine.RegionTiles)
	-- stub with Roblox's rule: NumberSequence.new(table) errors when the table has more than 20 keypoints
	local function stubSequence(kps)
		if #kps > 20 then error("NumberSequence.new(): table is too long") end
		return kps
	end
	for _, width in ipairs({ 1, 50, 100, 400, 800, 3000 }) do
		for _, fade in ipairs({ 0, 1, 40, 200, 500, 4000 }) do
			for _, perSide in ipairs({ 1, 8, 10, 15, 40, 200 }) do
				for _, sides in ipairs({ { fade, 0 }, { 0, fade }, { fade, fade } }) do
					local pts = RegionTiles.maskStops(width, sides[1], sides[2], perSide)
					expectTrue(#pts <= 20, "at most 20 keypoints")
					local kps = {}
					for _, p in ipairs(pts) do kps[#kps + 1] = { t = p.t, v = p.transparency } end
					local ok = pcall(stubSequence, kps)
					expectTrue(ok, "stub NumberSequence accepts width " .. width .. " fade " .. fade .. " perSide " .. perSide)
					expectEqual(0, pts[1].t, "starts at 0")
					expectEqual(1, pts[#pts].t, "ends at 1")
				end
			end
		end
	end
end })

