table.insert(tests, { name = "GlowCurve: every glow has 24+ eased steps, smooth falloff, and SoftGlow is the only file that stacks discs", fn = function()
	local GC = require(script.Parent.Parent.Engine.GlowCurve)
	expectTrue(GC.MIN_STEPS >= 24 and GC.DEFAULT_STEPS >= 24, "at least 24 steps")
	expectEqual(#GC.rings(3, 0.3), GC.MIN_STEPS, "a request for fewer steps is raised to the minimum")
	local rings = GC.rings(GC.DEFAULT_STEPS, 0.3)
	local cum = GC.cumulative(rings)
	local maxStep = 0
	for i = 1, #cum do
		expectTrue(cum[i] >= (cum[i - 1] or 0) - 1e-9, "opacity never drops toward the centre")
		maxStep = math.max(maxStep, cum[i] - (cum[i - 1] or 0))
	end
	expectTrue(math.abs(cum[#cum] - 0.3) < 0.02, "the centre reaches the peak")
	expectTrue(maxStep < 0.03, "no step between rings is visible (under 3 percent opacity)")
	expectTrue(cum[1] < 0.01, "the outermost ring is nearly clear")
	local function read(path)
		local f = io and io.open and io.open(path, "r")
		if not f then return nil end
		local s = f:read("*a"); f:close()
		return s
	end
	for _, name in ipairs({ "MenuRoom", "ChoicePanel", "MenuWorld", "ShopBackdrop", "AmbientLife", "CollectionGallery" }) do
		local src = read("src/Client/" .. name .. ".lua")
		if src then
			expectTrue(src:find('"Ring" ..', 1, true) == nil and src:find("GLOW_STEPS", 1, true) == nil and src:find("glowRings", 1, true) == nil, name .. " builds no stacked-disc glow of its own")
		end
	end
end })

table.insert(tests, { name = "Notice Board: every note rect sits inside the cork with 10 px margins at 1920x1080, 1280x720 and 800x450; All actions plate is stroked on its border only", fn = function()
	local RL = require(script.Parent.Parent.Engine.MenuRoomLayout)
	for _, size in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 800, 450 } }) do
		local W, H = size[1], size[2]
		local l, t, r, b = RL.corkRect(W, H)
		local cw, ch = r - l, b - t
		local fitted = RL.noteSlots(cw, ch, { 70, 80, 70, 90 })
		expectTrue(fitted.scale <= 1 and fitted.scale > 0, W .. ": scale in range")
		expectTrue(fitted.shown <= RL.MAX_NOTES, W .. ": at most four notes")
		expectTrue(fitted.shown >= 1 or ch < 90, W .. ": at least one note unless the cork is tiny")
		local prevBottom
		for i, n in ipairs(fitted.rects) do
			expectTrue(n.x >= RL.CORK_MARGIN and n.x + n.w <= cw - RL.CORK_MARGIN, W .. ": note " .. i .. " is inside the cork sideways")
			expectTrue(n.y >= RL.CORK_MARGIN and n.y + n.h <= ch - RL.CORK_MARGIN, W .. ": note " .. i .. " is inside the cork vertically")
			if prevBottom then expectTrue(n.y > prevBottom, W .. ": notes do not overlap") end
			prevBottom = n.y + n.h
		end
	end
	local f = io and io.open and io.open("src/Client/MenuHotspots.lua", "r")
	if not f then return end
	local src = f:read("*a"); f:close()
	local a = src:find('allButton.Name = "AllActionsButton"', 1, true)
	local seg = src:sub(a, a + 1800)
	expectTrue(seg:find("ApplyStrokeMode.Border", 1, true) ~= nil, "the brass edge strokes the border, not the letters")
end })

tests[#tests + 1] = ({ name = "Kit plates sit under their labels and text strokes use Border mode", fn = function()
	local f = io and io.open and io.open("src/Client/SidebarTheme.lua", "r")
	if not f then return end
	local src = f:read("*a"); f:close()
	expectTrue(src:find("bumpContent(inst, true)", 1, true) ~= nil, "kitPlate lifts content above the plate")
	expectTrue(src:find("bumpContent(inst, false)", 1, true) ~= nil, "removing the plate lowers content again")
	expectTrue(src:find("HudKitZBumped", 1, true) ~= nil, "the lift is recorded so repeats do not stack")
	local c = io.open("src/Client/ChoicePanel.lua", "r")
	local cs = c:read("*a"); c:close()
	local a = cs:find("local textStroke = Instance.new", 1, true)
	expectTrue(cs:sub(a, a + 300):find("ApplyStrokeMode.Border", 1, true) ~= nil, "Choice subtitle stroke is Border mode")
	local p = io.popen and io.popen("ls src/Client/*.lua 2>/dev/null")
	if not p then return end
	for path in p:lines() do
		local h = io.open(path, "r")
		local text = h:read("*a"); h:close()
		local pos = 1
		while true do
			local s, e, sv = text:find('local (%w+) = Instance%.new%("UIStroke"%)', pos)
			if not s then break end
			pos = e + 1
			local blk = text:sub(s, s + 600)
			local pv = blk:match(sv .. "%.Parent = (%w+)")
			if pv then
				local before = text:sub(math.max(1, s - 4000), s)
				local def
				for d in before:gmatch(pv .. " = ([^\n]*)") do def = d end
				if def and def:find('Instance.new("Text', 1, true) then
					local cut = blk:find(sv .. "%.Parent = " .. pv)
					expectTrue(blk:sub(1, cut):find("ApplyStrokeMode", 1, true) ~= nil, path .. ": stroke on text object " .. pv .. " needs Border mode")
				end
			end
		end
	end
	p:close()
end })

