table.insert(tests, { name = "TooltipSpec.correct absorbs an outside shift so the live rect lands on the target", fn = function()
	local TS = require(script.Parent.Parent.Engine.TooltipSpec)
	local ox, oy, changed = TS.correct({ X = 503, Y = 328 }, { X = 503, Y = 328 }, { X = 0, Y = 0 })
	expectFalse(changed, "no change when the live rect matches")
	-- the reported case: written 328, live 262 (66 px too high)
	ox, oy, changed = TS.correct({ X = 503, Y = 328 }, { X = 503, Y = 262 }, { X = 0, Y = 0 })
	expectTrue(changed, "a 66 px miss is corrected")
	expectEqual(oy, 66, "the offset pushes the frame 66 px down")
	expectEqual(ox, 0, "x untouched")
	-- applying it twice converges (a further identical miss would add, a landed rect stops)
	ox, oy, changed = TS.correct({ X = 503, Y = 328 }, { X = 503, Y = 328.5 }, { X = ox, Y = oy })
	expectFalse(changed, "within 1 px is left alone")
	local f = io and io.open and io.open("src/Client/Tooltip.lua", "r")
	if f then
		local src = f:read("*a"); f:close()
		expectTrue(src:find("TooltipSpec.correct", 1, true) ~= nil and src:find("frame.AbsolutePosition", 1, true) ~= nil, "Tooltip verifies the live AbsolutePosition after writing Position")
	end
end })

table.insert(tests, { name = "Sidebar seat rings keep 8 px clear of each other; My Patrons fits five seats in the free area", fn = function()
	local SeatFit = require(script.Parent.Parent.Engine.SeatFit)
	local CardShape = require(script.Parent.Parent.Engine.CardShape)
	local SSL = require(script.Parent.Parent.Engine.ShopSceneLayout)
	-- the open-seat pulse ring is the seat + 6 px (+2 px stroke): the gap between seats must leave 8 px beyond it
	local function read(path) local f = io and io.open and io.open(path, "r"); if not f then return nil end local t = f:read("*a"); f:close(); return t end
	local side = read("src/Client/Sidebar.lua")
	if side then
		local gap = tonumber(side:match("local SLOT, SLOT_GAP = %d+, (%d+)"))
		expectTrue(gap ~= nil and gap >= 14, "SLOT_GAP is at least 14 so pulse rings keep 8 px apart (got " .. tostring(gap) .. ")")
	end
	for _, n in ipairs({ 5, 6, 7 }) do
		local gap = n <= 5 and 14 or 3
		local size = SeatFit.size(n, 208, gap, 38, 26)
		expectTrue(SeatFit.rowWidth(n, size, gap) <= 208, n .. " seats still fit one row")
	end
	-- five owned seats fit the free zone right of Marlo with no sideways scroll
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 } }) do
		local zone = SSL.tabZone(sz[1] - 300, sz[2], false, nil)
		local s = CardShape.fitOwned(zone.w, 5, sz[1], sz[2])
		local shape = CardShape.shape("owned", s)
		expectTrue(CardShape.fitsRow(5, zone.w, shape, CardShape.OWNED_GAP, 14), "five seats fit " .. sz[1] .. "x" .. sz[2] .. " (zone " .. zone.w .. ", card " .. shape.w .. ")")
	end
	-- canvas never wider than the viewport: viewports measured in Studio (817 at 1506x751) and a 1067x600 one
	for _, v in ipairs({ { 817, 1506, 751 }, { 560, 1067, 600 }, { 1100, 1920, 1080 } }) do
		local s = CardShape.fitOwned(v[1], 5, v[2], v[3])
		local w = CardShape.shape("owned", s).w
		local canvas = 5 * w + 4 * CardShape.OWNED_GAP + 28
		expectTrue(canvas <= v[1], "five seats canvas " .. canvas .. " fits viewport " .. v[1] .. " at " .. v[2] .. "x" .. v[3])
		if v[1] >= 800 then expectTrue(w >= 140, "seat at least 140 px wide in " .. v[1] .. " (got " .. w .. ")") end
	end
end })

