table.insert(tests, { name = "TooltipSpec.placeRow: Counter tooltip intersects no other offer card or plate (4 offers, 1920x1080 and 1280x720)", fn = function()
	local TooltipSpec = require(script.Parent.Parent.Engine.TooltipSpec)
	local function hit(a, b) return a.X < b.X + b.W and b.X < a.X + a.W and a.Y < b.Y + b.H and b.Y < a.Y + a.H end
	for _, screen in ipairs({ { X = 1920, Y = 1080 }, { X = 1280, Y = 720 } }) do
		local cw, ch, gap = screen.X >= 1920 and 220 or 170, screen.X >= 1920 and 300 or 230, 16
		local total = 4 * cw + 3 * gap
		for _, rowTop in ipairs({ math.floor(screen.Y * 0.2), screen.Y - ch - 20 }) do -- room below, then no room below
			local row = { X = math.floor((screen.X - total) / 2), Y = rowTop, H = ch }
			for i = 0, 3 do
				local card = { X = row.X + i * (cw + gap), W = cw }
				local tip = { X = 294, Y = 80 }
				local x, y = TooltipSpec.placeRow(card, row, tip, screen)
				local tipRect = { X = x, Y = y, W = tip.X, H = tip.Y }
				expectTrue(x >= 0 and y >= 0 and x + tip.X <= screen.X and y + tip.Y <= screen.Y, "tooltip stays on screen")
				for j = 0, 3 do
					local other = { X = row.X + j * (cw + gap), Y = rowTop, W = cw, H = ch } -- card body, plate, tag and drawer all live inside
					expectFalse(hit(tipRect, other), "tooltip for card " .. i .. " covers card " .. j .. " at " .. screen.X)
				end
			end
		end
	end
end })

table.insert(tests, { name = "TooltipSpec.placeBeside: Counter pack tooltip sits beside the pack row and covers nothing (live numbers from Play: Standard Pack and Mega Menu Recipe Pack)", fn = function()
	local TooltipSpec = require(script.Parent.Parent.Engine.TooltipSpec)
	local CardShape = require(script.Parent.Parent.Engine.CardShape)
	local CounterScene = require(script.Parent.CounterScene)
	local function hit(a, b) return a.X < b.X + b.W and b.X < a.X + a.W and a.Y < b.Y + b.H and b.Y < a.Y + a.H end
	-- Read in Play on 8818aee (Studio coordinates). A card slot is the Body plus 16 px above and 4 below; the name plate
	-- (Banner) sits at the shape's bannerTop inside the Body, which starts 16 px under the slot top.
	local offers = { { X = 764, Y = 192, W = 226, H = 313 }, { X = 1006, Y = 192, W = 226, H = 313 } }
	local shape = CardShape.shape("patron", 226 / 220)
	local plates = {}
	for i, o in ipairs(offers) do
		plates[i] = { X = o.X + 2, Y = o.Y + 16 + shape.bannerTop, W = o.W - 4, H = CardShape.BANNER_H }
	end
	local packs = { { X = 894, Y = 501, W = 96, H = 148 }, { X = 1006, Y = 501, W = 96, H = 148 } }
	-- The controls come from the layout the Counter uses, in the frame Play had (1257 x 750 at 260,-58). The cards above are what Play
	-- reported on that commit; the Counter has since become a table scene (cards on an oval felt), so they are a fixed fixture of that
	-- report and no longer follow the layout. The sweep test below runs the real layout instead.
	local scene = CounterScene.build(1257, 750, 260, -58, 2, 2)
	local controls = scene.controls
	local blockers = {}
	for _, list in ipairs({ offers, plates, controls }) do
		for _, r in ipairs(list) do blockers[#blockers + 1] = r end
	end

	-- the reported hover: the tip must not land where the old code put it (884,453, over the Rowdy Bunch plate)
	local screen = { X = 1517, Y = 692 }
	for pi, tip in ipairs({ { X = 116.5, Y = 48 }, { X = 286, Y = 64 } }) do
		local card = packs[pi]
		local x, y, info = TooltipSpec.placeBeside(card, packs, blockers, tip, screen)
		local tr = { X = x, Y = y, W = tip.X, H = tip.Y }
		-- the short tip fits right of the row; the long one would reach the Reroll bell, so it opens on the left instead
		if pi == 1 then
			expectEqual(info.side, "right", "the short tip opens to the right of the pack row")
			expectEqual(x, 1102 + 12, "right: left edge 12 px right of the last pack")
		else
			expectEqual(info.side, "left", "the long tip would cover Reroll on the right, so it opens to the left")
			expectEqual(x + tip.X, 894 - 12, "left: right edge 12 px left of the first pack")
		end
		expectTrue(math.abs(y + tip.Y / 2 - (card.Y + card.H / 2)) < 0.5, "pack " .. pi .. " is centred on the hovered pack")
		expectEqual(info.area, 0, "pack " .. pi .. " covers nothing")
		expectFalse(info.slid, "pack " .. pi .. " needs no slide in the reported layout")
		expectFalse(hit(tr, plates[1]), "pack " .. pi .. " tip leaves the Rowdy Bunch plate alone")
		expectFalse(hit(tr, plates[2]), "pack " .. pi .. " tip leaves the second offer plate alone")
		for _, b in ipairs(blockers) do expectFalse(hit(tr, b), "pack " .. pi .. " tip covers an offer, plate or control") end
		for _, p in ipairs(packs) do expectFalse(hit(tr, p), "pack " .. pi .. " tip covers a pack") end
		expectTrue(x >= 0 and y >= 0 and x + tip.X <= screen.X and y + tip.Y <= screen.Y, "pack " .. pi .. " tip stays on screen")
	end

	-- no room on the right (narrow screen): the same placement on the left of the first pack
	local x, y, info = TooltipSpec.placeBeside(packs[1], packs, blockers, { X = 304, Y = 64 }, { X = 1250, Y = 1080 })
	expectEqual(info.side, "left", "no room on the right opens to the left")
	expectEqual(x, 894 - 12 - 304, "left: right edge 12 px left of the first pack")
	expectEqual(info.area, 0, "left placement covers nothing")

	-- something stands beside the row on both sides at the pack's height: the tip slides, never above or below the row
	local walled = { { X = 560, Y = 530, W = 330, H = 70 }, { X = 1104, Y = 530, W = 300, H = 70 } }
	local walls = {}
	for _, b in ipairs(blockers) do walls[#walls + 1] = b end
	for _, b in ipairs(walled) do walls[#walls + 1] = b end
	x, y, info = TooltipSpec.placeBeside(packs[1], packs, walls, { X = 116.5, Y = 48 }, screen)
	expectEqual(info.area, 0, "the slid tip covers nothing")
	expectTrue(info.slid, "the tip slid")
	expectEqual(x, 1114, "a slide keeps the 12 px gap to the row")
	expectTrue(math.abs(y - (packs[1].Y + packs[1].H / 2 - 24)) <= packs[1].H, "a slide moves at most one pack height")

	-- nothing clear anywhere: the less covered side wins, the result is still on screen
	local closed = { { X = 0, Y = 0, W = 1920, H = 1080 } }
	x, y, info = TooltipSpec.placeBeside(packs[1], packs, closed, { X = 116.5, Y = 48 }, screen)
	expectTrue(info.area > 0 and x >= 0 and y >= 0 and x + 116.5 <= screen.X and y + 48 <= screen.Y, "a closed counter still gives an on-screen spot")
end })

table.insert(tests, { name = "Counter pack tooltips from the real layout (ShopSceneLayout, CardShape): beside the row, clear of offers, plates, packs and controls (1 to 4 offers, 1 to 3 packs, four Counter frame sizes)", fn = function()
	local TooltipSpec = require(script.Parent.Parent.Engine.TooltipSpec)
	local CounterScene = require(script.Parent.CounterScene)
	local function hit(a, b) return a.X < b.X + b.W and b.X < a.X + a.W and a.Y < b.Y + b.H and b.Y < a.Y + a.H end
	local checked, rights, lefts = 0, 0, 0
	-- Counter frame size and position, and the screen it sits in: the Play window of 2026-11-10 first, then 3 common sizes
	local frames = {
		{ W = 1257, H = 750, ox = 260, oy = -58, screen = { X = 1517, Y = 692 } },
		{ W = 1660, H = 1080, ox = 260, oy = 0, screen = { X = 1920, Y = 1080 } },
		{ W = 1340, H = 900, ox = 260, oy = 0, screen = { X = 1600, Y = 900 } },
		{ W = 1020, H = 720, ox = 260, oy = 0, screen = { X = 1280, Y = 720 } },
	}
	for _, fr in ipairs(frames) do
		local screen = fr.screen
		for nO = 1, 4 do
			for nP = 1, 3 do
				local label = screen.X .. "x" .. screen.Y .. ", " .. nO .. " offers, " .. nP .. " packs"
				local scene = CounterScene.build(fr.W, fr.H, fr.ox, fr.oy, nO, nP)
				local packs, blockers = scene.packs, scene.blockers
				local x0 = packs[1].X
				local x1 = packs[#packs].X + packs[#packs].W
				for pi, card in ipairs(packs) do
					for _, tip in ipairs({ { X = 117, Y = 48 }, { X = 304, Y = 64 } }) do
						local x, y, info = TooltipSpec.placeBeside(card, packs, blockers, tip, screen)
						local tr = { X = x, Y = y, W = tip.X, H = tip.Y }
						local where = label .. ", pack " .. pi .. ", tip " .. tip.X .. "x" .. tip.Y
						expectEqual(info.area, 0, "covers something at " .. where)
						expectFalse(info.slid, "needed a slide at " .. where)
						for _, b in ipairs(blockers) do expectFalse(hit(tr, b), "covers an offer, plate or control at " .. where) end
						for _, p in ipairs(packs) do expectFalse(hit(tr, p), "covers a pack at " .. where) end
						expectTrue(x >= 0 and y >= 0 and x + tip.X <= screen.X and y + tip.Y <= screen.Y, "off screen at " .. where)
						if info.side == "right" then
							expectEqual(x, x1 + 12, "right: 12 px from the last pack at " .. where)
							rights = rights + 1
						else
							expectEqual(x + tip.X, x0 - 12, "left: 12 px from the first pack at " .. where)
							lefts = lefts + 1
						end
						expectTrue(y + tip.Y / 2 >= card.Y and y + tip.Y / 2 <= card.Y + card.H, "not beside the hovered pack at " .. where)
						checked = checked + 1
					end
				end
			end
		end
	end
	expectTrue(checked >= 100 and rights > 0 and lefts > 0, "the sweep covered every layout and both sides (" .. checked .. " tips, " .. rights .. " right, " .. lefts .. " left)")
end })

table.insert(tests, { name = "ShopTips.packPlacer: reads the live rows and controls (fake instances, live numbers) and opens the tip beside the pack row", fn = function()
	-- Local runner only: Studio cannot load a Client file from here, so the test skips there.
	local f = io and io.open and io.open("src/Client/ShopTips.lua", "r")
	if not f or not loadfile then return end
	f:close()
	local TooltipSpec = require(script.Parent.Parent.Engine.TooltipSpec)
	local rs = {}
	function rs:WaitForChild(name)
		if name == "TooltipSpec" then return { __module = TooltipSpec } end
		return rs
	end
	local env = setmetatable({ game = { GetService = function() return rs end }, require = function(m) return m.__module end }, { __index = _G })
	local chunk = loadfile("src/Client/ShopTips.lua", "t", env)
	expectTrue(chunk ~= nil, "ShopTips loads without Roblox constructors")
	local ShopTips = chunk()

	-- a duck-typed GuiObject: the placer only reads Name, Parent, Visible, AbsolutePosition, AbsoluteSize and the child list
	local function gui(parent, name, x, y, w, h)
		local g = { Name = name, Parent = parent, Visible = true, AbsolutePosition = { X = x, Y = y }, AbsoluteSize = { X = w, Y = h }, kids = {} }
		function g:GetChildren() local out = {} for i, k in ipairs(self.kids) do out[i] = k end return out end
		function g:IsA(c) return c == "GuiObject" or c == "Frame" end
		function g:FindFirstChild(n, deep)
			for _, k in ipairs(self.kids) do
				if k.Name == n then return k end
				local d = deep and k:FindFirstChild(n, true)
				if d then return d end
			end
		end
		if parent and parent.kids then table.insert(parent.kids, g) end
		return g
	end
	local root = { kids = {} }
	local offerRow = gui(root, "CardRow", 700, 180, 700, 340)
	for _, x in ipairs({ 764, 1006 }) do
		local slot = gui(offerRow, "Card_Offer", x, 192, 226, 313)
		local body = gui(slot, "Body", x, 208, 226, 293)
		gui(body, "Banner", x + 2, 452, 222, 40) -- the name plate the old tooltip covered
	end
	local packRow = gui(root, "CardRow", 700, 497, 700, 160)
	gui(packRow, "Card_Standard Pack", 894, 501, 96, 148)
	gui(packRow, "Card_Mega Menu Recipe Pack", 1006, 501, 96, 148)
	local haggle = gui(root, "HaggleButton", 285, 540, 72, 46)
	gui(haggle, "HaggleTag", 285, 590, 84, 24)
	local bell = gui(root, "RerollRow", 1500, 540, 60, 50)
	gui(bell, "BellTag", 1470, 594, 120, 24)
	local nextRound = gui(root, "NextRound", 1650, 955, 190, 44)
	local tabs = gui(root, "Tabs", 700, 8, 560, 34)
	local hidden = gui(root, "Hidden", 880, 540, 400, 200) -- invisible controls must not block anything
	hidden.Visible = false

	local placer = ShopTips.packPlacer({
		packRow = function() return packRow end,
		offerRow = function() return offerRow end,
		controls = function() return { tabs, nextRound, haggle, bell, hidden } end,
	})
	local function hit(a, b) return a.X < b.X + b.W and b.X < a.X + a.W and a.Y < b.Y + b.H and b.Y < a.Y + a.H end
	local screen = { X = 1920, Y = 1080 }
	-- hovering Standard Pack: the button is the Body, lifted 8 px by the hover
	local x, y, note = placer({ X = 894, Y = 509 }, { X = 96, Y = 128 }, { X = 116.5, Y = 48 }, screen)
	expectEqual(x, 1114, "the tip opens 12 px right of the last pack")
	expectTrue(math.abs(y - 551) < 0.5, "centred on the Standard Pack slot (the lifted button does not move it)")
	local tr = { X = x, Y = y, W = 116.5, H = 48 }
	for _, r in ipairs({ { 764, 192, 226, 313 }, { 1006, 192, 226, 313 }, { 766, 452, 222, 40 }, { 1008, 452, 222, 40 },
		{ 894, 501, 96, 148 }, { 1006, 501, 96, 148 }, { 285, 540, 72, 46 }, { 1500, 540, 60, 50 }, { 1650, 955, 190, 44 } }) do
		expectFalse(hit(tr, { X = r[1], Y = r[2], W = r[3], H = r[4] }), "the tip covers a live rect at " .. r[1] .. "," .. r[2])
	end
	expectEqual(type(note), "function", "the placer returns a lazy Studio note")
	local text = note()
	expectTrue(text:find("side=right", 1, true) ~= nil and text:find(ShopTips.VERSION, 1, true) ~= nil, "the note names the version and the side")
	expectTrue(text:find("offers=[764,192 226x313; 1006,192 226x313]", 1, true) ~= nil, "the note lists the offer rects it used")
	expectTrue(text:find("plates=[766,452 222x40; 1008,452 222x40]", 1, true) ~= nil, "the note lists the name plate rects it used")
	expectTrue(text:find("packs=[894,501 96x148; 1006,501 96x148]", 1, true) ~= nil, "the note lists the pack rects it used")

	-- a missing row or control list never throws and still gives a spot beside the hovered button
	local bare = ShopTips.packPlacer({})
	local bx, by = bare({ X = 894, Y = 509 }, { X = 96, Y = 128 }, { X = 116.5, Y = 48 }, screen)
	expectTrue(type(bx) == "number" and type(by) == "number", "a placer with no sources still places")
	expectEqual(bx, 894 + 96 + 12, "with no sources the tip sits 12 px right of the hovered button")

	-- ===== end to end: the real Client/Tooltip.lua on a tiny fake Roblox, hovered with the placer above =====
	local function signal()
		local s = { list = {} }
		function s:Connect(fn)
			local h = { fn = fn, on = true }
			s.list[#s.list + 1] = h
			return { Disconnect = function() h.on = false end }
		end
		function s:Fire(...) for _, h in ipairs(self.list) do if h.on then h.fn(...) end end end
		return s
	end
	local function vec(a, b) return { X = a, Y = b } end
	local studio, warns, prints, queued = true, {}, {}, {}
	local heartbeat = signal()
	local shift = vec(0, 0) -- pretend something outside moves the tooltip frame (the 66 px miss seen in Play)
	local instMT = { __index = function(self, k)
		local p = rawget(self, "Position")
		if k == "AbsolutePosition" and p then return vec(p.X.Offset + shift.X, p.Y.Offset + shift.Y) end
	end }
	local runService = { Heartbeat = heartbeat, IsStudio = function() return studio end }
	local tenv = setmetatable({
		game = { GetService = function(_, name)
			if name == "RunService" then return runService end
			return (name == "ReplicatedStorage") and rs or {}
		end },
		script = { Parent = { ModalStage = { __module = { blocks = function() return false end } } } },
		require = function(m) return m.__module end,
		Instance = { new = function(class) return setmetatable({ ClassName = class, Visible = true }, instMT) end },
		Vector2 = { new = vec, zero = vec(0, 0) },
		UDim = { new = function(s, o) return { Scale = s, Offset = o } end },
		UDim2 = { fromOffset = function(a, b) return { X = { Offset = a }, Y = { Offset = b } } end },
		Color3 = { fromRGB = function() return {} end },
		Enum = setmetatable({}, { __index = function(_, a) return setmetatable({}, { __index = function(_, b) return a .. "." .. b end }) end }),
		task = { defer = function(fn) queued[#queued + 1] = fn end, delay = function(_, fn) queued[#queued + 1] = fn end },
		warn = function(...) warns[#warns + 1] = table.concat({ ... }, " ") end,
		print = function(...) prints[#prints + 1] = table.concat({ ... }, " ") end,
	}, { __index = _G })
	local tchunk = loadfile("src/Client/Tooltip.lua", "t", tenv)
	expectTrue(tchunk ~= nil, "Tooltip.lua loads on the fake Roblox")
	local Tooltip = tchunk()
	local screenGui = { AbsoluteSize = vec(1517, 692), IsA = function(_, c) return c == "LayerCollector" end }
	local T = Tooltip.new(screenGui)
	expectTrue(#prints == 1 and prints[1]:find("v4", 1, true) ~= nil, "Studio prints the Tooltip version once, so a stale session is visible")
	T.frame.AbsoluteSize = vec(116.5, 48)
	local function flush() local q = queued; queued = {}; for _, fn in ipairs(q) do fn() end end
	local function newButton(a, b, w, h)
		local btn = { AbsolutePosition = vec(a, b), AbsoluteSize = vec(w, h), Parent = screenGui, Visible = true, MouseEnter = signal(), MouseLeave = signal() }
		function btn:FindFirstAncestor() return nil end
		function btn:IsA(c) return c == "GuiObject" or c == "TextButton" end
		return btn
	end

	local pack1 = newButton(894, 509, 96, 128) -- Standard Pack, lifted 8 px
	T.attach(pack1, "Standard Pack\nSee 3, keep 1", placer, nil)
	pack1.MouseEnter:Fire()
	expectTrue(T.frame.Visible, "hovering a pack shows the tooltip")
	expectEqual(T.frame.Position.X.Offset, 1114, "the tip is written 12 px right of the last pack")
	expectTrue(math.abs(T.frame.Position.Y.Offset - 551) < 0.5, "...centred on the pack, not above it")
	flush()
	heartbeat:Fire()
	expectTrue(warns[1] ~= nil and warns[1]:find("[Tooltip pack]", 1, true) == 1 and warns[1]:find("v4 side=right", 1, true) ~= nil, "Studio warns the version, side and rects used")
	expectTrue(warns[2] ~= nil and warns[2]:find("[Tooltip pack live] wanted 1114,551 live 1114,551", 1, true) == 1, "Studio warns the final live rect")
	for _, w in ipairs(warns) do expectTrue(w:find("place failed", 1, true) == nil, "no place failure: " .. w) end
	pack1.MouseLeave:Fire()
	expectFalse(T.frame.Visible, "leaving hides the tooltip")

	-- something outside shifts the frame by 66 px: the live rect is still driven onto the spot
	shift = vec(0, -66)
	warns = {}
	pack1.MouseEnter:Fire()
	flush()
	heartbeat:Fire()
	expectEqual(T.frame.AbsolutePosition.Y, 551, "an outside shift is absorbed so the live rect lands on the spot")
	expectEqual(T.frame.AbsolutePosition.X, 1114, "x stays on the spot")
	pack1.MouseLeave:Fire()
	shift = vec(0, 0)

	-- a placer that throws: the default spot above the button is used, Studio says so, nothing escapes
	warns = {}
	local pack2 = newButton(1006, 509, 96, 128)
	T.attach(pack2, "Mega Menu Recipe Pack\nSee 5, keep 2", function() error("boom") end, nil)
	pack2.MouseEnter:Fire()
	flush()
	expectTrue(T.frame.Visible, "a failing placer still shows the tooltip")
	expectTrue(math.abs(T.frame.Position.Y.Offset - (509 - 48 - 8)) < 0.5, "...at the default spot above the button")
	expectTrue(warns[1] ~= nil and warns[1]:find("placer failed", 1, true) ~= nil, "Studio says the placer failed")
	pack2.MouseLeave:Fire()

	-- the string aligns work as before
	local gear = newButton(1400, 300, 40, 40)
	T.attach(gear, "Settings", "left", nil)
	gear.MouseEnter:Fire()
	expectTrue(math.abs(T.frame.Position.X.Offset - (1400 + 40 - 116.5)) < 0.5 and math.abs(T.frame.Position.Y.Offset - (300 - 48 - 8)) < 0.5, "align left still lines the right edges up, above the button")
	gear.MouseLeave:Fire()

	-- with Studio off nothing is printed or warned
	studio, warns, prints = false, {}, {}
	pack1.MouseEnter:Fire()
	flush()
	expectEqual(#warns + #prints, 0, "outside Studio the tooltip is silent")
	pack1.MouseLeave:Fire()
end })

table.insert(tests, { name = "Counter pack tooltips are wired through a placer, not a name lookup (Shop, Tooltip, ShopStage, ShopTips sources)", fn = function()
	local function read(path) local f = io and io.open and io.open(path, "r"); if not f then return nil end local t = f:read("*a"); f:close(); return t end
	local shop = read("src/Client/Shop.lua")
	if shop then
		expectTrue(shop:find("ShopTips", 1, true) ~= nil and shop:find("tipAlign = packTip", 1, true) ~= nil, "Counter pack cards pass the ShopTips placer")
		expectTrue(shop:find('tipAlign = "side"', 1, true) == nil, "no string side alignment is left on the pack cards")
	end
	local tip = read("src/Client/Tooltip.lua")
	if tip then
		expectTrue(tip:find('type(align) == "function"', 1, true) ~= nil, "Tooltip accepts a placer function")
		expectTrue(tip:find('side == "side"', 1, true) == nil, "Tooltip no longer searches for a CardRow to place pack tips")
		expectTrue(tip:find("[Tooltip pack]", 1, true) ~= nil and tip:find("[Tooltip pack live]", 1, true) ~= nil, "Studio prints the rects used and the final live rect")
		expectTrue(tip:find("custom or side", 1, true) ~= nil, "a placer is re-measured every frame while shown")
	end
	local stage = read("src/Client/ShopStage.lua")
	if stage then expectTrue(stage:find("function self.keepOut", 1, true) ~= nil, "ShopStage lists the controls a tooltip must stay clear of") end
	local st = read("src/Client/ShopTips.lua")
	if st then
		expectTrue(st:find("FindFirstAncestor", 1, true) == nil, "ShopTips finds nothing by ancestor name")
		expectTrue(st:find("Instance.new", 1, true) == nil and st:find("Vector2", 1, true) == nil, "ShopTips builds no Roblox objects")
	end
end })

-- ===== Tavern Map layers (2026-11-10): paintings were invisible because their ZIndex was the tile number (1) =====
-- The GameUI ScreenGui draws with ZIndexBehavior.Global, so a ZIndex is absolute and a child never takes its parent's. These tests build
-- the REAL scenery, graph, discoveries and fog builders on a fake Roblox (Tests/FakeGui.lua, Tests/MapScene.lua) and apply that rule.
table.insert(tests, { name = "Tavern Map layers: built for real under ZIndexBehavior Global, every painting draws above ParchmentBase and the plate and below the roads", fn = function()
	-- Local runner only: the Client modules are built on a fake Roblox, which needs io and load.
	local probe = io and io.open and load and io.open("src/Client/JourneyMapScenery.lua", "r")
	if not probe then return end
	probe:close()
	local FakeGui = require(script.Parent.FakeGui)
	local MapScene = require(script.Parent.MapScene)

	-- control: the harness really applies the Global rule, so the original bug (a painting at its tile number, 1) is caught by it
	do
		local scene = MapScene.build({})
		local stray = scene.tiles[1][1]
		stray.ZIndex = 1
		local _, rank = FakeGui.drawOrder(scene.gui)
		expectTrue(rank[stray] < rank[scene.base] and rank[stray] < rank[scene.plate], "control: a painting at ZIndex 1 draws under ParchmentBase and the plate")
	end

	local cases = {
		{ name = "4072 x 734", canvasW = 4072, canvasH = 734 },
		{ name = "wide canvas, several tiles per region", canvasW = 9000, canvasH = 700 },
		{ name = "small canvas", canvasW = 900, canvasH = 300 },
		{ name = "only the road painting recorded, the rest fall back", regionArt = { "region_road" } },
		{ name = "doodles and painted fog", decor = true, fogImages = true },
		{ name = "no painting recorded", regionArt = {}, expectNone = true },
	}
	for _, case in ipairs(cases) do
		local where = " (" .. case.name .. ")"
		local scene = MapScene.build(case)
		local order, rank = FakeGui.drawOrder(scene.gui)
		expectTrue(scene.base and scene.graphRoot and scene.discRoot and scene.fogBand and scene.featherTop and scene.featherBottom,
			"the real builders made ParchmentBase, WorldGraph, Discoveries, FogBand and both feathers" .. where)
		local base, plate, graph = scene.base.ZIndex, scene.plate.ZIndex, scene.graphRoot.ZIndex
		expectEqual(base, 21, "ParchmentBase ZIndex" .. where)
		expectEqual(graph, 23, "WorldGraph ZIndex" .. where)
		expectTrue(rank[scene.base] > rank[scene.plate], "ParchmentBase draws above the map plate (" .. base .. " vs " .. plate .. ")" .. where)

		local all, tileCount = {}, 0
		for i = 1, 6 do
			expectEqual(scene.holders[i].ZIndex, base + 1, "Region" .. i .. " frame is one above ParchmentBase" .. where)
			for t, tile in ipairs(scene.tiles[i]) do
				tileCount = tileCount + 1
				all[#all + 1] = tile
				local label = "Region" .. i .. "." .. tile.Name
				expectEqual(tile.ClassName, "ImageLabel", label .. " is a painting" .. where)
				expectTrue(tile.ZIndex > base and tile.ZIndex < graph, label .. " ZIndex " .. tile.ZIndex .. " must be above ParchmentBase " .. base .. " and below WorldGraph " .. graph .. where)
				expectEqual(tile.ZIndex, base + 1, label .. " ZIndex" .. where)
				expectTrue(rank[tile] > rank[scene.plate] and rank[tile] > rank[scene.base], label .. " draws above the plate and ParchmentBase" .. where)
				if t > 1 then expectTrue(rank[tile] > rank[scene.tiles[i][t - 1]], label .. " cross-fades over the tile before it" .. where) end
				if i > 1 then
					for _, before in ipairs(scene.tiles[i - 1]) do
						expectTrue(rank[tile] > rank[before], label .. " fades in over Region" .. (i - 1) .. where)
					end
				end
			end
		end
		if case.expectNone then expectEqual(tileCount, 0, "no art means no paintings" .. where) else expectTrue(tileCount >= 6, "every region has a painting or its fallback" .. where) end
		if case.canvasW == 9000 then
			local tiled = 0
			for i = 1, 6 do if #scene.tiles[i] > 1 then tiled = tiled + 1 end end
			expectTrue(tiled >= 1, "the wide canvas exercises regions made of several tiles" .. where)
		end

		-- everything painted over the paintings: the roads (edge, fill, dots), the graph and discoveries, the feathers, the fog
		for _, tile in ipairs(all) do
			for _, name in ipairs({ "edge", "fill", "dot" }) do
				expectTrue(rank[scene.road[name]] > rank[tile], "the road " .. name .. " (ZIndex " .. scene.road[name].ZIndex .. ") draws over every painting" .. where)
			end
			for _, over in ipairs({ scene.graphRoot, scene.discRoot, scene.featherTop, scene.featherBottom, scene.fogBand }) do
				expectTrue(rank[over] > rank[tile], over.Name .. " draws over every painting" .. where)
			end
		end
		expectTrue(rank[scene.fogBand] > rank[scene.featherTop] and rank[scene.fogBand] > rank[scene.graphRoot], "the fog is over the feathers and the graph" .. where)
		for _, doodle in ipairs(scene.doodles) do
			expectTrue(doodle.ZIndex > scene.featherTop.ZIndex and doodle.ZIndex < scene.fogBand.ZIndex, doodle.Name .. " doodle is over the feathers and under the fog (" .. doodle.ZIndex .. ")" .. where)
		end
		if case.decor then expectTrue(#scene.doodles > 0, "the doodle path was exercised" .. where) end

		-- nothing in the map relies on the default ZIndex 1: every ImageLabel, and every GuiObject on the canvas, is at or above ParchmentBase
		for _, inst in ipairs(order) do
			if inst.ClassName == "ImageLabel" then
				expectTrue(inst.ZIndex >= base, "ImageLabel " .. inst.Name .. " has ZIndex " .. inst.ZIndex .. ", under ParchmentBase" .. where)
			end
		end
		for _, inst in ipairs(scene.canvas:GetDescendants()) do
			if FakeGui.GUI_CLASSES[inst.ClassName] then
				expectTrue(inst.ZIndex >= base, inst.ClassName .. " " .. inst.Name .. " has ZIndex " .. inst.ZIndex .. ", under ParchmentBase" .. where)
			end
		end
	end
end })

table.insert(tests, { name = "Tavern Map layers: Studio prints the ZIndex of every layer once, and says WRONG when a painting is under the base", fn = function()
	local probe = io and io.open and load and io.open("src/Client/JourneyMapScenery.lua", "r")
	if not probe then return end
	probe:close()
	local MapScene = require(script.Parent.MapScene)
	local scene = MapScene.build({ studio = true })
	scene.scenery.reportLayers()
	scene.scenery.reportLayers()
	expectEqual(#scene.state.warns, 1, "the layer report prints once per session")
	local line = scene.state.warns[1]
	for _, part in ipairs({ "[TavernMap z] v1", "ParchmentBase=21", "Region1.Tile1=22", "Region6.Tile1=22", "WorldGraph=23", "Discoveries=24", "FogBand=35", "FeatherTop=29", "layers=ok" }) do
		expectTrue(line:find(part, 1, true) ~= nil, "the report says " .. part .. ": " .. line)
	end
	-- a painting left under the base is reported
	local broken = MapScene.build({ studio = true })
	broken.tiles[3][1].ZIndex = 1
	broken.scenery.reportLayers()
	expectTrue(broken.state.warns[1]:find("layers=WRONG", 1, true) ~= nil and broken.state.warns[1]:find("Region3.Tile1=1", 1, true) ~= nil, "the report flags a painting under ParchmentBase: " .. tostring(broken.state.warns[1]))
	-- outside Studio nothing is printed
	local quiet = MapScene.build({ studio = false })
	quiet.scenery.reportLayers()
	expectEqual(#quiet.state.warns + #quiet.state.prints, 0, "outside Studio the report is silent")
	-- no paintings recorded: said plainly, not WRONG
	local bare = MapScene.build({ studio = true, regionArt = {} })
	bare.scenery.reportLayers()
	expectTrue(bare.state.warns[1]:find("layers=no paintings", 1, true) ~= nil, "no art is not an error: " .. tostring(bare.state.warns[1]))
	-- the View prints it when the map opens
	local f = io.open("src/Client/JourneyMapView.lua", "r")
	if f then
		local view = f:read("*a"); f:close()
		local layoutAt, reportAt = view:find("layout(true)\n\t\t\tscenery.reportLayers()", 1, true), view:find("scenery.reportLayers()", 1, true)
		expectTrue(layoutAt ~= nil and reportAt ~= nil, "the View reports the layers right after the first layout when the map opens")
	end
end })

table.insert(tests, { name = "CompassWheel: needle, hub, N, pips and rim icons follow the frame's ZIndex (absolute under Global), so they draw above the panel", fn = function()
	local probe = io and io.open and load and io.open("src/Client/CompassWheel.lua", "r")
	if not probe then return end
	probe:close()
	local FakeGui = require(script.Parent.FakeGui)
	local env, state = FakeGui.env({ stubs = { ClientSettings = { get = function() return false end }, Cue = { play = function() end } } })
	local folder = FakeGui.folder({ CompassLayout = require(script.Parent.Parent.Engine.CompassLayout) })
	state.services.ReplicatedStorage = { WaitForChild = function() return { WaitForChild = function() return folder end } end }
	local CompassWheel = FakeGui.load("src/Client/CompassWheel.lua", env)
	for _, zFrame in ipairs({ 22, 46 }) do -- RoadChoice sets 22, JourneyMapCompass 46
		local gui = FakeGui.new("ScreenGui")
		local panel = FakeGui.new("Frame")
		panel.ZIndex, panel.Parent = zFrame - 1, gui
		local wheel = CompassWheel.new({ parent = panel, size = 130, icons = { { bearing = 0, text = "A", id = "a" }, { bearing = 90, text = "B", id = "b" } }, onTurn = function() end })
		wheel.frame.ZIndex = zFrame -- callers move the frame after new()
		local pieces = wheel.frame:GetDescendants()
		expectTrue(#pieces >= 8, "the wheel has its ring, needle, hub, N, pips and two rim icons")
		for _, piece in ipairs(pieces) do
			if FakeGui.GUI_CLASSES[piece.ClassName] then
				expectTrue(piece.ZIndex > zFrame, piece.ClassName .. " " .. piece.Name .. " has ZIndex " .. piece.ZIndex .. ", not above the wheel's " .. zFrame)
			end
		end
		local _, rank = FakeGui.drawOrder(gui)
		for _, piece in ipairs(pieces) do
			if FakeGui.GUI_CLASSES[piece.ClassName] then
				expectTrue(rank[piece] > rank[wheel.frame] and rank[piece] > rank[panel], piece.Name .. " draws above the wheel disc and its panel")
			end
		end
		-- the needle sits under the hub, the rim icons over both
		local needle, hub = wheel.frame:FindFirstChild("Needle"), nil
		for _, kid in ipairs(wheel.frame:GetChildren()) do
			if kid.ClassName == "Frame" and kid.Name == "Frame" and kid.BackgroundColor3 and kid.Size.X.Offset > 0 and kid.Size.X.Scale == 0 then hub = kid end
		end
		expectTrue(needle ~= nil and hub ~= nil and hub.ZIndex > needle:GetChildren()[1].ZIndex, "the hub is over the needle")
		-- icons made after the frame moved use the new level too
		wheel.setIcons({ { bearing = 180, text = "C", id = "c" } })
		for _, kid in ipairs(wheel.frame:GetChildren()) do
			if kid.ClassName == "TextButton" then
				expectTrue(kid.ZIndex > wheel.frame.ZIndex, "a rim icon made after the move is above the wheel (" .. kid.ZIndex .. ")")
			end
		end
	end
end })

table.insert(tests, { name = "Tavern Map modules give every GuiObject an explicit ZIndex (absolute under Global, the default 1 draws under the whole map)", fn = function()
	if not (io and io.open) then return end
	local files = { "JourneyMapView", "JourneyMapGraph", "JourneyMapFog", "JourneyMapDiscoveries", "JourneyMapHero", "JourneyMapScenery", "JourneyMapCompass", "MapHover" }
	local classes = { Frame = true, ImageLabel = true, ImageButton = true, TextLabel = true, TextButton = true, ScrollingFrame = true, ViewportFrame = true, CanvasGroup = true }
	for _, name in ipairs(files) do
		local f = io and io.open and io.open("src/Client/" .. name .. ".lua", "r")
		if f then
			local lines = {}
			for line in f:lines() do lines[#lines + 1] = line end
			f:close()
			local made = 0
			for i, line in ipairs(lines) do
				local class = line:match('Instance%.new%("(%w+)"%)')
				if class and classes[class] then
					made = made + 1
					local var = line:match("^%s*local%s+([%w_]+)%s*=") or line:match("^%s*([%w_]+)%s*=")
					local found = false
					for k = i, math.min(i + 40, #lines) do
						local l = lines[k]
						if (var and l:find(var .. ".ZIndex", 1, true)) or (not var and l:find("ZIndex", 1, true)) then found = true break end
						if k > i and var and l:match("^%s*local%s+" .. var .. "%s*=") then break end -- the next object of that name
					end
					expectTrue(found, name .. ".lua:" .. i .. " creates a " .. class .. " with no ZIndex of its own (it would draw at 1, under the map): " .. line:gsub("^%s+", ""))
				end
			end
			expectTrue(made > 0, name .. ".lua creates GuiObjects (the scan found none, so the pattern is stale)")
		end
	end
	-- the scenery never passes a tile number as a ZIndex again
	local f = io.open("src/Client/JourneyMapScenery.lua", "r")
	if f then
		local src = f:read("*a"); f:close()
		local code = src:gsub("%-%-%[%[.-%]%]", ""):gsub("%-%-[^\n]*", "")
		expectTrue(code:find("canvasH, t, fadeL, fadeR", 1, true) == nil, "paintTile is not given the tile number as its ZIndex")
		expectTrue(code:find("canvasH, Z_PAINTING, fadeL, fadeR", 1, true) ~= nil, "paintTile is given Z_PAINTING")
	end
	-- the scenery is built before the road pieces and the graph, so at an equal ZIndex they draw over it
	local view = io.open("src/Client/JourneyMapView.lua", "r")
	if view then
		local src = view:read("*a"); view:close()
		local a, b, c = src:find("require(script.Parent.JourneyMapScenery)", 1, true), src:find("require(script.Parent.JourneyMapGraph)", 1, true), src:find("local function makeRoadPiece", 1, true)
		expectTrue(a and b and c and a < b and b < c, "the View builds the scenery first, then the graph, then the road pieces")
	end
end })

-- ===== Collection would not open (2026-11-10): makeTile called furnCols(), which was never defined =====
table.insert(tests, { name = "CollectionFurnitureLayout.colsIn: side padding comes off the width, a hidden scroll falls back, never below 1", fn = function()
	local F = require(script.Parent.Parent.Engine.CollectionFurnitureLayout)
	expectEqual(F.colsIn("cork", 1000, 0, nil), F.cols(1000, "cork"), "no padding is plain cols")
	expectEqual(F.colsIn("cork", 1000 + 2 * 16, 16, nil), F.cols(1000, "cork"), "16 px of padding on each side comes off first")
	expectEqual(F.colsIn("cork", 1000, 16, nil), F.cols(968, "cork"), "padding narrows the room")
	expectEqual(F.colsIn("cork", 0, 16, 1000 + 32), F.cols(1000, "cork"), "a scroll that is not laid out yet (width 0) uses the fallback width")
	expectEqual(F.colsIn("cork", nil, 16, 1000 + 32), F.cols(1000, "cork"), "...also when the width is nil")
	expectEqual(F.colsIn("cork", 0, 16, nil), 1, "nothing known at all is still one column")
	expectEqual(F.colsIn("plate", 10, 8, nil), 1, "a scroll narrower than a cell is one column")
	for kind in pairs(F.CELL) do
		expectTrue(F.colsIn(kind, 0, 8, 500) >= 1, kind .. " has a column while the scroll is hidden")
		local last = 0
		for width = 1, 2400, 37 do
			local cols = F.colsIn(kind, width, 8, 500)
			expectTrue(cols >= 1, kind .. " has at least one column at " .. width)
			expectTrue(cols >= last, kind .. " never loses columns as the scroll widens (" .. width .. ")")
			last = cols
		end
	end
end })

table.insert(tests, { name = "Collection.lua: furnCols and the furniture state are declared before makeTile, and the panel opens even when a tab fails to build", fn = function()
	local f = io and io.open and io.open("src/Client/Collection.lua", "r")
	if not f then return end
	local src = f:read("*a"); f:close()
	local code = src:gsub("%-%-%[%[.-%]%]", ""):gsub("%-%-[^\n]*", "") -- code only
	local state = code:find("local currentItems, furnRecords, currentKind", 1, true)
	local define = code:find("local function furnCols()", 1, true)
	local first = code:find("furnCols", 1, true)
	local makeTile = code:find("local function makeTile(", 1, true)
	expectTrue(state and define and makeTile, "the furniture state, furnCols and makeTile are all present")
	expectEqual(first, define + #"local function ", "the first mention of furnCols is its definition, not a call")
	expectTrue(state < makeTile and define < makeTile, "the state and furnCols are declared above makeTile")
	-- every tile goes through the pcall wrapper; refresh never calls makeTile bare
	expectTrue(code:find("pcall(makeTile", 1, true) ~= nil, "tiles are built through pcall")
	expectTrue(code:find("makeTile(items", 1, true) == nil, "no bare makeTile call in refresh")
	-- openCollection builds the tab through safeRefresh and ALWAYS reaches popIn afterwards
	local open = code:match("local function openCollection%(%).-\n\tend\n")
	expectTrue(open ~= nil, "openCollection found")
	local viaSafe, pop = open:find("safeRefresh(", 1, true), open:find("popIn(backdrop, panel)", 1, true)
	expectTrue(viaSafe ~= nil and pop ~= nil and viaSafe < pop, "openCollection refreshes through safeRefresh, then pops the panel in")
	expectTrue(open:find("%f[%w_]refresh%(") == nil, "openCollection does not call refresh bare")
	expectTrue(code:match("local function safeRefresh%(what%).-pcall%(refresh%)") ~= nil, "safeRefresh wraps refresh in pcall")
	-- the state refresh sets is local, never an accidental global
	expectTrue(code:find("currentItems, furnRecords, currentKind = items", 1, true) ~= nil, "refresh still sets the furniture state")
end })

table.insert(tests, { name = "Client modules use only declared locals and real globals (a nil global call like furnCols() fails here)", fn = function()
	-- Local runner only: asks the luac that ships with Lua which globals each file touches.
	if not (io and io.popen and os.tmpname) then return end
	local GlobalScan = require(script.Parent.GlobalScan)
	if not GlobalScan.available() then return end
	local files = GlobalScan.listLua("src/Client")
	if #files == 0 then return end
	local scanned, bad = 0, {}
	for _, path in ipairs(files) do
		local found = GlobalScan.scan(path) -- nil = uses Luau-only syntax plain Lua cannot compile (the file is skipped)
		if found then
			scanned = scanned + 1
			for _, hit in ipairs(found) do
				if not GlobalScan.KNOWN[hit.name] then
					bad[#bad + 1] = string.format("%s:%s %s %s", path:match("[^/]+$"), tostring(hit.line), hit.op == "SET" and "writes" or "reads", hit.name)
				end
			end
		end
	end
	expectTrue(scanned >= 100, "the scan compiled most of src/Client (" .. scanned .. " of " .. #files .. " files); the listing format may have changed")
	expectTrue(#bad == 0, #bad .. " undeclared global(s), each a nil call or an accidental global: " .. table.concat(bad, ", "))
	-- the files this guard exists for must have been compiled, not skipped
	for _, name in ipairs({ "Collection", "CollectionFurniture", "CollectionGallery", "CollectionWall", "JourneyMapScenery", "CompassWheel" }) do
		expectTrue(GlobalScan.scan("src/Client/" .. name .. ".lua") ~= nil, name .. ".lua is compiled by the global scan")
	end
	-- control: the scan really sees a global read and a global write
	local tmp = os.tmpname()
	local w = io.open(tmp, "w")
	if w then
		w:write("local function f()\n\tmissingFn()\n\taccidental = 1\nend\nreturn f\n")
		w:close()
		local seen = GlobalScan.scan(tmp)
		os.remove(tmp)
		local reads, writes = false, false
		for _, hit in ipairs(seen or {}) do
			if hit.name == "missingFn" and hit.op == "GET" then reads = true end
			if hit.name == "accidental" and hit.op == "SET" then writes = true end
		end
		expectTrue(reads and writes, "control: the scan reports an undefined call and an accidental global")
	end
end })

-- ===== Every screen can be exited (2026-11-10): Back, Escape and a click on the dark area =====
table.insert(tests, { name = "PopupDismissRules: exits per policy, the topmost popup, dim layers, which choices can be left", fn = function()
	local R = require(script.Parent.Parent.Engine.PopupDismissRules)
	-- a panel and a confirm dialog close on both exits; a confirm dialog's exits are Cancel, never a press
	for _, policy in ipairs({ "dismiss", "cancel" }) do
		expectEqual(R.action(policy, "escape"), "close", policy .. " closes on Escape")
		expectEqual(R.action(policy, "outside"), "close", policy .. " closes on a click on the dark area")
	end
	expectTrue(R.action("cancel", "escape") ~= "press" and R.action("cancel", "outside") ~= "press", "a confirm dialog never presses its Yes button")
	-- a result screen presses its one button on Escape and ignores the dark area; a locked screen opens Settings
	expectEqual(R.action("button", "escape"), "press")
	expectEqual(R.action("button", "outside"), "none")
	expectEqual(R.action("locked", "escape"), "pause")
	expectEqual(R.action("locked", "outside"), "none", "a mid-run choice cannot be left by clicking away")
	expectEqual(R.action("typo", "escape"), "none", "an unknown policy does nothing")
	expectEqual(R.action("dismiss", "typo"), "none", "an unknown trigger does nothing")
	for name in pairs(R.POLICIES) do expectTrue(R.isPolicy(name), name .. " is a policy") end
	expectFalse(R.isPolicy("typo") or R.isPolicy(nil), "typos are not policies")

	-- topmost: highest ZIndex, ties to the one opened last, hidden ones ignored
	local list = {
		{ id = "panel", z = 20, order = 1, visible = true },
		{ id = "confirm", z = 20, order = 3, visible = true },
		{ id = "older", z = 20, order = 2, visible = true },
		{ id = "hidden", z = 99, order = 9, visible = false },
	}
	expectEqual(R.topmost(list).id, "confirm", "of equal ZIndex the one opened last is on top; a hidden popup never is")
	list[#list + 1] = { id = "plate", z = 150, order = 1, visible = true }
	expectEqual(R.topmost(list).id, "plate", "a higher ZIndex beats a later opening")
	expectEqual(R.topmost({}), nil)
	expectEqual(R.topmost({ { id = "x", z = 1, order = 1, visible = false } }), nil, "nothing visible, nothing on top")

	-- dim layers: a scene or stage that covers the backdrop; never a shadow, a panel or a tab strip
	expectTrue(R.isDimLayer(1920, 1080, 1920, 1080), "a full-screen scene is dark area")
	expectTrue(R.isDimLayer(1700, 960, 1920, 1080), "88 percent in both axes still is")
	expectFalse(R.isDimLayer(614, 454, 1920, 1080), "a panel's shadow is not")
	expectFalse(R.isDimLayer(1920, 90, 1920, 1080), "a tab strip across the top is not")
	expectFalse(R.isDimLayer(1600, 1080, 1920, 1080), "83 percent wide is not")
	expectFalse(R.isDimLayer(0, 0, 0, 0) or R.isDimLayer(nil, nil, 1920, 1080), "no size, no dim layer")

	-- the start-of-run draft can be left, a between-Nights event card cannot
	for _, kind in ipairs({ "patron", "modifier", "rushPatron" }) do expectTrue(R.canAbandonChoice(kind), kind .. " can be left") end
	expectFalse(R.canAbandonChoice("event") or R.canAbandonChoice(nil) or R.canAbandonChoice("typo"), "an event card cannot")
	local ex = R.exits("dismiss", true)
	expectTrue(ex.button and ex.escape and ex.outside, "a panel has all three exits")
	ex = R.exits("locked", false)
	expectTrue(ex.escape and not ex.outside and not ex.button, "a locked screen has Escape only")
	for name in pairs(R.EXCEPTIONS) do expectEqual(name:sub(-8), "Backdrop", name .. " is a Backdrop name that is not a popup") end
end })

table.insert(tests, { name = "State resync: the client asks the server for the table (RequestState) until a state arrives, the server answers with pushState", fn = function()
	local function read(path)
		local f = io and io.open and io.open(path, "r")
		if not f then return nil end
		local src = f:read("*a")
		f:close()
		return src
	end
	local remotes, server, client = read("src/Server/Remotes.lua"), read("src/Server/init.server.lua"), read("src/Client/init.client.lua")
	if not (remotes and server and client) then return end
	expectTrue(remotes:find('newRemote("RequestState")', 1, true) ~= nil, "the RequestState remote exists")
	expectTrue(server:find("Rem.RequestState.OnServerEvent", 1, true) ~= nil, "the server answers RequestState")
	expectTrue(client:find('WaitForChild("RequestState")', 1, true) ~= nil and client:find("if latestState ~= nil then return end", 1, true) ~= nil,
		"the client requests the state until one has arrived")
end })

table.insert(tests, { name = "ChoicePanel on a fake Roblox: after a panel is opened and closed, Play (menu hidden) shows the pending Choice, in either order of state and Play", fn = function()
	local probe = io and io.open and load and io.open("src/Client/ChoicePanel.lua", "r")
	if not probe then return end
	probe:close()
	local FakeGui = require(script.Parent.FakeGui)
	local Engine = script.Parent.Parent.Engine
	local stubs = {
		PatronPlaque = {}, ClientSettings = { get = function() return "fast" end },
		ModalStage = { mount = function() return nil end, setKind = function() end },
		SmoothVignette = { add = function() end, edge = function() end }, SoftGlow = { add = function() end, new = function() end },
		PopupDismiss = { attach = function() end },
	}
	local env, st = FakeGui.env({ studio = true, stubs = stubs })
	setmetatable(stubs.SmoothVignette, { __index = function() return function() end end })
	setmetatable(stubs.SoftGlow, { __index = function() return function() end end })
	st.services.ReplicatedStorage = { WaitForChild = function()
		return { WaitForChild = function()
			return FakeGui.folder({
				ContentArt = { getImageId = function() return "" end }, ChoiceSceneLayout = require(Engine.ChoiceSceneLayout),
				MenuSceneArt = require(Engine.MenuSceneArt), PopupDismissRules = require(Engine.PopupDismissRules), ChoiceRarity = require(Engine.ChoiceRarity),
				ResponsiveLayout = require(Engine.ResponsiveLayout),
			})
		end }
	end }
	local ChoicePanel = FakeGui.load("src/Client/ChoicePanel.lua", env)
	local gui, menu, root = FakeGui.new("ScreenGui"), FakeGui.new("Frame"), FakeGui.new("Frame")
	menu.Visible, root.Visible = true, false
	gui.AbsoluteSize = { X = 1920, Y = 1080 }
	local ok, err = pcall(ChoicePanel.init, { screenGui = gui, menuFrame = menu, root = root, polishButton = function() end,
		roundCorner = function() end, playClickSfx = function() end, choiceRemote = {} })
	if not ok then error("ChoicePanel.init on the fake Roblox: " .. tostring(err), 0) end
	local backdrop = gui:FindFirstChild("ChoiceBackdrop")
	expectTrue(backdrop ~= nil, "the Choice backdrop is built")
	local choice = { kind = "patron", title = "Pick a Patron", text = "", options = {} }

	-- 1. the state arrives while the Menu is up (panels opened and closed before Play): nothing shows over the Menu
	ChoicePanel.update({ choice = choice })
	expectTrue(not backdrop.Visible, "the Choice stays hidden behind the Menu")
	-- 2. Play: the Menu hides, the table shows; the Choice must appear
	menu.Visible, root.Visible = false, true
	ChoicePanel.refresh()
	expectTrue(backdrop.Visible, "Play shows the pending Choice screen")
	-- 3. back to the Menu and Play again: it comes back
	menu.Visible, root.Visible = true, false
	ChoicePanel.refresh()
	expectTrue(not backdrop.Visible, "the Menu hides the Choice again")
	menu.Visible, root.Visible = false, true
	ChoicePanel.refresh()
	expectTrue(backdrop.Visible, "Play brings the same Choice back")
end })

table.insert(tests, { name = "PopupDismiss on a fake Roblox: Escape reaches the topmost popup only, outside clicks, button and locked policies, Settings lifted over a locked screen", fn = function()
	local probe = io and io.open and load and io.open("src/Client/PopupDismiss.lua", "r")
	if not probe then return end
	probe:close()
	local FakeGui = require(script.Parent.FakeGui)
	local Engine = script.Parent.Parent.Engine
	local stubs = {}
	local env, st = FakeGui.env({ studio = true, stubs = stubs })
	st.services.ReplicatedStorage = { WaitForChild = function()
		return { WaitForChild = function()
			return FakeGui.folder({ PopupDismissRules = require(Engine.PopupDismissRules), PopupRules = require(Engine.PopupRules) })
		end }
	end }
	stubs.OverlayManager = FakeGui.load("src/Client/OverlayManager.lua", env)
	local OverlayManager = stubs.OverlayManager
	local PopupDismiss = FakeGui.load("src/Client/PopupDismiss.lua", env)
	local gui = FakeGui.new("ScreenGui")
	local log = {}
	local function press(input) st.services.UserInputService.InputBegan:Fire(input) end
	local function escape() press({ KeyCode = env.Enum.KeyCode.Escape, UserInputType = env.Enum.UserInputType.Keyboard }) end
	local function click(obj, kind) obj.InputBegan:Fire({ UserInputType = env.Enum.UserInputType[kind or "MouseButton1"] }) end

	-- a popup: backdrop, panel, a panel shadow and a full-screen scene (the dark area), like the real ones
	local function popup(name, z, spec)
		local b = FakeGui.new("Frame")
		b.Name, b.ZIndex, b.Visible, b.Parent = name, z, false, gui
		b.AbsoluteSize = { X = 1920, Y = 1080 }
		local panel = FakeGui.new("Frame")
		panel.Name, panel.ZIndex, panel.Parent, panel.AbsoluteSize = "Panel", z + 1, b, { X = 600, Y = 440 }
		local shadow = FakeGui.new("Frame")
		shadow.Name, shadow.Parent, shadow.AbsoluteSize = "Shadow", b, { X = 614, Y = 454 }
		local scene = FakeGui.new("Frame")
		scene.Name, scene.Parent, scene.AbsoluteSize = "Scene", b, { X = 1920, Y = 1080 }
		spec = spec or {}
		spec.panel = spec.panel == nil and panel or spec.panel
		spec.close = spec.close or function() log[#log + 1] = name; b.Visible = false end
		spec.button = true
		PopupDismiss.attach(b, spec)
		return b, panel, shadow, scene
	end

	-- 1. Escape reaches the topmost visible popup only: of equal ZIndex the one opened last, a higher ZIndex first
	local a = popup("ABackdrop", 20)
	local b = popup("BBackdrop", 20, { policy = "cancel" })
	a.Visible = true
	b.Visible = true
	escape()
	expectEqual(table.concat(log, ","), "BBackdrop", "Escape closes the popup opened last, not the one under it")
	escape()
	expectEqual(table.concat(log, ","), "BBackdrop,ABackdrop", "the next Escape closes the one under it")
	escape()
	expectEqual(#log, 2, "with nothing open Escape does nothing")
	expectEqual(#st.services.UserInputService.InputBegan.handlers, 1, "one Escape listener serves every popup")
	log = {}
	local high = popup("HighBackdrop", 40)
	high.Visible = true
	a.Visible = true -- opened later but lower
	escape()
	expectEqual(table.concat(log, ","), "HighBackdrop", "a higher ZIndex wins over a later opening")
	a.Visible = false

	-- 2. a click on the dark area: the backdrop, a scene that covers it and touch close; the panel, its shadow and other input do not
	log = {}
	local d, dPanel, dShadow, dScene = popup("DBackdrop", 20)
	d.Visible = true
	click(dPanel)
	click(dShadow)
	click(d, "MouseMovement")
	expectEqual(#log, 0, "a click on the panel, its shadow or a mouse move is not a click outside")
	click(dScene)
	expectEqual(table.concat(log, ","), "DBackdrop", "a click on the scene that covers the backdrop closes it")
	log = {}
	d.Visible = true
	click(d, "Touch")
	expectEqual(table.concat(log, ","), "DBackdrop", "a touch on the dark area closes it")
	-- only the topmost popup reacts, and a popup that left its outside click to its module does not
	log = {}
	d.Visible = true
	local top = popup("TopBackdrop", 20, { policy = "cancel" })
	top.Visible = true
	click(d)
	expectEqual(#log, 0, "a click that reaches a popup under the topmost one is ignored")
	top.Visible = false
	d.Visible = false
	local own = popup("OwnBackdrop", 20, { outside = false })
	own.Visible = true
	click(own)
	expectEqual(#log, 0, "outside = false leaves the click to the module")
	escape()
	expectEqual(table.concat(log, ","), "OwnBackdrop", "...but Escape is still shared")
	local bare = popup("BareBackdrop", 20, { panel = false })
	log = {}
	bare.Visible = true
	click(bare)
	expectEqual(#log, 0, "without a declared panel the outside click stays off")
	bare.Visible = false

	-- 3. a result screen: Escape presses its one button, the dark area does nothing
	log = {}
	local result = popup("ResultBackdrop", 60, { policy = "button", press = function() log[#log + 1] = "press" end })
	result.Visible = true
	click(result)
	expectEqual(#log, 0, "the dark area does nothing on a result screen")
	escape()
	expectEqual(table.concat(log, ","), "press", "Escape presses the result screen's button")
	result.Visible = false

	-- 4. a locked mid-run screen: Escape opens Settings ABOVE it (ZIndex is absolute under Global), Escape again closes Settings
	log = {}
	local settings, sPanel = popup("SettingsBackdrop", 20, { id = "settings" })
	local sLabel = FakeGui.new("TextLabel")
	sLabel.ZIndex, sLabel.Parent = 22, sPanel
	OverlayManager.register("settings", function() settings.Visible = false end)
	OverlayManager.registerOpener("settings", function() settings.Visible = true end)
	local locked = popup("LockedBackdrop", 60, { policy = "locked" })
	locked.Visible = true
	click(locked)
	expectFalse(settings.Visible, "a click on a locked screen does nothing")
	escape()
	expectTrue(settings.Visible, "Escape on a locked screen opens Settings")
	expectTrue(settings.ZIndex > 60 and sPanel.ZIndex > 60 and sLabel.ZIndex > 60, "...above it: backdrop " .. settings.ZIndex .. ", panel " .. sPanel.ZIndex .. ", label " .. sLabel.ZIndex)
	expectTrue(locked.Visible, "the locked screen is still there")
	escape()
	expectFalse(settings.Visible, "Escape again closes Settings, the topmost popup")
	expectEqual(settings.ZIndex, 20, "Settings drops back to its own level")
	expectEqual(sPanel.ZIndex, 21)
	expectEqual(sLabel.ZIndex, 22)
	escape()
	expectTrue(settings.Visible and settings.ZIndex > 60, "the locked screen opens it again")
	settings.Visible = false
	locked.Visible = false

	-- 5. failures never reach the player: a close that errors is warned, the other popups still work; a destroyed popup is forgotten
	local broken = popup("BrokenBackdrop", 20, { close = function() error("boom") end })
	broken.Visible = true
	escape()
	expectTrue(st.warns[#st.warns] and st.warns[#st.warns]:find("could not close: ", 1, true) ~= nil, "a failing close is warned: " .. tostring(st.warns[#st.warns]))
	broken.Destroying:Fire()
	broken.Visible = true
	local before = #st.warns
	escape()
	expectEqual(#st.warns, before, "a destroyed popup is out of the registry")
	broken.Visible = false
	expectTrue(PopupDismiss.attach(nil, {}) == nil, "attach(nil) is refused, not thrown")

	-- 6. the Studio report lists every popup root with its exits, and flags the ones that have none
	local orphan = FakeGui.new("Frame")
	orphan.Name, orphan.Parent = "OrphanBackdrop", gui
	local shopScene = FakeGui.new("Frame")
	shopScene.Name, shopScene.Parent = "ShopBackdrop", gui
	st.warns = {}
	PopupDismiss.report(gui, gui)
	local report = st.warns[1] or ""
	expectTrue(report:find("[PopupDismiss] v1", 1, true) ~= nil, "the report names its version")
	expectTrue(report:find("SettingsBackdrop", 1, true) ~= nil and report:find("dismiss  ", 1, true) ~= nil and report:find("button=true escape=true outside=true", 1, true) ~= nil, "a panel shows all three exits: " .. report)
	expectTrue(report:find("ResultBackdrop%s+button%s+button=true escape=true outside=false") ~= nil, "a result screen: Escape, no outside click")
	expectTrue(report:find("LockedBackdrop%s+locked%s+button=true escape=true outside=false") ~= nil, "a locked screen: Escape only")
	expectTrue(report:find("OwnBackdrop%s+dismiss%s+button=true escape=true outside=module") ~= nil, "a module that keeps its own click says so")
	expectTrue(report:find("OrphanBackdrop%s+NO EXIT") ~= nil, "a popup root without an exit is flagged")
	expectTrue(report:find("ShopBackdrop%s+EXCEPTION") ~= nil, "an explicit exception is listed as one")
	-- install is quiet outside Studio and never throws inside it
	PopupDismiss.install(gui, gui)
	expectEqual(#st.prints, 0)
end })

table.insert(tests, { name = "Every ...Backdrop the client builds is registered with PopupDismiss or an explicit exception, and Escape is handled in one place", fn = function()
	if not (io and io.open and io.popen) then return end
	local GlobalScan = require(script.Parent.GlobalScan)
	local files = GlobalScan.listLua("src/Client")
	if #files == 0 then return end
	local R = require(script.Parent.Parent.Engine.PopupDismissRules)
	local function read(path)
		local f = io.open(path, "r")
		if not f then return nil end
		local s = f:read("*a"); f:close()
		return s
	end
	local found, unregistered, escapes = 0, {}, {}
	for _, path in ipairs(files) do
		local src = read(path)
		local name = path:match("[^/]+$")
		if src then
			local code = src:gsub("%-%-%[%[.-%]%]", ""):gsub("%-%-[^\n]*", "")
			for backdropName in code:gmatch('%.Name%s*=%s*"([%w]+Backdrop)"') do
				found = found + 1
				-- registered in this file: directly, or through PanelTabs.attach(backdrop, id, click, panel), which registers the panel
				local direct = code:find("PopupDismiss", 1, true) ~= nil
				local viaTabs = code:find("PanelTabs).attach(", 1, true) ~= nil and code:find(", panel)", 1, true) ~= nil
				if not (direct or viaTabs or R.EXCEPTIONS[backdropName]) then unregistered[#unregistered + 1] = name .. ":" .. backdropName end
			end
			if code:find("KeyCode.Escape", 1, true) and name ~= "PopupDismiss.lua" and name ~= "MenuHotspots.lua" then escapes[#escapes + 1] = name end
		end
	end
	expectTrue(found >= 28, "the scan found the popup roots (" .. found .. "); the naming pattern may have changed")
	expectTrue(#unregistered == 0, "popup roots with no exit: register them with PopupDismiss.attach or add an explicit exception: " .. table.concat(unregistered, ", "))
	expectTrue(#escapes == 0, "Escape is handled by PopupDismiss (and the Menu's own scrolls), not again in: " .. table.concat(escapes, ", "))

	-- the policies that matter
	local function has(file, text) local s = read("src/Client/" .. file); return s ~= nil and s:find(text, 1, true) ~= nil end
	expectTrue(has("ConfirmDialog.lua", 'policy = "cancel"') and has("RestartRun.lua", 'policy = "cancel"'), "confirm dialogs: Escape and a click outside mean Cancel")
	expectTrue(has("NightVictory.lua", 'policy = "button"') and has("OverlayQueue.lua", 'policy = "button"'), "result plates: Escape presses their one button")
	-- run summary and Run Setup polish: road names, buttons clear of the Patrons box, no emoji in Run Setup headers
	expectTrue(has("GameOver.lua", "stop.name or stop.id") and not has("GameOver.lua", "stop.icon"), "Run Over lists road names, not icon codes")
	expectTrue(has("GameOver.lua", "RunOverLayout.computeTouch(sw, sh") and has("GameOver.lua", "RunOverPanel"), "Run Over is laid out by the RunOverLayout module in one RunOverPanel")
	expectTrue(has("GameOver.lua", "b.TextStrokeTransparency = 1"), "Run Over buttons have no heavy text stroke")
	expectTrue(has("GameOver.lua", "ring.ApplyStrokeMode = Enum.ApplyStrokeMode.Border"), "Run Over strokes use Border mode, so text is not doubled")
	expectTrue(has("NightVictory.lua", '"StoreBackdrop"') and has("GameOver.lua", '"StoreBackdrop"'), "result screens hide StoreBackdrop and its tab strip")
	expectTrue(has("NightVictory.lua", "Rules.KIT_PLATE") and has("NightVictory.lua", "ImageLabel") and not has("NightVictory.lua", "👑") and not has("NightVictory.lua", "♾") and has("NightVictory.lua", 'Text = "-"'), "Night victory uses the Round Complete kit plate, no emoji, stat values start as a dash")
	expectTrue(has("NightVictory.lua", "HudKit.piece(setId, Rules.KIT_PLATE)") and has("OverlayQueue.lua", "HudKit.piece(setId, Rules.KIT_PLATE)"), "Night victory and Round Complete resolve the same kit plate id")
	expectTrue(has("NightVictory.lua", 'GetPropertyChangedSignal("Visible")') and not has("NightVictory.lua", "polishButton(button"), "Night victory paints its plate whenever it becomes visible, and its button has no chrome underline")
	expectTrue(has("NightVictory.lua", "PARCH.y, PARCH.inset") and has("NightVictory.lua", 'FindFirstChild("Shadow")') and has("NightVictory.lua", "PLATE_W, PLATE_H = 560, 520"), "Night victory content sits inside the plate's parchment and its shadow box is hidden while painted")
	expectTrue(has("GameOver.lua", "Text = patron.name or patron.id"), "Run Over names each patron under its medallion")
	expectFalse(has("GameOver.lua", "Continue\""), "Run Over has no Continue button (there is no second screen to continue to)")
	local setupSrc = read("src/Client/RunSetup.lua") or ""
	expectTrue(not setupSrc:find("\240\159", 1, true) and not setupSrc:find("\226\154", 1, true) and not setupSrc:find("\226\156", 1, true), "Run Setup has no emoji in headers or labels")
	expectTrue(has("RoadChoice.lua", 'policy = "locked"') and has("RoundSelect.lua", 'policy = "locked"'), "mid-run choices are locked: Escape opens Settings")
	expectTrue(has("Settings.lua", 'registerOpener("settings"'), "Settings can be opened by id, which a locked screen's Escape needs")
	expectTrue(has("PanelTabs.lua", "function PanelTabs.attach(backdrop, id, playClick, panel)") and has("PanelTabs.lua", "PopupDismiss"), "PanelTabs registers the account panels")
	for _, file in ipairs({ "Collection", "CosmeticSetsPanel", "BadgesPanel", "CollectionRewardsPanel", "FlairPanel", "LegendPanel", "StatsPanel", "SeasonPanel", "StorePanel", "QuestsPanel", "DailyRewardsPanel" }) do
		local src = read("src/Client/" .. file .. ".lua")
		expectTrue(src ~= nil and src:find("PanelTabs).attach(backdrop, ", 1, true) ~= nil and src:find(", panel)", 1, true) ~= nil, file .. " passes its panel to PanelTabs.attach")
	end

	-- the first Patron and blessing choice: a Back plate button, 44 px high, that never talks to the server
	local choice = read("src/Client/ChoicePanel.lua")
	expectTrue(choice ~= nil, "ChoicePanel.lua readable")
	expectTrue(choice:find('Text = "Back to menu"', 1, true) ~= nil and choice:find("UDim2.fromOffset(150, 44)", 1, true) ~= nil, "a 44 px Back to menu button")
	expectTrue(choice:find("canAbandonChoice", 1, true) ~= nil and choice:find('"dismiss" or "locked"', 1, true) ~= nil, "the draft can be left, an event card is locked")
	local back = choice:match("local function backToMenu%(%).-\n\tend\n")
	expectTrue(back ~= nil and back:find("FireServer", 1, true) == nil and back:find("menuFrame.Visible = true", 1, true) ~= nil, "Back to menu only shows the Menu: nothing is sent to the server, so no run is abandoned")
	expectTrue(choice:find("panel = holder", 1, true) ~= nil, "the cards' holder is the panel: a click on a card is never outside")
end })

-- ===== Haggle and Reroll did nothing on the Counter (2026-11-10): the gold pill was a label, never a button =====
table.insert(tests, { name = "ShopRefusal: every way the Counter says no has one line of text, and the Reroll and Haggle words", fn = function()
	local R = require(script.Parent.Parent.Engine.ShopRefusal)
	local Haggle = require(script.Parent.Parent.Engine.Haggle)
	-- Reroll: allowed, or the first reason in the order the server checks (phase, pack, tips)
	expectEqual(R.reroll(true, nil, 14, 3), nil, "14 tips buys a 3 tip reroll")
	expectEqual(R.reroll(true, nil, 3, 3), nil, "exactly enough is enough")
	expectEqual(R.reroll(true, nil, 2, 3), R.REASONS.tips)
	expectEqual(R.reroll(true, {}, 14, 3), R.REASONS.pack_open, "a pack that is open comes first")
	expectEqual(R.reroll(false, {}, 0, 3), R.REASONS.wrong_phase, "outside the shop comes before everything")
	-- Haggle: every code Haggle.canStart can return has its own sentence
	for _, code in ipairs({ "wrong_phase", "ranked", "tutorial", "pack_open", "used", "bad_item" }) do
		expectTrue(type(R.haggle(code)) == "string" and #R.haggle(code) > 10, code .. " has a sentence")
	end
	expectTrue(R.haggle("surprise") ~= "" and R.haggle(nil) ~= "", "an unknown code still says something")
	local seen = {}
	for _, text in pairs(R.REASONS) do
		expectFalse(seen[text], "no two reasons share a sentence: " .. text)
		seen[text] = true
		expectTrue(not text:find("\226\128\148", 1, true), "no em dash: " .. text)
	end
	-- the words on the controls
	expectEqual(R.rerollLabel(3), "Reroll 3")
	expectEqual(R.rerollLabel(0), "Reroll 0")
	expectEqual(R.rerollLabel(nil), "Reroll 0")
	expectEqual(R.haggleLabel({ used = false }), "Haggle")
	expectEqual(R.haggleLabel({ used = true }), "Haggled")
	expectEqual(R.haggleLabel(nil), "Haggle")
	-- a click on Haggle: opens the chooser, or says why not
	expectEqual(R.haggleDenied({ available = true }), nil)
	expectEqual(R.haggleDenied({ available = false, open = { kind = "patron", id = "x" } }), nil, "with the bar already up there is nothing to refuse")
	expectEqual(R.haggleDenied({ available = false, used = true, reason = "used" }), R.REASONS.used)
	expectEqual(R.haggleDenied({ available = false, reason = "pack_open" }), R.REASONS.pack_open)
	expectEqual(R.haggleDenied(nil), R.REASONS.wrong_phase)
	-- the real engine view carries the reason, so the client never has to guess
	local state = { haggle = { used = true } }
	local view = Haggle.view(state, {}, "shop")
	expectTrue(view.available == false and view.reason == "used" and view.used == true, "a used haggle says why")
	expectEqual(R.haggleLabel(view), "Haggled")
	view = Haggle.view({}, { ranked = true }, "shop")
	expectTrue(not view.available and view.reason == "ranked" and R.hiddenCodes[view.reason], "a ranked board has no Haggle at all")
	view = Haggle.view({ pendingPack = {} }, {}, "shop")
	expectTrue(not view.available and view.reason == "pack_open" and not R.hiddenCodes[view.reason], "a pack that is open only dims it")
	expectTrue(Haggle.view({}, {}, "shop").available and Haggle.view({}, {}, "shop").reason == nil, "an available haggle has no reason")
end })

table.insert(tests, { name = "The Counter's Reroll and Haggle on the real stage: a click on the visible gold pill reaches the control (layer order, four sizes)", fn = function()
	local probe = io and io.open and load and io.open("src/Client/ShopStage.lua", "r")
	if not probe then return end
	probe:close()
	local FakeGui = require(script.Parent.FakeGui)
	local Engine = script.Parent.Parent.Engine
	local sizes = { { 1257, 750, "your Play window" }, { 1920, 1080, "1920x1080" }, { 1280, 720, "1280x720" }, { 800, 450, "800x450" } }
	for _, size in ipairs(sizes) do
		local W, H, where = size[1], size[2], " at " .. size[3]
		local stubs = {}
		local env, st = FakeGui.env({ stubs = stubs })
		st.services.ReplicatedStorage = FakeGui.new("Folder")
		local Remotes = FakeGui.new("Folder")
		Remotes.Name, Remotes.Parent = "Remotes", st.services.ReplicatedStorage
		st.services.ReplicatedStorage = setmetatable({
			WaitForChild = function()
				return { WaitForChild = function()
					return FakeGui.folder({ ShopSceneLayout = require(Engine.ShopSceneLayout), ShopRefusal = require(Engine.ShopRefusal), GlowCurve = require(Engine.GlowCurve),
						ScrollOfferLayout = require(Engine.ScrollOfferLayout), ImageSpace = require(Engine.ImageSpace), ContentArt = require(Engine.ContentArt) })
				end }
			end,
			FindFirstChild = function(_, name) return name == "Remotes" and Remotes or nil end,
		}, {})
		local calmOn = false
		stubs.ClientSettings = { get = function(key) if key == "reduceShake" then return calmOn end return false end }
		stubs.ShopTrace = FakeGui.load("src/Client/ShopTrace.lua", env)
		stubs.SoftGlow = FakeGui.load("src/Client/SoftGlow.lua", env)
		stubs.ShopPaint = { plate = function() end, hover = function() end, tabs = function() end } -- painted frames are not under test here
		local ShopStage = FakeGui.load("src/Client/ShopStage.lua", env)
		local ShopHaggle = FakeGui.load("src/Client/ShopHaggle.lua", env)
		local UDim2 = env.UDim2

		-- the Shop frame with what Shop.lua puts in it: the Buy list, the tab bar, Next Round, and the Haggle button from ShopHaggle
		local gui = FakeGui.new("ScreenGui")
		local shopFrame = FakeGui.new("Frame")
		shopFrame.Name, shopFrame.ZIndex, shopFrame.Size, shopFrame.Parent = "Shop", 6, UDim2.fromOffset(W, H), gui
		local buyList = FakeGui.new("ScrollingFrame")
		buyList.ZIndex, buyList.Parent = 6, shopFrame
		local tabBar = FakeGui.new("Frame")
		tabBar.ZIndex, tabBar.Parent = 6, shopFrame
		for i = 1, 3 do
			local t = FakeGui.new("TextButton")
			t.ZIndex, t.Parent = 6, tabBar
		end
		local nextRound = FakeGui.new("TextButton")
		nextRound.ZIndex, nextRound.Parent = 6, shopFrame
		local said, warned = {}, {}
		local haggle = ShopHaggle.new({ shopFrame = shopFrame, playClickSfx = function() end,
			say = function(t) said[#said + 1] = t end, warn = function(t) warned[#warned + 1] = t end })

		local stage = ShopStage.new({
			shopFrame = shopFrame, buyList = buyList, contentArea = shopFrame, tabBar = tabBar, nextRoundButton = nextRound,
			backdrop = { marlo = nil, relayout = function() end }, cardRowHeight = function() return 300 end, setCardScale = function() end,
		})
		expectTrue(stage ~= nil, "the stage builds" .. where)

		-- the Reroll row exactly as Shop.lua builds it: a row in the Buy list holding the button and the table label
		local patronRow, packRow = FakeGui.new("ScrollingFrame"), FakeGui.new("ScrollingFrame")
		patronRow.ZIndex, packRow.ZIndex, patronRow.Parent, packRow.Parent = 6, 6, buyList, buyList
		local slots = {} -- two Patron cards and two packs, the way ShopCards.row leaves them
		for i = 1, 4 do
			local slot = FakeGui.new("Frame")
			slot.Name, slot.ZIndex, slot.Parent = "Card_" .. i, 6, i <= 2 and patronRow or packRow
			local wrapper = FakeGui.new("Frame") -- the inner Tilt wrapper ShopCards builds: a direct child of a ScrollingFrame ignores Rotation
			wrapper.Name, wrapper.ZIndex, wrapper.Parent = "Tilt", 6, slot
			slots[i] = slot
		end
		local rerollRow = FakeGui.new("Frame")
		rerollRow.ZIndex, rerollRow.Parent = 6, buyList
		local rerollButton = FakeGui.new("TextButton")
		rerollButton.Text, rerollButton.ZIndex, rerollButton.Parent = "Reroll 3", 6, rerollRow
		local tableLabel = FakeGui.new("TextLabel")
		tableLabel.ZIndex, tableLabel.Parent = 6, rerollRow
		local rerolls = 0
		rerollButton.MouseButton1Click:Connect(function() rerolls = rerolls + 1 end)

		haggle.update({ tips = 14, shopOffers = { { id = "p1", name = "Rowdy Bunch", price = 5 } }, packOffers = {},
			haggle = { available = true, used = false } })
		FakeGui.layout(gui, W, H) -- the stage reads the Shop frame's size when it arranges
		stage.arrange({ patronRow = patronRow, packRow = packRow, rerollRow = rerollRow, rerollButton = rerollButton, tableLabel = tableLabel,
			counts = { offers = 2, packs = 2, noMarlo = true }, patronRowHeight = 340, packRowHeight = 180 })
		FakeGui.layout(gui, W, H)

		local function centre(o) return o.AbsolutePosition.X + o.AbsoluteSize.X / 2, o.AbsolutePosition.Y + o.AbsoluteSize.Y / 2 end
		local haggleButton = shopFrame:FindFirstChild("HaggleButton")
		local bellTag, haggleTag = rerollRow:FindFirstChild("BellTag"), haggleButton:FindFirstChild("HaggleTag")
		expectTrue(bellTag ~= nil and haggleTag ~= nil, "both gold pills exist" .. where)
		expectEqual(bellTag.Text, "Reroll 3", "the Reroll pill shows its price" .. where)
		expectEqual(haggleTag.Text, "Haggle", "the Haggle pill shows its state" .. where)

		-- the pill hangs under the painted prop: the old hit area (the row, the prop rect) did not include it
		local rowBottom = rerollRow.AbsolutePosition.Y + rerollRow.AbsoluteSize.Y
		expectTrue(bellTag.AbsolutePosition.Y >= rowBottom or (bellTag.AbsoluteSize.Y >= 44 and bellTag.AbsolutePosition.Y >= rerollRow.AbsolutePosition.Y), "the Reroll pill is the 44 px plate that is the row itself, or sits below the bell's own rect (" .. bellTag.AbsolutePosition.Y .. " vs " .. rowBottom .. ")" .. where)

		-- a click on the middle of each pill, and on each prop, reaches that control
		local x, y = centre(bellTag)
		expectEqual(FakeGui.hit(gui, x, y), rerollButton, "a click on the Reroll pill reaches the Reroll button" .. where)
		x, y = centre(rerollRow)
		expectEqual(FakeGui.hit(gui, x, y), rerollButton, "a click on the bell reaches it too" .. where)
		x, y = bellTag.AbsolutePosition.X + 2, bellTag.AbsolutePosition.Y + 2
		expectEqual(FakeGui.hit(gui, x, y), rerollButton, "...also at the corner of the pill" .. where)
		x, y = centre(haggleTag)
		expectEqual(FakeGui.hit(gui, x, y), haggleButton, "a click on the Haggle pill reaches the Haggle button" .. where)
		x, y = haggleButton.AbsolutePosition.X + haggleButton.AbsoluteSize.X / 2, haggleButton.AbsolutePosition.Y + 6
		expectEqual(FakeGui.hit(gui, x, y), haggleButton, "a click on the ledger reaches it too" .. where)
		x, y = haggleTag.AbsolutePosition.X + haggleTag.AbsoluteSize.X - 2, haggleTag.AbsolutePosition.Y + haggleTag.AbsoluteSize.Y - 2
		expectEqual(FakeGui.hit(gui, x, y), haggleButton, "...also at the far corner of the pill" .. where)

		-- and the handlers run: Reroll counts, Haggle opens its chooser
		FakeGui.hit(gui, centre(bellTag)).MouseButton1Click:Fire()
		expectEqual(rerolls, 1, "the click on the pill runs the Reroll handler" .. where)
		local chooser = shopFrame:FindFirstChild("HaggleChooser")
		expectFalse(chooser.Visible, "the chooser starts closed" .. where)
		FakeGui.hit(gui, centre(haggleTag)).MouseButton1Click:Fire()
		expectTrue(chooser.Visible, "the click on the Haggle pill opens the item chooser" .. where)
		FakeGui.hit(gui, centre(haggleTag)).MouseButton1Click:Fire()
		expectFalse(chooser.Visible, "a second click closes it" .. where)
		local cancel, dimmer = chooser:FindFirstChild("HaggleCancel"), shopFrame:FindFirstChild("HaggleDim")
		expectTrue(cancel ~= nil and dimmer ~= nil, "the chooser has a Cancel button and a dim catcher" .. where)
		FakeGui.hit(gui, centre(haggleTag)).MouseButton1Click:Fire()
		expectTrue(dimmer.Visible, "the dim catcher shows with the chooser" .. where)
		do -- ZIndexBehavior is Global: the plate and its dim sit above every other element of the Counter, and the plate is opaque
			local top = 0
			for _, d in ipairs(shopFrame:GetDescendants()) do
				local inside = d == chooser or d == dimmer or d:IsDescendantOf(chooser)
				for _, own in ipairs({ "HaggleBar", "StrangerCard", "StrangerScroll", "HaggleButton" }) do -- ShopHaggle's own pieces, never shown together with the chooser
					local o = shopFrame:FindFirstChild(own)
					if o and (d == o or d:IsDescendantOf(o)) then inside = true end
				end
				if not inside and d:IsA("GuiObject") then top = math.max(top, d.ZIndex) end
			end
			expectTrue(dimmer.ZIndex > top, "the dim catcher is above every card element" .. where)
			expectTrue(chooser.ZIndex > top and cancel.ZIndex > chooser.ZIndex, "the plate and Cancel are above every card element" .. where)
			expectTrue(chooser.BackgroundTransparency == 0, "the plate is opaque parchment" .. where)
		end
		cancel.MouseButton1Click:Fire()
		expectFalse(chooser.Visible or dimmer.Visible, "Cancel closes the chooser" .. where)
		FakeGui.hit(gui, centre(haggleTag)).MouseButton1Click:Fire()
		dimmer.MouseButton1Click:Fire()
		expectFalse(chooser.Visible, "a click outside the plate closes it" .. where)

		-- the room: each dealt card lies at its own fixed angle; the props glow while the pointer is on them (never in calm mode)
		local SL = require(Engine.ShopSceneLayout)
		expectEqual(#scrollChildRotations(gui), 0, "no card is rotated directly in a ScrollingFrame row" .. where .. ": " .. table.concat(scrollChildRotations(gui), ", "))
		for i, slot in ipairs(slots) do
			local wrapper = slot:FindFirstChild("Tilt")
			expectTrue((slot.Rotation or 0) == 0, "card " .. i .. ": the slot (a direct child of a ScrollingFrame) is not rotated" .. where)
			expectEqual(wrapper.Rotation, SL.cardTilt(i), "card " .. i .. " lies at its fixed angle, on its Tilt wrapper" .. where)
			expectEqual(slot:GetAttribute("Tilt"), SL.cardTilt(i), "...and the slot remembers it for the hover" .. where)
			expectTrue(math.abs(wrapper.Rotation) >= 3 and math.abs(wrapper.Rotation) <= 8, "...a visible angle, 3 to 8 degrees" .. where)
			if i > 1 then expectTrue(wrapper.Rotation ~= slots[i - 1]:FindFirstChild("Tilt").Rotation, "...and not like its neighbour" .. where) end
		end
		local bellGlow, ledgerGlow = shopFrame:FindFirstChild("Glow_Reroll"), shopFrame:FindFirstChild("Glow_Haggle")
		expectTrue(bellGlow ~= nil and ledgerGlow ~= nil, "both props have a glow" .. where)
		expectFalse(bellGlow.Visible or ledgerGlow.Visible, "...off until the pointer is on them" .. where)
		rerollButton.MouseEnter:Fire()
		expectTrue(bellGlow.Visible and bellTag.BackgroundColor3 ~= nil, "the bell glows under the pointer" .. where)
		rerollButton.MouseLeave:Fire()
		expectFalse(bellGlow.Visible, "...and goes out when it leaves" .. where)
		calmOn = true
		haggleButton.MouseEnter:Fire()
		expectFalse(ledgerGlow.Visible, "calm mode never lights the glow" .. where)
		haggleButton.MouseLeave:Fire()
		calmOn = false
		haggleButton.MouseEnter:Fire()
		expectTrue(ledgerGlow.Visible, "the ledger glows under the pointer" .. where)
		haggleButton.MouseLeave:Fire()
		-- the words sit on a dark name plate, cream on dark above 4.5:1, not a gold pill
		local LL = require(Engine.LedgerLayout)
		local function rgb(c) return { c.R * 255, c.G * 255, c.B * 255 } end
		for _, plate in ipairs({ bellTag, haggleTag }) do
			expectTrue(LL.contrast(rgb(plate.TextColor3), rgb(plate.BackgroundColor3)) >= 4.5, plate.Name .. " text is at least 4.5:1 on its plate" .. where)
		end

		-- after the visit's haggle: the control stays and reads Haggled, a click says why, nothing opens
		haggle.update({ tips = 14, shopOffers = {}, packOffers = {}, haggle = { available = false, used = true, reason = "used" } })
		expectTrue(haggleButton.Visible, "the Haggle control stays after it is used" .. where)
		expectEqual(haggleTag.Text, "Haggled", "...and says so" .. where)
		stage.relayout()
		expectEqual(haggleTag.Text, "Haggled", "a relayout keeps the word" .. where)
		expectEqual(rerollRow:FindFirstChild("BellTag").Text, "Reroll 3", "a relayout keeps the Reroll price too" .. where)
		said, warned = {}, {}
		FakeGui.hit(gui, centre(haggleTag)).MouseButton1Click:Fire()
		expectFalse(chooser.Visible, "nothing opens once it is used" .. where)
		expectTrue(said[1] == "You already haggled this visit." and warned[1] == "You already haggled this visit.", "a click that does nothing says why, in Marlo's bubble and on the Counter" .. where)
		-- while a pack is open it is dimmed with its own reason; on a ranked board it is not drawn at all
		haggle.update({ shopOffers = {}, packOffers = {}, haggle = { available = false, used = false, reason = "pack_open" } })
		expectTrue(haggleButton.Visible and haggleTag.Text == "Haggle", "an open pack only dims it" .. where)
		haggle.update({ shopOffers = {}, packOffers = {}, haggle = { available = false, used = false, reason = "ranked" } })
		expectFalse(haggleButton.Visible, "a ranked board has no Haggle" .. where)
		haggle.update({ shopOffers = {}, packOffers = {}, haggle = nil })
		expectFalse(haggleButton.Visible, "no haggle state, no control" .. where)
	end
end })

table.insert(tests, { name = "The Counter's oval card table: a wide oval with a 12 to 16 px rim, every offer and pack turned by its tilt lies on the felt with 18 px to spare, clear of Marlo, the bell, the ledger and the controls (three sizes)", fn = function()
	local SL = require(script.Parent.Parent.Engine.ShopSceneLayout)
	expectTrue(SL.TABLE_RIM >= 12 and SL.TABLE_RIM <= 16, "the wood rim is 12 to 16 px wide")
	expectTrue(SL.TABLE_MARGIN >= 18, "cards keep at least 18 px of felt to the rim")
	local keep = SL.TABLE_RIM + SL.TABLE_MARGIN
	-- the Counter frame is the screen right of the 260 px HUD (the whole width on a compact screen)
	for _, frame in ipairs({ { 1660, 1080 }, { 1020, 720 }, { 788, 450 } }) do
		local W, H = frame[1], frame[2]
		for nOffers = 1, 4 do
			for nPacks = 0, 3 do
				local r = SL.rects(W, H, { offers = nOffers, packs = nPacks })
				local where = " (" .. nOffers .. " offers, " .. nPacks .. " packs at " .. W .. "x" .. H .. ")"
				expectTrue(r.table ~= nil and r.felt ~= nil, "there is a table with felt" .. where)
				expectTrue(SL.inside(r.table, r.area), "the table is inside the Counter" .. where)
				expectTrue(r.table.w >= r.table.h * 1.2, "the table is a wide oval, not a square (" .. r.table.w .. " x " .. r.table.h .. ")" .. where)
				-- a Counter has two Patron offers (sometimes a voucher) and two packs; more than that crowds the felt, and so does the
				-- smallest window (the table there is about 395 x 263): the layout says so with fitted = false
				local crowded = W < 900 or nOffers >= 4 or nPacks >= 3
				expectTrue(r.fitted or crowded, "two offers and two packs (three offers on a roomy window) always lie on the felt with their margin" .. where)
				expectTrue(r.felt.x - r.table.x == SL.TABLE_RIM and r.felt.y - r.table.y == SL.TABLE_RIM, "the felt sits one rim width inside the table" .. where)
				expectTrue(r.table.x + r.table.w - (r.felt.x + r.felt.w) == SL.TABLE_RIM, "...on the right too" .. where)
				-- every card, turned by its own tilt, lies on the felt with its margin; a hovered one (straight, 6 px higher) stays on the table
				-- (four offers on the smallest window are the crowded case the layout reports with fitted = false)
				local index = 0
				for _, list in ipairs({ r.offers, r.packs }) do
					for k, card in ipairs(list) do
						index = index + 1
						local label = (list == r.offers and "Patron card " or "pack ") .. k
						if r.fitted then
							expectTrue(SL.cardOnTable(r.table, card, SL.cardTilt(index), keep), label .. " lies on the felt with 18 px to spare" .. where)
							expectTrue(SL.cardOnTable(r.table, { x = card.x, y = card.y - 6, w = card.w, h = card.h }, 0, SL.TABLE_RIM + 6), label .. " stays on the table when it lifts and straightens" .. where)
						end
					end
				end
				-- cards do not overlap each other
				for i = 1, #r.offers do
					for j = i + 1, #r.offers do expectFalse(SL.intersects(r.offers[i], r.offers[j]), "Patron cards " .. i .. " and " .. j .. " do not overlap" .. where) end
					for j = 1, #r.packs do expectFalse(SL.intersects(r.offers[i], r.packs[j]), "Patron card " .. i .. " and pack " .. j .. " do not overlap" .. where) end
				end
				for i = 1, #r.packs do
					for j = i + 1, #r.packs do expectFalse(SL.intersects(r.packs[i], r.packs[j]), "packs " .. i .. " and " .. j .. " do not overlap" .. where) end
				end
				if nPacks > 0 and nOffers > 0 then
					expectTrue(r.packs[1].h < r.offers[1].h and r.packs[1].w <= r.offers[1].w, "packs lie smaller than the Patron cards" .. where)
					expectTrue(r.packs[1].y > r.offers[1].y, "...on the lower part of the felt" .. where)
				end
				-- the table keeps clear of what is not on it (the brass rail is a layer of the counter, behind the table)
				for name, other in pairs({ marlo = r.marlo, bell = r.props.bell, ledger = r.props.ledger, tabs = r.tabs, nextBoss = r.nextBoss, leave = r.leave }) do
					expectFalse(SL.intersects(r.table, other), "the table does not touch the " .. name .. where)
				end
				-- the table's upper part is over the counter's back edge, and its foot stays 30 px above the Next Round sign
				expectTrue(r.table.y < r.counter.y and r.table.y + r.table.h > r.counter.y + 10, "the table straddles the counter's back edge" .. where)
				expectTrue(r.table.y + r.table.h <= r.leave.y - SL.TABLE_FOOT, "the table's foot is at least 30 px above Next Round" .. where)
				-- it is the 12 percent narrower table: well inside the room between Marlo and the bell, centred in it
				local roomL, roomR = r.marlo.x + r.marlo.w + 2, r.props.bell.x - 6
				expectTrue(r.table.w <= (roomR - roomL) * 0.9, "the table leaves room beside it (12 percent narrower)" .. where)
				expectTrue(math.abs((r.table.x + r.table.w / 2) - (roomL + roomR) / 2) <= 2, "...and is centred in that room, under the offers" .. where)
			end
		end
	end
	local phone = SL.rects(390, 700, { offers = 3, packs = 2 })
	expectEqual(phone.table, nil, "a phone has no table: its cards wrap in rows on the counter")
	-- the dealt tilt: -4, +3, -3, +4 by slot, the same every visit, never zero, never past 4 degrees
	for i, want in ipairs({ -4, 3, -3, 4, -4, 3 }) do expectEqual(SL.cardTilt(i), want, "slot " .. i .. " lies at " .. want .. " degrees") end
	for i = 1, 12 do
		expectTrue(math.abs(SL.cardTilt(i)) >= 3 and math.abs(SL.cardTilt(i)) <= 4, "tilt " .. i .. " is visible and within 4 degrees")
		if i > 1 then expectTrue(SL.cardTilt(i) ~= SL.cardTilt(i - 1), "neighbours lean differently (" .. i .. ")") end
	end
	-- a point just inside and just outside the oval's end tell the shape: a capsule, not a rectangle
	local t = { x = 0, y = 0, w = 600, h = 400 }
	expectTrue(SL.insideTable(t, 0, 300, 2) and SL.insideTable(t, 0, 2, 200), "the middle of the long edge and the tip of the end are on the table")
	expectFalse(SL.insideTable(t, 0, 2, 2), "...the square corner is not")
	expectFalse(SL.insideTable(t, 20, 300, 10), "an inset shrinks the oval")
end })

table.insert(tests, { name = "ShopBackdrop draws an oval felt table with a wood rim, a seam, a shadow and a calm light (colour stops only), over the counter and under the cards, none on a phone", fn = function()
	local probe = io and io.open and load and io.open("src/Client/ShopBackdrop.lua", "r")
	if not probe then return end
	probe:close()
	local FakeGui = require(script.Parent.FakeGui)
	local Engine = script.Parent.Parent.Engine
	local SL = require(Engine.ShopSceneLayout)
	local stubs = { SmoothVignette = { build = function() end } }
	local env, st = FakeGui.env({ stubs = stubs })
	st.services.ReplicatedStorage = { WaitForChild = function()
		return { WaitForChild = function()
			return FakeGui.folder({ ShopSceneLayout = SL, ContentArt = require(Engine.ContentArt), GlowCurve = require(Engine.GlowCurve), ImageSpace = require(Engine.ImageSpace) })
		end }
	end }
	stubs.SoftGlow = FakeGui.load("src/Client/SoftGlow.lua", env) -- the real soft light pool (many eased discs)
	local ShopBackdrop = FakeGui.load("src/Client/ShopBackdrop.lua", env)
	local gui = FakeGui.new("ScreenGui")
	local shopFrame = FakeGui.new("Frame")
	shopFrame.Parent = gui
	shopFrame.AbsoluteSize = { X = 1020, Y = 720 }
	local backdrop = ShopBackdrop.new({ shopFrame = shopFrame })
	local root = backdrop.root
	local rim = root:FindFirstChild("TableTop")
	expectTrue(rim ~= nil, "the backdrop makes a TableTop")
	expectFalse(rim.Active, "the table sinks no clicks")
	backdrop.relayout({ offers = 3, packs = 2 })
	local want = SL.rects(1020, 720, { offers = 3, packs = 2 })
	expectTrue(rim.Visible, "the table is shown on the Counter")
	expectTrue(rim.Position.X.Offset == want.table.x and rim.Position.Y.Offset == want.table.y and rim.Size.X.Offset == want.table.w and rim.Size.Y.Offset == want.table.h, "the rim follows the layout's table rect")
	expectTrue(rim.Size.X.Offset > rim.Size.Y.Offset * 1.2, "wider than tall")
	local function corner(inst)
		local c = inst:FindFirstChildOfClass("UICorner")
		return c and c.CornerRadius
	end
	if rim.ClassName == "Frame" then
		-- the shape: an oval, a UICorner at half the short side (the Menu room's felt table is made the same way)
		local radius = corner(rim)
		expectTrue(radius ~= nil and radius.Scale == 0.5 and radius.Offset == 0, "the rim is an oval (UICorner radius 0.5 scale)")
		local felt = root:FindFirstChild("TableFelt")
		expectTrue(felt ~= nil, "there is felt inside the rim")
		radius = corner(felt)
		expectTrue(radius ~= nil and radius.Scale == 0.5, "the felt is an oval too")
		expectTrue(felt.Position.X.Offset == want.felt.x and felt.Position.Y.Offset == want.felt.y and felt.Size.X.Offset == want.felt.w and felt.Size.Y.Offset == want.felt.h, "the felt follows the layout's felt rect")
		local rimWidth = felt.Position.X.Offset - rim.Position.X.Offset
		expectTrue(rimWidth >= 12 and rimWidth <= 16, "the wood rim is 12 to 16 px wide (" .. rimWidth .. ")")
		expectEqual(rim.Size.X.Offset - felt.Size.X.Offset, 2 * rimWidth, "...the same on both sides")
		-- the rim is the Menu table's brown, not a dark box
		local wood = rim.BackgroundColor3
		expectTrue(wood.R > wood.G and wood.G > wood.B and wood.R * 255 >= 100, "the rim is wood brown")
		-- the felt: soft green, never darker than (24, 40, 28) at any stop, lighter in the middle than at the edge
		local gradient = felt:FindFirstChildOfClass("UIGradient")
		expectTrue(gradient ~= nil, "the felt has a colour ramp")
		local stops = gradient.Color.Keypoints
		local centre, edge
		for _, k in ipairs(stops) do
			expectTrue(k.Value.R * 255 >= 24 and k.Value.G * 255 >= 40 and k.Value.B * 255 >= 28, "no felt stop is darker than (24, 40, 28)")
			expectTrue(k.Value.G > k.Value.R and k.Value.G > k.Value.B, "every felt stop is green")
			if k.Time == 0.5 then centre = k.Value end
			if k.Time == 0 then edge = k.Value end
		end
		expectTrue(centre ~= nil and edge ~= nil and centre.G > edge.G, "the felt is lighter in the middle than at the edge")
		expectTrue(felt:FindFirstChildOfClass("UIStroke") ~= nil, "a darker seam where the felt meets the rim")
		-- calm: nothing in the table touches a gradient's Transparency, and nothing sinks a click
		for _, d in ipairs(root:GetDescendants()) do
			if d.ClassName == "UIGradient" then expectEqual(d.Transparency, nil, "UIGradient.Transparency is never touched") end
		end
		for _, name in ipairs({ "TableShadowFar", "TableShadow", "TableRimLight", "TableFelt", "TableFeltShade", "TableFeltLight" }) do
			local piece = root:FindFirstChild(name)
			expectTrue(piece ~= nil and piece.Active == false and piece.Visible, name .. " is drawn and sinks no click")
		end
		expectTrue(root:FindFirstChild("TableShadow").BackgroundTransparency >= 0.5, "the shadow is soft, not a black blot")
		expectTrue(root:FindFirstChild("TableFeltLight").BackgroundTransparency >= 0.9, "the lantern light on the felt is faint")
	end
	-- layers: the shadow is under the rim, the felt over it, and all of it over the counter (the brass rail passes behind the table)
	local _, rank = FakeGui.drawOrder(gui)
	local counter = root:FindFirstChild("CounterTop") or root:FindFirstChild("FallbackCounter")
	expectTrue(counter ~= nil and rank[counter] < rank[rim], "the table is drawn over the counter")
	if rim.ClassName == "Frame" then
		expectTrue(rank[root:FindFirstChild("TableShadow")] < rank[rim], "the shadow is under the table")
	else
		-- the painted table is taller than its oval (the pedestal hangs below), so an oval shadow of the whole rect was a smoky disc
		expectTrue(root:FindFirstChild("TableShadow") == nil and root:FindFirstChild("TableShadowFar") == nil, "the painted table has no oversized shadow ovals")
	end
	if rim.ClassName == "Frame" then expectTrue(rank[root:FindFirstChild("TableFelt")] > rank[rim], "the felt is over the rim") end
	-- a phone has no table: nothing of it shows
	shopFrame.AbsoluteSize = { X = 390, Y = 700 }
	backdrop.relayout({ offers = 3, packs = 2 })
	expectFalse(rim.Visible, "no table on a phone")
	for _, name in ipairs({ "TableShadowFar", "TableShadow", "TableFelt" }) do
		local piece = root:FindFirstChild(name)
		expectTrue(piece == nil or piece.Visible == false, name .. " is hidden on a phone")
	end
end })

table.insert(tests, { name = "Counter room: the cover-crop mapping of the painted picture is exact on 1536x1024, a wide window and a phone portrait", fn = function()
	local SL = require(script.Parent.Parent.Engine.ShopSceneLayout)
	local p = SL.pic(1536, 1024)
	expectTrue(p.x == 0 and p.y == 0 and p.w == 1536 and p.h == 1024, "the picture's own size maps one to one")
	local wide = SL.pic(2000, 1000) -- wider than 3:2: the width fills, the height overflows evenly top and bottom
	expectTrue(math.abs(wide.w - 2000) < 1e-6 and wide.h > 1000 and math.abs(wide.y + (wide.h - 1000) / 2) < 1e-6, "a wide window crops top and bottom")
	local tall = SL.pic(390, 700) -- portrait: the height fills, the width overflows evenly left and right
	expectTrue(math.abs(tall.h - 700) < 1e-6 and tall.w > 390 and math.abs(tall.x + (tall.w - 390) / 2) < 1e-6, "a portrait window crops left and right")
	local r = SL.picRect(1536, 1024, 0.5, 0.5, 1, 1)
	expectTrue(r.x == 768 and r.y == 512 and r.w == 768 and r.h == 512, "a fraction rect maps through the crop")
	local ph = SL.rects(390, 700, { offers = 3, packs = 2, room = true })
	expectTrue(ph.phone and not ph.room, "a phone keeps its own layout and never crops the room picture to a sliver")
end })

table.insert(tests, { name = "Counter room: cards lie on the painted felt and never cover the bell, ledger, arch, Marlo's wall or Next Round (four sizes)", fn = function()
	local SL = require(script.Parent.Parent.Engine.ShopSceneLayout)
	local R = SL.ROOM
	for _, frame in ipairs({ { 1660, 1080 }, { 1257, 750 }, { 1020, 720 }, { 788, 450 } }) do
		local W, H = frame[1], frame[2]
		local where = " at " .. W .. "x" .. H
		local r = SL.rects(W, H, { offers = 2, packs = 2, room = true })
		expectTrue(r.room == true, "room layout" .. where)
		local p = SL.pic(W, H)
		local bellMid = r.props.bell.x + r.props.bell.w / 2
		expectTrue(math.abs(bellMid - (p.x + R.bell[1] * p.w)) <= 1, "the Reroll hotspot is on the painted bell" .. where)
		local ledgerMid = r.props.ledger.x + r.props.ledger.w / 2
		expectTrue(math.abs(ledgerMid - (p.x + R.ledger[1] * p.w)) <= 1, "the Haggle hotspot is on the painted ledger" .. where)
		local blockers = {
			{ x = r.props.bell.x - 30, y = r.props.bell.y, w = r.props.bell.w + 60, h = r.props.bell.h + 32, name = "bell" },
			{ x = r.props.ledger.x, y = r.props.ledger.y, w = r.props.ledger.w, h = r.props.ledger.h + 32, name = "ledger" },
			{ x = r.arch.x, y = r.arch.y, w = r.arch.w, h = r.arch.h, name = "arch" },
			{ x = r.shopkeeper.x, y = r.shopkeeper.y, w = r.shopkeeper.w, h = r.shopkeeper.h, name = "Marlo's wall" },
			{ x = r.leave.x, y = r.leave.y, w = r.leave.w, h = r.leave.h, name = "Next Round" },
		}
		local index = 0
		for _, list in ipairs({ r.offers, r.packs }) do
			for _, card in ipairs(list) do
				index = index + 1
				local bx0, by0, bx1, by1 = math.huge, math.huge, -math.huge, -math.huge
				for _, c in ipairs(SL.corners(card, SL.cardTilt(index))) do
					bx0, by0, bx1, by1 = math.min(bx0, c.x), math.min(by0, c.y), math.max(bx1, c.x), math.max(by1, c.y)
				end
				local box = { x = bx0, y = by0, w = bx1 - bx0, h = by1 - by0 }
				if r.fitted then
					for _, b in ipairs(blockers) do
						expectFalse(SL.intersects(box, b), "card " .. index .. " does not cover the " .. b.name .. where)
					end
					expectTrue(by0 >= p.y + R.surface * p.h - 1, "card " .. index .. " starts below the counter top" .. where)
					expectTrue(SL.inside(card, r.area), "card " .. index .. " is on screen" .. where)
				end
			end
		end
		if r.fitted then
			local foot = r.offers[1].y + r.offers[1].h
			expectTrue(foot > r.felt.y + r.felt.h * 0.3 and foot <= r.table.y + r.table.h, "the Patron cards' lower parts lie on the felt" .. where)
		end
		expectTrue(r.fitted or W < 900 or H < 600, "the cards fit the painted felt" .. where)
	end
	local big = SL.rects(1660, 1080, { offers = 2, packs = 2, room = true })
	expectTrue(big.offers[1].w >= SL.READABLE_SCALE * 220, "cards reach the readable scale at 1660x1080 (" .. big.offers[1].w .. " px)")
end })

table.insert(tests, { name = "Counter room: 3, 4 and 5 offers never overlap, stay inside the felt and keep a gap of 2 percent of the room width (1280x720, 1920x1080, phone)", fn = function()
	local SL = require(script.Parent.Parent.Engine.ShopSceneLayout)
	for _, frame in ipairs({ { 1280, 720 }, { 1920, 1080 }, { 390, 700 } }) do
		local W, H = frame[1], frame[2]
		for nOffers = 3, 5 do
			local where = " (" .. nOffers .. " offers at " .. W .. "x" .. H .. ")"
			local r = SL.rects(W, H, { offers = nOffers, packs = 2, room = true })
			expectEqual(#r.offers, nOffers, "offer count" .. where)
			if r.room and r.fitted and not r.sideBySide then
				local p = SL.pic(W, H)
				local clear = 0.02 * p.w - 1
				local boxes = {}
				for i, o in ipairs(r.offers) do
					local x0, y0, x1, y1 = math.huge, math.huge, -math.huge, -math.huge
					for _, c in ipairs(SL.corners(o, SL.cardTilt(i))) do
						x0, y0, x1, y1 = math.min(x0, c.x), math.min(y0, c.y), math.max(x1, c.x), math.max(y1, c.y)
					end
					boxes[i] = { x = x0, y = y0, w = x1 - x0, h = y1 - y0 }
					expectTrue(x0 >= r.felt.x and x1 <= r.felt.x + r.felt.w, "offer " .. i .. " is inside the felt's rims" .. where)
					expectTrue(math.abs(SL.cardTilt(i)) <= 4, "tilt stays within 4 degrees" .. where)
					for _, pk in ipairs(r.packs) do expectFalse(SL.intersects(o, pk), "offer " .. i .. " and the packs never share space" .. where) end
				end
				for i = 1, #boxes - 1 do
					expectTrue(boxes[i + 1].x - (boxes[i].x + boxes[i].w) >= clear, "offers " .. i .. "/" .. (i + 1) .. " keep the gap" .. where)
				end
				expectTrue(r.cardGap and r.cardGap >= 0.02 * p.w, "the row gap handed to the card row keeps the clearance" .. where)
			end
		end
	end
	-- the common case must fit: four offers in a 1920x1080 room
	local r = SL.rects(1920, 1080, { offers = 4, packs = 2, room = true })
	expectTrue(r.fitted, "four offers fit the painted felt at 1920x1080")
end })

