table.insert(tests, { name = "Counter room: the backdrop is ONE cropped picture, Marlo sits in a frame clipped at the counter top, the older pieces hide (and return without the room)", fn = function()
	if not (io and io.open) then return end
	local FakeGui = require(script.Parent.FakeGui)
	local Engine = script.Parent.Parent.Engine
	local SL = require(Engine.ShopSceneLayout)
	local stubs = { SmoothVignette = { build = function() end } }
	local env, st = FakeGui.env({ stubs = stubs })
	st.services.ReplicatedStorage = { WaitForChild = function()
		return { WaitForChild = function()
			return FakeGui.folder({ ShopSceneLayout = SL, ContentArt = require(Engine.ContentArt), GlowCurve = require(Engine.GlowCurve), ImageSpace = require(Engine.ImageSpace) })
		end }
	end }
	stubs.SoftGlow = FakeGui.load("src/Client/SoftGlow.lua", env)
	local ShopBackdrop = FakeGui.load("src/Client/ShopBackdrop.lua", env)
	local gui = FakeGui.new("ScreenGui")
	local shopFrame = FakeGui.new("Frame")
	shopFrame.Parent = gui
	shopFrame.AbsoluteSize = { X = 1257, Y = 750 }
	local backdrop = ShopBackdrop.new({ shopFrame = shopFrame })
	expectTrue(backdrop.roomId ~= nil and backdrop.room ~= nil, "the room picture is recorded and mounted")
	expectTrue(tostring(backdrop.room.ScaleType):find("Crop") ~= nil,"the room is cover-cropped, never stretched")
	local root = backdrop.root
	backdrop.relayout({ offers = 2, packs = 2, room = true })
	local want = SL.rects(1257, 750, { offers = 2, packs = 2, room = true })
	expectTrue(backdrop.room.Visible, "the room shows")
	local wall = root:FindFirstChild("Wall")
	expectTrue(wall == nil or not wall.Visible, "the older wall is hidden")
	local rim = root:FindFirstChild("TableTop")
	expectTrue(rim == nil or not rim.Visible, "the drawn table is hidden: the table is in the picture")
	local clip = root:FindFirstChild("MarloClip")
	expectTrue(clip ~= nil and not clip.ClipsDescendants, "in the painted room Marlo's frame does not clip him (he is whole, the counter band covers him)")
	expectTrue(backdrop.marlo == nil or backdrop.marlo.Parent == clip, "Marlo lives in his frame")
	local band = root:FindFirstChild("CounterFront")
	expectTrue(band ~= nil and band.Visible and band.Image == backdrop.room.Image, "the counter band is a second label of the same room picture")
	expectTrue(band.Position.X.Offset == want.counterBand.x and band.Position.Y.Offset == want.counterBand.y and band.Size.X.Offset == want.counterBand.w and band.Size.Y.Offset == want.counterBand.h,
		"the band sits exactly where that part of the room is drawn")
	local order, marloAt, bandAt = root:GetChildren(), 0, 0
	for i, c in ipairs(order) do
		if c == clip then marloAt = i end
		if c == band then bandAt = i end
	end
	expectTrue(bandAt > marloAt and band.ZIndex >= clip.ZIndex, "the band draws above Marlo (later sibling, same or higher ZIndex)")
	backdrop.relayout({ offers = 2, packs = 2 })
	expectFalse(band.Visible, "no band without the room")
	expectTrue(clip.ClipsDescendants, "the older scenes still clip Marlo at the counter top")
	expectFalse(backdrop.room.Visible, "no room picture without the flag")
	expectTrue(wall == nil or wall.Visible, "the older wall returns")
end })

table.insert(tests, { name = "Reroll and Haggle refusals: the server says why, the Counter shows it once, Studio traces the path", fn = function()
	local function read(path)
		local f = io and io.open and io.open(path, "r")
		if not f then return nil end
		local s = f:read("*a"); f:close()
		return s
	end
	local server = read("src/Server/init.server.lua")
	local shop = read("src/Client/Shop.lua")
	local haggle = read("src/Client/ShopHaggle.lua")
	local stage = read("src/Client/ShopStage.lua")
	if not (server and shop and haggle and stage) then return end
	-- server: neither handler returns silently on a refusal any more
	local reroll = server:match("Rem%.RerollShop%.OnServerEvent:Connect.-\nend%)\n")
	expectTrue(reroll ~= nil and reroll:find("ShopRefusal", 1, true) ~= nil and reroll:find("counterNotice(player, session, why)", 1, true) ~= nil, "Reroll turns a refusal into a notice")
	expectTrue(reroll:find("counterTrace", 1, true) ~= nil, "Reroll is traced in Studio")
	local hag = server:match("Rem%.Haggle%.OnServerEvent:Connect.-\nend%)\n")
	expectTrue(hag ~= nil and hag:find("counterNotice(player, session, Refusal.haggle(code))", 1, true) ~= nil, "a Haggle start that fails says why")
	expectTrue(hag:find('Refusal.haggle(session.state.pendingPack and "pack_open" or "wrong_phase")', 1, true) ~= nil, "...also when the phase or an open pack stops it")
	expectTrue(server:find("shopNotice = session.shopNotice", 1, true) ~= nil, "the notice reaches the client in the state")
	-- client: the notice is shown once per seq, the words are the shared ones, every click is traced
	expectTrue(shop:find("state.shopNotice.seq ~= lastNoticeSeq", 1, true) ~= nil and shop:find("showWarning(state.shopNotice.text)", 1, true) ~= nil, "the Counter shows a server notice once")
	expectTrue(shop:find("ShopRefusal.rerollLabel(state.rerollCost)", 1, true) ~= nil, "the Reroll button shows its cost")
	expectTrue(shop:find('ShopTrace.log("Reroll clicked")', 1, true) ~= nil and shop:find("Reroll sent to the server", 1, true) ~= nil, "the Reroll click is traced")
	expectTrue(haggle:find('ShopTrace.log("Haggle clicked', 1, true) ~= nil and haggle:find("ShopRefusal.haggleDenied", 1, true) ~= nil, "the Haggle click is traced and refused out loud")
	-- the tags are part of the hit area, not labels beside it
	expectTrue(stage:find("TAG_H + TAG_GAP", 1, true) ~= nil and stage:find("bindHover(", 1, true) ~= nil, "the pill is inside its control's hit area and lights on hover")
	-- ... and the trace is silent outside Studio
	local trace = read("src/Client/ShopTrace.lua")
	expectTrue(trace ~= nil and trace:find("IsStudio()", 1, true) ~= nil, "ShopTrace prints only in Studio")
end })

-- ===== Small notices are a corner toast, the big plate is only for the daily reward and Round Complete (2026-11-10) =====
table.insert(tests, { name = "CornerToastRules: words, the slot, and a stack of at most three (newest on top, unlocks merge, 4 seconds)", fn = function()
	local R = require(script.Parent.Parent.Engine.CornerToastRules)
	-- style: a plate only when asked
	expectEqual(R.styleOf({ text = "x" }), "toast")
	expectEqual(R.styleOf({ plate = true }), "plate")
	expectEqual(R.styleOf({ plate = false, button = "Continue" }), "toast", "a button does not make a plate")
	expectEqual(R.styleOf(nil), "toast")
	-- words: no emoji, the name only, merged
	expectEqual(R.stripEmoji("\240\159\148\147 Straight Shooter"), "Straight Shooter", "a padlock emoji goes")
	expectEqual(R.stripEmoji("Quest done: Pair Up   +40 XP"), "Quest done: Pair Up +40 XP", "spaces are tidied")
	expectEqual(R.stripEmoji("\226\156\148 Done \240\159\143\133"), "Done")
	expectEqual(R.stripEmoji("Caf\195\169"), "Caf\195\169", "plain letters with accents stay")
	expectEqual(R.mergeNames({ "A" }), "Unlocked: A")
	expectEqual(R.mergeNames({ "A", "B" }), "Unlocked: A and B")
	expectEqual(R.mergeNames({ "A", "B", "C", "D" }), "Unlocked: A, B and 2 more")
	expectEqual(R.textFor({ group = "unlock", rows = { "\240\159\148\147 Straight Shooter" } }), "Unlocked: Straight Shooter")
	expectEqual(R.textFor({ text = "Blessing: Generous House" }), "Blessing: Generous House")
	expectEqual(R.textFor({ title = "Welcome" }), "Welcome", "a title alone still says something")
	-- the slot: right edge, under the corner buttons (they end at y 66), compact on Round Select
	for _, screenSize in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 800, 450 } }) do
		local w, h = screenSize[1], screenSize[2]
		for _, screen in ipairs({ "table", "shop", "choice", "roundSelect" }) do
			local plan = R.plan(screen)
			for i = 1, plan.maxVisible do
				local s = R.slot(w, h, plan, i)
				local where = screen .. " slot " .. i .. " at " .. w .. "x" .. h
				expectTrue(s.x >= 0 and s.x + s.w <= w - R.EDGE + 0.5 and s.y + s.h <= h, where .. " is on the screen")
				expectEqual(s.x + s.w, w - R.EDGE, where .. " hugs the right edge")
				expectTrue(s.w <= 320 and s.w >= 240 or w < 900, where .. " is at most 320 wide (" .. s.w .. ")")
				expectTrue(s.y >= 66 + (screen == "roundSelect" and 2 or 8), where .. " is under the corner buttons")
				if i > 1 then expectTrue(s.y > R.slot(w, h, plan, i - 1).y + plan.height - 1, where .. " does not overlap the one above") end
			end
		end
		local compact = R.plan("roundSelect")
		expectTrue(R.slot(w, h, compact, 1).y + compact.height <= R.CARDS_TOP, "Round Select's one compact line ends above its cards")
		expectEqual(R.plan("table").maxVisible, 3)
		expectEqual(compact.maxVisible, 1)
	end

	-- the stack
	local st = R.new()
	for i = 1, 5 do expectTrue(st:push({ id = "n" .. i, text = "Quest " .. i }, 0), "notice " .. i .. " is taken") end
	expectFalse(st:push({ id = "n1", text = "again" }, 0), "the same id is not shown twice in a round")
	expectFalse(st:push({ id = "empty" }, 0), "a notice with no words is dropped")
	st:tick(0, 3)
	expectEqual(#st.visible, 3, "never more than three stacked")
	expectEqual(st.visible[1].text, "Quest 3", "the newest one in is on top")
	expectEqual(#st.pending, 2, "the others wait")
	st:tick(R.AUTO_SECONDS - 0.1, 3)
	expectEqual(#st.visible, 3, "they stay about 4 seconds")
	st:tick(R.AUTO_SECONDS + 0.1, 3)
	expectEqual(st.visible[1].text, "Quest 5", "when they go, the waiting ones come in")
	expectEqual(#st.visible, 2)
	st:tick(2 * R.AUTO_SECONDS + 1, 3)
	expectTrue(st:isEmpty(), "and then the stack is empty")
	-- unlocks merge into one toast, and a repeat restarts its time
	st = R.new()
	st:push({ id = "u1", group = "unlock", rows = { "A", "B" } }, 0)
	st:tick(0, 3)
	st:push({ id = "u2", group = "unlock", rows = { "C", "D" } }, 2)
	st:tick(2, 3)
	expectEqual(#st.visible, 1, "later unlocks join the one on screen")
	expectEqual(st.visible[1].text, "Unlocked: A, B and 2 more", "extras merge into 'A, B and 2 more'")
	st:tick(R.AUTO_SECONDS + 1, 3)
	expectEqual(#st.visible, 1, "the merge gave it a fresh 4 seconds")
	-- a tap closes one; a smaller slot (Round Select) sends the oldest back to wait and they return when there is room
	st = R.new()
	for i = 1, 3 do st:push({ id = "q" .. i, text = "Quest " .. i }, 0) st:tick(0, 3) end
	expectEqual(#st.visible, 3)
	local top = st.visible[1].order
	expectTrue(st:dismiss(top) and #st.visible == 2, "a tap closes that toast")
	st:push({ id = "q4", text = "Quest 4" }, 1)
	st:tick(1, 1)
	expectEqual(#st.visible, 1, "Round Select shows one")
	expectEqual(st.visible[1].text, "Quest 2", "the newest of the ones already up stays; the new notice waits for room")
	expectEqual(#st.pending, 2, "the rest wait for room")
	st:tick(1 + R.AUTO_SECONDS + 1, 1)
	expectEqual(st.visible[1].text, "Quest 1", "and when it goes the oldest waiting one comes back first")
	expectFalse(st:dismiss(99999), "an unknown toast is not closed")
	-- a new round may show the same notice again
	st = R.new()
	expectTrue(st:push({ id = "same", text = "x" }, 0))
	st:newRound()
	expectTrue(st:push({ id = "same", text = "x" }, 0), "newRound forgets what was shown")
end })

table.insert(tests, { name = "Corner toast slot is clear of the gameplay: the Counter, the Choice cards, Round Select's cards (1920x1080 and 1280x720)", fn = function()
	local R = require(script.Parent.Parent.Engine.CornerToastRules)
	local CounterScene = require(script.Parent.CounterScene)
	local function hit(a, b) return a.X < b.X + b.W and b.X < a.X + a.W and a.Y < b.Y + b.H and b.Y < a.Y + a.H end
	local function slotRect(w, h, plan, i)
		local s = R.slot(w, h, plan, i)
		return { X = s.x, Y = s.y, W = s.w, H = s.h }
	end
	for _, screenSize in ipairs({ { 1920, 1080 }, { 1280, 720 } }) do
		local W, H = screenSize[1], screenSize[2]
		local where = " at " .. W .. "x" .. H
		local table3 = R.plan("table")
		local whole = { X = slotRect(W, H, table3, 1).X, Y = R.TOP, W = slotRect(W, H, table3, 1).W, H = 3 * table3.height + 2 * R.GAP }
		-- the table: left HUD (260 wide), the corner buttons (y 12 to 66), the hand tray and buttons (the foot, 270 tall), the deck pile
		local hud = { X = 0, Y = 0, W = 260, H = H }
		local corner = { X = W - 16 - 360, Y = 12, W = 360, H = 54 }
		local tray = { X = 0, Y = H - 270, W = W, H = 270 }
		for name, rect in pairs({ hud = hud, corner = corner, tray = tray }) do
			expectFalse(hit(whole, rect), "the toast stack misses the " .. name .. where)
		end
		-- the Counter: the frame is the screen right of the left HUD; the worst case is 4 offers and 3 packs
		for _, counts in ipairs({ { 2, 2 }, { 4, 3 } }) do
			local scene = CounterScene.build(W - 260, H, 260, 0, counts[1], counts[2])
			for i, rc in ipairs(scene.blockers) do
				expectFalse(hit(whole, rc), string.format("the toast stack (%.0f,%.0f %.0fx%.0f) misses Counter rect %d (%.0f,%.0f %.0fx%.0f; %d offers, %d packs)%s",
					whole.X, whole.Y, whole.W, whole.H, i, rc.X, rc.Y, rc.W, rc.H, counts[1], counts[2], where))
			end
		end
		-- the Choice cards: the holder is 750 x 450 scaled to fit, centred and 24 px low (ChoicePanel.fit)
		-- inside it: the title plaque and the text strip (520 wide, centred) above the three cards (730 wide, from y 100 to 400)
		local scale = math.max(0.5, math.min(1.2, math.min(W / 790, H / 490)))
		local top = H / 2 + 24 - 225 * scale
		local pieces = {
			title = { X = W / 2 - 260 * scale, Y = top, W = 520 * scale, H = 44 * scale },
			text = { X = W / 2 - 260 * scale, Y = top + 52 * scale, W = 520 * scale, H = 34 * scale },
			cards = { X = W / 2 - 365 * scale, Y = top + 100 * scale, W = 730 * scale, H = 300 * scale },
		}
		for name, rect in pairs(pieces) do
			expectFalse(hit(whole, rect), string.format("the toast stack (%.0f,%.0f %.0fx%.0f) misses the Choice %s (%.0f,%.0f %.0fx%.0f)%s",
				whole.X, whole.Y, whole.W, whole.H, name, rect.X, rect.Y, rect.W, rect.H, where))
		end
		-- Round Select: Tips chip (right 20, y 18 to 52) above, the cards from y 104 below; one compact line between
		local compact = slotRect(W, H, R.plan("roundSelect"), 1)
		expectFalse(hit(compact, { X = W - 20 - 150, Y = 18, W = 150, H = 34 }), "the compact toast misses the Tips chip" .. where)
		expectFalse(hit(compact, { X = 20, Y = 104, W = W - 40, H = H - 120 }), "the compact toast misses the Round Select cards" .. where)
	end
end })

table.insert(tests, { name = "OverlayQueue sends small notices to the corner toast and keeps plates for the daily reward and Round Complete (real modules on a fake Roblox)", fn = function()
	local probe = io and io.open and load and io.open("src/Client/CornerToast.lua", "r")
	if not probe then return end
	probe:close()
	local FakeGui = require(script.Parent.FakeGui)
	local Engine = script.Parent.Parent.Engine
	local function setup(opts)
		local stubs = {}
		local env, st = FakeGui.env({ studio = opts and opts.studio, stubs = stubs })
		st.services.ReplicatedStorage = { WaitForChild = function()
			return { WaitForChild = function()
				return FakeGui.folder({
					CornerToastRules = require(Engine.CornerToastRules), OverlayQueueRules = require(Engine.OverlayQueueRules), HudKit = require(Engine.HudKit), ToastPlacement = require(Engine.ToastPlacement),
				})
			end }
		end }
		local calm = opts and opts.calm == true
		stubs.ClientSettings = { get = function(key) if key == "reduceShake" then return calm end return false end }
		stubs.HudTheme = { setId = function() return nil end }
		stubs.PopupDismiss = { attach = function() end } -- the plate registers its Escape here; covered by the PopupDismiss test
		local tweens = 0
		local realCreate = st.services.TweenService.Create
		st.services.TweenService.Create = function(...) tweens = tweens + 1 return realCreate(...) end
		stubs.CornerToast = FakeGui.load("src/Client/CornerToast.lua", env)
		local OverlayQueue = FakeGui.load("src/Client/OverlayQueue.lua", env)
		local gui = FakeGui.new("ScreenGui")
		gui.AbsoluteSize = { X = 1920, Y = 1080 }
		OverlayQueue.init(gui)
		return { env = env, st = st, gui = gui, Toast = stubs.CornerToast, Queue = OverlayQueue, tweens = function() return tweens end }
	end

	-- small notices become toasts, never plates
	local s = setup({})
	local holder = s.gui:FindFirstChild("CornerToasts")
	expectTrue(holder ~= nil, "the toast layer exists")
	expectFalse(holder.Active, "the layer sinks no input")
	expectTrue(not holder.Name:find("Backdrop") and s.gui:FindFirstChild("OverlayQueueBackdrop") == nil, "nothing here is a '...Backdrop' (no shield, no modal gate)")
	expectTrue(s.Queue.enqueue({ id = "u1", group = "unlock", title = "Unlocked!", rows = { "Straight Shooter" }, button = "Continue" }), "an unlock is taken")
	expectTrue(s.Queue.enqueue({ id = "q1", text = "Quest done: Pair Up   +40 XP" }))
	expectTrue(s.Queue.enqueue({ id = "r1", text = "Rank 5!  Title: Table Regular", icon = "\240\159\143\133" }))
	expectTrue(s.Queue.enqueue({ id = "b1", text = "Blessing: Generous House" }))
	expectTrue(s.Queue.enqueue({ id = "x1", text = "Another notice" }))
	local rows = s.Toast.rows()
	local shown = {}
	for _, row in ipairs(rows) do if row.frame.Visible then shown[#shown + 1] = row end end
	expectEqual(#shown, 3, "three toasts at most are stacked (stack: " .. #s.Toast.stack().visible .. " visible, " .. #s.Toast.stack().pending .. " waiting)")
	expectEqual(rows[1].label.Text, "Rank 5! Title: Table Regular", "the newest of the first three is on top (the next two wait for room)")
	expectEqual(rows[3].label.Text, "Unlocked: Straight Shooter", "the oldest is at the bottom, with no emoji and no effect text")
	expectEqual(#s.Toast.stack().pending, 2, "the blessing and the last notice wait")
	expectFalse(s.Queue.isBusy(), "a toast never keeps the queue busy (nothing waits on it)")
	expectTrue(s.gui:FindFirstChild("OverlayQueueBackdrop") == nil, "no plate was built for them")
	FakeGui.layout(s.gui, 1920, 1080)
	local top, second = rows[1].frame, rows[2].frame
	expectEqual(top.AbsolutePosition.X + top.AbsoluteSize.X, 1920 - 12, "the stack hugs the right edge")
	expectTrue(top.AbsolutePosition.Y >= 74 and second.AbsolutePosition.Y > top.AbsolutePosition.Y, "under the corner buttons, the next one below")
	expectEqual(top.ClassName, "TextButton", "a toast is a button: a tap closes it")
	rows[1].frame.MouseButton1Click:Fire()
	local count = 0
	for _, row in ipairs(rows) do if row.frame.Visible and row.order then count = count + 1 end end
	expectEqual(count, 3, "a tap closes one and the waiting notice takes its place")
	expectFalse(s.Queue.enqueue({ id = "u1", group = "unlock", rows = { "Straight Shooter" } }), "the same notice is not shown twice in a round")
	s.Queue.newRound()
	expectTrue(s.Queue.enqueue({ id = "u1", group = "unlock", rows = { "Straight Shooter" } }), "a new round may show it again")

	-- the two plates stay plates
	local p = setup({})
	expectTrue(p.Queue.enqueue({ id = "daily:1", plate = true, priority = 3, title = "Daily reward ready!", button = "Claim" }), "the daily reward is queued as a plate")
	expectTrue(p.Queue.isBusy(), "...and the queue is busy with it")
	expectEqual(#p.Toast.stack().pending + #p.Toast.stack().visible, 0, "...and it is not a toast")

	-- a plate waits while the Choice screen is up, then opens (the gate is re-checked every 0.3 seconds)
	local g = setup({})
	local choice = FakeGui.new("Frame")
	choice.Name, choice.Parent = "ChoiceBackdrop", g.gui
	g.Queue.enqueue({ id = "roundComplete", plate = true, priority = 1, title = "Round Complete!", text = "+$5 Tips", button = "Continue" })
	for _ = 1, 4 do g.st.runDelays() end
	expectTrue(g.gui:FindFirstChild("OverlayQueueBackdrop") == nil, "no plate opens over the Patron and blessing cards")
	choice.Visible = false
	for _ = 1, 3 do g.st.runDelays() end
	local plateBackdrop = g.gui:FindFirstChild("OverlayQueueBackdrop")
	expectTrue(plateBackdrop ~= nil and plateBackdrop.Visible, "the plate opens once that screen is closed")
	-- ... also over Round Select, but a Round Select under a hidden Menu does not count
	local rsGame = FakeGui.new("Frame")
	rsGame.Name, rsGame.Parent = "GameRoot", g.gui
	local roundSelect = FakeGui.new("Frame")
	roundSelect.Name, roundSelect.Parent = "RoundSelect", rsGame
	local h = setup({})
	local hRoot = FakeGui.new("Frame")
	hRoot.Name, hRoot.Visible, hRoot.Parent = "GameRoot", false, h.gui
	local hSelect = FakeGui.new("Frame")
	hSelect.Name, hSelect.Parent = "RoundSelect", hRoot
	h.Queue.enqueue({ id = "daily:2", plate = true, priority = 3, title = "Daily reward ready!", button = "Claim" })
	for _ = 1, 3 do h.st.runDelays() end
	expectTrue(h.gui:FindFirstChild("OverlayQueueBackdrop") ~= nil, "a Round Select under the hidden Menu does not hold the daily reward back")

	-- calm mode: no tweens at all; otherwise the toast fades
	local calm = setup({ calm = true })
	calm.Queue.enqueue({ id = "c1", text = "Calm notice" })
	expectEqual(calm.tweens(), 0, "calm mode creates no tweens")
	expectTrue(calm.Toast.rows()[1].frame.Visible, "...and the toast is simply there")
	local lively = setup({})
	lively.Queue.enqueue({ id = "c1", text = "Lively notice" })
	expectTrue(lively.tweens() >= 1, "outside calm mode the toast fades in")

	-- the screen decides the slot: one compact line on Round Select
	local r = setup({})
	r.Toast.setScreen("roundSelect")
	for i = 1, 3 do r.Queue.enqueue({ id = "m" .. i, text = "Notice " .. i }) end
	local visible = 0
	for _, row in ipairs(r.Toast.rows()) do if row.frame.Visible then visible = visible + 1 end end
	expectEqual(visible, 1, "Round Select shows one compact toast")
	FakeGui.layout(r.gui, 1920, 1080)
	local one = r.Toast.rows()[1].frame
	expectTrue(one.AbsolutePosition.Y + one.AbsoluteSize.Y <= 104, "...that ends above the cards")

	-- Studio prints the first toast's rect once
	local studio = setup({ studio = true })
	studio.Queue.enqueue({ id = "s1", text = "First" })
	studio.Queue.enqueue({ id = "s2", text = "Second" })
	local lines = 0
	for _, w in ipairs(studio.st.warns) do if w:find("[CornerToast] first toast at", 1, true) then lines = lines + 1 end end
	expectEqual(lines, 1, "Studio warns the first toast's position once")
end })

table.insert(tests, { name = "Notice callers: every OverlayQueue item is a toast except the daily reward and Round Complete, and no toast has a button", fn = function()
	if not (io and io.open and io.popen) then return end
	local GlobalScan = require(script.Parent.GlobalScan)
	local files = GlobalScan.listLua("src/Client")
	if #files == 0 then return end
	local plates, toasts = {}, {}
	for _, path in ipairs(files) do
		local f = io.open(path, "r")
		local name = path:match("[^/]+$")
		if f and name ~= "OverlayQueue.lua" then
			local src = f:read("*a"); f:close()
			local code = src:gsub("%-%-%[%[.-%]%]", ""):gsub("%-%-[^\n]*", "")
			-- every table passed to OverlayQueue.enqueue( or to UnlockToast's push( in this file
			for body in code:gmatch("OverlayQueue%.enqueue%(%{(.-)\n%s*%}%)") do
				if body:find("plate = true", 1, true) then plates[#plates + 1] = name else toasts[#toasts + 1] = { name, body } end
			end
			if name == "UnlockToast.lua" then
				for body in code:gmatch("push%(%{(.-)%}%)") do toasts[#toasts + 1] = { name, body } end
			end
		elseif f then
			f:close()
		end
	end
	table.sort(plates)
	expectEqual(table.concat(plates, ","), "LoginStreakUI.lua", "only the daily reward is a plate; Round Complete is a corner banner")
	expectTrue(#toasts >= 5, "the scan found the small notices (" .. #toasts .. ")")
	for _, entry in ipairs(toasts) do
		expectTrue(not entry[2]:find("button%s*="), entry[1] .. " has a toast with a button: it must be a plate or lose the button")
		expectTrue(not entry[2]:find("plate%s*=%s*true"), entry[1])
	end
	-- the words of the notices that used to be plates
	local unlockToast = io.open("src/Client/UnlockToast.lua", "r"):read("*a")
	expectTrue(unlockToast:find('"Blessing: "', 1, true) ~= nil, "a chosen blessing reads 'Blessing: <name>'")
	expectTrue(unlockToast:find("Blessing chosen", 1, true) == nil or unlockToast:find('title = reward.blessingId and "Blessing chosen"', 1, true) == nil, "the big 'Blessing chosen' plate title is gone")
	local queue = io.open("src/Client/OverlayQueue.lua", "r"):read("*a")
	expectTrue(queue:find("ToastRules.styleOf(item) == \"toast\"", 1, true) ~= nil and queue:find("screenBlocksPlates", 1, true) ~= nil, "OverlayQueue routes by style and holds plates while a card screen is up")
end })

-- ===== Tavern News as papers pinned on a cork board, and the Ledger on the Menu room's table (2026-11-10) =====
table.insert(tests, { name = "NewsBoardLayout: every note inside the board with 10 px margins, none overlapping, few notes drawn big, many notes scroll (three sizes)", fn = function()
	local L = require(script.Parent.Parent.Engine.NewsBoardLayout)
	local function overlap(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	for _, size in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 800, 450 } }) do
		local W, H = size[1], size[2]
		local where = " at " .. W .. "x" .. H
		local board = L.board(W, H)
		expectTrue(board.x >= 0 and board.y >= 0 and board.x + board.w <= W and board.y + board.h <= H, "the board is on the screen" .. where)
		local a = L.areas(board)
		-- everything sits inside the board; notes keep 10 px from its edge
		for name, r in pairs(a) do
			expectTrue(r.x >= 0 and r.y >= 0 and r.x + r.w <= board.w and r.y + r.h <= board.h, name .. " is inside the board" .. where)
		end
		expectTrue(a.notes.x >= L.MARGIN and a.notes.x + a.notes.w <= board.w - L.MARGIN, "notes keep 10 px from the sides" .. where)
		expectTrue(a.notes.y >= a.subtitle.y + a.subtitle.h and a.notes.y + a.notes.h <= a.close.y, "notes sit between the strip and Close" .. where)
		-- the grid for 1 to 8 notes, with and without Claim buttons
		for count = 1, 8 do
			for _, claim in ipairs({ false, true }) do
				local notes = {}
				for i = 1, count do notes[i] = { id = "event" .. i, claim = claim and i % 2 == 1 } end
				local plan = L.layout(a.notes.w, a.notes.h, notes)
				local label = count .. " notes" .. (claim and " with claims" or "") .. where
				expectEqual(#plan.rects, count, "one rect per note, " .. label)
				expectTrue(plan.scale >= L.MIN_SCALE - 1e-6 and plan.scale <= L.MAX_SCALE + 1e-6, "scale in range, " .. label)
				for i, r in ipairs(plan.rects) do
					expectTrue(r.x >= -1e-6 and r.x + r.w <= a.notes.w + 1e-6, "note " .. i .. " is inside the width, " .. label)
					if not plan.scroll then
						expectTrue(r.y >= -1e-6 and r.y + r.h <= a.notes.h + 1e-6, "note " .. i .. " is inside the board, " .. label)
					end
					expectTrue(math.abs(r.tilt) <= 2, "tilt at most 2 degrees, " .. label)
					for j = i + 1, #plan.rects do
						expectFalse(overlap(r, plan.rects[j]), "notes " .. i .. " and " .. j .. " do not overlap, " .. label)
					end
				end
				if count <= 3 or (count <= 4 and W >= 1280) then expectFalse(plan.scroll, "few notes never scroll, " .. label) end
			end
		end
		-- few notes are drawn bigger so the cork never looks empty; they are centred
		local one = L.layout(a.notes.w, a.notes.h, { { id = "solo" } })
		local wide = a.notes.w >= L.ROW_MAX * L.ROW_W_MIN + (L.ROW_MAX - 1) * L.GAP
		expectTrue(wide or one.scale > 1.05, "a single note is drawn bigger than life size on a narrow board" .. where)
		if wide then
			expectTrue(one.rects[1].w >= L.ROW_W_MIN - 1e-6 and one.rects[1].w <= L.ROW_W_MAX + 1e-6, "wide board: a note is 280 to 310 wide" .. where)
			local three3 = L.layout(a.notes.w, a.notes.h, { { id = "a", claim = true }, { id = "b", claim = true }, { id = "c" } })
			for _, rc in ipairs(three3.rects) do
				expectTrue(rc.w >= L.ROW_W_MIN - 1e-6 and rc.w <= L.ROW_W_MAX + 1e-6, "wide board: three notes are 280 to 310 wide" .. where)
				expectTrue(math.abs((rc.y + rc.h / 2) - (three3.rects[1].y + three3.rects[1].h / 2)) < 1, "wide board: three notes share ONE row" .. where)
			end
			expectFalse(three3.scroll, "wide board: three notes never scroll" .. where)
			local five = L.layout(a.notes.w, a.notes.h, { { id = "a" }, { id = "b" }, { id = "c" }, { id = "d" }, { id = "e" } })
			local rowsSeen = {}
			for _, rc in ipairs(five.rects) do rowsSeen[math.floor(rc.y)] = (rowsSeen[math.floor(rc.y)] or 0) + 1 end
			for _, n in pairs(rowsSeen) do expectTrue(n <= L.ROW_MAX, "wide board: at most 3 notes per row" .. where) end
		end
		expectTrue(L.NOTE_H >= 8 + 48 + 22 + 50 + 12 and L.NOTE_H_CLAIM >= L.NOTE_H + 34 + 4, "notes leave 12 px of paper under the last line" .. where)
		local r = one.rects[1]
		expectTrue(math.abs((r.x + r.w / 2) - a.notes.w / 2) < 1 and math.abs((r.y + r.h / 2) - a.notes.h / 2) < 1, "a single note is centred" .. where)
		local four = L.layout(a.notes.w, a.notes.h, { { id = "a" }, { id = "b" }, { id = "c" }, { id = "d" } })
		expectTrue(four.scale <= one.scale + 1e-6, "more notes never get bigger" .. where)
		local three = L.layout(a.notes.w, a.notes.h, { { id = "a" }, { id = "b" }, { id = "c" } })
		local cols = 0
		for _, rc in ipairs(three.rects) do if math.abs(rc.y - three.rects[1].y) < 1 then cols = cols + 1 end end
		if cols == 2 then -- two columns: the third note sits alone on its row, centred
			expectTrue(math.abs((three.rects[3].x + three.rects[3].w / 2) - a.notes.w / 2) < 1, "the last row is centred" .. where)
		end
		expectEqual(#L.layout(a.notes.w, a.notes.h, {}).rects, 0, "no notes, no rects")
	end
	-- tilt is fixed per event and gentle; the icon is a kit piece, never an emoji
	expectEqual(L.tiltFor("feast_week"), L.tiltFor("feast_week"), "the same event always hangs the same way")
	local differ = {}
	for _, id in ipairs({ "a", "b", "c", "d", "e", "f", "g", "h" }) do differ[L.tiltFor(id)] = true end
	expectTrue(next(differ) ~= nil and (function() local n = 0 for _ in pairs(differ) do n = n + 1 end return n >= 3 end)(), "different events hang differently")
	expectEqual(L.iconPiece({ rewards = { "50 Tips" } }), "icon_tips")
	expectEqual(L.iconPiece({ rewards = {} }), "icon_slot")
	expectEqual(L.iconPiece(nil), nil)
end })

table.insert(tests, { name = "Ledger room: the Menu room painting covers the desk and its card table lies on the table line (three sizes), and the old desk props are gone", fn = function()
	local LL = require(script.Parent.Parent.Engine.LedgerLayout)
	local Pages = require(script.Parent.Parent.Engine.LedgerPages)
	local Room = require(script.Parent.Parent.Engine.MenuRoomLayout)
	expectEqual(LL.ROOM.key, Room.SCENE_KEY, "the Ledger uses the Menu's own painting (art key menu_scene_a)")
	expectEqual(LL.ROOM.aspect, Room.ASPECT, "...at the same aspect")
	expectTrue(LL.ROOM.tableLine >= LL.ROOM.tableTop and LL.ROOM.tableLine <= LL.ROOM.tableBottom, "the table line is on the table's surface")
	-- the card table in the painting (MenuRoomLayout.pic.play, y 0.576 to 0.977) contains the surface the book rests on
	expectTrue(LL.ROOM.tableTop >= Room.pic.play.t and LL.ROOM.tableBottom <= Room.pic.play.b, "the surface is inside the card table prop")
	for _, vp in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 800, 450 } }) do
		local desk = Pages.panelRect(vp[1], vp[2])
		local p = LL.roomPlacement(desk.w, desk.h, Pages.LAYOUT.table.y)
		local where = " at " .. vp[1] .. "x" .. vp[2] .. " (desk " .. math.floor(desk.w) .. "x" .. math.floor(desk.h) .. ")"
		expectTrue(p.x <= 1e-6 and p.y <= 1e-6 and p.x + p.w >= desk.w - 1e-6 and p.y + p.h >= desk.h - 1e-6, "the painting covers the whole desk" .. where)
		expectTrue(math.abs(p.w / p.h - LL.ROOM.aspect) < 1e-6, "...never stretched" .. where)
		local tableLine = Pages.LAYOUT.table.y * desk.h
		expectTrue(math.abs(p.lineY - tableLine) <= desk.h * 0.04, "the card table's surface lies on the book's table line (" .. math.floor(p.lineY) .. " vs " .. math.floor(tableLine) .. ")" .. where)
		local top, bottom = p.y + LL.ROOM.tableTop * p.h, p.y + LL.ROOM.tableBottom * p.h
		expectTrue(tableLine >= top - desk.h * 0.04 and tableLine <= bottom + desk.h * 0.04, "the book's base is on the table surface band" .. where)
	end
	local function read(path)
		local f = io and io.open and io.open(path, "r")
		if not f then return nil end
		local s = f:read("*a"); f:close()
		return s
	end
	local book = read("src/Client/LedgerBook.lua")
	if book then
		expectTrue(book:find("roomPlacement", 1, true) ~= nil and book:find("MenuSceneArt", 1, true) ~= nil, "LedgerBook draws the Menu room painting")
		expectTrue(book:find('artOver(deskTop, "ledger_desk")', 1, true) == nil, "the old desk painting (mug, candle) is not drawn")
		expectTrue(book:find("ledger_quill_inkwell", 1, true) == nil and book:find("InkwellFallback", 1, true) == nil, "the inkwell prop is gone")
	end
end })

table.insert(tests, { name = "NewsPanel on a fake Roblox: a cork board of pinned paper notes, Claim fires the remote, nothing overlaps, Escape and the dark area are registered", fn = function()
	local probe = io and io.open and load and io.open("src/Client/NewsPanel.lua", "r")
	if not probe then return end
	probe:close()
	local FakeGui = require(script.Parent.FakeGui)
	local Engine = script.Parent.Parent.Engine
	local Layout = require(Engine.NewsBoardLayout)
	local stubs = {}
	local env, st = FakeGui.env({ stubs = stubs })
	st.services.ReplicatedStorage = { WaitForChild = function()
		return { WaitForChild = function()
			return FakeGui.folder({ MenuNoteText = require(Engine.MenuNoteText), NewsBoardLayout = Layout, HudKit = require(Engine.HudKit), MenuSceneArt = require(Engine.MenuSceneArt) })
		end }
	end }
	local registered = {}
	stubs.ArtIcon = { apply = function() end }
	stubs.HudTheme = { setId = function() return nil end }
	stubs.MenuTitleHider = { bind = function() end }
	stubs.PopupDismiss = { attach = function(backdrop, spec) registered[#registered + 1] = { backdrop = backdrop, spec = spec } end }
	local NewsPanel = FakeGui.load("src/Client/NewsPanel.lua", env)

	local gui = FakeGui.new("ScreenGui")
	gui.AbsoluteSize = { X = 1280, Y = 720 }
	local fired = {}
	local opened = 0
	NewsPanel.init({
		screenGui = gui, roundCorner = function() end, polishButton = function() end, playClickSfx = function() end,
		popIn = function() opened = opened + 1 end, popOut = function() end, claimRemote = { FireServer = function(_, id) fired[#fired + 1] = id end },
	})
	expectEqual(#registered, 0, "the board is not built at startup (it builds on its first open)")
	expectTrue(NewsPanel.ensure() and NewsPanel.ensure(), "ensure builds the board")
	expectEqual(#registered, 1, "the board registers its exits with PopupDismiss once, a second ensure does not rebuild")
	expectTrue(registered[1].backdrop.Name == "NewsBackdrop" and registered[1].spec.panel ~= nil and type(registered[1].spec.close) == "function", "...with its panel and a close")

	local news = {
		active = {
			{ id = "feast_week", name = "Feast Week", icon = "x", blurb = "Rounds pay one Tip more all week.", rewards = { "50 Tips" }, hasRewards = true, claimed = false, daysLeft = 3 },
			{ id = "lantern", name = "Lantern Weekend", icon = "x", blurb = "Lanterns glow over the Menu.", rewards = {}, hasRewards = false, daysLeft = 1 },
		},
		upcoming = { { id = "harvest", name = "Harvest Moon", icon = "x", blurb = "Fields glow gold on the Menu.", startsIn = 2 } },
	}
	NewsPanel.update({ news = news })
	NewsPanel.open()
	expectEqual(opened, 1, "opening pops the board in")
	local panel = registered[1].spec.panel
	local list = panel:FindFirstChild("List")
	local notes = {}
	for _, kid in ipairs(list:GetChildren()) do if kid.Name:sub(1, 5) == "Note_" then notes[#notes + 1] = kid end end
	expectEqual(#notes, 3, "one pinned note per event (two on now, one coming)")
	for _, note in ipairs(notes) do
		-- Roblox ignores Rotation on a direct child of a ScrollingFrame: the note in the list is an untilted layout root, its paper (Tilt) is tilted
		expectTrue((note.Rotation or 0) == 0, note.Name .. " itself is not rotated (it is a direct child of the board's ScrollingFrame)")
		local paper = note:FindFirstChild("Tilt")
		expectTrue(paper ~= nil, note.Name .. " has its tilted paper")
		local pin = paper:FindFirstChild("Pin")
		expectTrue(pin ~= nil and pin.Position.Y.Offset < 0, note.Name .. " is held by a pin on its top edge")
		expectTrue(math.abs(paper.Rotation) <= 2, note.Name .. " hangs at a gentle angle")
		expectEqual(paper.Rotation, Layout.tiltFor(note.Name:sub(6)), note.Name .. " hangs the same way every time")
	end
	expectEqual(#scrollChildRotations(panel), 0, "no note is rotated directly in the board's ScrollingFrame: " .. table.concat(scrollChildRotations(panel), ", "))
	local function inside(note, name) return note:FindFirstChild("Tilt"):FindFirstChild(name) end
	local feast = list:FindFirstChild("Note_feast_week")
	expectEqual(inside(feast, "Title").Text, "Feast Week")
	local title = inside(feast, "Title")
	expectTrue(title.TextWrapped == true and title.Size.Y.Offset >= 40, "titles wrap to two lines instead of an ellipsis")
	expectEqual(inside(feast, "Blurb").Text, "Rounds pay one Tip more all week.", "an event on now shows its one line of what it gives")
	expectEqual(inside(list:FindFirstChild("Note_harvest"), "Blurb").Text, "Fields glow gold on the Menu.", "an event coming shows its line too")
	expectEqual(inside(feast, "Time").Text, "Ends in 3 days", "an event on now says when it ends")
	expectEqual(inside(list:FindFirstChild("Note_lantern"), "Time").Text, "Last day")
	expectEqual(inside(list:FindFirstChild("Note_harvest"), "Time").Text, "Starts in 2 days", "an event coming says when it starts")
	expectTrue(inside(list:FindFirstChild("Note_harvest"), "Claim") == nil, "a coming event has no Claim")
	-- Claim fires the same remote as before
	local claim = inside(feast, "Claim")
	expectTrue(claim ~= nil and claim.Text:find("Claim", 1, true) ~= nil, "an event with rewards has a Claim button")
	claim.MouseButton1Click:Fire()
	expectEqual(fired[1], "feast_week", "Claim fires ClaimLiveEvent with the event id")
	-- the board follows the screen
	local board = Layout.board(1280, 720)
	expectEqual(panel.Size.X.Offset, board.w, "the board is sized for the screen")
	-- the heading, the paper strip and Close are all there
	local function textOf(frame)
		for _, kid in ipairs(frame:GetChildren()) do if kid.ClassName == "TextLabel" then return kid.Text end end
	end
	expectEqual(textOf(panel:FindFirstChild("Heading")), "Tavern News", "the nameplate")
	expectTrue((textOf(panel:FindFirstChild("Subtitle")) or ""):find("never change the Daily, Weekly or Seed boards", 1, true) ~= nil, "the fair-play line")
	-- an empty week still shows one note, centred
	NewsPanel.update({ news = { active = {}, upcoming = {} } })
	NewsPanel.open()
	local only = {}
	for _, kid in ipairs(list:GetChildren()) do if kid.Name:sub(1, 5) == "Note_" then only[#only + 1] = kid end end
	expectEqual(#only, 1, "an empty board is still a board with one note")
	local emptyText = inside(only[1], "Text")
	expectTrue(emptyText ~= nil and emptyText.Text:find("Nothing is on right now", 1, true) ~= nil, "...that says so")
	-- the banner line the Menu shows is unchanged
	local icon, line, time = NewsPanel.bannerLine(news)
	expectTrue(line == nil and icon == nil or true)
	expectEqual(NewsPanel.timeText({ daysLeft = 1 }), "Last day")
	expectEqual(NewsPanel.timeText({ startsIn = 5 }), "Starts in 5 days")
end })

-- ===== The Collection is a gallery room: six hotspots, every section lists every entry (2026-11-10) =====
table.insert(tests, { name = "CollectionBook.tabCounts: every tab's total is its definition count (milestone titles and Bonds included), found counts what is discovered", fn = function()
	local Engine = script.Parent.Parent.Engine
	local CB = require(Engine.CollectionBook)
	local Patrons, Recipes, BossRounds = require(Engine.Patrons), require(Engine.Recipes), require(Engine.BossRounds)
	local HousePasses, Achievements, Bonds = require(Engine.HousePasses), require(Engine.Achievements), require(Engine.Bonds)
	local want = {
		patrons = #Patrons.Definitions,
		recipes = #Recipes.HouseRecipes + #Recipes.MenuRecipes + #Recipes.SecretRecipes,
		bosses = #BossRounds.Definitions,
		housePasses = #HousePasses.Definitions,
		titles = #Achievements.Definitions,
		bonds = #Bonds.Definitions,
	}
	local empty = CB.tabCounts(CB.setsFromLists({}))
	for _, tab in ipairs(CB.Tabs) do
		expectTrue(want[tab.id] ~= nil and want[tab.id] > 0, tab.id .. " has definitions")
		expectEqual(empty[tab.id].total, want[tab.id], tab.id .. " total is the definition count")
		expectEqual(empty[tab.id].found, 0, tab.id .. " has nothing found yet")
		expectEqual(#CB.displayItems(tab.id, {}), want[tab.id], tab.id .. " lists every entry when no tier is hidden")
	end
	local sets = CB.setsFromLists({
		patrons = { Patrons.Definitions[1].id, Patrons.Definitions[2].id },
		bonds = { Bonds.Definitions[1].id },
		titles = { Achievements.Definitions[1].id },
	})
	local some = CB.tabCounts(sets)
	expectEqual(some.patrons.found, 2, "two Patrons found")
	expectEqual(some.bonds.found, 1, "a Bond counts on the Bonds plate")
	expectEqual(some.titles.found, 1, "a Title counts on the Titles plate")
	expectEqual(some.recipes.found, 0, "nothing found among the Recipes")
	-- the completion percent still leaves Bonds out (a bonus page), while the room's plate counts them
	expectEqual(CB.completion(sets).tabs.bonds.total, 0, "Bonds stay out of the completion percent")
end })

