table.insert(tests, { name = "CollectionRoomLayout.rects: six hotspots (object plus name plate) inside the room, none overlapping, at three sizes and a phone", fn = function()
	local Engine = script.Parent.Parent.Engine
	local RL, RS = require(Engine.CollectionRoomLayout), require(Engine.ResponsiveLayout)
	local rooms = {}
	for _, vp in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 800, 450 }, { 390, 700 } }) do
		local fit = RS.collectionPanel(vp[1], vp[2])
		local W, H = math.floor(fit.w * vp[1]), math.floor(fit.h * vp[2])
		local P = RL.panel(W, H, vp[1] < 500 and 62 or 24, nil)
		rooms[#rooms + 1] = { name = vp[1] .. "x" .. vp[2], w = P.area.w, h = P.area.h }
	end
	for _, room in ipairs(rooms) do
		local R = RL.rects(room.w, room.h)
		local where = " (" .. room.name .. ", room " .. room.w .. "x" .. room.h .. ")"
		expectEqual(#R.order, 6, "six hotspots" .. where)
		expectEqual(R.cols * R.rows >= 6, true, "the grid holds six" .. where)
		for _, id in ipairs(R.order) do
			local s = R.spots[id]
			expectTrue(s ~= nil, id .. " has a hotspot" .. where)
			for _, part in ipairs({ "object", "plate", "hit" }) do
				expectTrue(RL.inside(s[part], room.w, room.h), id .. " " .. part .. " is inside the room" .. where)
				expectTrue(s[part].w > 0 and s[part].h > 0, id .. " " .. part .. " has a size" .. where)
			end
			expectTrue(s.object.h >= 40, id .. " object is big enough to hit and to read" .. where)
			expectTrue(s.plate.h >= 24 and s.plate.w >= 140, id .. " name plate holds '" .. RL.plateText("House Passes", 12, 12) .. "'" .. where)
			expectTrue(s.plate.y >= s.object.y + s.object.h, id .. " plate sits under its object" .. where)
			expectTrue(RL.inside(s.object, s.hit.x + s.hit.w, s.hit.y + s.hit.h) and s.hit.x <= s.object.x and s.hit.x <= s.plate.x, id .. " hit covers object and plate" .. where)
		end
		for i = 1, #R.order do
			for j = i + 1, #R.order do
				expectFalse(RL.intersects(R.spots[R.order[i]].hit, R.spots[R.order[j]].hit), R.order[i] .. " and " .. R.order[j] .. " do not overlap" .. where)
			end
		end
	end
	expectEqual(RL.rects(738, 233).cols, 3, "a wide room is three across")
	expectEqual(RL.rects(344, 400).cols, 2, "a phone room is two across")
end })

-- The real Collection panel (Client/Collection.lua) on the fake Roblox, with some entries found in every section.
local function collectionBuild(extra)
	if not (io and io.open and load) then return nil end
	local probe = io.open("src/Client/Collection.lua", "r")
	if not probe then return nil end
	probe:close()
	local CS = require(script.Parent.CollectionScene)
	local CB = require(script.Parent.Parent.Engine.CollectionBook)
	local discovered, titles = {}, {}
	for _, tab in ipairs(CB.Tabs) do
		local ids = {}
		for i, item in ipairs(CB.itemsFor(tab.id)) do
			if i <= 2 then ids[#ids + 1] = item.id end
		end
		if tab.id == "titles" then titles = ids elseif tab.profileField then discovered[tab.id] = ids end
	end
	local opts = { discovered = discovered, unlockedAchievementIds = titles }
	for k, v in pairs(extra or {}) do opts[k] = v end
	return CS.build(opts), CB, discovered, titles
end

local function visibleLabel(root, text) -- a TextLabel under root that shows `text` and is not hidden by any ancestor up to root
	for _, d in ipairs(root:GetDescendants()) do
		if d.ClassName == "TextLabel" and d.Text == text then
			local hidden, p = false, d
			while p and p ~= root do
				if p.Visible == false then hidden = true end
				p = p.Parent
			end
			if not hidden and root.Visible ~= false then return d end
		end
	end
	return nil
end

table.insert(tests, { name = "Collection opens on the gallery room: six hotspots with count plates, a quiet row of small tab plates, a wooden rarity plate", fn = function()
	local col, CB = collectionBuild()
	if not col then return end
	local RL = require(script.Parent.Parent.Engine.CollectionRoomLayout)
	col.open()
	expectTrue(col.backdrop.Visible, "the Collection is open")
	expectTrue(col.room.Visible, "the gallery room is the first view")
	expectFalse(col.grid.Visible, "the section grid waits behind it")
	local sets = CB.setsFromLists({ patrons = col.latest.collection.discovered.patrons, recipes = col.latest.collection.discovered.recipes,
		bosses = col.latest.collection.discovered.bosses, housePasses = col.latest.collection.discovered.housePasses,
		bonds = col.latest.collection.discovered.bonds, titles = col.latest.unlockedAchievementIds })
	local counts = CB.tabCounts(sets)
	for i, tab in ipairs(CB.Tabs) do
		local hot = col.hotspot(tab.id)
		expectTrue(hot ~= nil, tab.name .. " has a hotspot in the room")
		expectEqual(hot:GetChildren()[1] ~= nil, true)
		local surface = hot:FindFirstChild("Surface")
		expectTrue(surface ~= nil and surface.ClassName == "TextButton", tab.name .. " hotspot has a clickable surface")
		local top = true
		for _, d in ipairs(hot:GetDescendants()) do
			if d.ClassName ~= "UICorner" and d.ZIndex and d ~= surface and d.ZIndex >= surface.ZIndex then top = false end
		end
		expectTrue(top, tab.name .. " surface sits above everything drawn in its hotspot")
		local label = hot:FindFirstChild("NamePlate"):FindFirstChild("Label")
		expectEqual(label.Text, RL.plateText(tab.name, counts[tab.id].found, counts[tab.id].total), tab.name .. " plate carries its count")
		expectEqual(counts[tab.id].found, 2, tab.name .. " shows the two entries this test found")
		expectTrue(label.TextSize >= 14, tab.name .. " plate text is at least 14")
		expectFalse(label.Text:find("%?") ~= nil, "no question marks on a plate")
	end
	-- the quiet row: "< Gallery" and the six sections as small plates
	local plates = {}
	for _, c in ipairs(col.quiet:GetChildren()) do
		if c.ClassName == "TextButton" then plates[#plates + 1] = c end
	end
	table.sort(plates, function(a, b) return a.LayoutOrder < b.LayoutOrder end)
	expectEqual(#plates, 7, "a Gallery plate and one per section")
	expectEqual(plates[1].Text, "< Gallery")
	for i, tab in ipairs(CB.Tabs) do -- each tab plate carries its count pill: "Name  found / total"
		local counts = CB.tabCounts(col.view and col.view.sets or {})[tab.id]
		expectTrue(plates[i + 1].Text:sub(1, #tab.name + 2) == tab.name .. "  " and plates[i + 1].Text:find(" / %d+$") ~= nil,
			"quiet plate " .. i .. " reads '" .. tostring(plates[i + 1].Text) .. "'")
	end
	for _, p in ipairs(plates) do
		expectTrue(p.TextSize >= 14, p.Text .. " plate text is at least 14")
		expectTrue(p.Size.Y.Offset <= 28, p.Text .. " is a small plate")
	end
	-- the rarity filter is one wooden plate with a brass rim and six chips
	expectEqual(col.legend.BackgroundTransparency, 0, "the filter sits on a solid plate")
	expectTrue(col.legend:FindFirstChildOfClass("UIStroke") ~= nil, "...with a brass rim")
	local chips = 0
	for _, c in ipairs(col.legend:GetChildren()) do
		if c.Name:sub(1, 5) == "Chip_" then chips = chips + 1 end
	end
	expectEqual(chips, #CB.RarityOrder, "one chip per rarity tier")
	expectEqual(col.legend.AnchorPoint.Y, 1, "the plate hangs from the bottom of the panel")
	-- the chip names read on the wooden plate, checked and unchecked
	local LL = require(script.Parent.Parent.Engine.LedgerLayout)
	local function rgb255(c) return { math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5) } end
	local chip = col.legend:FindFirstChild("Chip_common")
	local nameLabel
	for _, c in ipairs(chip:GetChildren()) do
		if c.ClassName == "TextLabel" and c.Text == "Common" then nameLabel = c end
	end
	expectTrue(nameLabel ~= nil, "the Common chip names its tier")
	expectTrue(LL.contrast(rgb255(nameLabel.TextColor3), rgb255(col.legend.BackgroundColor3)) >= 4.5, "a checked tier's name reads on the wooden plate")
	chip.MouseButton1Click:Fire() -- unchecked
	expectTrue(LL.contrast(rgb255(nameLabel.TextColor3), rgb255(col.legend.BackgroundColor3)) >= 4.5, "an unchecked tier's name still reads (4.5:1)")
	chip.MouseButton1Click:Fire() -- checked again
	expectEqual(#col.state.warns, 0, "nothing warned while building: " .. table.concat(col.state.warns, " | "))
end })

table.insert(tests, { name = "Collection: every section lists ALL of its entries (count equals the definitions), locked ones as silhouettes with their name, no ??? and no blank note", fn = function()
	local col, CB, discovered, titles = collectionBuild()
	if not col then return end
	local Engine = script.Parent.Parent.Engine
	local want = {
		patrons = #require(Engine.Patrons).Definitions,
		recipes = #require(Engine.Recipes).HouseRecipes + #require(Engine.Recipes).MenuRecipes + #require(Engine.Recipes).SecretRecipes,
		bosses = #require(Engine.BossRounds).Definitions,
		housePasses = #require(Engine.HousePasses).Definitions,
		titles = #require(Engine.Achievements).Definitions,
		bonds = #require(Engine.Bonds).Definitions,
	}
	col.open()
	for _, tab in ipairs(CB.Tabs) do
		col.pick(tab.id)
		expectTrue(col.grid.Visible and not col.room.Visible, tab.name .. ": the section replaces the room")
		local tiles = col.tiles()
		local items = CB.displayItems(tab.id, {})
		expectEqual(#tiles, want[tab.id], tab.name .. ": one tile per definition")
		expectEqual(#tiles, #items, tab.name .. ": one tile per listed entry")
		-- Roblox ignores Rotation on a direct child of a ScrollingFrame: a tilted tile carries its angle on an inner Tilt wrapper
		expectEqual(#scrollChildRotations(col.panel), 0, tab.name .. ": no tile is rotated directly in the section's ScrollingFrame: " .. table.concat(scrollChildRotations(col.panel), ", "))
		if tab.id == "patrons" then
			local tilted = 0
			for _, tile in ipairs(tiles) do
				local wrap = tile:FindFirstChild("Tilt")
				expectTrue(wrap ~= nil, "Patron frame " .. tile.LayoutOrder .. " hangs on its Tilt wrapper")
				if wrap then
					expectTrue(math.abs(wrap.Rotation) <= 2, "...at a gentle angle")
					if wrap.Rotation ~= 0 then tilted = tilted + 1 end
				end
			end
			expectTrue(tilted > 0, "the Patron frames really hang at different angles")
		end
		local foundIds = {}
		for _, id in ipairs(tab.id == "titles" and titles or discovered[tab.id] or {}) do foundIds[id] = true end
		local locked, lit = 0, 0
		for _, tile in ipairs(tiles) do
			local item = items[tile.LayoutOrder]
			expectTrue(item ~= nil, tab.name .. ": tile " .. tostring(tile.LayoutOrder) .. " belongs to an entry")
			if item then
				local name = tab.id == "titles" and item.def.title or item.def.name
				expectTrue(visibleLabel(tile, name) ~= nil, tab.name .. ": '" .. tostring(name) .. "' is on its plate")
				expectTrue(visibleLabel(tile, "???") == nil, tab.name .. ": no ??? on " .. tostring(name))
				if tab.id ~= "titles" then -- titles are engraved plates without a picture
					local well = tile:FindFirstChild("IconWell", true)
					expectTrue(well ~= nil and well.Visible ~= false, tab.name .. ": '" .. tostring(name) .. "' keeps its picture (a dim silhouette when locked)")
				end
				if foundIds[item.id] then lit = lit + 1 else locked = locked + 1 end
			end
		end
		expectEqual(lit, 2, tab.name .. ": the two found entries are drawn lit")
		expectEqual(locked, want[tab.id] - 2, tab.name .. ": every other entry is drawn locked, not left out")
		expectEqual(#col.state.warns, 0, tab.name .. " built without a warning: " .. table.concat(col.state.warns, " | "))
		expectTrue(col.step(), tab.name .. ": Escape returns to the room")
	end
end })

table.insert(tests, { name = "LazyPanel: a panel is built on its first open only, the opener runs its handler, a second open never rebuilds", fn = function()
	if not (io and io.open) then return end
	local FakeGui = require(script.Parent.FakeGui)
	local stubs, openers = {}, {}
	stubs.OverlayManager = { registerOpener = function(id, fn) openers[id] = fn end }
	local env = FakeGui.env({ stubs = stubs })
	local Lazy = FakeGui.load("src/Client/LazyPanel.lua", env)
	local builds, opens = 0, 0
	local button = FakeGui.new("TextButton")
	local wrapped = Lazy.wrap("demo", function(deps)
		builds = builds + 1
		deps.openButton.MouseButton1Click:Connect(function() opens = opens + 1 end)
		openers.demo = function() opens = opens + 1 end -- a built panel replaces the stand-in opener
	end)
	wrapped({ openButton = button })
	expectEqual(builds, 0, "nothing is built at startup")
	expectTrue(openers.demo ~= nil, "the opener is registered at startup")
	button.MouseButton1Click:Fire()
	expectEqual(builds, 1, "the first click builds the panel")
	expectEqual(opens, 1, "and then opens it")
	button.MouseButton1Click:Fire()
	expectEqual(builds, 1, "a second click does not rebuild")
	expectEqual(opens, 2, "but opens again")
end })

table.insert(tests, { name = "LazyPanel: a group builds on any of its buttons or ids, the stand-in replaces every button, and the built panel's return value is kept", fn = function()
	if not (io and io.open) then return end
	local FakeGui = require(script.Parent.FakeGui)
	local stubs, openers, opened = {}, {}, {}
	stubs.OverlayManager = { registerOpener = function(id, fn) openers[id] = fn end, open = function(id) opened[#opened + 1] = id; if openers[id] then openers[id]() end end }
	local env = FakeGui.env({ stubs = stubs })
	local Lazy = FakeGui.load("src/Client/LazyPanel.lua", env)
	local builds, opens = 0, 0
	local a, b = FakeGui.new("TextButton"), FakeGui.new("TextButton")
	local lazy = Lazy.wrap("group", function(deps)
		builds = builds + 1
		local function open() opens = opens + 1 end
		openers.group, openers.child = open, open -- the built group registers its own pages
		deps.a.MouseButton1Click:Connect(open)
		deps.b.MouseButton1Click:Connect(open)
		return { notice = true }
	end, { "a", "b" }, { "child", "ghost" })({ a = a, b = b })
	expectEqual(builds, 0, "nothing built at startup")
	expectTrue(lazy.api() == nil, "no api before the first build")
	openers.child() -- the Menu opening a page of the group
	expectEqual(builds, 1, "opening a page id builds the group")
	expectEqual(opens, 1, "and then opens that page for real")
	expectTrue(lazy.api() ~= nil and lazy.api().notice, "the constructor's return value is kept")
	b.MouseButton1Click:Fire()
	expectEqual(builds, 1, "the second button does not rebuild")
	-- an id the group never registers must not loop
	openers.ghost()
	expectEqual(builds, 1, "an unregistered id does not rebuild or recurse")
end })

table.insert(tests, { name = "Collection: Escape and the Gallery plate step back (detail card, then section, then the room), a quiet plate goes to its section", fn = function()
	local col, CB = collectionBuild()
	if not col then return end
	col.open()
	expectFalse(col.step(), "in the room Escape has nothing to step back from, so it closes the Collection")
	col.pick("bosses")
	local tiles = col.tiles()
	tiles[1].MouseButton1Click:Fire()
	expectTrue(col.detail.Visible, "a click on an entry opens its detail card")
	expectTrue(col.step(), "Escape closes the detail card first")
	expectFalse(col.detail.Visible)
	expectTrue(col.grid.Visible, "...and stays in the section")
	expectTrue(col.step(), "the next Escape returns to the room")
	expectTrue(col.room.Visible and not col.grid.Visible)
	local function plate(text)
		for _, c in ipairs(col.quiet:GetChildren()) do
			if c.ClassName == "TextButton" and (c.Text == text or c.Text:sub(1, #text + 2) == text .. "  ") then return c end -- a tab plate carries its count ("Titles  3 / 20")
		end
	end
	plate("Titles").MouseButton1Click:Fire()
	expectTrue(col.grid.Visible and not col.room.Visible, "a quiet plate zooms into its section")
	plate("< Gallery").MouseButton1Click:Fire()
	expectTrue(col.room.Visible and not col.grid.Visible, "the Gallery plate returns to the room")
	-- reopening always starts at the room
	col.pick("recipes")
	col.open()
	expectTrue(col.room.Visible and not col.grid.Visible, "the Collection always opens on the room")
	expectEqual(#col.state.warns, 0, table.concat(col.state.warns, " | "))
	-- the rarity chips filter the section grid; they never drop an entry from the room's count
	col.pick("recipes")
	expectEqual(#col.tiles(), #CB.displayItems("recipes", {}))
	col.legend:FindFirstChild("Chip_common").MouseButton1Click:Fire()
	expectEqual(#col.tiles(), #CB.displayItems("recipes", { common = true }), "hiding Common leaves the other tiers")
	col.legend:FindFirstChild("Chip_common").MouseButton1Click:Fire()
	expectEqual(#col.tiles(), #CB.displayItems("recipes", {}), "showing it again brings them back")
	-- the wiring: Escape (PopupDismiss) asks the panel to step back before it closes it
	local function read(path)
		local f = io.open(path, "r")
		if not f then return nil end
		local s = f:read("*a")
		f:close()
		return s
	end
	local dismiss, tabs, collection = read("src/Client/PopupDismiss.lua"), read("src/Client/PanelTabs.lua"), read("src/Client/Collection.lua")
	if dismiss and tabs and collection then
		local escape = dismiss:match("function PopupDismiss%.escape%(%).-\nend\n")
		expectTrue(escape ~= nil and escape:find("entry.spec.step", 1, true) ~= nil and escape:find("return", 1, true) ~= nil, "Escape calls the popup's step and stops when it handled it")
		expectTrue(escape:find("entry.spec.step", 1, true) < escape:find('Rules.action(policyOf(entry), "escape")', 1, true), "...before the policy closes the popup")
		expectTrue(tabs:find("function PanelTabs.setStep(id, fn)", 1, true) ~= nil and tabs:find("step = function()", 1, true) ~= nil, "PanelTabs hands a panel's step to PopupDismiss")
		expectTrue(collection:find('setStep("collection", stepBack)', 1, true) ~= nil, "the Collection registers its step")
	end
end })

table.insert(tests, { name = "Shop cards on the table: a hovered card lifts 6 px and turns straight, leaving turns it back to its own angle, calm mode moves nothing, every card has a soft oval shadow", fn = function()
	local probe = io and io.open and load and io.open("src/Client/ShopCards.lua", "r")
	if not probe then return end
	probe:close()
	local FakeGui = require(script.Parent.FakeGui)
	local Engine = script.Parent.Parent.Engine
	local function build(calm)
		local env, st = FakeGui.env({ stubs = {
			RarityFrame = { apply = function() end },
			PatronPlaque = { applyById = function() return nil end },
			ClientSettings = { get = function(key) return calm == true and key == "reduceShake" end },
			ModalStage = { blocks = function() return false end },
		} })
		env.workspace = { CurrentCamera = { ViewportSize = { X = 1280, Y = 720 } } }
		local folder = FakeGui.folder({ CollectionBook = require(Engine.CollectionBook), ContentArt = require(Engine.ContentArt),
			CardShape = require(Engine.CardShape), ShopSceneLayout = require(Engine.ShopSceneLayout), ChoiceRarity = require(Engine.ChoiceRarity), AbilityText = require(Engine.AbilityText), Gameplay2Synergy = require(Engine.Gameplay2Synergy) })
		st.services.ReplicatedStorage = { WaitForChild = function() return { WaitForChild = function() return folder end } end }
		local tweens = {}
		st.services.TweenService.Create = function(_, inst, _, goal)
			tweens[#tweens + 1] = { inst = inst, goal = goal }
			return { Play = function() end, Cancel = function() end, Completed = FakeGui.signal() }
		end
		local ShopCards = FakeGui.load("src/Client/ShopCards.lua", env)
		ShopCards.setScale(1)
		local cards = ShopCards.new({ playClickSfx = function() end })
		local parent = FakeGui.new("Frame")
		local row = cards.row(parent, 1, 340)
		local card = cards.card(row, { kind = "patron", name = "Regular's Chair", description = "A seat.", price = 5, affordable = true,
			actionText = "Buy", enabled = true, onAction = function() return true end })
		return card, tweens, st
	end
	local function lastTween(tweens, inst)
		for i = #tweens, 1, -1 do
			if tweens[i].inst == inst then return tweens[i].goal end
		end
	end
	local card, tweens, st = build(false)
	local slot = card.slot
	-- the slot is the layout root in a ScrollingFrame row (it ignores Rotation there), the card is tilted on its inner wrapper
	local wrapper = slot:FindFirstChild("Tilt")
	expectTrue(wrapper ~= nil and wrapper == card.tilt and wrapper.Parent == slot, "the card has an inner Tilt wrapper")
	expectTrue(wrapper.Size.X.Scale == 1 and wrapper.Size.Y.Scale == 1 and wrapper.BackgroundTransparency == 1, "...full size and transparent")
	expectTrue(card.body.Parent == wrapper and slot:FindFirstChild("Body") == nil, "the card's body lives inside the wrapper, not in the row")
	for _, kid in ipairs(slot:GetChildren()) do
		expectTrue(kid == wrapper or kid.ClassName ~= "Frame", "nothing but the wrapper sits in the slot (a Frame beside it would not tilt)")
	end
	wrapper.Rotation = -5
	slot:SetAttribute("Tilt", -5) -- ShopStage deals it like this
	-- a soft oval shadow on the felt under the card's lower edge
	local contact = wrapper:FindFirstChild("ContactShadow")
	expectTrue(contact ~= nil and contact.Active == false and contact.BackgroundTransparency >= 0.5, "the card has a soft contact shadow")
	local c = contact:FindFirstChildOfClass("UICorner")
	expectTrue(c ~= nil and c.CornerRadius.Offset * 2 >= contact.Size.Y.Offset, "...an oval (a pill as tall as its corners)")
	expectTrue(contact.Size.Y.Offset <= 24 and contact.Size.X.Offset <= slot.Size.X.Offset, "...flat, and no wider than the card")
	card.hit.MouseEnter:Fire()
	local up, turn = lastTween(tweens, card.body), lastTween(tweens, wrapper)
	expectTrue(up ~= nil and up.Position.Y.Offset == 16 - 6, "the hovered card lifts 6 px (from 16 to 10)")
	expectTrue(turn ~= nil and turn.Rotation == 0, "...and its Tilt wrapper turns straight")
	expectEqual(lastTween(tweens, slot), nil, "the slot itself is never tweened (a direct child of the row ignores it)")
	card.hit.MouseLeave:Fire()
	st.runDelays() -- the leave settles 0.06 s later
	up, turn = lastTween(tweens, card.body), lastTween(tweens, wrapper)
	expectTrue(up.Position.Y.Offset == 16, "leaving puts it back down")
	expectEqual(turn.Rotation, -5, "...and back to its own angle")
	-- calm mode: the card stays exactly where it lies
	local calmCard, calmTweens, calmState = build(true)
	calmCard.slot:SetAttribute("Tilt", 4)
	calmCard.hit.MouseEnter:Fire()
	calmCard.hit.MouseLeave:Fire()
	calmState.runDelays()
	expectEqual(lastTween(calmTweens, calmCard.body), nil, "calm mode: no lift")
	expectEqual(lastTween(calmTweens, calmCard.tilt), nil, "calm mode: no turn")
	-- the source says the same
	local f = io.open("src/Client/ShopCards.lua", "r")
	local src = f:read("*a")
	f:close()
	expectTrue(src:find("local LIFT = 6", 1, true) ~= nil, "the lift is 6 px")
end })

-- ===== The Badges panel is a trophy room: four hotspots, the Roads medals hang on the map (2026-11-11) =====
local function badgeWindows() -- the panel and the area under the quiet row, at the three window sizes
	local Engine = script.Parent.Parent.Engine
	local BRL, RS = require(Engine.BadgeRoomLayout), require(Engine.ResponsiveLayout)
	local out = {}
	for _, vp in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 800, 450 } }) do
		local f = RS.badgesPanel(vp[1], vp[2])
		local W, H = f.w, math.max(f.h, math.floor(vp[2] * 0.84)) -- BadgesPanel sizes the panel like this
		out[#out + 1] = { name = vp[1] .. "x" .. vp[2], vp = vp, W = W, H = H, P = BRL.panel(W, H) }
	end
	return out
end

table.insert(tests, { name = "BadgeRoomLayout: four shelves with their counts, and the plaque, quiet row, room and Close stack without overlap, hotspots inside the room and apart (three sizes)", fn = function()
	local Engine = script.Parent.Parent.Engine
	local BRL, B, W = require(Engine.BadgeRoomLayout), require(Engine.Badges), require(Engine.BadgeWallLayout)
	expectEqual(#BRL.SECTIONS, #B.Chips - 1, "one hotspot per shelf: All is the room itself")
	for i, s in ipairs(BRL.SECTIONS) do expectEqual(s.id, B.Chips[i + 1], "section " .. i .. " is the " .. tostring(s.id) .. " shelf") end
	local none = W.sectionCounts({})
	expectEqual(none.Roads.total, 8, "eight road badges")
	expectEqual(none.Masters.total, 8, "eight master badges")
	expectEqual(none.Night.total, 4, "four Night badges")
	expectEqual(none.Special.total, 12, "twelve special badges")
	expectEqual(none.Roads.total + none.Masters.total + none.Night.total + none.Special.total, #B.Definitions, "the four shelves hold all 32 badges")
	local some = W.sectionCounts({ biome_meadow = true, biome_river = true, night_3 = true, wins_1 = true, wins_5 = true, wins_25 = true })
	expectTrue(some.Roads.found == 2 and some.Night.found == 1 and some.Special.found == 3 and some.Masters.found == 0, "earned badges count on their own shelf")
	expectEqual(BRL.plateText("Roads", 2, 8), "Roads 2/8")
	for _, win in ipairs(badgeWindows()) do
		local P, where = win.P, " (" .. win.name .. ", panel " .. win.W .. "x" .. win.H .. ")"
		local list = { "plaque", "tabs", "area", "close" }
		for _, name in ipairs(list) do
			expectTrue(BRL.inside(P[name], win.W, win.H) and P[name].w > 0 and P[name].h > 0, name .. " is inside the panel" .. where)
		end
		for i = 1, #list do
			for j = i + 1, #list do expectFalse(BRL.intersects(P[list[i]], P[list[j]]), list[i] .. " and " .. list[j] .. " do not overlap" .. where) end
		end
		expectTrue(P.plaque.h <= 48 and P.plaque.w <= 360, "the header is a small plaque" .. where)
		expectTrue(P.tabs.h <= 28, "the tab row is a quiet row of small plates" .. where)
		expectTrue(P.area.h >= 150, "the room has height to work with" .. where)
		local R = BRL.rects(P.area.w, P.area.h)
		expectEqual(#R.order, 4, "four hotspots" .. where)
		for _, id in ipairs(R.order) do
			local s = R.spots[id]
			for _, part in ipairs({ "object", "plate", "hit" }) do
				expectTrue(BRL.inside(s[part], P.area.w, P.area.h) and s[part].w > 0 and s[part].h > 0, id .. " " .. part .. " is inside the room" .. where)
			end
			expectTrue(s.object.h >= 40 and s.plate.h >= 24 and s.plate.w >= 140, id .. " object and plate are big enough" .. where)
		end
		for i = 1, #R.order do
			for j = i + 1, #R.order do
				expectFalse(BRL.intersects(R.spots[R.order[i]].hit, R.spots[R.order[j]].hit), R.order[i] .. " and " .. R.order[j] .. " do not overlap" .. where)
			end
		end
	end
end })

table.insert(tests, { name = "Badge walls: every badge has a socket and a plate inside its wall, none overlap, and the Roads medals hang on the map at their stops (three sizes)", fn = function()
	local Engine = script.Parent.Parent.Engine
	local W, B = require(Engine.BadgeWallLayout), require(Engine.Badges)
	local function apart(a, b) return a.x + a.w <= b.x or b.x + b.w <= a.x or a.y + a.h <= b.y or b.y + b.h <= a.y end
	for _, win in ipairs(badgeWindows()) do
		local bw, bh = win.P.area.w, win.P.area.h
		local seen = {}
		for _, chip in ipairs({ "Roads", "Masters", "Night", "Special" }) do
			local lay = W.layout(chip, nil, bw, bh)
			local where = " (" .. chip .. " wall " .. bw .. "x" .. bh .. " at " .. win.name .. ")"
			local boxes = {}
			for _, it in ipairs(lay.items) do
				seen[it.id] = (seen[it.id] or 0) + 1
				local s, pr = W.socketRect(it), W.plateRect(it)
				local plate = { x = it.x + pr.x, y = it.y + W.plateY(it), w = pr.w, h = pr.h }
				expectTrue(s.x >= 0 and s.y >= 0 and s.x + s.w <= bw and s.y + s.h <= bh, it.id .. " socket is inside its wall" .. where)
				expectTrue(plate.x >= 0 and plate.y >= 0 and plate.x + plate.w <= bw and plate.y + plate.h <= bh, it.id .. " nameplate is inside its wall" .. where)
				boxes[#boxes + 1] = { id = it.id, socket = s, plate = plate }
				if chip == "Roads" then
					local pin = W.pinFor(it)
					expectTrue(pin.y - W.PIN / 2 >= 0 and pin.x >= 0 and pin.x <= bw, it.id .. " pin is on the map" .. where)
				end
			end
			for i = 1, #boxes do
				for j = i + 1, #boxes do
					local a, b = boxes[i], boxes[j]
					expectTrue(apart(a.socket, b.socket), a.id .. " and " .. b.id .. " sockets do not overlap" .. where)
					expectTrue(apart(a.socket, b.plate) and apart(b.socket, a.plate), a.id .. " and " .. b.id .. ": a plate never covers a neighbour's socket" .. where)
					expectTrue(apart(a.plate, b.plate), a.id .. " and " .. b.id .. " plates do not overlap" .. where)
				end
			end
		end
		for _, def in ipairs(B.Definitions) do expectEqual(seen[def.id], 1, def.id .. " hangs on exactly one wall at " .. win.name) end
	end
end })

table.insert(tests, { name = "Badges panel (real, on the fake Roblox) opens on the trophy room: four hotspots with counts, a wooden plaque, quiet plates; a click zooms into the wall; Escape steps back", fn = function()
	if not (io and io.open and load) then return end
	local probe = io.open("src/Client/BadgesPanel.lua", "r")
	if not probe then return end
	probe:close()
	local BS = require(script.Parent.BadgeScene)
	local Engine = script.Parent.Parent.Engine
	local W, B, BRL = require(Engine.BadgeWallLayout), require(Engine.Badges), require(Engine.BadgeRoomLayout)
	local scene = BS.build({ badgeIds = { "biome_meadow", "biome_river", "wins_1" } })
	scene.open()
	expectTrue(scene.backdrop.Visible and scene.room.Visible, "the Badges panel opens on the trophy room")
	expectFalse(scene.board.Visible, "the wall waits behind it")
	local want = { Roads = "Roads 2/8", Masters = "Masters 0/8", Night = "Night 0/4", Special = "Special 1/12" }
	for shelf, text in pairs(want) do
		local hot = scene.hotspot(shelf)
		expectTrue(hot ~= nil, shelf .. " has a hotspot")
		local surface = hot:FindFirstChild("Surface")
		expectTrue(surface ~= nil and surface.ClassName == "TextButton", shelf .. " hotspot takes the click")
		expectEqual(hot:FindFirstChild("NamePlate"):FindFirstChild("Label").Text, text, shelf .. " plate carries its count")
	end
	-- the small wooden plaque
	local plaque = scene.plaque
	expectTrue(plaque ~= nil and plaque.Size.Y.Offset <= 48 and plaque.Size.X.Offset <= 360, "the header is a small plaque")
	local count
	for _, c in ipairs(plaque:GetChildren()) do
		if c.ClassName == "TextLabel" and c.Text:find("earned", 1, true) then count = c end
	end
	expectTrue(count ~= nil and count.Text == "3 of 32 earned", "the plaque says how many are earned")
	local wood = plaque.BackgroundColor3
	expectTrue(wood.R > wood.G and wood.G > wood.B, "the plaque is wood")
	-- the quiet row of small plates
	local plates = {}
	for _, c in ipairs(scene.quiet:GetChildren()) do
		if c.ClassName == "TextButton" then plates[#plates + 1] = c end
	end
	table.sort(plates, function(a, b) return a.LayoutOrder < b.LayoutOrder end)
	expectEqual(#plates, 5, "a room plate and one per shelf")
	expectEqual(plates[1].Text, "< Room")
	for i, name in ipairs({ "Roads", "Masters", "Night", "Special" }) do expectEqual(plates[i + 1].Text, name, "quiet plate " .. (i + 1)) end
	for _, p in ipairs(plates) do expectTrue(p.TextSize >= 14 and p.Size.Y.Offset <= 28, p.Text .. " is a small plate") end
	-- zoom into every wall: every badge of the shelf hangs on it, in a socket, with its plate
	for _, win in ipairs(badgeWindows()) do
		scene.resize(win.vp[1], win.vp[2])
		for _, chip in ipairs({ "Roads", "Masters", "Night", "Special" }) do
			scene.open()
			scene.resize(win.vp[1], win.vp[2])
			scene.pick(chip)
			local where = " (" .. chip .. " at " .. win.name .. ")"
			expectTrue(scene.board.Visible and not scene.room.Visible, "the wall replaces the room" .. where)
			for _, def in ipairs(W.members(chip)) do
				local holder = scene.board:FindFirstChild("Badge_" .. def.id)
				expectTrue(holder ~= nil, def.id .. " hangs on the wall" .. where)
				expectTrue(scene.board:FindFirstChild("Socket_" .. def.id) ~= nil, def.id .. " has its socket" .. where)
				local plate = holder and holder:FindFirstChild("Nameplate")
				expectTrue(plate ~= nil and plate:FindFirstChildOfClass("TextLabel").Text == W.plateText(def, false), def.id .. " nameplate shows the whole name" .. where)
			end
			if chip == "Roads" then
				local pins, dots = 0, 0
				for _, c in ipairs(scene.board:GetChildren()) do
					if c.Name == "Pin" then pins = pins + 1 elseif c.Name == "PathDot" then dots = dots + 1 end
				end
				local paintedRoads = W.sceneLayout("Roads", nil, win.vp[1], win.vp[2]) ~= nil -- pins and path are in the picture
				expectEqual(pins, paintedRoads and 0 or 8, "one pin on the map per road stop" .. where)
				expectTrue(paintedRoads or dots >= 14, "a dotted road runs between the stops" .. where)
			end
			expectTrue(scene.step(), "Escape leaves the wall for the room" .. where)
			expectTrue(scene.room.Visible and not scene.board.Visible, "...and shows the room" .. where)
		end
	end
	expectEqual(#scene.state.warns, 0, "nothing warned: " .. table.concat(scene.state.warns, " | "))
	-- Escape: the detail card first, then the wall, then the room, then the panel closes
	scene.open()
	expectFalse(scene.step(), "in the room Escape has nothing to step back from, so it closes the panel")
	scene.pick("Special")
	scene.board:FindFirstChild("Badge_wins_1"):FindFirstChild("Hit").MouseButton1Click:Fire()
	expectTrue(scene.detail.Visible, "a click on a medal opens its card")
	expectTrue(scene.step() and not scene.detail.Visible and scene.board.Visible, "Escape closes the card first")
	expectTrue(scene.step() and scene.room.Visible, "the next Escape returns to the room")
	-- a quiet plate zooms in, the room plate comes back
	local function plate(text)
		for _, c in ipairs(scene.quiet:GetChildren()) do
			if c.ClassName == "TextButton" and c.Text == text then return c end
		end
	end
	plate("Night").MouseButton1Click:Fire()
	expectTrue(scene.board.Visible and not scene.room.Visible, "a quiet plate zooms into its wall")
	plate("< Room").MouseButton1Click:Fire()
	expectTrue(scene.room.Visible and not scene.board.Visible, "the room plate returns")
	scene.pick("Roads")
	scene.open()
	expectTrue(scene.room.Visible and not scene.board.Visible, "the panel always opens on the room")
	-- reading the room: a New tag on the shelf that holds a badge not yet looked at
	scene.latest.badgeIds = { "biome_meadow", "biome_river", "wins_1", "night_3" }
	scene.open()
	expectTrue(scene.hotspot("Night"):FindFirstChild("NewTag").Visible, "a newly earned Night badge shows New on its shelf")
	expectFalse(scene.hotspot("Roads"):FindFirstChild("NewTag").Visible, "...and only there")
	local f = io.open("src/Client/BadgesPanel.lua", "r")
	local src = f:read("*a")
	f:close()
	expectTrue(src:find('setStep("badges", stepBack)', 1, true) ~= nil, "the panel registers its Escape step")
end })

table.insert(tests, { name = "Collection room and section area: inside the panel, clear of the title, quiet row, filter plate and Close at three window sizes, hotspots match the layout", fn = function()
	local col = collectionBuild()
	if not col then return end
	local Engine = script.Parent.Parent.Engine
