			end
		end
	end
end })

table.insert(tests, { name = "PlayTableLayout: table is bottom anchored full width, rail and deck inside it, plates in a row under the rail without overlaps (1280x720, 1920x1080, phone fallback)", fn = function()
	local PT = require(script.Parent.Parent.Engine.PlayTableLayout)
	expectFalse(PT.usable(390), "phone uses the old layout")
	expectTrue(PT.usable(1280))
	for _, sz in ipairs({ { 1280, 720 }, { 1920, 1080 }, { 1000, 600 } }) do
		local w, h = sz[1], sz[2]
		local m = PT.map(w, h)
		expectEqual(m.image.w, w)
		expectEqual(m.image.y + m.image.h, h, "table sits on the bottom edge")
		local function inside(r, name)
			expectTrue(r.x >= 0 and r.y >= m.image.y and r.x + r.w <= w and r.y + r.h <= h, name .. " inside the area at " .. w .. "x" .. h)
		end
		inside(m.felt, "felt")
		inside(m.rail, "rail")
		inside(m.deck, "deck")
		for k, p in pairs(m.plates) do
			inside(p, "plate " .. k)
			expectTrue(p.y >= m.rail.y + m.rail.h, k .. " plate is under the rail")
		end
		expectTrue(m.plates.sort.x + m.plates.sort.w <= m.plates.play.x, "sort left of play")
		expectTrue(m.plates.play.x + m.plates.play.w <= m.plates.discard.x, "play left of discard")
		expectTrue(m.deck.x >= m.rail.x + m.rail.w, "deck is right of the rail")
	end
end })

table.insert(tests, { name = "PlayTableLayout.placement: hand stands on the rail, clear of sidebar and deck, Actions row under it (1920x957, 1280x720, 1000x600, phone nil)", fn = function()
	local PT = require(script.Parent.Parent.Engine.PlayTableLayout)
	expectTrue(PT.placement(390, 844, 0, 150) == nil, "phone keeps the old layout")
	for _, sz in ipairs({ { 1920, 957 }, { 1920, 1080 }, { 1280, 720 }, { 1000, 600 } }) do
		local w, h = sz[1], sz[2]
		local p = PT.placement(w, h, 260, 150)
		expectTrue(p ~= nil, "placement exists at " .. w .. "x" .. h)
		if p then
			expectTrue(p.hand.x >= 260 and p.hand.x + p.hand.w <= w - 150, "hand between sidebar and deck at " .. w)
			expectTrue(p.hand.y >= 0, "hand top on screen")
			local cardBottom = p.hand.y + p.hand.h - PT.CARD_PAD
			expectTrue(math.abs(cardBottom - (p.map.rail.y + p.map.rail.h / 2)) <= 1, "card bottom on the rail groove at " .. w)
			expectTrue(p.actions.y >= p.hand.y + p.hand.h - PT.CARD_PAD, "Actions row below the cards")
			expectTrue(p.actions.x >= 260, "Actions row right of the sidebar at " .. w)
			expectTrue(PT.FACE.y > 0.3 and PT.FACE.y + PT.FACE.h <= 0.9 and PT.FACE.x + PT.FACE.w <= 1, "plate face inside the box, below the bar")
			expectTrue(p.actions.y + p.actions.h <= h, "Actions row on screen")
			expectTrue(p.hand.x + p.hand.w <= p.map.deck.x + 1 or p.hand.y + p.hand.h <= p.map.deck.y + p.map.deck.h + PT.CARD_PAD, "hand does not cover the deck recess")
		end
	end
end })

table.insert(tests, { name = "PlayTableLayout plates: Play Hand and Discard equal height, each rect keeps its box aspect, whole sign inside the Actions row", fn = function()
	local PT = require(script.Parent.Parent.Engine.PlayTableLayout)
	for _, sz in ipairs({ { 1506, 751 }, { 1920, 957 }, { 1280, 720 } }) do
		local p = PT.placement(sz[1], sz[2], 260, 150)
		expectTrue(p ~= nil, "placement at " .. sz[1])
		if p then
			local pl = p.map.plates
			expectTrue(pl.play.h > pl.discard.h and pl.play.w > pl.discard.w, "Play Hand is the primary at " .. sz[1])
			expectTrue(math.abs((pl.play.y + pl.play.h) - (pl.discard.y + pl.discard.h)) <= 1, "one baseline at " .. sz[1])
			expectTrue(math.abs((pl.play.y + pl.play.h) - (pl.sort.y + pl.sort.h)) <= 1, "sort on the same baseline at " .. sz[1])
			for _, k in ipairs({ "sort", "play", "discard" }) do
				local b = PT.PLATE_BOXES[k]
				expectTrue(math.abs(pl[k].w / pl[k].h - b.w / b.h) < 0.03, k .. " keeps its aspect at " .. sz[1])
				expectTrue(pl[k].h >= 40, k .. " is a whole sign, not a strip")
				expectTrue(pl[k].y >= p.actions.y and pl[k].y + pl[k].h <= p.actions.y + p.actions.h, k .. " inside the Actions row")
			end
		end
	end
	if io and io.open then
		local f = io.open("src/Client/PlayPlates.lua", "r")
		if f then
			local src = f:read("*a")
			f:close()
			expectTrue(not src:find('"UIPadding"', 1, true), "no UIPadding on plate buttons (it shrinks the picture child)")
			expectTrue(src:find('inst:IsA("GuiObject") then\n\t\t\tinst.BorderSizePixel', 1, true) ~= nil, "ensure() sets BorderSizePixel and Active only on GuiObjects (a UITextSizeConstraint has neither and threw)")
			expectTrue(src:find('"EmberGlow"', 1, true) ~= nil, "the Play Hand ember ring is hidden under the painted plate")
		end
	end
end })

table.insert(tests, { name = "PlayTableLayout.deckRects: card 85 percent of the recess height with a margin, count board right of it, text fits, all inside the recess", fn = function()
