		expectTrue(string.find(covers, n, 1, true) ~= nil, n .. " must cover the lip")
	end
	local g = io.open("src/Client/PlayScenePaint.lua", "r")
	local src = g:read("*a")
	g:close()
	expectTrue(not string.find(src, "lip.Visible = handFrame.Visible", 1, true), "the lip must not follow the hand alone")
end })

table.insert(tests, { name = "SidebarMetrics: painted board sets the left edge of full screens, flat sidebar keeps 240/260, under 900 px stays flat", fn = function()
	local SM = require(script.Parent.Parent.Engine.SidebarMetrics)
	local PB = require(script.Parent.Parent.Engine.PlayBoardLayout)
	SM.setPainted(false)
	expectTrue(SM.width(1506, 751) == 240 and SM.hostLeft(1506, 751) == 240 and SM.contentLeft(1506, 751) == 260, "flat numbers")
	local fired = 0
	SM.onChange(function() fired = fired + 1 end)
	SM.setPainted(true)
	expectTrue(fired == 1, "listeners run when the painted state changes")
	for _, sz in ipairs({ { 1506, 751 }, { 1920, 957 }, { 1280, 720 } }) do
		local w = PB.placement(sz[1], sz[2]).w
		expectTrue(SM.width(sz[1], sz[2]) == w, "width is the board width at " .. sz[1])
		expectTrue(SM.contentLeft(sz[1], sz[2]) == w + 8 and SM.hostLeft(sz[1], sz[2]) == w + 8, "board right edge plus 8 at " .. sz[1])
		expectTrue(sz[1] - SM.contentLeft(sz[1], sz[2]) - 20 >= 600, "the Counter keeps room at " .. sz[1])
	end
	expectTrue(SM.contentLeft(800, 450) == 260, "narrow window keeps the old inset")
	SM.setPainted(false)
	expectTrue(fired == 2, "listeners run again on leaving painted")
	if io and io.open then
		for _, f in ipairs({ "src/Client/Shop.lua", "src/Client/BossFight.lua", "src/Client/PlayBoardPaint.lua" }) do
			local h = io.open(f, "r")
			if h then
				local c = h:read("*a"); h:close()
				expectTrue(c:find("SidebarMetrics", 1, true) ~= nil, f .. " uses the shared sidebar number")
			end
		end
	end
end })

table.insert(tests, { name = "PlayBoardLayout: board keeps 2:3,width at most 24 percent, slots inside and stacked without overlap, five rings in a row", fn = function()
	local PB = require(script.Parent.Parent.Engine.PlayBoardLayout)
	expectFalse(PB.usable(390))
	for _, sz in ipairs({ { 1280, 720 }, { 1920, 1080 }, { 1000, 600 } }) do
		local w, h = PB.size(sz[1], sz[2])
		expectTrue(w <= sz[1] * 0.24 + 1, "width cap at " .. sz[1])
		expectTrue(h <= sz[2], "fits the height")
		expectTrue(math.abs(w / h - 2 / 3) < 0.02, "2:3 ratio")
		local m = PB.map(w, h)
		local order = { "title", "target", "wide", "hands" }
		for i = 1, #order - 1 do
			expectTrue(m[order[i]].y + m[order[i]].h <= m[order[i + 1]].y, order[i] .. " above " .. order[i + 1])
		end
		expectTrue(m.hands.x + m.hands.w <= m.discards.x, "hands left of discards")
		expectEqual(#m.rings, 5)
		for i, r in ipairs(m.rings) do
			expectTrue(r.cx - r.d / 2 >= 0 and r.cx + r.d / 2 <= w and r.cy + r.d / 2 <= h, "ring " .. i .. " inside")
			expectTrue(r.cy - r.d / 2 >= m.hands.y + m.hands.h, "rings under the small slots")
			if i > 1 then
				expectTrue(r.cx - r.d / 2 >= m.rings[i - 1].cx + m.rings[i - 1].d / 2 - 1, "rings do not overlap")
			end
		end
	end
end })

table.insert(tests, { name = "ImagePreload: loaded comes from the PreloadAsync status even when IsLoaded is false; failure or no status keeps the old UI", fn = function()
	local IP = require(script.Parent.Parent.Engine.ImagePreload)
	local img = { IsLoaded = false }
	local function provider(status)
		return { PreloadAsync = function(_, _, cb) if status then cb("rbxassetid://1", status) end end }
	end
	expectTrue(IP.run(provider("Success"), img, "Success") == true, "success status counts as loaded")
	expectTrue(IP.run(provider("Failure"), img, "Success") == false, "failure keeps the old UI")
	expectTrue(IP.run(provider(nil), img, "Success") == false, "no status keeps the old UI")
	expectTrue(IP.run({ PreloadAsync = function() error("x") end }, img, "Success") == false, "error keeps the old UI")
end })

table.insert(tests, { name = "ImageSpace: rects of sheets over 1024 px scale by 1024 over the long side", fn = function()
	local IS = require(script.Parent.Parent.Engine.ImageSpace)
	expectTrue(math.abs(IS.rectScale(1536, 1024) - 2 / 3) < 1e-9, "1536x1024 -> 2/3")
	expectTrue(IS.rectScale(1024, 1024) == 1, "1024 -> 1")
	expectTrue(IS.rectScale(800, 600) == 1, "800 -> 1")
	local x, y, w, h = IS.rect(300, 150, 150, 75, 1536, 1024)
	expectTrue(x == 200 and y == 100 and w == 100 and h == 50, "rect scaled")
end })

table.insert(tests, { name = "PlayBoardLayout.seats: every seat is the same size and the row is centred on the plate (filled and empty rings alike)", fn = function()
	local PBL = require(script.Parent.Parent.Engine.PlayBoardLayout)
	for _, size in ipairs({ { 1920, 1080 }, { 1280, 720 } }) do
		local w, h = PBL.size(size[1], size[2])
		local m = PBL.map(w, h)
		local plateMid = m.target.x + m.target.w / 2
		for n = 1, 5 do
			local seats = PBL.seats(w, h, n)
			for i = 2, n do
				expectTrue(seats[i].w == seats[1].w and seats[i].h == seats[1].h, "seat " .. i .. " matches seat 1 for n=" .. n)
			end
		end
		local five = PBL.seats(w, h, 5)
		local mid = (five[1].x + five[5].x + five[5].w) / 2
		expectTrue(math.abs(mid - plateMid) <= 0.03 * m.target.w, "five seats are centred on the plate")
	end
end })

table.insert(tests, { name = "PlayBoardLayout.hud/seats: rows sit inside the board, Tips and rule do not overlap, 1 to 7 Patron seats fit inside the ring row without touching", fn = function()
	local PB = require(script.Parent.Parent.Engine.PlayBoardLayout)
	local function inside(r, w, h) return r.x >= 0 and r.y >= 0 and r.x + r.w <= w and r.y + r.h <= h end
	local function overlap(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	for _, sz in ipairs({ { 1506, 751 }, { 1920, 957 }, { 1280, 720 }, { 1000, 600 } }) do
		local bw, bh = PB.size(sz[1], sz[2])
		local H = PB.hud(bw, bh)
		for k, r in pairs(H) do expectTrue(inside(r, bw, bh), k .. " inside the board at " .. sz[1]) end
		expectTrue(H.tips == nil and H.rule.w >= 150 * bw / 361, "the rule has the whole wide slot, Tips goes under the board")
		expectTrue(H.title.w >= math.floor(190 * bw / 361), "the title has the width of the target slot")
		expectTrue(not overlap(H.hands, H.discards), "hands and discards apart")
		expectTrue(H.rule.h >= 30, "wide slot tall enough for 14 px text at " .. sz[1])
		for n = 1, 7 do
			local seats = PB.seats(bw, bh, n)
			expectTrue(#seats == n, n .. " seats returned")
			for i, a in ipairs(seats) do
				expectTrue(inside(a, bw, bh) and a.w >= 12, "seat " .. i .. " of " .. n .. " inside the board at " .. sz[1])
				if i <= 5 then
					expectTrue(a.x >= H.ringRow.x and a.x + a.w <= H.ringRow.x + H.ringRow.w and a.y >= H.ringRow.y and a.y + a.h <= H.ringRow.y + H.ringRow.h, "seat inside the ring row")
				else
					expectTrue(a.extra == true and a.ring ~= nil and a.y > H.ringRow.y + H.ringRow.h, "a sixth or later seat sits on the base row under the rings, in its own brass ring")
				end
				for j = i + 1, n do expectTrue(not overlap(a, seats[j]), "seats " .. i .. " and " .. j .. " of " .. n .. " do not touch") end
			end
		end
	end
end })

-- polish 2: at three window sizes the title fits its slot and the plates under the board stay on screen
table.insert(tests, { name = "Painted play screen polish 2: title fits and plates under the board stay inside the screen at 1506x751, 1920x957, 1280x720", fn = function()
	if not (io and io.open) then return end
	local FakeGui = require(script.Parent.FakeGui)
	local E = script.Parent.Parent.Engine
	local map = {}
	for _, n in ipairs({ "PlayTableLayout", "ImageSpace", "PlayBoardLayout", "BoardPanelRows" }) do map[n] = require(E[n]) end
	for _, size in ipairs({ { 1506, 751 }, { 1920, 957 }, { 1280, 720 } }) do
		local stubs = {}
		local env, state = FakeGui.env({ stubs = stubs })
		local folder = FakeGui.folder(map)
		local UDim2 = env.UDim2
		state.services.ReplicatedStorage = { WaitForChild = function() return { WaitForChild = function() return folder end } end }
		stubs.LayoutSwitch = FakeGui.load("src/Client/LayoutSwitch.lua", env)
		local PlayBoardHud = FakeGui.load("src/Client/PlayBoardHud.lua", env)
		local function mk(class, name, parent, order)
			local i = FakeGui.new(class)
			i.Name = name
			if order then i.LayoutOrder = order end
			i.Parent = parent
			return i
		end
		local root = mk("Frame", "Root", nil)
		local sidebar = mk("Frame", "Sidebar", root)
		mk("UIListLayout", "L", sidebar)
		local ribbon = mk("Frame", "HeaderRibbon", sidebar)
		local title = mk("TextLabel", "T", ribbon)
		title.Text = "Night 8/8 \194\183 Round 3"
		mk("Frame", "SidebarBoard", root)
		local content = mk("Frame", "BoardContent", sidebar)
		mk("UIListLayout", "L", content)
		local tips = mk("Frame", "TipsRow", content, 5)
		tips.Size = UDim2.fromOffset(300, 44)
		local hint = mk("Frame", "Hint", content, 10)
		hint.Size = UDim2.fromOffset(353, 56)
		local chip = mk("Frame", "BlessingChip", sidebar)
		chip.Size = UDim2.fromOffset(216, 44)
		local rect = map.PlayBoardLayout.placement(size[1], size[2])
		local H = map.PlayBoardLayout.hud(rect.w, rect.h)
		local label = size[1] .. "x" .. size[2]
		expectTrue(PlayBoardHud.apply(root, rect) == true, "applies at " .. label)
		expectTrue(title.TextSize <= 17 and title.TextSize * #title.Text * 0.6 <= H.title.w - 16 or title.TextSize == 15, "title fits its slot at " .. label)
		for _, f in ipairs({ tips, hint, chip }) do
			local x, y, w, h = f.Position.X.Offset, f.Position.Y.Offset, f.Size.X.Offset, f.Size.Y.Offset
			local onBoard = f ~= chip -- in this fake the chip is a Sidebar child with no row, so it is stacked below the grown board
			expectTrue(x >= 0 and x + w <= rect.w and y + h <= size[2]
				and (onBoard and y >= map.PlayBoardLayout.panelTop(rect.w) and y + h <= rect.h + (root:GetAttribute("BoardExtend") or 0) or y >= rect.h),
				f.Name .. " lies on the board's own parchment under the rings and on screen at " .. label)
		end
		expectTrue(tips.Position.Y.Offset + tips.Size.Y.Offset <= hint.Position.Y.Offset, "Tips above the hint at " .. label)
	end
end })

-- polish 1: rows keep their bar and Reward, the title fits, the leftover frames and brackets are gone, the deck brackets stay hidden
table.insert(tests, { name = "Painted play screen polish: score slot keeps bar and Reward, rule and Tips apart, frame decor hidden, deck brackets hidden", fn = function()
	if not (io and io.open) then return end
	local FakeGui = require(script.Parent.FakeGui)
	local E = script.Parent.Parent.Engine
	local map = {}
	for _, n in ipairs({ "PlayTableLayout", "ImageSpace", "PlayBoardLayout", "BoardPanelRows" }) do map[n] = require(E[n]) end
	local stubs = {}
	local env, state = FakeGui.env({ stubs = stubs })
	local folder = FakeGui.folder(map)
	local UDim2 = env.UDim2
	state.services.ReplicatedStorage = { WaitForChild = function() return { WaitForChild = function() return folder end } end }
	stubs.LayoutSwitch = FakeGui.load("src/Client/LayoutSwitch.lua", env)
	local PlayBoardHud = FakeGui.load("src/Client/PlayBoardHud.lua", env)
	local PlayDeckPaint = FakeGui.load("src/Client/PlayDeckPaint.lua", env)
	local function mk(class, name, parent, order)
		local i = FakeGui.new(class)
		i.Name = name
		if order then i.LayoutOrder = order end
		i.Parent = parent
		return i
	end

	local root = mk("Frame", "Root", nil)
	local sidebar = mk("Frame", "Sidebar", root)
	mk("UIListLayout", "L", sidebar)
	local ribbon = mk("Frame", "HeaderRibbon", sidebar)
	local title = mk("TextLabel", "T", ribbon)
	local board = mk("Frame", "SidebarBoard", root)
	local decorNames = { "SetSkinBorder", "SetAccent", "CornerStud", "InnerRim", "BracketH", "BracketV" }
	for _, n in ipairs(decorNames) do
		mk("Frame", n, sidebar)
		mk("Frame", n, board)
	end
	sidebar.BackgroundTransparency = 0
	board.BackgroundTransparency = 0
	local content = mk("Frame", "BoardContent", sidebar)
	mk("UIListLayout", "L", content)
	local rule = mk("Frame", "RoundRule", content, 1)
	local ruleLabel = mk("TextLabel", "R", rule)
	ruleLabel.Text = '<font size="17">Small Round</font>\n<font size="13" color="#E6D2AA">No special rules this round.</font>'
	local score = mk("Frame", "ScoreBox", content, 3)
	local big = mk("TextLabel", "Big", score)
	big.TextScaled = true
	local bar = mk("Frame", "TargetBar", score)
	local plate = mk("Frame", "RewardPlate", score)
	mk("TextLabel", "Line", plate)
	local tips = mk("Frame", "TipsRow", content, 5)
	tips.Size = UDim2.fromOffset(300, 44)
	mk("TextLabel", "Tips", tips)
	tips.BackgroundTransparency = 1
	local hd = mk("Frame", "HandsDiscards", content, 6)
	local ht = mk("Frame", "HandsTile", hd)
	local hl = mk("TextLabel", "H", ht)
	hl.Text = "Hands 4"
	local dt = mk("Frame", "DiscardsTile", hd)
	local dl = mk("TextLabel", "D", dt)
	dl.Text = "Discards 5 of 5 left"
	local hint = mk("Frame", "Hint", content, 10)
	hint.Size = UDim2.fromOffset(353, 56)
	hint.BackgroundTransparency = 1
	local badge = mk("Frame", "RunBadge", sidebar, -1) -- the Daily / Weekly / Seed bar
	badge.Size = UDim2.new(1, 0, 0, 36)
	badge.BackgroundTransparency = 0
	local strip = mk("Frame", "GoldStrip", board) -- a flat wide column left on the board frame
	strip.Size = UDim2.fromOffset(305, 800)
	strip.BackgroundTransparency = 0
	-- the dark band: depth, kit frame and accent wash on the board, also ones the theme adds after the first paint
	local band = {}
	for _, n in ipairs({ "HudDepth", "HudKitFrame", "SetAccent" }) do band[n] = mk("Frame", n, board) end
	title.Text = "Night 1/8 \194\183 Round 1"
	local rect = map.PlayBoardLayout.placement(1506, 751)
	local H = map.PlayBoardLayout.hud(rect.w, rect.h)
	local called, applied = pcall(PlayBoardHud.apply, root, rect)
	expectTrue(called and applied == true, "board HUD applies: " .. tostring(PlayBoardHud.lastError))
	if not applied then
		local why = PlayBoardHud.lastError
		expectTrue(false, "run failed: " .. tostring(why))
		return
	end

	-- (1) the title has its full slot (about 200 px) and shrinks to fit between 14 and 19
	expectTrue(ribbon.Size.X.Offset >= 190 and ribbon.Size.X.Offset == H.title.w, "title slot is about 200 px wide: " .. tostring(ribbon.Size.X.Offset))
	expectTrue(title.TextSize >= 14 and title.TextSize <= 17 and not title.TextScaled and not title.TextWrapped, "title is one unscaled line of 14 to 17")
	expectTrue(bar.Visible and plate.Visible, "the bar and the Reward plate are not hidden")
	expectTrue(big.Position.Y.Scale < bar.Position.Y.Scale and bar.Position.Y.Scale < plate.Position.Y.Scale, "target, bar and Reward are stacked top to bottom")
	expectTrue(rule.Size.X.Offset == H.rule.w and rule.Position.Y.Offset == H.rule.y, "the rule has the whole wide slot")
	local ruleName = rule:FindFirstChild("BoardRuleName")
	expectTrue(ruleName ~= nil and ruleName.Position.X.Offset == 12 and ruleName.Size.X.Offset == -24, "rule text is inset 12 px")
	expectTrue(hl.Position.X.Offset == 10 and hl.Size.X.Offset == -20, "Hands text is inset 10 px")
	local extend = root:GetAttribute("BoardExtend") or 0
	expectTrue(tips.Position.Y.Offset >= map.PlayBoardLayout.panelTop(rect.w) and tips.Position.Y.Offset < rect.h, "Tips sits on the board's parchment under the rings")
	expectTrue(extend > 0, "the board grows (BoardExtend) to hold the rows")

	-- (2) the hint is clamped to the board width and sits under the board
	expectTrue(hint.Size.X.Offset <= 230 and hint.Position.X.Offset + hint.Size.X.Offset <= rect.w, "the hint is clamped to the board width")
	expectTrue(hint.Position.Y.Offset + hint.Size.Y.Offset <= rect.h + extend, "the hint ends inside the grown board")
	local panel = sidebar and sidebar:FindFirstChild("BoardPanelBack")
	expectTrue(panel ~= nil and panel.Visible and panel.BackgroundTransparency == 1, "no cream card: the holder of the brass lines is see-through")
	local pstroke = panel and panel:FindFirstChildOfClass("UIStroke")
	expectTrue(pstroke == nil and panel:FindFirstChildOfClass("UICorner") == nil and panel:FindFirstChildOfClass("UIGradient") == nil, "no gold edge, corners or gradient of its own")
	expectTrue(tips:FindFirstChild("BoardPlateBack") == nil and hint:FindFirstChild("BoardPlateBack") == nil, "no separate plate per row")
	expectTrue(tips.BackgroundTransparency == 1 and hint.BackgroundTransparency == 1, "the rows are see-through on the panel")
	expectTrue(tips.Position.X.Offset == hint.Position.X.Offset and hint.Position.Y.Offset >= tips.Position.Y.Offset + tips.Size.Y.Offset, "the rows share a left edge, the hint under Tips")
	expectTrue(panel ~= nil and tips.Position.X.Offset >= panel.Position.X.Offset and hint.Position.Y.Offset + hint.Size.Y.Offset <= panel.Position.Y.Offset + panel.Size.Y.Offset, "both rows sit inside the panel")
	for n, f in pairs(band) do expectTrue(f.Visible == false, n .. " is hidden while painted (no dark band over the table)") end
	expectTrue(board:GetAttribute("PlayBoardPainted") == true, "the board is marked painted so the theme draws nothing over the table")
	expectTrue(badge.Visible == false, "the Seed / Daily bar is hidden on the painted board (no bar at the top left)")
	expectTrue(strip.Visible == false, "a flat wide column on the board frame is hidden")
	band.HudKitFrame.Visible = true -- the theme paints again later
	PlayBoardHud.apply(root, rect)
	expectTrue(band.HudKitFrame.Visible == false, "a piece the theme re-shows is hidden again")
	do -- a second pass must not take the panel itself for a row and stack it under the board (the cream box off the bottom)
		local again = sidebar:FindFirstChild("BoardPanelBack")
		expectTrue(again == panel and again.Position.Y.Offset < tips.Position.Y.Offset,
			"the panel stays behind its rows after a second pass")
		local n = 0
		for _, c in ipairs(sidebar:GetChildren()) do if c.Name == "BoardPanelBack" then n = n + 1 end end
		expectTrue(n == 1, "exactly one panel")
	end
	-- the rule: name on the first line, the rule line only when it fits, never outside the slot
	local rn, rl = rule:FindFirstChild("BoardRuleName"), rule:FindFirstChild("BoardRuleLine")
	expectTrue(rn and rn.Text == "Small Round" and rl and rl.Text == "No special rules this round.", "rule slot holds the round name, then the rule")
	expectTrue(ruleLabel.Visible == false and not rn.TextWrapped and not rl.TextWrapped, "the rich text label is replaced by one-line labels")
	expectTrue(rn.TextSize >= 15 and rn.TextSize <= 16 and (not rl.Visible or rl.TextSize == 15), "rule text is 15 to 16 px, or the line is dropped when it does not fit")
	expectTrue(rl.Visible and (rn.TextYAlignment == env.Enum.TextYAlignment.Bottom and rl.TextYAlignment == env.Enum.TextYAlignment.Top) or (not rl.Visible and rn.TextYAlignment == env.Enum.TextYAlignment.Center and rn.Size.Y.Scale == 1), "the two rule lines are one block centred in the slot")
	expectTrue(hl.TextSize == dl.TextSize, "Hands and Discards use one text size: " .. tostring(hl.TextSize) .. " vs " .. tostring(dl.TextSize))
	expectTrue((rule:GetAttribute("RuleTooltip") or ""):find("No special rules"), "the full rule text is kept for the tooltip")

	-- the TableLook edge vignettes are hidden while the table is painted (the hard dark strip), shown again otherwise
	do
		local src = io and io.open and io.open("src/Client/PlayScenePaint.lua", "r")
		if src then
			local text = src:read("*a")
			src:close()
			expectTrue(text:find('"Vignette_"', 1, true) ~= nil and text:find("vignette(true)", 1, true) ~= nil and text:find("vignette(false)", 1, true) ~= nil,
				"PlayScenePaint hides the Vignette_ edges while painted and restores them after")
			expectTrue(text:find('FindFirstChild("EdgeShadow")', 1, true) ~= nil and text:find("edge.Visible = not hidden", 1, true) ~= nil,
				"PlayScenePaint hides GameRoot.EdgeShadow (the dark band) while painted and restores it after")
		end
	end

	-- (3) the old frames: no parchment, no gold line, studs or brackets
	expectTrue(sidebar.BackgroundTransparency == 1 and board.BackgroundTransparency == 1, "parchment fills are gone")
	for _, n in ipairs(decorNames) do
		expectTrue(sidebar:FindFirstChild(n).Visible == false and board:FindFirstChild(n).Visible == false, n .. " is hidden while painted")
	end
	PlayBoardHud.apply(root, nil)
	expectTrue(sidebar.BackgroundTransparency == 0 and sidebar:FindFirstChild("CornerStud").Visible, "everything comes back on restore")
	expectTrue(badge.Visible == true, "the bar comes back when the board is not painted")
	-- boss round: wood slot with a red band, brass studs, text at least 15 px, the rule line is one line with an ellipsis
	ruleLabel.Text = '<font size="17">\u{1F451} Slow Night</font>\n<font size="13">1 random card is tossed out of your hand after every hand you play.</font>'
	ruleLabel:SetAttribute("Boss", true)
	PlayBoardHud.apply(root, rect)
	local bn, bl = rule:FindFirstChild("BoardRuleName"), rule:FindFirstChild("BoardRuleLine")
	expectTrue(bn and bl and bn.TextSize >= 15 and bl.TextSize >= 15 and bl.Visible, "boss rule text is 15 px or more")
	expectTrue(bl.TextWrapped == false and bl.TextTruncate ~= nil and tostring(bl.TextTruncate.Name or bl.TextTruncate):find("AtEnd", 1, true) ~= nil, "the rule is one line that ends in an ellipsis, never a wrapped line cut in half")
	expectTrue((rule:GetAttribute("RuleTooltip") or ""):find("after every hand you play", 1, true) ~= nil, "the whole rule is kept for the slot's tooltip")
	expectTrue((rule:GetAttribute("RuleTooltip") or ""):find(" - ", 1, true) == nil, "name and rule are joined with a colon, not a dash")
	expectTrue(rule.BackgroundTransparency == 1, "the boss slot has no flat fill")
	local bossStuds = 0
	for _, d in ipairs(rule:GetChildren()) do if string.sub(d.Name, 1, 8) == "BossStud" and d.Visible then bossStuds = bossStuds + 1 end end
	expectTrue(bossStuds == 4, "the boss slot has four brass studs")
	PlayBoardHud.apply(root, nil)

	-- (4) deck: no brackets, studs or rim anywhere, even when the skin turns them on again
	local widget = mk("Frame", "DeckWidget", nil)
	widget.Size = UDim2.fromOffset(196, 93)
	local card = mk("Frame", "DeckCardBack", widget)
	mk("TextLabel", "DeckCount", widget)
	mk("ImageLabel", "StackBackA", widget)
	mk("ImageLabel", "StackBackB", widget)
	for _, n in ipairs({ "BracketH", "BracketV", "CornerStud", "InnerRim" }) do mk("Frame", n, widget) end
	mk("Frame", "HudBrackets", card)
	mk("Frame", "CornerStud", card)
	expectTrue(PlayDeckPaint.apply(widget, { x = 1250, y = 375, w = 196, h = 93 }, "rbxassetid://1"), "deck paints")
	local rects = PlayDeckPaint.rects(196, 93)
	expectTrue(rects.card.h <= 93 * 0.86 and rects.card.y >= 6 and rects.card.y + rects.card.h <= 93 - 6, "card back fits the recess with a margin")
	for _, n in ipairs({ "BracketH", "BracketV", "CornerStud", "InnerRim" }) do
		expectTrue(widget:FindFirstChild(n).Visible == false, "widget " .. n .. " hidden")
	end
	expectTrue(card:FindFirstChild("HudBrackets").Visible == false and card:FindFirstChild("CornerStud").Visible == false, "card back brackets hidden")
	card:FindFirstChild("HudBrackets").Visible = true
	expectTrue(card:FindFirstChild("HudBrackets").Visible == false, "brackets turned back on by the skin are hidden again")
end })

table.insert(tests, { name = "PlayMotion: parallax is capped and opposite the cursor, calm and modal hold still, arc ends on target, light is themed", fn = function()
	local PM = require(script.Parent.Parent.Engine.PlayMotion)
	local dx, dy = PM.parallax(1, 1, 14, false, false)
	expectTrue(dx == -14 and dy < 0 and dy >= -14, "opposite the cursor, capped at 14")
	dx = PM.parallax(5, 0, 9, false, false)
	expectTrue(dx == -9, "cursor clamped to the screen")
	expectTrue(PM.parallax(1, 1, 9, true, false) == 0 and PM.parallax(1, 1, 9, false, true) == 0, "calm and modal = no motion")
	expectTrue(PM.LAYER_PX.backdrop < PM.LAYER_PX.table and PM.LAYER_PX.table < PM.LAYER_PX.rail and PM.LAYER_PX.rail <= 14, "rail moves most")
	local x0, y0 = PM.arc(100, 50, 0, 0, 0, 40)
	local x1, y1 = PM.arc(100, 50, 0, 0, 1, 40)
	local _, ym = PM.arc(100, 50, 0, 0, 0.5, 40)
	expectTrue(x0 == 100 and y0 == 50 and x1 == 0 and y1 == 0, "arc starts at the deck and lands in the slot")
	expectTrue(ym < 25, "arc bows above the straight line")
	local d1, t1 = PM.dealTiming(1, 8)
	local d8, t8 = PM.dealTiming(8, 8)
	expectTrue(d1 == 0 and math.abs(d8 - 0.42) < 1e-9 and t1 >= 0.25 and t8 <= 0.35 and d8 + t8 <= 0.6 + 1e-9, "0.06 s stagger, at most 0.35 s each, all landed by 0.6 s")
	expectTrue(select(1, PM.slideTarget("discard", 10, 10, 50, 50, 90, 70)) == 80, "discards head for the deck")
	expectTrue(PM.lightFor("festival_night").color[3] > PM.lightFor("classic_tavern").color[3], "cool sets lean blue, Classic warm")
	local pt = PM.lightFor("classic_tavern").poolTransparency
	expectTrue(1 - pt >= 0.25 and 1 - pt <= 0.4, "pool lightens the felt visibly (12 to 18 percent)")
	expectTrue(PM.FELT.grainOpacity >= 0.08 and PM.FELT.grainOpacity <= 0.12, "grain 8 to 12 percent")
	local cg = PM.cornerGlows(100, 50, 800, 400)
	expectTrue(#cg == 4 and cg[1][1] == 100 and cg[4][1] == 900 and cg[4][2] == 450 and cg[1][3] == 440, "four corner glows centred on the felt corners")
	local x, y, w, h = PM.poolRect(1920, 1080, 800, 180)
	expectTrue(x >= 0 and x + w <= 1920 and h > 0 and y + h > 800, "pool sits over the hand inside the screen")
end })

table.insert(tests, { name = "PlayMotion: one frame step over the real layers gives whole numbers and survives nil inputs (leanPx regression)", fn = function()
	local PM = require(script.Parent.Parent.Engine.PlayMotion)
	local layers = {
		{ name = "PlayTableFront", px = PM.LAYER_PX.table, leanPx = PM.LEAN_PX.table },
		{ name = "PlayRailBack", px = PM.LAYER_PX.rail, leanPx = PM.LEAN_PX.rail },
		{ name = "PlayRailFront", px = PM.LAYER_PX.rail, leanPx = PM.LEAN_PX.rail },
	}
	for _, calm in ipairs({ false, true }) do
		for _, lean in ipairs({ 0, 0.6, 1 }) do
			for _, layer in ipairs(layers) do
				local dx, dy = PM.layerOffset(0.5, -0.5, layer, lean, calm)
				assert(dx == math.floor(dx) and dy == math.floor(dy), "offsets are whole pixels")
			end
		end
	end
	local _, dy = PM.layerOffset(0, 0, layers[2], 1, true)
	assert(dy == PM.LEAN_PX.rail or dy == 0, "calm parallax is still, lean only moves down")
	local nx, ny = PM.layerOffset(nil, nil, {}, nil, nil)
	assert(nx == 0 and ny == 0, "nil safe")
	assert(PM.layerOffset(0, 0, nil, 0, false) == 0)
end })
