end })
table.insert(tests, { name = "PlayMotion: the hand is a level row by default (no tilt, dip, tuck or end shrink, no per-card capsule shadow); the fan maths come back with HAND_FAN_ENABLED", fn = function()
	local PM = require(script.Parent.Parent.Engine.PlayMotion)
	expectFalse(PM.HAND_FAN_ENABLED, "the fan is off")
	for count = 1, 9 do
		for pos = 1, count do
			local dx, dy = PM.cardOffset(pos, count)
			expectTrue(PM.cardTilt(pos, count) == 0 and PM.cardScale(pos, count) == 1 and dx == 0 and dy == 0, "card " .. pos .. " of " .. count .. " is level, full size, same Y")
		end
	end
	local f = io and io.open and io.open("src/Client/PlayRailLip.lua", "r")
	if f then
		local text = f:read("*a")
		f:close()
		expectTrue(text:find("CardPolish", 1, true) ~= nil, "card shadows come from the tested CardPolish rules (three soft layers, 0.25 alpha core)")
	end
	PM.HAND_FAN_ENABLED = true
	local ok, err = pcall(function()
	for count = 2, 8 do
		for pos = 1, count do
			local d, sc = PM.cardTilt(pos, count), PM.cardScale(pos, count)
			local dx, dy = PM.cardOffset(pos, count)
			expectTrue(math.abs(d) <= 6.5 and sc >= 0.92 and sc <= 1, "tilt within 5 degrees, scale within 8 percent")
			expectTrue(dy >= 0 and dy <= 30 and math.abs(dx) <= 14, "dip 0 to 30 px, tuck up to 14 px")
		end
		expectTrue(PM.cardTilt(1, count) == -6.5 and PM.cardTilt(count, count) == 6.5, "ends lean outward 6.5 degrees")
		local _, dyEnd = PM.cardOffset(1, count)
		expectTrue(dyEnd >= 26 and dyEnd <= 30 and math.abs(PM.cardScale(1, count) - 0.92) < 1e-9, "ends dip 26 to 30 px and scale 0.92")
		expectTrue(PM.cardOffset(1, count) > 0 and PM.cardOffset(count, count) < 0, "ends tuck toward the middle")
	end
	local _, dyMid = PM.cardOffset(2, 3)
	expectTrue(dyMid == 0 and PM.cardTilt(2, 3) == 0 and PM.cardScale(2, 3) == 1, "the centre card sits level, largest and lowest on the arc")
	expectTrue(PM.cardTilt(1, 1) == 0 and PM.cardScale(1, 1) == 1, "a lone card is straight")
	end)
	PM.HAND_FAN_ENABLED = false
	if not ok then error(err, 0) end
	local dx1, _, r1 = PM.stackSpec(1, 4)
	local dx4, _, r4 = PM.stackSpec(4, 4)
	expectTrue(dx1 < 0 and dx4 > 0 and r1 ~= r4 and math.abs(r1) <= 12, "played cards form a small tilted overlapping group")
	local tr0, w0 = PM.shadowFor(false)
	local tr1, w1 = PM.shadowFor(true)
	expectTrue(tr1 > tr0 and w1 < w0 and tr0 >= 0.65, "a lifted card's shadow shrinks and fades")
	expectTrue(PM.leanTarget(0, false, false, false) == 0 and PM.leanTarget(2, false, false, false) == 0.6 and PM.leanTarget(0, true, false, false) == 1, "lean steps")
	expectTrue(PM.leanTarget(2, true, true, false) == 0 and PM.leanTarget(2, true, false, true) == 0, "plate or calm returns to rest")
	local dy, sc = PM.leanOffset(1, PM.LEAN_PX.rail)
	expectTrue(dy == 16 and sc > 1.01 and sc <= 1.02, "lean 16 px, up to 2 percent")
	expectTrue(PM.LEAN_PX.table >= 8 and PM.LEAN_PX.rail <= 16, "lean px in 8 to 16")
end })

table.insert(tests, { name = "CardPolish: 0.25 alpha core shadow, bigger when selected, 4 deck thickness steps that never rise, stable tilt within 1 degree", fn = function()
	local CP = require(script.Parent.Parent.Engine.CardPolish)
	local rest, sel = CP.shadow(false), CP.shadow(true)
	expectEqual(#rest.layers, 3, "three stacked layers")
	local core = rest.layers[3]
	expectTrue(math.abs((1 - core.transparency) - 0.30) < 1e-9, "resting core shadow is 0.30 alpha")
	for i = 1, 3 do
		local a, b = rest.layers[i], sel.layers[i]
		expectTrue(b.w > a.w and b.h > a.h and b.dy > a.dy, "selected layer " .. i .. " is larger and lower")
		expectTrue(a.transparency >= 0.70 - 1e-9 and a.transparency <= 1 and b.transparency >= 0.70 - 1e-9 and b.transparency <= 1, "layer alpha never above 0.30")
	end
	expectEqual(CP.deckSteps(52, 52), 4, "full deck")
	expectEqual(CP.deckSteps(40, 52), 4, "77 percent")
	expectEqual(CP.deckSteps(39, 52), 3, "75 percent")
	expectEqual(CP.deckSteps(26, 52), 2, "50 percent")
	expectEqual(CP.deckSteps(13, 52), 1, "25 percent")
	expectEqual(CP.deckSteps(1, 52), 1, "one card left")
	expectEqual(CP.deckSteps(0, 52), 0, "empty")
	expectEqual(CP.deckSteps(nil, nil), 0, "nil safe")
	local prev = 4
	for n = 52, 0, -1 do
		local s = CP.deckSteps(n, 52)
		expectTrue(s <= prev and s >= 0 and s <= 4, "steps never rise as cards are drawn")
		prev = s
	end
	expectEqual(#CP.deckEdge(3), 3, "one edge line per step")
	expectEqual(#CP.deckEdge(99), 4, "capped at 4")
	expectEqual(#CP.deckEdge(-2), 0, "negative is none")
	local distinct = {}
	for k = 1, 60 do
		local t = CP.tilt(k)
		expectTrue(math.abs(t) <= 1 + 1e-9, "tilt within 1 degree")
		expectTrue(CP.tilt(k) == t, "tilt is stable per key")
		distinct[string.format("%.2f", t)] = true
	end
	local n = 0
	for _ in pairs(distinct) do n = n + 1 end
	expectTrue(n > 20, "tilts differ from card to card")
	expectTrue(CP.tilt("AS") == CP.tilt("AS") and CP.tilt("AS") ~= CP.tilt("KH"), "string keys work")
end })

table.insert(tests, { name = "Badge scenes: Night v2 has four round recesses,badges at 85 percent of the recess, used only once its Image id is recorded, every plate inside the board", fn = function()
	local W = require(script.Parent.Parent.Engine.BadgeWallLayout)
