	expectTrue(W.sceneOf("Night", { badge_scene_night = "rbxassetid://1", badge_scene_night_b = "rbxassetid://2" }) == v2, "the round-recess picture wins once recorded")
	for _, win in ipairs(badgeWindows()) do
