table.insert(tests, { name = "DebugGoto round1:mod=: the client copies the parsed ids, and open_hands / sharp_eyes change Hands / Discards and show in the view", fn = function()
	local RM = require(script.Parent.Parent.Engine.RunModifiers)
	for id, key in pairs({ open_hands = "handsPerRound", sharp_eyes = "discardsPerRound" }) do
		local state = { config = { handsPerRound = 4, discardsPerRound = 3, patronSlotLimit = 5, recipeSlotLimit = 2, tipsPerRoundWin = 3 }, tips = 0, handsRemaining = 4, discardsRemaining = 3 }
		local ok = RM.apply(state, id)
		assert(ok, id .. " applies")
		local base = (key == "handsPerRound") and 4 or 3
		assert(state.config[key] == base + 1, id .. " adds one to " .. key)
		local view = RM.view(state.runModifierId)
		assert(view and view.id == id and view.blessing and view.curse, id .. " has a view the board row shows")
	end
	do -- RunChoice.forceOption puts a blessing outside the random draw on offer, so round1:mod= can always apply it
		local RC = require(script.Parent.Parent.Engine.RunChoice)
		local choice = { kind = "modifier", options = { { id = "a" }, { id = "b" }, { id = "c" } } }
		assert(RC.forceOption(choice, "open_hands") and choice.options[1].id == "open_hands" and #choice.options == 3, "swaps in the wanted blessing")
		assert(RC.forceOption(choice, "b") and choice.options[2].id == "b", "an offered id changes nothing")
		assert(not RC.forceOption(choice, "no_such_blessing"), "unknown id refused")
		assert(not RC.forceOption({ kind = "patron", options = {} }, "open_hands"), "only a blessing draft is touched")
	end
	if type(io) ~= "table" or not io.open then return end -- Studio has no io library
	local f = io.open("src/Client/DebugGoto.lua", "r")
	if not f then return end
	local src = f:read("*a"); f:close()
	assert(src:find("wantedMod, wantedTag = target.modId, target.tagId", 1, true), "round1 jump stores the wanted blessing and Tag")
end })

table.insert(tests, { name = "DebugGotoRules: round1:mod= and round1:tag= parse, combine, and reject junk", fn = function()
	local R = require(script.Parent.Parent.Engine.DebugGotoRules)
	local a = R.parse("round1:mod=open_hands")
	assert(a and a.kind == "round1" and a.modId == "open_hands" and a.tagId == nil, "mod only")
	local b = R.parse("round1:tag=tip_jar")
	assert(b and b.kind == "round1" and b.tagId == "tip_jar" and b.modId == nil, "tag only")
	local c = R.parse("round1:mod=open_hands,tag=tip_jar")
	assert(c and c.modId == "open_hands" and c.tagId == "tip_jar", "both")
	assert(R.parse("round1:mod=") == nil and R.parse("round1:foo=bar") == nil and R.parse("round1:mod=a,mod=b") == nil, "junk rejected")
	local state = { choice = { kind = "modifier", options = { { id = "x" }, { id = "open_hands" } } } }
	local _, id = R.round1Step(state, "open_hands")
	assert(id == "open_hands", "wanted blessing picked")
	local _, id2 = R.round1Step(state, "missing")
	assert(id2 == "x", "unknown blessing falls back to the first option")
	local _, id3 = R.round1Step(state)
	assert(id3 == "x", "default unchanged")
end })
table.insert(tests, { name = "DebugGotoRules: known jump values parse, unknown ones return nil, round1 steps", fn = function()
