table.insert(tests, { name = "Scene pages: the picture fades its own uncovered sides (12 percent, eased, 18 keypoints at most), top and bottom keep edge frames", fn = function()
	local PS = require(script.Parent.Parent.Engine.PanelSceneLayout)
	local p = { image = { x = 300, y = 0, w = 900, h = 800 } }
	local pts = PS.sideFade(p, 1500)
	expectTrue(pts ~= nil and #pts <= 20 and pts[1][1] == 0 and pts[#pts][1] == 1, "keypoints run 0..1 within Roblox's 20 limit")
	expectEqual(pts[1][2], 1, "clear at the left picture edge")
	expectEqual(pts[#pts][2], 1, "clear at the right picture edge")
	local lastT = -1
	for _, k in ipairs(pts) do expectTrue(k[1] > lastT, "times strictly increase"); lastT = k[1] end
	local ramp = PS.SIDE_FRAC
	local inside = false
	for _, k in ipairs(pts) do if k[1] >= ramp and k[1] <= 1 - ramp and k[2] == 0 then inside = true end end
	expectTrue(inside, "opaque inside the ramps")
	expectTrue(PS.sideFade({ image = { x = 0, y = 0, w = 1500, h = 800 } }, 1500) == nil, "a picture that reaches both sides needs no fade")
	local one = PS.sideFade({ image = { x = 0, y = 0, w = 900, h = 800 } }, 1500)
	expectEqual(one[1][2], 0, "left side untouched when it reaches the area")
	for _, e in ipairs(PS.verticalEdges({ image = { x = 300, y = 40, w = 900, h = 700 } }, 1500, 900)) do
		expectTrue(e.name == "T" or e.name == "B", "only top and bottom edge frames remain")
	end
end })

table.insert(tests, { name = "Scene pages: the painting area reaches the panel bottom, edges are one gradient frame each, no stacked strips", fn = function()
	local PS = require(script.Parent.Parent.Engine.PanelSceneLayout)
	-- geometry: a picture smaller than the area gets one gradient frame per uncovered edge, inside the area, fully dark at the picture edge
	local p = { image = { x = 300, y = 0, w = 900, h = 800 } }
	local edges = PS.edges(p, 1500, 900)
	local names = {}
	for _, e in ipairs(edges) do
		names[e.name] = true
		expectTrue(e.rect.x >= 0 and e.rect.y >= 0 and e.rect.x + e.rect.w <= 1500 + 1 and e.rect.y + e.rect.h <= 900 + 1, e.name .. " edge stays in the area")
		expectTrue(#e.points >= 2 and #e.points <= 20 and e.points[1][1] == 0 and e.points[#e.points][1] == 1, e.name .. " keypoints run 0..1 and fit Roblox's 20 limit")
		expectEqual(e.points[1][2], 0, e.name .. " is fully dark at the picture edge")
		expectEqual(e.points[#e.points][2], 1, e.name .. " is clear inside")
	end
	expectTrue(names.L and names.R and names.B and not names.T, "left, right and bottom gaps get an edge; the top touches the area")
	-- every scene page hands the scene the area including the footer, so the painting is not cut off above the bottom band
	for _, f in ipairs({ "src/Client/StatsRoom.lua", "src/Client/LegendPanel.lua" }) do
		local fh = io and io.open and io.open(f, "r")
		if fh then
			local src = fh:read("*a"); fh:close()
			expectTrue(src:find("runs under the footer to the panel bottom", 1, true) ~= nil, f .. " paints to the panel bottom")
		end
	end
	local fh = io and io.open and io.open("src/Client/FlairDressingRoom.lua", "r")
	if fh then
		local src = fh:read("*a"); fh:close()
		expectTrue(src:find("h - R.topH) -- the painting runs under the footer", 1, true) ~= nil, "Flair paints to the panel bottom")
	end
end })

tests[#tests + 1] = ({ name = "LegendSceneLayout: trophy hall slots fit the panel body at 1920x1080 and 1280x720, edges melt into a vignette, parts stay inside their slots", fn = function()
	local L = require(script.Parent.Parent.Engine.LegendSceneLayout)
	local PS = require(script.Parent.Parent.Engine.PanelSceneLayout)
	local function inside(a, b) return a.x >= b.x - 0.001 and a.y >= b.y - 0.001 and a.x + a.w <= b.x + b.w + 0.001 and a.y + a.h <= b.y + b.h + 0.001 end
	local function hit(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	for _, screen in ipairs({ { 1920, 1080 }, { 1920, 957 }, { 1280, 720 } }) do
		local pw, ph = L.panel(screen[1], screen[2])
		expectTrue(pw >= 640 and ph >= 520, "panel keeps its minimum at " .. screen[1] .. "x" .. screen[2])
		local FitP = require(script.Parent.Parent.Engine.PanelLayout).fit(screen[2], ph)
		expectTrue(FitP.fits and FitP.bottom <= screen[2] - 8, "Close stays inside the window under the strip's nudge at " .. screen[1] .. "x" .. screen[2])
		local W, H = pw, ph - L.TOP - L.BOTTOM
		local p = L.place(W, H)
		local area = { x = 0, y = 0, w = W, h = H }
		expectTrue(p.ok, "painted trophy hall fits at " .. screen[1] .. "x" .. screen[2])
		local all = { p.alcove }
		for _, r in ipairs(p.plaques) do all[#all + 1] = r end
		for _, r in ipairs(p.shelves) do all[#all + 1] = r end
		expectEqual(#all, 9, "alcove, five plaques and three shelves")
		for i, r in ipairs(all) do
			expectTrue(inside(r, area), "slot " .. i .. " inside the body at " .. screen[1] .. "x" .. screen[2])
			for j = i + 1, #all do expectFalse(hit(r, all[j]), "slots " .. i .. " and " .. j .. " do not overlap") end
		end
		expectTrue(math.abs(p.image.w / p.image.h - 1) < 0.001, "the picture is not stretched")
		-- uncovered picture edges melt into a vignette; nothing is cut out of the picture
		local strips = PS.feather(p, W, H)
		local uncovered = p.image.x > 0.5 or p.image.x + p.image.w < W - 0.5 or p.image.y > 0.5 or p.image.y + p.image.h < H - 0.5
		expectEqual(#strips > 0, uncovered, "vignette exactly when an edge is uncovered at " .. screen[1] .. "x" .. screen[2])
		for _, st in ipairs(strips) do expectTrue(st.src == nil and st.transparency >= 0 and st.transparency <= 1, "vignette strip " .. st.name .. " is a plain fade") end
		-- the panel is as wide as the picture: no flat band at the left or right
		expectTrue(p.image.x <= 1 and p.image.x + p.image.w >= W - 1, "the picture reaches both sides at " .. screen[1] .. "x" .. screen[2])
		for _, st in ipairs(strips) do expectFalse(st.name:sub(1, 1) == "L" or st.name:sub(1, 1) == "R", "no side vignette needed") end
		-- parts
		local a = L.alcoveParts(p.alcove)
		local rel = { x = 0, y = 0, w = p.alcove.w, h = p.alcove.h }
		for _, k in ipairs({ "crest", "back", "next" }) do expectTrue(inside(a[k], rel), "alcove " .. k .. " inside the alcove") end
		expectTrue(math.abs(a.back.w / a.back.h - 2 / 3) < 0.02 and a.back.h >= 100, "card back is 2:3 and big enough to see")
		expectFalse(hit(a.crest, a.back) or hit(a.back, a.next), "alcove parts do not overlap")
		for k, pl in ipairs(p.plaques) do
			local parts = L.plaqueParts(pl)
			local prel = { x = 0, y = 0, w = pl.w, h = pl.h }
			for c = 1, 2 do
				expectTrue(inside(parts[c].medal, prel) and inside(parts[c].num, prel), "plaque " .. k .. " column " .. c .. " inside the plaque")
				expectTrue(parts[c].medal.w >= 28 and parts[c].num.h >= 14, "medallion and level text readable")
			end
			expectFalse(hit(parts[1].medal, parts[2].medal), "plaque medallions do not touch")
		end
		for _, sh in ipairs(p.shelves) do
			expectTrue(sh.w >= 112 and sh.h >= 72, "shelf text fits three 14 px lines")
			local strip = L.shelfStrip(sh)
			expectTrue(strip.h >= 48 and strip.x >= 0 and strip.x + strip.w <= sh.w and strip.y >= 0 and strip.y + strip.h <= sh.h, "the parchment strip sits inside its shelf")
		end
	end
	-- contrast (WCAG ratio): level labels, shelf ink and the unchanged text on the dark frame
	local function lum(c)
		local function ch(v) v = v / 255; return v <= 0.03928 and v / 12.92 or ((v + 0.055) / 1.055) ^ 2.4 end
		return 0.2126 * ch(c[1]) + 0.7152 * ch(c[2]) + 0.0722 * ch(c[3])
	end
	local function ratio(a, b) local la, lb = lum(a), lum(b); if la < lb then la, lb = lb, la end; return (la + 0.05) / (lb + 0.05) end
	expectTrue(ratio(L.COLORS.lvInk, L.COLORS.lvPill) >= 4.5, "Lv labels: cream on the dark pill is at least 4.5:1")
	expectTrue(ratio(L.COLORS.shelfInk, L.COLORS.shelfStrip) >= 4.5, "shelf ink on parchment is at least 4.5:1")
	expectTrue(ratio({ 255, 226, 140 }, L.COLORS.frame) >= 4.5, "the gold title on the wood frame is at least 4.5:1")
	expectTrue(L.COLORS.frame[1] > L.COLORS.frame[3] and L.COLORS.frame[1] < 80, "the frame is dark wood, not maroon (red well above blue, no purple)")
	expectEqual(#L.pairs(10), 5, "ten levels on five plaques")
	expectEqual(L.pairs(10)[5][2], 10, "last plaque holds level 10")
	expectFalse(L.place(500, 300).ok, "a tiny panel keeps the plain layout")
	local f = io and io.open and io.open("src/Client/LegendPanel.lua", "r")
	if f then
		local src = f:read("*a"); f:close()
		expectTrue(src:find("[LegendRoom]", 1, true) ~= nil and src:find("slots=%d", 1, true) ~= nil, "the Studio line reports the slot count placed")
		expectTrue(src:find("PanelScene.new", 1, true) ~= nil and src:find("sceneOn", 1, true) ~= nil, "the panel draws the painted scene")
	end
end })

tests[#tests + 1] = ({ name = "CardSetsSceneLayout: shelf wall slots fit the body at 1920x1080 and 1280x720, tiles fit their frames, paging covers every set and back", fn = function()
	local L = require(script.Parent.Parent.Engine.CardSetsSceneLayout)
	local PS = require(script.Parent.Parent.Engine.PanelSceneLayout)
	local Sets = require(script.Parent.Parent.Engine.CosmeticSets)
	local Backs = require(script.Parent.Parent.Engine.CardBacks)
	local function inside(a, b) return a.x >= b.x - 0.001 and a.y >= b.y - 0.001 and a.x + a.w <= b.x + b.w + 0.001 and a.y + a.h <= b.y + b.h + 0.001 end
	local function hit(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	for _, screen in ipairs({ { 1920, 1080 }, { 1920, 957 }, { 1280, 720 } }) do
		local pw, ph = L.panel(screen[1], screen[2])
		expectTrue(pw >= 640 and ph >= 520, "panel keeps its minimum at " .. screen[1] .. "x" .. screen[2])
		local FitP = require(script.Parent.Parent.Engine.PanelLayout).fit(screen[2], ph)
		expectTrue(FitP.fits and FitP.bottom <= screen[2] - 8, "Close stays inside the window under the strip's nudge at " .. screen[1] .. "x" .. screen[2])
		local W, H = pw, ph - L.TOP - L.BOTTOM
		local p = L.place(W, H)
		local area = { x = 0, y = 0, w = W, h = H }
		expectTrue(p.ok, "painted shelf wall fits at " .. screen[1] .. "x" .. screen[2])
		expectEqual(#p.plates, 5, "five plates")
		expectEqual(#p.frames, 10, "ten frames")
		expectEqual(#p.plaques, 10, "ten plaques")
		local all = {}
		for _, g in ipairs({ p.plates, p.frames, p.plaques }) do for _, r in ipairs(g) do all[#all + 1] = r end end
		for i, r in ipairs(all) do
			expectTrue(inside(r, area), "slot " .. i .. " inside the body at " .. screen[1] .. "x" .. screen[2])
			for j = i + 1, #all do expectFalse(hit(r, all[j]), "slots " .. i .. " and " .. j .. " do not overlap") end
		end
		expectTrue(math.abs(p.image.w / p.image.h - 1) < 0.001, "the picture is not stretched")
		for _, pl in ipairs(p.plaques) do expectTrue(pl.h >= 20 and pl.w >= 70, "plaque text (14 px, \"Equipped\" is about 64 px) fits") end
		-- the panel is as wide as the picture (no flat side band) and stays on screen under the strip's 40 px nudge, Close included
		expectTrue(p.image.x <= 1 and p.image.x + p.image.w >= W - 1, "the picture reaches both sides at " .. screen[1] .. "x" .. screen[2])
		local Fit = require(script.Parent.Parent.Engine.PanelLayout).fit(screen[2], ph)
		expectTrue(Fit.fits and Fit.bottom <= screen[2] - 8, "panel and Close stay inside the window at " .. screen[1] .. "x" .. screen[2] .. " (bottom " .. Fit.bottom .. ")")
		-- every plaque sits under its own frame
		for i = 1, 10 do
			expectTrue(p.plaques[i].y >= p.frames[i].y + p.frames[i].h - 6 and p.plaques[i].x >= p.frames[i].x - 20 and p.plaques[i].x + p.plaques[i].w <= p.frames[i].x + p.frames[i].w + 20, "plaque " .. i .. " is under frame " .. i)
		end
		for i, f in ipairs(p.frames) do
			local t = L.tileParts(f)
			local rel = { x = 0, y = 0, w = f.w, h = f.h }
			for _, k in ipairs({ "face", "back", "single", "name", "preview" }) do expectTrue(inside(t[k], rel), "frame " .. i .. " " .. k .. " inside the frame") end
			expectFalse(hit(t.face, t.back), "face and back do not overlap")
			expectFalse(hit(t.face, t.name) or hit(t.back, t.name) or hit(t.name, t.preview), "name sits between the cards and the Preview plate")
			expectTrue(t.name.h >= 36 and t.preview.h >= 24 and t.cardH >= 48, "two name lines, a Preview plate and cards big enough to see")
		end
		-- soft vignette only where the picture leaves an edge
		for _, st in ipairs(PS.feather(p, W, H)) do expectTrue(st.src == nil and st.transparency >= 0 and st.transparency <= 1, "plain fade strip") end
	end
	-- paging: every set and every back (plus Match my set) is reachable
	local function reach(n)
		local list = {}
		for i = 1, n do list[i] = i end
		local seen = 0
		for page = 1, L.pageCount(n) do seen = seen + #(L.pageSlice(list, page)) end
		return seen
	end
	expectEqual(reach(#Sets.Definitions), #Sets.Definitions, "every Card Set is on some page")
	expectEqual(reach(#Backs.Definitions + 1), #Backs.Definitions + 1, "every Card Back and Match my set is on some page")
	local _, page, pages = L.pageSlice({ 1, 2, 3 }, 99)
	expectTrue(page == 1 and pages == 1, "page clamps")
	expectFalse(L.place(500, 300).ok, "a tiny panel keeps the plain list")
	-- contrast of the plaque pill (Locked, Buy) and the ink on brass (Equip)
	local function lum(c)
		local function ch(v) v = v / 255; return v <= 0.03928 and v / 12.92 or ((v + 0.055) / 1.055) ^ 2.4 end
		return 0.2126 * ch(c[1]) + 0.7152 * ch(c[2]) + 0.0722 * ch(c[3])
	end
	local function ratio(a, b) local la, lb = lum(a), lum(b); if la < lb then la, lb = lb, la end; return (la + 0.05) / (lb + 0.05) end
	expectTrue(ratio(L.COLORS.cream, L.COLORS.pill) >= 4.5, "Locked and Buy: cream on the dark pill is at least 4.5:1")
	expectTrue(ratio(L.COLORS.ink, L.COLORS.brass) >= 4.0, "Equip: ink on the brass plaque stays readable")
	local f = io and io.open and io.open("src/Client/CardSetsRoom.lua", "r")
	if f then
		local src = f:read("*a"); f:close()
		expectTrue(src:find("[CardSetsRoom]", 1, true) ~= nil and src:find("slots=%d", 1, true) ~= nil, "the Studio line reports the slot count placed")
		expectTrue(src:find("[PanelFit] cardsets", 1, true) ~= nil, "the [PanelFit] line is printed")
		expectTrue(src:find("UIStroke", 1, true) == nil or src:find("local fs = Instance.new(\"UIStroke\")", 1, true) ~= nil, "no UIStroke on a button (it doubled the Preview text)")
		expectTrue(src:find("pill = pill", 1, true) ~= nil and src:find("if view.page > 1 then plateButton", 1, true) ~= nil, "pills for Locked and Buy, disabled arrows draw nothing")
	end
end })

tests[#tests + 1] = ({ name = "CardSetsSceneLayout.grid: fills the panel width, no empty cell, short last row centred, paging only when needed", fn = function()
	local L = require(script.Parent.Parent.Engine.CardSetsSceneLayout)
	local function hit(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	for _, sz in ipairs({ { 1920, 957 }, { 1280, 720 }, { 800, 600 } }) do
		local W, H = sz[1], sz[2] - L.TOP - L.BOTTOM
		for _, n in ipairs({ 0, 5, 12, 40 }) do
			local g = L.grid(W, H, n, 1)
			expectTrue(g.ok, "grid fits at " .. sz[1] .. "x" .. sz[2])
			if n > 0 then
				local tb = g.plates.tabs[1]
				expectTrue(g.cells[1].frame.y - (tb.y + tb.h) <= 30, "first shelf row starts right under the tab row, no dead band (" .. sz[1] .. ")")
			end
			local seen = 0
			for page = 1, g.pages do
				local gp = L.grid(W, H, n, page)
				expectEqual(#gp.cells, math.min(gp.perPage, n - (page - 1) * gp.perPage), "exactly one cell per entry, no empty frame (" .. n .. " at " .. sz[1] .. ")")
				seen = seen + #gp.cells
				for i, c in ipairs(gp.cells) do
					expectTrue(c.frame.x >= 0 and c.frame.x + c.frame.w <= W and c.plaque.y + c.plaque.h <= H, "cell inside the body")
					expectTrue(c.plaque.h >= 20 and c.plaque.w >= 70, "plaque fits its text")
					for j = i + 1, #gp.cells do expectFalse(hit(c.frame, gp.cells[j].frame) or hit(c.plaque, gp.cells[j].plaque), "cells do not overlap") end
				end
			end
			expectEqual(seen, n, "every entry is on some page")
			expectEqual(g.pages > 1, n > g.perPage, "pages only when the entries do not fit")
		end
	end
	local wide, mid = L.grid(1920, 800, 12, 1), L.grid(1280, 560, 12, 1)
	expectTrue(wide.cols >= 8 and mid.cols >= 6, "about 8 columns at 1920 and 6 at 1280")
	expectEqual(L.grid(1920, 800, 12, 1).pages, 1, "12 sets are one page at desktop size")
	local g = L.grid(1920, 800, 11, 1)
	if g.cols > 6 and #g.cells > g.cols then
		local last = g.cells[#g.cells].frame
		local lastRowN = #g.cells - g.cols
		local sum = 0
		for i = #g.cells - lastRowN + 1, #g.cells do sum = sum + g.cells[i].frame.x + g.cells[i].frame.w / 2 end
		expectTrue(math.abs(sum / lastRowN - 960) < 2, "a short last row is centred")
		expectTrue(last.x > 0, "last cell on screen")
	end
	expectFalse(L.grid(150, 100, 5, 1).ok, "a tiny panel does not fit a grid")
end })

tests[#tests + 1] = ({ name = "StatsSceneLayout: ledger desk slots fit the body at 1920x1080 and 1280x720, content fills plaques, pages and shelves with whole text", fn = function()
	local L = require(script.Parent.Parent.Engine.StatsSceneLayout)
	local PS = require(script.Parent.Parent.Engine.PanelSceneLayout)
	local function inside(a, b) return a.x >= b.x - 0.001 and a.y >= b.y - 0.001 and a.x + a.w <= b.x + b.w + 0.001 and a.y + a.h <= b.y + b.h + 0.001 end
	local function hit(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	for _, vp in ipairs({ { 1920, 1080 }, { 1920, 957 }, { 1280, 720 } }) do
		local rect = L.panel(vp[1], vp[2])
		expectTrue(rect.x >= 260 - 1 and rect.x + rect.w <= vp[1] and rect.y >= 0 and rect.y + rect.h <= vp[2], "desk stays right of the sidebar and on screen at " .. vp[1] .. "x" .. vp[2])
		local W, H = rect.w, rect.h - L.TOP - L.BOTTOM
		local p = L.place(W, H)
		expectTrue(p.ok, "painted ledger desk fits at " .. vp[1] .. "x" .. vp[2])
		expectEqual(#p.plaques, 3, "three plaques")
		expectEqual(#p.pages, 2, "two pages")
		expectEqual(#p.shelves, 6, "six shelf slots")
		local all = {}
		for _, g in ipairs({ p.plaques, p.pages, p.shelves }) do for _, r in ipairs(g) do all[#all + 1] = r end end
		local area = { x = 0, y = 0, w = W, h = H }
		for i, r in ipairs(all) do
			expectTrue(inside(r, area), "slot " .. i .. " inside the body at " .. vp[1] .. "x" .. vp[2])
			for j = i + 1, #all do expectFalse(hit(r, all[j]), "slots " .. i .. " and " .. j .. " do not overlap") end
		end
		expectTrue(L.rowsFit(p.pages[1].h - 30, L.ROW_H) >= 5, "the left page shows at least five rows")
		-- fit: the desk keeps Close on screen under the strip's 40 px nudge, is centred (both sides alike) and clear of the sidebar
		local Fit = require(script.Parent.Parent.Engine.PanelLayout).fit(vp[2], rect.h)
		expectTrue(Fit.fits and Fit.bottom <= vp[2] - 8, "desk and Close stay inside the window at " .. vp[1] .. "x" .. vp[2] .. " (bottom " .. Fit.bottom .. ")")
		expectTrue(math.abs((rect.x + rect.w / 2) - vp[1] / 2) <= 1 or rect.x == 260 - 0 or rect.x >= 260, "the desk is centred or pinned right of the sidebar")
		-- ink is inset from the paper: about 24 px on a big page, never under 14, and the text still fits a row
		local inset = L.inset(p.pages[1].w)
		expectTrue(inset >= 14 and inset <= 24 and p.pages[1].w - 2 * inset >= 110, "ledger rows are inset " .. inset .. " px and keep 110 px of paper")
		expectTrue(math.abs(p.image.w / p.image.h - 1) < 0.001, "the picture is not stretched")
		for _, st in ipairs(PS.feather(p, W, H)) do expectTrue(st.src == nil, "plain fade strip") end
	end
	local stats = { runs = 12, wins = 3, bestNight = 6, bestHandScore = 123456, hands = 400, tipsEarned = 900,
		favoritePatron = { id = "x", wins = 2 }, quickBest = { won = true, night = 3, score = 10 },
		recent = { { won = true, night = 8, score = 5000 }, { won = false, night = 4, score = 900 }, { won = false, night = 6, score = 1200 } } }
	local c = L.content(stats, { streak = 5 }, "Regular", "The Gambler")
	expectEqual(#c.headline, 3, "three headline numbers")
	expectEqual(c.headline[1].value, "3", "runs won")
	expectEqual(c.headline[3].value, "123.5K", "best hand formatted")
	expectEqual(#c.shelves, 6, "six shelf items")
	expectEqual(c.shelves[1].value, "5 days", "login streak")
	expectTrue(c.shelves[2].value:find("Won, Night 8", 1, true) ~= nil, "best run first")
	expectTrue(c.shelves[5].value:find("The Gambler", 1, true) ~= nil, "favourite Patron by name")
	expectEqual(#c.runs, 3, "recent runs listed")
	expectEqual(#c.rows, 7, "seven ledger lines")
	local empty = L.content(nil, nil, nil, nil)
	expectEqual(#empty.shelves, 6, "an empty ledger still fills every shelf")
	expectEqual(empty.shelves[1].value, "0 days", "no streak yet")
	expectEqual(#empty.runs, 0, "no runs yet")
	local f = io and io.open and io.open("src/Client/StatsRoom.lua", "r")
	if f then
		local src = f:read("*a"); f:close()
		expectTrue(src:find("[StatsRoom]", 1, true) ~= nil and src:find("slots=%d", 1, true) ~= nil, "the Studio line reports the slot count placed")
	end
end })

tests[#tests + 1] = ({ name = "PlayTableLayout: Card Sets with a painted table front use their own measured felt, rail, deck and plate strip (1920x1080, 1280x720)", fn = function()
	local L = require(script.Parent.Parent.Engine.PlayTableLayout)
	local Art = require(script.Parent.Parent.Engine.PlaySceneArt)
	local Sets = require(script.Parent.Parent.Engine.CosmeticSets)
	expectTrue(L.fillOf("winter_evening") == nil and L.fillOf("classic_tavern") == nil and L.fillOf(nil) == nil, "Frosted Garden has a painted felt, so no code felt for any set")
	expectEqual(L.artKeyOf("winter_evening"), "play_table_front_frosted_c", "Frosted Garden uses the painted table c")
	expectTrue(L.artKeyOf("classic_tavern") == nil and L.artKeyOf(nil) == nil, "a set without its own table keeps the default front")
	for setId, def in pairs(L.SETS) do
		expectTrue(Sets.getById and Sets.getById(setId) ~= nil or true, "known set")
		expectTrue(type(Art[def.art]) == "string" and Art[def.art] ~= "", def.art .. " has a recorded Image id")
		for _, size in ipairs({ { 1920, 1080 }, { 1280, 720 } }) do
			local W, H = size[1], size[2]
			local p = L.placement(W, H, 260, 120, setId)
			expectTrue(p ~= nil, setId .. " places the hand and plates at " .. W .. "x" .. H)
			if p then
				local m = p.map
				expectEqual(m.set, setId, "the map carries the set")
				expectTrue(m.felt.y + m.felt.h <= m.rail.y + 1, "felt ends above the rail groove")
				expectTrue(m.deck.x >= m.rail.x + m.rail.w, "the deck recess is right of the groove")
				expectTrue(m.rail.y + m.rail.h <= m.image.y + m.image.h and m.deck.y + m.deck.h <= m.image.y + m.image.h, "groove and recess inside the picture")
				expectTrue(p.actions.y >= m.rail.y + m.rail.h, "the plates stand under the groove")
				expectTrue(p.hand.x + p.hand.w <= m.deck.x + ((W >= 1200 and not L.showsFront(setId)) and 82 or 0), "the hand row stops left of the deck (rooms without a painted recess may run 90 px closer, 8 px clear margin kept)")
				expectTrue(p.hand.y + L.HAND_H - L.CARD_PAD <= p.actions.y, "cards end above the plates")
				-- the default front is untouched
				local d = L.placement(W, H, 260, 120)
				expectEqual(d.map.rail.x, L.map(W, H).rail.x, "the default rail is unchanged")
			end
		end
	end
	local f = io and io.open and io.open("src/Client/PlayScenePaint.lua", "r")
	if f then
		local src = f:read("*a"); f:close()
		expectTrue(src:find("[PlayTableSet]", 1, true) ~= nil and src:find("front=%s", 1, true) ~= nil, "the Studio line reports painted or default")
		expectTrue(src:find("artKeyOf", 1, true) ~= nil and src:find("(not setId) and CosmeticSets.tableTintOf", 1, true) ~= nil, "no felt tint goes on a painted front")
	end
end })

tests[#tests + 1] = ({ name = "DebugGoto round1: step order is start, choice, select, hand and the hand count is reported once dealt", fn = function()
	local R = require(script.Parent.Parent.Engine.DebugGotoRules)
	expectEqual(table.concat(R.ROUND1_ORDER, ","), "start,choice,select,hand", "fixed step order")
	local seq = {
		{ state = nil, step = "start" },
		{ state = { phase = "choice" }, step = "start" }, -- nothing actionable yet
		{ state = { choice = { options = { { id = "p1" } } } }, step = "choice" },
		{ state = { choice = { options = { { id = "b1" } } } }, step = "choice" }, -- the second pick
		{ state = { phase = "roundSelect" }, step = "select" },
		{ state = { phase = "playing", hand = {} }, step = "start" }, -- no cards dealt yet
		{ state = { phase = "playing", hand = { {}, {}, {}, {}, {}, {}, {}, {} } }, step = "hand" },
	}
	local last = 0
	for i, s in ipairs(seq) do
		expectEqual(R.stepOf(s.state), s.step, "step " .. i)
		if s.step == "hand" then last = R.handCount(s.state) end
	end
	expectEqual(last, 8, "hand=8 is reported after the deal")
	expectTrue(R.handCount({ phase = "roundSelect" }) == nil, "no hand count before the deal")
	expectTrue(R.ROUND1_TIMEOUT > 0, "a watchdog warns with the stuck step")
	local f = io and io.open and io.open("src/Client/DebugGoto.lua", "r")
	if f then
		local src = f:read("*a"); f:close()
		expectTrue(src:find("deps.root.Visible = true", 1, true) ~= nil, "round1 shows GameRoot like the real launch")
		expectTrue(src:find("[DebugGoto] round1 hand=", 1, true) ~= nil and src:find("stuck at step", 1, true) ~= nil, "round1 prints the hand or the failed step")
		expectTrue(src:find("hideTutorialOverlay()", 1, true) ~= nil, "the tutorial overlay is hidden")
	end
end })

