tests[#tests + 1] = ({ name = "NewsSceneLayout: painted notice board slots fit the square board at 1920x957, 1920x1080 and 1280x720, none overlap; tiny screens and more than 3 events use the plain board", fn = function()
	local L = require(script.Parent.Parent.Engine.NewsSceneLayout)
	local function inside(a, b) return a.x >= b.x - 0.001 and a.y >= b.y - 0.001 and a.x + a.w <= b.x + b.w + 0.001 and a.y + a.h <= b.y + b.h + 0.001 end
	local function hit(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	expectEqual(L.MAX_SLOTS, 5, "the layout allows up to five event slots")
	for _, vp in ipairs({ { 1920, 957 }, { 1920, 1080 }, { 1280, 720 } }) do
		local r = L.panel(vp[1], vp[2])
		expectTrue(r.w == r.h and r.x >= 0 and r.y >= 0 and r.x + r.w <= vp[1] and r.y + r.h <= vp[2], "square board on screen at " .. vp[1] .. "x" .. vp[2])
		local p = L.place(r.w)
		expectTrue(p ~= nil, "painted board fits at " .. vp[1] .. "x" .. vp[2])
		expectEqual(#p.notes, 3, "three pinned notes")
		local all = { p.banner, p.strip, p.close }
		for _, n in ipairs(p.notes) do all[#all + 1] = n end
		local area = { x = 0, y = 0, w = r.w, h = r.h }
		for i, s in ipairs(all) do
			expectTrue(inside(s, area), "slot " .. i .. " inside the board")
			for j = i + 1, #all do expectFalse(hit(s, all[j]), "slots " .. i .. " and " .. j .. " do not overlap") end
		end
		expectTrue(p.notes[1].w >= 140 and p.notes[1].h >= 190, "a note is big enough for 14 px text")
	end
	expectTrue(L.place(L.panel(800, 450).w) == nil, "a tiny window keeps the plain board")
	expectTrue(L.canShow(1) and L.canShow(3) and not L.canShow(4) and not L.canShow(0), "up to three events use the painted notes")
end })

tests[#tests + 1] = ({ name = "PanelScene: bands beside a smaller picture are flat wall colour with feathered edges, no copy of the painting", fn = function()
	local probe = io and io.open and load and io.open("src/Client/PanelScene.lua", "r")
	if not probe then return end
	probe:close()
	local FakeGui = require(script.Parent.FakeGui)
	local Engine = script.Parent.Parent.Engine
	local PSL = require(Engine.PanelSceneLayout)
	local stubs = {}
	local env, st = FakeGui.env({ stubs = stubs })
	st.services.ReplicatedStorage = { WaitForChild = function() return { WaitForChild = function()
		return FakeGui.folder({ ContentArt = { getImageId = function() return "rbxassetid://7" end }, PanelSceneLayout = PSL })
	end } end }
	local PanelScene = FakeGui.load("src/Client/PanelScene.lua", env)
	local panel = FakeGui.new("Frame")
	local scene = PanelScene.new(panel, { artKey = "x", def = {}, z = 41 })
	local holder = panel:FindFirstChild("PanelScene")
	local function names() local t = {} for _, c in ipairs(holder:GetChildren()) do t[c.Name] = true end return t end
	local small = { image = { x = 200, y = 0, w = 800, h = 800 }, scale = 1 }
	scene.show({ x = 0, y = 0, w = 1200, h = 800 }, small)
	local n = names()
	expectFalse(n.Backdrop or n.BackdropWash, "bands beside the picture are flat wall colour, never a second copy of the painting")
	expectTrue(holder:FindFirstChild("Picture"):FindFirstChild("SideFade") ~= nil, "the picture fades its own uncovered sides into the wall (one UIGradient)")
	expectFalse(n.Vignette_L or n.Vignette_R, "no flat side vignette frames that would show a seam against the painted wall")
	expectTrue(holder.Size.Y.Offset > 800, "the wall runs past the area bottom so no strip shows")
	expectTrue(n.Wall and n.Picture, "the shared painted wall sits under the picture so the sides are never flat dark voids")
	scene.show({ x = 0, y = 0, w = 1200, h = 800 }, small)
	expectTrue(names().Wall ~= nil and holder:FindFirstChild("Wall").ZIndex == 41, "a second show keeps the wall")
end })

tests[#tests + 1] = ({ name = "NewsPanel with a painted notice board (fake ids): events sit in the three slots without paper or pin of their own, Close is a plain plaque, four events use the cork board", fn = function()
	local probe = io and io.open and load and io.open("src/Client/NewsPanel.lua", "r")
	if not probe then return end
	probe:close()
	local FakeGui = require(script.Parent.FakeGui)
	local Engine = script.Parent.Parent.Engine
	local SL = require(Engine.NewsSceneLayout)
	local stubs = {}
	local env, st = FakeGui.env({ stubs = stubs })
	st.services.ReplicatedStorage = { WaitForChild = function()
		return { WaitForChild = function()
			return FakeGui.folder({ MenuNoteText = require(Engine.MenuNoteText), NewsBoardLayout = require(Engine.NewsBoardLayout), HudKit = require(Engine.HudKit), MenuSceneArt = require(Engine.MenuSceneArt), NewsSceneLayout = SL })
		end }
	end }
