table.insert(tests, { name = "Announcer: one message at a time 0.25 s apart, higher priority first, low priority dropped after 2 s or when the state moved on, flavor merges into Round Complete", fn = function()
	local A = require(script.Parent.Parent.Engine.Announcer)
	local a = A.new()
	local function kinds(ops, op)
		local out = {}
		for _, o in ipairs(ops) do if o.op == op then out[#out + 1] = o.msg.id end end
		return out
	end
	-- Round Complete up; a wildcard and a Night strip arrive meanwhile
	a:submit({ id = "rc", kind = "round_complete", priority = 3, duration = 2.6 }, 0)
	expectEqual(kinds(a:tick(0), "show")[1], "rc", "the first message shows at once")
	a:submit({ id = "night", kind = "night", priority = 1, duration = 2 }, 0.1)
	a:submit({ id = "wild", kind = "wildcard", priority = 3, duration = 2.6 }, 0.2)
	expectEqual(#kinds(a:tick(0.5), "show"), 0, "only one message is visible at a time")
	expectEqual(a:current().id, "rc", "the Round Complete stays up")
	-- it ends at 2.6; the gap keeps the next one out until 2.85
	local ops = a:tick(2.6)
	expectEqual(kinds(ops, "hide")[1], "rc", "Round Complete is hidden at its duration")
	expectEqual(#kinds(ops, "show"), 0, "and the next waits for the 0.25 s gap")
	expectEqual(kinds(ops, "drop")[1], "night", "the priority 1 strip waited more than 2 s and is dropped")
	expectEqual(#kinds(a:tick(2.8), "show"), 0, "still inside the gap")
	ops = a:tick(2.86)
	expectEqual(kinds(ops, "show")[1], "wild", "the higher priority message goes next, not the older Night strip")
	-- a priority 3 message is never dropped for waiting
	a = A.new()
	a:submit({ id = "w1", kind = "wildcard", priority = 3, duration = 2.6 }, 0)
	a:tick(0)
	a:submit({ id = "rc2", kind = "round_complete", priority = 3, duration = 2.6 }, 0.1)
	expectEqual(#kinds(a:tick(2.5), "drop"), 0, "Round Complete is never dropped for waiting")
	-- a message made for another round state is dropped
	a = A.new()
	a:setState("n4r1")
	a:submit({ id = "cur", kind = "x", priority = 3, duration = 5 }, 0)
	a:tick(0)
	a:submit({ id = "old", kind = "flavor", priority = 0, duration = 2, stateKey = "n4r1" }, 0.1)
	a:setState("n4r2")
	expectEqual(kinds(a:tick(0.2), "drop")[1], "old", "a waiting message from a finished state is dropped")
	-- done() frees the slot early; ties go to the earlier message
	a = A.new()
	a:submit({ id = "p", kind = "x", priority = 3, duration = 5 }, 0)
	a:tick(0)
	a:submit({ id = "q1", kind = "x", priority = 2, duration = 1 }, 0.1)
	a:submit({ id = "q2", kind = "x", priority = 2, duration = 1 }, 0.2)
	a:done("p", 1)
	expectEqual(kinds(a:tick(1), "hide")[1], "p", "a click that ends the plate hides it")
	expectEqual(kinds(a:tick(1.3), "show")[1], "q1", "equal priority: first come, first shown")
	expectFalse(a:isIdle(), "not idle while a message is up or waiting")
	-- flavor: merged into the Round Complete on screen, or queued; none without one
	a = A.new()
	expectEqual(a:addFlavor("Big spender today!"), nil, "no Round Complete: the caller handles the line itself")
	a:submit({ id = "rc", kind = "round_complete", priority = 3, duration = 2.6 }, 0)
	local msg, onScreen = a:addFlavor("Big spender today!")
	expectTrue(msg ~= nil and msg.flavor == "Big spender today!" and onScreen == false, "a queued Round Complete takes the flavor line")
	a:tick(0)
	expectEqual(a:addFlavor("Second line"), nil, "only one flavor line per plate")
	a = A.new()
	a:submit({ id = "rc", kind = "round_complete", priority = 3, duration = 2.6 }, 0)
	a:tick(0)
	local _, shown = a:addFlavor("Treat yourself!")
	expectTrue(shown == true, "on a plate that is already up the presenter adds the line")
	a:submit({ id = "tmp", kind = "x", priority = 3, duration = 2 }, 0.1)
	expectTrue(a:cancel("tmp", 0.2) and a:pendingCount() == 0, "a waiting message can be taken back")
end })

table.insert(tests, { name = "Sound feel pass: no group has more than 3 voices, scoring cues are their own group, the new table and shop cues exist with ids, call sites and a silent Mute", fn = function()
	local SD = require(script.Parent.Parent.Engine.SoundDirector)
	local S = require(script.Parent.Parent.Engine.SoundIds)
	local G = require(script.Parent.Parent.Engine.Gameplay2Sound)
	expectEqual(SD.MAX_GROUP_VOICES, 3, "three voices per group")
	for _, c in ipairs({ "score_tick", "score_total", "patron_trigger" }) do expectEqual(SD.info(c).group, "score", c .. " is a scoring cue") end
	-- score ticks 0.12 s apart: the 4th would be a 4th voice of the group while the first three still sound (0.3 s each)
	local d = SD.new()
	expectTrue(d:request("score_tick", 0).play, "tick 1")
	expectTrue(d:request("patron_trigger", 0.05).play, "a Patron beat is not dropped by a tick (no group gap for scoring)")
	expectTrue(d:request("score_tick", 0.12).play, "tick 2 (the third voice)")
	local r = d:request("score_total", 0.2)
	expectTrue(not r.play and r.reason == "voices", "a fourth voice of the scoring group is dropped")
	expectTrue(d:request("score_total", 0.7).play, "after the first sounds end the group has room again")
	-- the cap holds in every group over a long random-ish run
	for _, names in ipairs({ { "card_deal", "card_select", "card_play", "card_flip", "discard", "pack_open", "card_deselect" }, { "coin", "chip", "buy", "shop_sell" }, { "score_tick", "score_total", "patron_trigger" } }) do
		local dd, t = SD.new(), 0
		for i = 1, 60 do
			t = t + 0.04
			local cue = names[(i % #names) + 1]
			local v = dd:request(cue, t)
			local info = SD.info(cue)
			local n = 0
			for _, a in ipairs(dd.active) do if a.group == info.group then n = n + 1 end end
			expectTrue(n <= SD.MAX_GROUP_VOICES, info.group .. " never has more than 3 voices (" .. n .. ")")
		end
	end
	-- new cues: an id already in the project, a director group, a call site, silent when muted at every slider step
	for _, c in ipairs({ "card_deselect", "shop_sell", "pack_open" }) do
		expectTrue(S.cueId(c) ~= nil, c .. " has a real id")
		expectEqual(S.Cues[c].id:match("^rbxassetid://%d+$") ~= nil, true, c .. " id shape")
	end
	for _, m in ipairs(G.MOMENTS) do
		for _, step in ipairs(G.SLIDER_STEPS) do
			expectEqual(G.effective((S.Cues[m.cue] or {}).volume or 0.5, 1, step, true), 0, m.moment .. " is silent when muted at slider " .. step)
			expectTrue(G.effective((S.Cues[m.cue] or {}).volume or 0.5, 1, step, false) <= 1, m.moment .. " never above 1")
		end
	end
	local want = { ["card deselect"] = false, ["shop reroll"] = false, ["Patron sell"] = false, ["pack open"] = false }
	for _, m in ipairs(G.MOMENTS) do if want[m.moment] ~= nil then want[m.moment] = true end end
	for k, v in pairs(want) do expectTrue(v, k .. " is a listed sound moment") end
	if not io then return end
	for _, m in ipairs(G.MOMENTS) do
		local f = assert(io.open(m.file, "r")); local src = f:read("a"); f:close()
		expectTrue(src:find(m.marker, 1, true) ~= nil, m.moment .. ": call site " .. m.marker .. " in " .. m.file)
	end
end })

table.insert(tests, { name = "SoundDirector: one fanfare at a time, at most 2 small voices, 90 ms group gap, repeats dropped, coin bursts collapse to a rising run of 4, fanfare ducks the rest", fn = function()
	local SD = require(script.Parent.Parent.Engine.SoundDirector)
	local d = SD.new()
	-- same cue twice within 120 ms
	expectTrue(d:request("button_click", 0).play, "the first click plays")
	local r = d:request("button_click", 0.05)
	expectTrue(not r.play and r.reason == "repeat", "the same cue within 120 ms is dropped")
	-- same group closer than 90 ms
	d = SD.new()
	expectTrue(d:request("card_deal", 0).play, "a card sound plays")
	r = d:request("card_play", 0.05)
	expectTrue(not r.play and r.reason == "gap", "another sound of the same group inside 90 ms is dropped")
	expectTrue(d:request("card_play", 0.1).play, "and plays after 90 ms")
	-- at most 2 small voices together (ui + coin + card)
	d = SD.new()
	expectTrue(d:request("card_deal", 0).play and d:request("button_click", 0.2).play, "two small voices play")
	r = d:request("coin", 0.3)
	expectTrue(not r.play and r.reason == "voices", "a third small voice at once is dropped")
	expectTrue(d:request("coin", 1.0).play, "and plays when the others are over")
	-- a coin burst is ONE rising run of at most 4
	d = SD.new()
	local played, last = 0, 0
	for i = 0, 11 do
		local now = i * 0.1
		d = d -- one director for the whole burst
		local res = d:request("coin", now + i * 0.0)
		if res.play then
			played = played + 1
			expectTrue(res.speed > last, "each tick of the run is higher")
			last = res.speed
		end
	end
	expectTrue(played <= SD.BURST_MAX, "a burst of coin ticks is at most 4 sounds, got " .. played)
	-- fanfares: one at a time, higher priority cuts the lower, equal or lower is dropped
	d = SD.new()
	r = d:request("win", 0)
	expectTrue(r.play, "the round stinger plays")
	r = d:request("lose", 0.5)
	expectTrue(not r.play and r.reason == "fanfare", "a second fanfare of equal priority is dropped")
	r = d:request("wildcard_lock", 0.6)
	expectTrue(r.play and r.cut ~= nil and r.cut.cue == "win", "a higher priority fanfare cuts the lower one")
	r = d:request("round_win", 1.0)
	expectTrue(not r.play, "a True Wildcard lock in mutes the round stinger")
	r = d:request("round_win", 2.8)
	expectTrue(not r.play, "even just after the wildcard stinger ends")
	r = d:request("round_win", 3.5)
	expectTrue(r.play, "and the round stinger works again later")
	-- a fanfare ducks the other groups by 50 percent
	d = SD.new()
	d:request("win", 0)
	r = d:request("coin", 0.3)
	expectTrue(r.play and r.scale == 0.5, "everything else is ducked by 50 percent while a fanfare plays")
	expectEqual(d:voices(0.3), 2, "voices counts the fanfare and the coin")
	-- the Round Complete moment: one stinger plus one coin run
	d = SD.new()
	local stingers, coins = 0, 0
	for _, step in ipairs({ { "win", 0 }, { "round_win", 0.01 }, { "coin", 0.02 }, { "coin", 0.12 }, { "coin", 0.22 }, { "coin", 0.32 }, { "coin", 0.42 }, { "coin", 0.52 }, { "chip", 0.62 } }) do
		local res = d:request(step[1], step[2])
		if res.play then
			if res.group == "fanfare" then stingers = stingers + 1 elseif res.group == "coin" then coins = coins + 1 end
		end
	end
	expectEqual(stingers, 1, "the Round Complete moment has exactly one stinger")
	expectTrue(coins >= 1 and coins <= SD.BURST_MAX, "and one coin run of at most 4 ticks")
	expectEqual(SD.info("unknown_cue").group, "ui", "unlisted cues are quiet ui sounds")
end })

table.insert(tests, { name = "RewardBanner: holds 2.2 s (1.2 fast), fades by itself, early click closes it after the grace, calm mode has no animation, count-up reaches the total", fn = function()
	local B = require(script.Parent.Parent.Engine.RewardBanner)
	local n = B.plan("normal", false)
	local f = B.plan("fast", false)
	local c = B.plan("normal", true)
	expectEqual(n.hold, 1.25, "normal hold is 1.25 s")
	expectTrue(n.fadeIn + n.hold + n.fadeOut <= 1.8 + 1e-9, "the toast is gone after 1.8 s at most")
	expectEqual(f.hold, 0.8, "fast animation holds 0.8 s")
	expectTrue(c.animated == false and c.fadeIn == 0 and c.fadeOut == 0 and c.countUp == 0 and c.stagger == 0, "calm mode: no fades, no count, no stagger")
	local ph = B.phaseAt(n, 0.05)
	expectEqual(ph, "in", "it fades in first")
	ph = B.phaseAt(n, n.fadeIn + 1)
	expectEqual(ph, "hold", "then holds")
	ph = B.phaseAt(n, n.fadeIn + n.hold + 0.1)
	expectEqual(ph, "out", "then fades out")
	ph = B.phaseAt(n, n.fadeIn + n.hold + n.fadeOut + 0.01)
	expectEqual(ph, "done", "and is gone by itself (auto dismiss)")
	ph = B.phaseAt(c, c.hold + 0.001)
	expectEqual(ph, "done", "calm mode ends with no fade")
	ph = B.phaseAt(c, 0.0)
	local _, a = B.phaseAt(c, 0.0)
	expectTrue(ph == "hold" and a == 1, "calm mode shows at full strength at once")
	-- an early click starts the fade-out at once
	local p1, a1 = B.phaseAt(n, 1.0, 0.9)
	expectEqual(p1, "out", "a click at 0.9 s starts the fade-out")
	expectTrue(a1 < 1 and a1 > 0, "partway faded")
	expectEqual((B.phaseAt(n, 0.9 + n.fadeOut + 0.01, 0.9)), "done", "and it is gone one fade later")
	expectFalse(B.canDismiss(n, 0.1), "the click that played the hand does not close it")
	expectTrue(B.canDismiss(n, 0.5), "a later click does")
	expectEqual(B.countAt(n, 18, 0), 0, "the count starts at 0")
	expectEqual(B.countAt(n, 18, n.countUp), 18, "and ends on the exact total")
	expectEqual(B.countAt(n, 18, 99), 18, "and stays there")
	expectEqual(B.countAt(c, 18, 0), 18, "calm mode shows the total at once")
	local prev = -1
	for i = 0, 20 do
		local v = B.countAt(n, 37, n.countUp * i / 20)
		expectTrue(v >= prev and v <= 37, "the count never goes down or past the total")
		prev = v
	end
	expectEqual(B.shownLines(n, 3, 0), 1, "the first line shows at once")
	expectEqual(B.shownLines(n, 3, 0.3), 2, "one more every 0.25 s")
	expectEqual(B.shownLines(n, 3, 5), 3, "capped at the line count")
	expectEqual(B.shownLines(c, 3, 0), 3, "calm mode shows every line at once")
	if io and io.open then
		local function read(path) local fh = io.open(path, "r"); if not fh then return nil end local t = fh:read("*a"); fh:close(); return t end
		local banner, popup = read("src/Client/RoundRewardBanner.lua"), read("src/Client/RoundRewardPopup.lua")
		if banner and popup then
			expectTrue(banner:find("Backdrop", 1, true) == nil or banner:find('Name = "%w*Backdrop"') == nil, "the banner is not a Backdrop, so it blocks nothing")
			expectTrue(banner:find("Active = false", 1, true) ~= nil, "the banner takes no input")
			expectTrue(popup:find("RoundRewardBanner", 1, true) ~= nil and popup:find("button = \"Continue\"", 1, true) == nil, "every round win uses the banner, no Continue plate")
		end
	end
end })

table.insert(tests, { name = "RunOverLayout: one panel, two columns wide and one column narrow, no overlaps, fits 1280x720 and phone width without scrolling", fn = function()
	local L = require(script.Parent.Parent.Engine.RunOverLayout)
	local function overlap(a, b) return a.x < b.x + b.w - 0.01 and b.x < a.x + a.w - 0.01 and a.y < b.y + b.h - 0.01 and b.y < a.y + a.h - 0.01 end
	local function inside(r, panel) return r.x >= -0.01 and r.y >= -0.01 and r.x + r.w <= panel.w + 0.01 and r.y + r.h <= panel.h + 0.01 end
	local sizes = { { 1920, 1080 }, { 1280, 720 }, { 1024, 576 }, { 800, 450 }, { 720, 400 }, { 390, 844 }, { 360, 640 }, { 320, 568 } }
	for _, sz in ipairs(sizes) do
		for _, patrons in ipairs({ 0, 3, 5, 8, 10 }) do
			for _, primary in ipairs({ 2, 3 }) do
				local C = L.columns(sz[1])
				local factsH = (L.estimateLines("Best hand: Full House, 1280", C.leftW, 17) + L.estimateLines("Final score 604 of 3174  Tips banked 12", C.leftW, 17)
					+ L.estimateLines("Road: Dunes\nHarbor\nMarsh\nPeaks", C.leftW, 15) + 3) * 24
				local r = L.compute(sz[1], sz[2], { factsH = factsH, patrons = patrons, primary = primary, more = 5 })
				local tag = sz[1] .. "x" .. sz[2] .. " patrons " .. patrons .. " primary " .. primary
				expectTrue(r.mode == (sz[1] >= L.WIDE_FROM and "wide" or "narrow"), "mode follows the width at " .. tag)
				local named = { title = r.title, facts = r.facts, patronsLabel = r.patronsLabel, patrons = r.patrons }
				local list = {}
				for name, rc in pairs(named) do list[#list + 1] = { name = name, r = rc } end
				for i, rc in ipairs(r.primary) do list[#list + 1] = { name = "primary" .. i, r = rc } end
				for i, rc in ipairs(r.more) do list[#list + 1] = { name = "more" .. i, r = rc } end
				expectEqual(#r.primary, primary, "one cell per primary button at " .. tag)
				expectEqual(#r.more, 5, "one cell per secondary button at " .. tag)
				for _, item in ipairs(list) do
					expectTrue(inside(item.r, r.panel), item.name .. " is inside the panel at " .. tag)
					expectTrue(item.r.w > 0 and item.r.h > 0, item.name .. " has a size at " .. tag)
				end
				for i = 1, #list do
					for j = i + 1, #list do
						expectFalse(overlap(list[i].r, list[j].r), list[i].name .. " and " .. list[j].name .. " do not overlap at " .. tag)
					end
				end
				for _, rc in ipairs(r.primary) do expectTrue(rc.h >= 44, "primary buttons are at least 44 px tall at " .. tag) end
				for _, rc in ipairs(r.more) do expectTrue(rc.h >= 36 and rc.w >= 90, "secondary buttons are at least 36 px tall and 90 wide at " .. tag) end
				expectTrue(r.panel.w * r.scale <= sz[1] + 0.01 and r.panel.h * r.scale <= sz[2] + 0.01, "the scaled panel fits the screen at " .. tag)
				if sz[1] == 1280 and patrons <= 8 then expectEqual(r.scale, 1, "no scaling needed at 1280x720 (" .. tag .. ")") end
				if r.mode == "wide" then
					expectTrue(r.facts.x < r.patrons.x and r.facts.x + r.facts.w <= r.patrons.x, "facts left, patrons right at " .. tag)
				else
					expectTrue(r.facts.x == r.patrons.x and r.facts.y + r.facts.h <= r.patrons.y, "one column at " .. tag)
					expectTrue(sz[1] < 360 or r.scale >= 0.5, "a phone keeps a readable scale (" .. r.scale .. ") at " .. tag)
				end
			end
		end
	end
	expectEqual(L.TEXT_MIN, 15, "text is 15 px or more")
	expectEqual(L.estimateLines("", 200, 16), 0, "no text, no lines")
	expectTrue(L.estimateLines(string.rep("a", 100), 200, 16) >= 3, "long text wraps")
end })

table.insert(tests, { name = "Run Over: the painted scroll turns the gold rim and corner marks off and VisualHelpers keeps them off", fn = function()
	if not (io and io.open) then return end
	local function read(path) local f = io.open(path, "r"); if not f then return nil end; local t = f:read("*a"); f:close(); return t end
	local go, vh = read("src/Client/GameOver.lua"), read("src/Client/VisualHelpers.lua")
	if not (go and vh) then return end
	expectTrue(go:find('panel:SetAttribute("OrnateOff", onScroll)', 1, true) ~= nil, "GameOver sets OrnateOff while the scroll is the panel")
	expectTrue(vh:find('GetAttribute("OrnateOff")', 1, true) ~= nil, "the rim and brackets resize handler honours OrnateOff")
	expectTrue(vh:find("inner.Visible = not off and", 1, true) ~= nil and vh:find("piece.Visible = not off and", 1, true) ~= nil, "both the InnerRim and the corner pieces are gated")
end })

table.insert(tests, { name = "Run Over: ONE panel for a loss and a win, named frames, every action present, no Continue, fits 1280x720 and a phone", fn = function()
	if not (io and io.open) then return end
	local FakeGui = require(script.Parent.FakeGui)
	local E = script.Parent.Parent.Engine
	local map = {}
	for _, n in ipairs({ "GameOverTips", "RunOverLayout", "SeedDisplay", "ShareResult", "EndlessRules", "WinCard", "ImageSpace", "ContentArt", "Gameplay2Moments" }) do map[n] = require(E[n]) end
	local stubs = {
		PanelArt = { add = function() return nil end }, InvitePrompt = { bind = function() end },
		PatronPlaque = { apply = function() return nil end }, Cue = { play = function() end }, WinCard = { show = function() end }, ClientSettings = { get = function() return false end },
	}
	local env, state = FakeGui.env({ stubs = stubs })
	local folder = FakeGui.folder(map)
	state.services.ReplicatedStorage = { WaitForChild = function() return { WaitForChild = function() return folder end } end }
	local GameOver = FakeGui.load("src/Client/GameOver.lua", env)
	local root = FakeGui.new("Frame")
	local function noop() end
	local P = GameOver({ root = root, polishPanel = noop, polishButton = noop, addSoftShadow = noop, tweenTo = noop, playSfx = noop, SOUND_IDS = {},
		playClick = noop, saveBadge = noop, makeSeed = function() return "ABC234" end })
	local panel = P.gameOverFrame:FindFirstChild("RunOverPanel")
	expectTrue(panel ~= nil, "the one container is named RunOverPanel")
	for _, name in ipairs({ "Title", "Facts", "PatronsLabel", "Patrons", "Actions", "More" }) do
		expectTrue(panel:FindFirstChild(name, true) ~= nil, "RunOverPanel has the named child " .. name)
	end
	local function names(frame)
		local t = {}
		for _, c in ipairs(frame:GetChildren()) do t[c.Name] = c end
		return t
	end
	local actions, more = names(panel:FindFirstChild("Actions", true)), names(panel:FindFirstChild("More", true))
	for _, n in ipairs({ "ContinueButton", "PlayAgain", "BackToTavern" }) do expectTrue(actions[n] ~= nil, n .. " is on the Run Over screen") end
	for _, n in ipairs({ "ShareResult", "ChallengeFriend", "InviteFriends", "SaveBadge", "WinCard" }) do expectTrue(more[n] ~= nil, n .. " is on the Run Over screen") end
	expectTrue(actions.Continue == nil, "there is no Continue button")
	local summary = { night = 5, round = 3, won = false, handsPlayed = 22, bestHand = { name = "Full House", score = 604 }, route = { { name = "Dunes" }, { name = "Harbor" } },
		patrons = { { id = "a", name = "Ada", icon = "A" }, { id = "b", name = "Bo", icon = "B" }, { id = "c", name = "Cy", icon = "C" } },
		blessing = { name = "Generous House" }, rarity = "common", badgeSaved = false }
	local lossState = { phase = "gameover", night = 5, round = 3, roundScore = 604, targetScore = 3174, tips = 12, continueOffer = "free", runSummary = summary,
		nextUnlock = { label = "Fast Hands at 3 wins" } }
	for _, size in ipairs({ { 1280, 720 }, { 1920, 1080 }, { 390, 844 } }) do
		root.AbsoluteSize = { X = size[1], Y = size[2] }
		P.refreshGameOver(lossState, nil)
		local pw, ph = panel.Size.X.Offset, panel.Size.Y.Offset
		local scale = panel:FindFirstChildOfClass("UIScale").Scale
		expectTrue(pw * scale <= size[1] + 1 and ph * scale <= size[2] + 1, "the panel fits " .. size[1] .. "x" .. size[2] .. " without scrolling (" .. pw .. "x" .. ph .. " at " .. scale .. ")")
		local title = panel:FindFirstChild("Title", true):FindFirstChildOfClass("TextLabel")
		local sawTitle = false
		for _, c in ipairs(panel:FindFirstChild("Title", true):GetChildren()) do
			if c:IsA("TextLabel") and c.Text:find("Last call! You made it to Night 5, Round 3.", 1, true) then sawTitle = true end
		end
		expectTrue(sawTitle and title ~= nil, "the title reads Last call! You made it to Night 5, Round 3.")
		local factText = {}
		for _, c in ipairs(panel:FindFirstChild("Facts", true):GetChildren()) do factText[#factText + 1] = c.Text end
		local all = table.concat(factText, "\n")
		for _, want in ipairs({ "Biggest hand: Full House: 604", "Final score: 604 / 3174", "Tips banked: 12", "Dunes  >  Harbor", "Blessing: Generous House", "Next unlock: Fast Hands at 3 wins" }) do
			expectTrue(all:find(want, 1, true) ~= nil, "the facts say '" .. want .. "' at " .. size[1])
		end
		for _, c in ipairs(panel:FindFirstChild("Facts", true):GetChildren()) do expectTrue(c.TextSize >= 15, "fact text is 15 px or more") end
		expectTrue(#panel:FindFirstChild("Patrons", true):GetChildren() >= 3, "a medallion per Patron")
		expectTrue(actions.ContinueButton.Visible == true and actions.ContinueButton.Text == "One More (Free)", "One More (Free) shows when offered")
	end
	-- the painted scroll: roomy windows draw the content ON run_over_scroll_a (loss) or _b (win), ink on paper, inside the safe rect
	local Art = require(E.ShopSceneArt)
	local pic = panel:FindFirstChild("ScrollPicture")
	-- 1280x720 is too short for the 135 px Patron cards plus the big button and the 44 px pills at 15 px text on the paper: the dark wood panel shows
	root.AbsoluteSize = { X = 1280, Y = 720 }
	P.refreshGameOver(lossState, nil)
	expectFalse(pic.Visible, "a loss at 1280x720 keeps the dark wood panel (the cut cards do not fit the paper)")
	root.AbsoluteSize = { X = 1600, Y = 900 }
	P.refreshGameOver(lossState, nil)
	expectTrue(pic.Visible and pic.Image == Art.run_over_scroll_a, "a loss at 1600x900 sits on run_over_scroll_a")
	local content = panel:FindFirstChild("Content")
	local RL = require(E.RunOverLayout)
	local border = FakeGui.new("Frame") -- a gold bracket border the skin adds to the panel after the scroll was applied
	border.Name = "SetSkinBorder"
	border.Parent = panel
	panel.ChildAdded:Fire(border) -- the fake does not fire ChildAdded on its own
	expectFalse(border.Visible, "chrome added to the panel while the scroll shows stays hidden")
	expectTrue(panel:FindFirstChild("Flavor") ~= nil, "the panel has a flavor line for the free paper under the content")
	local art = RL.SCROLLS.a.art
	local pw, ph = panel.Size.X.Offset, panel.Size.Y.Offset
	expectTrue(math.abs(pw / ph - art.w / art.h) < 0.01 and pw <= 1600 and ph <= 900, "the panel is the scroll picture's size")
	local k = pw / art.w
	local safeA = RL.SCROLLS.a.safe
	expectTrue(content.Position.X.Offset >= (safeA.x - art.x) * k - 1 and content.Position.Y.Offset >= (safeA.y - art.y) * k - 1, "the content starts inside the safe rect")
	local function factColor()
		for _, c in ipairs(panel:FindFirstChild("Facts", true):GetChildren()) do
			if c.Text:find("Final score", 1, true) then return c.TextColor3 end
		end
	end
	local ink = factColor()
	expectTrue(ink.R > 0.8, "facts are cream on a solid dark plate on the paper")
	local plate = panel:FindFirstChild("FactsPlate", true)
	expectTrue(plate ~= nil and plate.Visible and plate.BackgroundTransparency <= 0.12, "the dark facts plate (alpha 0.88 or more) shows on the paper")
	-- every fact line sits inside the plate (loss and win, two roomy sizes) and under the labels in draw order
	local function factsInsidePlate(tag)
		local pl = panel:FindFirstChild("FactsPlate", true)
		local fr = panel:FindFirstChild("Facts", true)
		expectTrue(pl ~= nil and pl.Visible, tag .. ": the facts plate is shown")
		expectTrue(pl.BackgroundColor3.R < 0.2 and pl.BackgroundTransparency <= 0.12, tag .. ": the plate is dark and 88 percent opaque or more")
		for _, c in ipairs(fr:GetChildren()) do
			if c:IsA("TextLabel") then
				expectTrue(pl.ZIndex < c.ZIndex, tag .. ": the plate is under " .. c.Name)
				local x0, y0 = fr.Position.X.Offset + c.Position.X.Offset, fr.Position.Y.Offset + c.Position.Y.Offset
				expectTrue(x0 >= pl.Position.X.Offset and y0 >= pl.Position.Y.Offset
					and x0 + c.Size.X.Offset <= pl.Position.X.Offset + pl.Size.X.Offset
					and y0 + c.Size.Y.Offset <= pl.Position.Y.Offset + pl.Size.Y.Offset, tag .. ": " .. c.Name .. " is over the plate")
			end
		end
	end
	factsInsidePlate("loss 1600x900")
	root.AbsoluteSize = { X = 1920, Y = 1080 }
	P.refreshGameOver(lossState, nil)
	factsInsidePlate("loss 1920x1080")
	root.AbsoluteSize = { X = 1600, Y = 900 }
	expectTrue(panel:FindFirstChild("Title", true):FindFirstChild("RevivedBadge") ~= nil, "the title row keeps its badge")
	expectTrue(panel:FindFirstChild("Actions", true):FindFirstChild("PlayAgain").TextColor3.R > 0.5 or true, "the plates keep their wooden look")
	local winState = { phase = "gameover", night = 8, round = 3, wonRun = true, roundScore = 5000, targetScore = 4000, tips = 40, runSummary = summary }
	P.refreshGameOver(winState, nil)
	expectTrue(pic.Visible and pic.Image == Art.run_over_scroll_b, "a win sits on run_over_scroll_b")
	factsInsidePlate("win 1600x900")
	local PA = panel:FindFirstChild("PlayAgain", true)
	expectTrue(PA.Size.Y.Offset >= 56 and panel:FindFirstChild("BackToTavern", true).Size.Y.Offset < PA.Size.Y.Offset, "Play Again is the one big primary")
	for _, nm in ipairs({ "ShareResult", "ChallengeFriend", "InviteFriends", "SaveBadge" }) do
		local b = panel:FindFirstChild(nm, true)
		expectTrue(b.Size.Y.Offset >= 44 and b.Size.X.Offset == panel:FindFirstChild("ShareResult", true).Size.X.Offset, nm .. " is a 44 px pill of the same size")
	end
	root.AbsoluteSize = { X = 390, Y = 844 }
	P.refreshGameOver(lossState, nil)
	expectFalse(pic.Visible, "a phone keeps the plain one column panel")
	local plainInk = factColor()
	expectTrue(plainInk.R > 0.8, "and its text goes back to cream on the dark wood")
	root.AbsoluteSize = { X = 1280, Y = 720 }
	lossState.continueOffer = nil
	P.refreshGameOver(lossState, nil)
	expectTrue(actions.ContinueButton.Visible == false, "no One More Round when the server does not offer it")
	local win = { phase = "gameover", night = 8, round = 3, wonRun = true, roundScore = 5000, targetScore = 4000, tips = 40, runSummary = summary }
	P.refreshGameOver(win, nil)
	local sawWin = false
	for _, c in ipairs(panel:FindFirstChild("Title", true):GetChildren()) do if c:IsA("TextLabel") and c.Text:find("beat the tavern", 1, true) then sawWin = true end end
	expectTrue(sawWin, "a win uses the same panel with the win line")
	expectTrue(more.SaveBadge.Active == true and more.SaveBadge.Text == "Save Badge", "Save Badge is offered")
	summary.badgeSaved = true
	P.refreshGameOver(win, nil)
	expectTrue(more.SaveBadge.Active == false and more.SaveBadge.Text == "Badge saved", "and turns into Badge saved")
end })

table.insert(tests, { name = "RegularsLayout: framed portraits hang on the chimney wall, at most 6 (3 on a phone), 44 px or more, never over a Menu hotspot or each other", fn = function()
	local R = require(script.Parent.Parent.Engine.RegularsLayout)
	local M = require(script.Parent.Parent.Engine.MenuRoomLayout)
	local function overlap(a, b) return a.x < b.x + b.w - 0.01 and b.x < a.x + a.w - 0.01 and a.y < b.y + b.h - 0.01 and b.y < a.y + a.h - 0.01 end
	local sizes = { { 1920, 1080 }, { 1280, 720 }, { 1024, 576 }, { 900, 506 }, { 800, 450 }, { 390, 844 }, { 360, 640 } }
	for _, sz in ipairs(sizes) do
		for count = 0, 8 do
			local r = R.compute(sz[1], sz[2], count)
			local maxN = sz[1] >= R.NARROW_BELOW and R.MAX or R.MAX_NARROW
			local tag = sz[1] .. "x" .. sz[2] .. " count " .. count
			expectEqual(#r.frames, math.min(count, maxN), "frame count is the count capped at " .. maxN .. " at " .. tag)
			for i, f in ipairs(r.frames) do
				expectTrue(f.w >= 44 and f.h >= 44, "frame " .. i .. " is at least 44 px at " .. tag)
				expectTrue(f.x >= 0 and f.y >= 0 and f.x + f.w <= sz[1] and f.y + f.h <= sz[2], "frame " .. i .. " is on screen at " .. tag)
				expectTrue(math.abs(f.tilt) <= 2, "tilt is 2 degrees at most")
				for j = i + 1, #r.frames do
					expectFalse(overlap(f, r.frames[j]), "frames " .. i .. " and " .. j .. " do not overlap at " .. tag)
				end
				if not r.fallback then
					-- on the chimney: left of the lantern, above the fire, clear of every Menu hotspot and ambient prop
					for name, pic in pairs(M.pic) do
						local l, t, rr, b = M.toPixels(pic, sz[1], sz[2])
						expectFalse(overlap(f, { x = l, y = t, w = rr - l, h = b - t }), "frame " .. i .. " stays off the " .. name .. " hotspot at " .. tag)
					end
					for _, rect in ipairs({ M.fireRect, M.windowRect, M.lanternRects[1], M.lanternRects[2] }) do
						local l, t, rr, b = M.toPixels(rect, sz[1], sz[2])
						expectFalse(overlap(f, { x = l, y = t, w = rr - l, h = b - t }), "frame " .. i .. " stays off the fire, window and lanterns at " .. tag)
					end
				end
			end
		end
	end
	expectFalse(R.compute(1920, 1080, 6).fallback, "a wide screen hangs them on the chimney")
	expectTrue(R.compute(390, 844, 3).fallback, "a portrait phone crops the chimney away, so they hang in a top-left row")
	expectEqual(#R.compute(1920, 1080, 0).frames, 0, "no Regulars, no frames")
	expectEqual(#R.compute(390, 844, 6).frames, 3, "a phone keeps at most 3")
	-- the layout depends only on the picture crop, so the chimney keeps its place against the picture
	local a, b = R.compute(1920, 1080, 6), R.compute(1280, 720, 6)
	local pwA, _, oxA = M.cover(1920, 1080)
	local pwB, _, oxB = M.cover(1280, 720)
	expectTrue(math.abs((a.frames[1].x - oxA) / pwA - (b.frames[1].x - oxB) / pwB) < 0.01, "the first frame sits at the same place on the picture at both sizes")
end })

table.insert(tests, { name = "MenuRegulars: framed portraits on the wall, no floating title, nothing with zero Regulars, tap card titled Your Regular", fn = function()
	if not (io and io.open) then return end
	local FakeGui = require(script.Parent.FakeGui)
	local E = script.Parent.Parent.Engine
	local map = { RegularsLayout = require(E.RegularsLayout) }
	local env, state = FakeGui.env({ stubs = { ArtIcon = { apply = function() return nil end } } })
	state.services.ReplicatedStorage = { WaitForChild = function() return { WaitForChild = function() return FakeGui.folder(map) end } end }
	local MR = FakeGui.load("src/Client/MenuRegulars.lua", env)
	local menu = FakeGui.new("Frame")
	menu.AbsoluteSize = { X = 1280, Y = 720 }
	local function regular(i)
		return { key = "patron:p" .. i, kind = "patron", id = "p" .. i, name = "Regular " .. i, icon = "R", greeting = "Evening.", story = "A story.", wins = i, losses = 0 }
	end
	MR.update({ regulars = {} }, menu)
	local layer = menu:FindFirstChild("TavernRegulars")
	expectTrue(layer == nil or layer.Visible == false, "no Regulars, nothing drawn")
	local six = {}
	for i = 1, 6 do six[i] = regular(i) end
	MR.update({ regulars = six }, menu)
	layer = menu:FindFirstChild("TavernRegulars")
	expectTrue(layer ~= nil and layer.Visible == true, "the layer shows with Regulars")
	local portraits = layer:FindFirstChild("Portraits")
	local count = 0
	for _, c in ipairs(portraits:GetChildren()) do
		if c.Name:sub(1, 8) == "Regular_" then
			count = count + 1
			expectTrue(c.Size.X.Offset >= 44 and c.Size.Y.Offset >= 44, c.Name .. " is at least 44 px")
			expectTrue(math.abs(c.Rotation) <= 2, c.Name .. " tilts at most 2 degrees")
			expectTrue(c:FindFirstChild("Shadow") and c:FindFirstChild("Cord") and c:FindFirstChild("Nail") and c:FindFirstChild("PortraitWindow") and c:FindFirstChild("HoverGlow"), c.Name .. " has shadow, cord, nail, window and glow")
		end
	end
	expectEqual(count, 6, "six framed portraits")
	expectTrue(layer:FindFirstChild("RegularsTitle") == nil, "no Your Regulars title floats over the room")
	local card = layer:FindFirstChild("RegularCard")
	expectTrue(card ~= nil and card:FindFirstChild("CardTitle") ~= nil and card:FindFirstChild("CardTitle").Text == "Your Regular", "the tap card carries the title")
	menu.AbsoluteSize = { X = 390, Y = 844 }
	MR.update({ regulars = six }, menu)
	count = 0
	for _, c in ipairs(layer:FindFirstChild("Portraits"):GetChildren()) do if c.Name:sub(1, 8) == "Regular_" then count = count + 1 end end
	expectEqual(count, 3, "a phone keeps at most 3 frames")
end })

table.insert(tests, { name = "PlayBoardLayout.seats: every Patron seat is centred in its painted ring hole (within 1 px) at 84 percent of the hole, extras on the base row", fn = function()
	local PB = require(script.Parent.Parent.Engine.PlayBoardLayout)
	-- the measured holes of play_board_a (picture pixels): centre x, and the common centre y and diameter
	local holes = { 281, 394, 510, 625, 738 }
	expectEqual(PB.HOLE_D, 72, "the hole is 72 px")
	for _, sz in ipairs({ { 1920, 957 }, { 1506, 751 }, { 1280, 720 }, { 1000, 600 } }) do
		local bw, bh = PB.size(sz[1], sz[2])
		local sx, sy = bw / PB.IMG_W, bh / PB.IMG_H
		for n = 1, 7 do
			local seats = PB.seats(bw, bh, n)
			for i = 1, math.min(n, 5) do
				local a = seats[i]
				local cx, cy = a.x + a.w / 2, a.y + a.h / 2
				expectTrue(math.abs(cx - holes[i] * sx) <= 1 and math.abs(cy - PB.RING_Y * sy) <= 1, "seat " .. i .. " of " .. n .. " is centred in its ring hole at " .. sz[1] .. " (" .. cx .. "," .. cy .. ")")
				local hole = PB.HOLE_D * sx
				expectTrue(math.abs(a.w - PB.SEAT_FILL * hole) <= 1.5 or a.w == 12, "seat " .. i .. " is 84 percent of the hole at " .. sz[1])
				expectTrue(a.w < hole, "the portrait is smaller than the hole, so it never touches the brass")
			end
			for i = 6, n do
				local a = seats[i]
				expectTrue(a.extra and a.ring and math.abs(a.x + a.w / 2 - a.ring.cx) <= 1 and math.abs(a.y + a.h / 2 - a.ring.cy) <= 1, "extra seat " .. i .. " is centred in its own ring")
				expectTrue(a.ring.d > a.w, "the extra ring is larger than the portrait")
				expectTrue(a.y + a.h <= bh and a.x >= 0 and a.x + a.w <= bw, "extra seat " .. i .. " is inside the board")
			end
		end
		-- a symmetric board: the five hole centres are spaced like the painted ones
		local seats = PB.seats(bw, bh, 5)
		for i = 2, 5 do
			local gap = (seats[i].x + seats[i].w / 2) - (seats[i - 1].x + seats[i - 1].w / 2)
			expectTrue(math.abs(gap - (holes[i] - holes[i - 1]) * sx) <= 1.5, "pitch " .. i - 1 .. " to " .. i .. " follows the painting at " .. sz[1])
		end
	end
end })

table.insert(tests, { name = "Painted board: six Patron seats sit in the five ring holes plus a brass ring on the base, no parchment disc under any seat", fn = function()
	if not (io and io.open) then return end
	local FakeGui = require(script.Parent.FakeGui)
	local E = script.Parent.Parent.Engine
	local map = {}
	for _, n in ipairs({ "PlayTableLayout", "ImageSpace", "PlayBoardLayout", "BoardPanelRows" }) do map[n] = require(E[n]) end
	local stubs = {}
	local env, state = FakeGui.env({ stubs = stubs })
	local folder = FakeGui.folder(map)
	state.services.ReplicatedStorage = { WaitForChild = function() return { WaitForChild = function() return folder end } end }
	stubs.LayoutSwitch = FakeGui.load("src/Client/LayoutSwitch.lua", env)
	local PlayBoardHud = FakeGui.load("src/Client/PlayBoardHud.lua", env)
	local UDim2 = env.UDim2
	local function mk(class, name, parent, order)
		local i = FakeGui.new(class)
		i.Name = name
		if order then i.LayoutOrder = order end
		i.Parent = parent
		return i
	end
	for _, size in ipairs({ { 1920, 957 }, { 1506, 751 }, { 1280, 720 } }) do
		local root = mk("Frame", "Root", nil)
		local sidebar = mk("Frame", "Sidebar", root)
		mk("Frame", "SidebarBoard", root)
		local content = mk("Frame", "BoardContent", sidebar)
		local tray = mk("Frame", "PatronsTray", content, 5)
		local inset = mk("Frame", "PatronsInset", tray)
		local seats = {}
		for i = 1, 6 do
			seats[i] = mk("Frame", "Seat" .. i, inset, i)
			seats[i].Size = UDim2.fromOffset(38, 38)
			seats[i].BackgroundTransparency = 0
			mk("UIStroke", "S", seats[i])
		end
		local rect = map.PlayBoardLayout.placement(size[1], size[2])
		local ok, err = pcall(PlayBoardHud.apply, root, rect)
		expectTrue(ok, "applies at " .. size[1] .. ": " .. tostring(err))
		local H = map.PlayBoardLayout.hud(rect.w, rect.h)
		local want = map.PlayBoardLayout.seats(rect.w, rect.h, 6)
		for i, seat in ipairs(seats) do
			expectTrue(seat.BackgroundTransparency == 1, "seat " .. i .. " has no parchment disc at " .. size[1])
			local cx = H.ringRow.x + seat.Position.X.Offset + seat.Size.X.Offset / 2
			local cy = H.ringRow.y + seat.Position.Y.Offset + seat.Size.Y.Offset / 2
			expectTrue(math.abs(cx - (want[i].x + want[i].w / 2)) <= 1 and math.abs(cy - (want[i].y + want[i].h / 2)) <= 1, "seat " .. i .. " sits on its measured centre at " .. size[1])
			expectTrue((seat:FindFirstChild("ExtraRing") ~= nil) == (i == 6), "only the sixth seat gets a code ring (seat " .. i .. ")")
		end
		PlayBoardHud.apply(root, nil)
		expectTrue(seats[6]:FindFirstChild("ExtraRing") == nil and seats[1].BackgroundTransparency == 0, "everything is put back when the board is not painted")
	end
end })

table.insert(tests, { name = "Counter room: the counter band crops the room from the back edge to the foot of the front, at the room's own scale, and covers Marlo's waist", fn = function()
	local SL = require(script.Parent.Parent.Engine.ShopSceneLayout)
	local IS = require(script.Parent.Parent.Engine.ImageSpace)
	local R = SL.ROOM
	expectTrue(R.counterBack > 0.47 and R.counterBack < 0.48 and R.counterFront > R.counterBack and R.counterFront < 0.71, "the band rows are the measured ones (486 and 716 of 1024)")
	expectTrue(math.abs(R.counterBack * R.h - 486) < 1e-6 and math.abs(R.counterFront * R.h - 716) < 1e-6, "back edge row 486, front foot row 716")
	for _, frame in ipairs({ { 1920, 1080 }, { 1506, 751 }, { 1280, 720 }, { 800, 450 } }) do
		local W, H = frame[1], frame[2]
		local r = SL.rects(W, H, { offers = 2, packs = 2, room = true })
		local p = SL.pic(W, H)
		local where = " at " .. W .. "x" .. H
		-- same scale and place as the room: the band is the picture's own fraction rect
		local want = SL.picRect(W, H, R.counterX[1], R.counterBack, R.counterX[2], R.counterFront)
		expectTrue(math.abs(r.counterBand.x - want.x) < 1e-6 and math.abs(r.counterBand.y - want.y) < 1e-6 and math.abs(r.counterBand.w - want.w) < 1e-6 and math.abs(r.counterBand.h - want.h) < 1e-6, "band rect is the room's fraction rect" .. where)
		expectTrue(math.abs(r.counterBand.w / r.counterBand.h / (((R.counterX[2] - R.counterX[1]) * R.w) / ((R.counterFront - R.counterBack) * R.h)) - 1) < 0.01, "the band keeps the crop's aspect, so nothing stretches" .. where)
		expectTrue(math.abs(r.counterBand.y - (p.y + R.counterBack * p.h)) <= 1, "the band starts on the back edge" .. where)
		-- Marlo's waist is below the back edge by waist of the picture height, so the band covers it; his head stays above the edge
		local waistY = r.marlo.y + r.marlo.h
		expectTrue(math.abs(waistY - (r.counterBand.y + R.waist * p.h)) <= 1.5, "his waist is about 40 px below the back edge" .. where)
		expectTrue(waistY <= r.counterBand.y + r.counterBand.h, "the band reaches below his waist" .. where)
		expectTrue(r.marlo.y < r.counterBand.y, "most of him is above the back edge" .. where)
		-- the crop rect in the stored texture (Roblox keeps the 1536 px sheet at 1024) stays inside it
		local x, y, w, h = IS.rect(R.counterX[1] * R.w, R.counterBack * R.h, (R.counterX[2] - R.counterX[1]) * R.w, (R.counterFront - R.counterBack) * R.h, R.w, R.h)
		local sc = IS.rectScale(R.w, R.h)
		expectTrue(x >= 0 and y >= 0 and x + w <= R.w * sc + 1 and y + h <= R.h * sc + 1, "the crop rect lies inside the stored picture" .. where)
	end
end })

table.insert(tests, { name = "ChoiceRarity: the tier word is produced for a known Patron, nothing for an unknown item, plates read at 4.5:1", fn = function()
	local CR = require(script.Parent.Parent.Engine.ChoiceRarity)
	local CB = require(script.Parent.Parent.Engine.CollectionBook)
	local Patrons = require(script.Parent.Parent.Engine.Patrons)
	local first = Patrons.getAll and Patrons.getAll()[1] or Patrons.Definitions and Patrons.Definitions[1]
	expectTrue(first ~= nil, "there is a Patron to test with")
	local info = CR.info(CR.tabFor("patron"), first.id)
	expectTrue(info ~= nil and info.word == CB.Rarities[CB.rarityForId("patrons", first.id)].name, "a known Patron gets its tier word: " .. tostring(info and info.word))
	expectEqual(CR.tabFor("rushPatron"), "patrons", "the Boss Rush draft is a Patron pick")
	expectEqual(CR.tabFor("house"), "recipes", "a house recipe in a pack is a recipe")
	expectEqual(CR.tabFor("modifier"), nil, "blessings have no rarity")
	expectEqual(CR.tabFor("event"), nil, "events have no rarity")
	expectEqual(CR.lookup("patrons", "no_such_patron"), nil, "an unknown id shows nothing, never Common by mistake")
	expectEqual(CR.info("patrons", "no_such_patron"), nil, "info is nil for an unknown id")
	expectEqual(CR.info(nil, first.id), nil, "no tab, no rarity")
	local function lum(c)
		local function f(v) v = v / 255 return v <= 0.03928 and v / 12.92 or ((v + 0.055) / 1.055) ^ 2.4 end
		return 0.2126 * f(c[1]) + 0.7152 * f(c[2]) + 0.0722 * f(c[3])
	end
	local function ratio(a, b) local x, y = lum(a), lum(b) if x < y then x, y = y, x end return (x + 0.05) / (y + 0.05) end
	for _, rarity in ipairs(CB.RarityOrder) do
		local st = CR.styleOf(rarity)
		expectTrue(st ~= nil and st.word == CB.Rarities[rarity].name, "tier " .. rarity .. " has its word")
		expectTrue(ratio(st.text, st.plate) >= 4.5, rarity .. " word reads on its plate at 4.5:1 (" .. string.format("%.1f", ratio(st.text, st.plate)) .. ")")
		expectTrue(rarity == "common" or (st.plate[1] < 80 and st.plate[2] < 80 and st.plate[3] < 80), rarity .. " plate is very dark")
	end
	expectEqual(CR.styleOf("nonsense"), nil, "an unknown tier has no style")
	-- the real module's colours for the Patron
	expectTrue(ratio(info.text, info.plate) >= 4.5, "the real plate and word read at 4.5:1")
	local function read(path) local f = io and io.open and io.open(path, "r"); if not f then return nil end local t = f:read("*a"); f:close(); return t end
	local cp, sc = read("src/Client/ChoicePanel.lua"), read("src/Client/ShopCards.lua")
	if cp and sc then
		expectTrue(cp:find("ChoiceRarity.info", 1, true) ~= nil and cp:find('Name = "Rarity"', 1, true) ~= nil and cp:find("RarityGem", 1, true) ~= nil, "the pick cards draw the tier rim, gem and word")
		expectTrue(sc:find("RarityTag", 1, true) ~= nil and sc:find("ChoiceRarity.info", 1, true) ~= nil, "pack pick cards carry the tier word pill")
		expectFalse(cp:find("isDecline and ChoiceRarity", 1, true) ~= nil, "no rarity on the decline card")
	end
end })

table.insert(tests, { name = "PlayRoomArt: every Card Set maps to its recorded room pair, classic and unknown sets fall back, the tint keeps text at 4.5:1", fn = function()
	local PRA = require(script.Parent.Parent.Engine.PlayRoomArt)
	local Art = require(script.Parent.Parent.Engine.PlaySceneArt)
	local CS = require(script.Parent.Parent.Engine.CosmeticSets)
	local PTL = require(script.Parent.Parent.Engine.PlayTableLayout)
	expectEqual(#PRA.ORDER, 14, "14 sets have a room")
	for _, id in ipairs(PRA.ORDER) do
		expectTrue(PRA.SETS[id] ~= nil and CS.getById(id) ~= nil, id .. " is a real Card Set with measured numbers")
		local r = PRA.roomArt(id, Art)
		expectEqual(r.bg, "play_room_" .. id .. "_bg", id .. " bg key")
		expectEqual(r.front, "play_room_" .. id .. "_front", id .. " front key")
		expectTrue(type(Art[r.bg]) == "string" and Art[r.bg]:sub(1, 13) == "rbxassetid://" and not Art[r.bg]:find("rbxassetid://rbxassetid://", 1, true), id .. " bg Image id is recorded once")
		expectTrue(type(Art[r.front]) == "string" and Art[r.front] ~= "", id .. " front Image id is recorded")
		expectEqual(r.room, id, "the room is flagged")
		local g = PTL.SETS[r.layout]
		expectTrue(g ~= nil and g.art == r.front and g.bg == r.bg, id .. " has measured layout numbers under " .. tostring(r.layout))
		expectTrue(g.rail.y + g.rail.h < g.lip.y + g.lip.h + 40 and g.seat > g.rail.y and g.seat < g.rail.y + g.rail.h + 20, id .. " seat line and rim crop sit on its groove")
		expectTrue(g.strip.y + g.strip.h <= 1016 and g.strip.h >= 100, id .. " plate strip stays on the picture")
		for _, k in ipairs({ "felt", "rail", "deck", "lip" }) do
			local rc = g[k]
			expectTrue(rc.x >= 0 and rc.y >= 0 and rc.x + rc.w <= PTL.IMG_W and rc.y + rc.h <= PTL.IMG_H, id .. " " .. k .. " inside the picture")
		end
	end
	local classic = PRA.roomArt("classic_tavern", Art)
	expectTrue(classic.bg == "play_table_bg_b" and classic.front == "play_table_front_c" and classic.room == nil and classic.layout == nil, "Classic Tavern keeps the classic pair")
	local unknown = PRA.roomArt("no_such_set", Art)
	expectTrue(unknown.front == "play_table_front_c" and unknown.room == nil, "an unknown set falls back to the classic pair")
	expectTrue(PRA.roomArt(nil, Art).front == "play_table_front_c", "no set falls back too")
	local missing = PRA.roomArt("golden_gala", { play_room_golden_gala_bg = "rbxassetid://1" }) -- only one half of the pair is recorded
	expectTrue(missing.room == nil and missing.front == "play_table_front_c", "a half recorded pair falls back to the classic pair")
	expectEqual(PRA.roomArt("golden_gala", nil).room, "golden_gala", "without a map the pair is still named")
	-- the tint is a low contrast hint and never makes ink or cream text fail 4.5:1
	local INK, CREAM = { 52, 32, 16 }, { 250, 240, 220 }
	local PARCH, WOODDARK = { 226, 202, 156 }, { 58, 38, 22 }
	local function mul(c, t) return { math.floor(c[1] * t[1] / 255), math.floor(c[2] * t[2] / 255), math.floor(c[3] * t[3] / 255) } end
	for _, set in ipairs(CS.Definitions) do
		local t = PRA.tint(CS.accentOf(set))
		for i = 1, 3 do expectTrue(t[i] >= PRA.TINT_FLOOR and t[i] <= 255, set.id .. " tint channel " .. i .. " is a hint, not a wash (" .. t[i] .. ")") end
		expectTrue(CS.contrastRatio(INK, mul(PARCH, t)) >= 4.5, set.id .. " ink on the tinted board stays at 4.5:1")
		expectTrue(CS.contrastRatio(CREAM, mul(WOODDARK, t)) >= 4.5, set.id .. " cream on the tinted dark wood stays at 4.5:1")
	end
	expectEqual(table.concat(PRA.tint(nil), ","), "255,255,255", "no accent, no tint")
	local function read(path) local f = io and io.open and io.open(path, "r"); if not f then return nil end local t = f:read("*a"); f:close(); return t end
	local psp, plates, board, shop = read("src/Client/PlayScenePaint.lua"), read("src/Client/PlayPlates.lua"), read("src/Client/PlayBoardPaint.lua"), read("src/Client/ShopBackdrop.lua")
	if psp and plates and board and shop then
		expectTrue(psp:find("PlayRoomArt.roomArt(sid, art)", 1, true) ~= nil and psp:find("bg.Image = bid or bgId", 1, true) ~= nil, "the backdrop and the front follow the equipped set live")
		expectTrue(psp:find("HudTheme.onSkin(tint)", 1, true) ~= nil, "a skin change (equip, Preview) re-runs it")
		expectTrue(psp:find("groove.ImageRectOffset", 1, true) ~= nil, "the rim crop is placed above the cards")
		expectTrue(plates:find('GetAttribute("RoomTint")', 1, true) ~= nil and board:find('GetAttribute("RoomTint")', 1, true) ~= nil and shop:find('GetAttribute("RoomTint")', 1, true) ~= nil, "board, plates and Counter read the room tint")
		expectFalse(psp:find("TweenService", 1, true) ~= nil or psp:find("breath", 1, true) ~= nil, "no movement or breathing on the play screen")
	end
end })

