table.insert(tests, { name = "PackMakeRoom: the panel lists the owned Patrons with sell values, needs exactly the overflow, Back and Confirm work", fn = function()
	if not (io and io.open) then return end
	local FakeGui = require(script.Parent.FakeGui)
	local E = script.Parent.Parent.Engine
	local env, state = FakeGui.env({})
	state.services.ReplicatedStorage = { WaitForChild = function() return { WaitForChild = function() return FakeGui.folder({ PackRoom = require(E.PackRoom), ChoiceRarity = require(E.ChoiceRarity) }) end } end }
	local PackMakeRoom = FakeGui.load("src/Client/PackMakeRoom.lua", env)
	local Patrons = require(E.Patrons)
	local host = FakeGui.new("Frame")
	local clicks = 0
	local room = PackMakeRoom.new({ parent = host, z = 30, playClick = function() clicks = clicks + 1 end })
	local owned = { Patrons.Definitions[1].id, Patrons.Definitions[2].id, Patrons.Definitions[3].id }
	local view = { ownedPatrons = owned, recipes = {}, patronLimit = 3, recipeLimit = 2 }
	local items = { { id = Patrons.Definitions[4].id, name = Patrons.Definitions[4].name, category = "patron" } }
	local got
	room.open(view, items, function(ids) got = ids end)
	local panel = host:FindFirstChild("MakeRoomPanel")
	expectTrue(panel ~= nil and panel.Visible and room.isOpen(), "the panel opens")
	local list = panel:FindFirstChild("Owned", true)
	local cards = {}
	for _, c in ipairs(list:GetChildren()) do if c.ClassName == "TextButton" then cards[#cards + 1] = c end end
	expectEqual(#cards, 3, "one card per owned Patron")
	local first = cards[1]
	expectTrue(first:FindFirstChild("Value").Text == "Sells for $" .. math.floor(Patrons.Definitions[1].price / 2), "the card shows the sell value")
	local confirm, back = panel:FindFirstChild("Confirm", true), panel:FindFirstChild("Back", true)
	expectFalse(confirm.Active, "Confirm waits until the overflow is chosen")
	confirm.MouseButton1Click:Fire()
	expectTrue(got == nil, "an early Confirm does nothing")
	cards[2].MouseButton1Click:Fire()
	expectTrue(confirm.Active, "choosing one for one overflow enables Confirm")
	expectTrue(panel:FindFirstChild("Summary", true).Text:find("leaves, " .. items[1].name .. " joins your table.", 1, true) ~= nil, "the line says who leaves and who joins")
	cards[3].MouseButton1Click:Fire()
	local picks = 0
	for _, c in ipairs(list:GetChildren()) do if c.ClassName == "TextButton" and c:GetAttribute("Chosen") then picks = picks + 1 end end
	expectEqual(picks, 1, "a second tap does not choose more than the overflow")
	expectTrue(cards[2]:FindFirstChild("Ribbon").Visible and not cards[1]:FindFirstChild("Ribbon").Visible, "the chosen card wears the Leaves ribbon")
	expectTrue(cards[1]:FindFirstChild("Dim").Visible and not cards[2]:FindFirstChild("Dim").Visible, "the others dim once enough are chosen")
	expectTrue(cards[1]:FindFirstChild("RarityGem", true) ~= nil and cards[1]:FindFirstChild("Rarity", true) ~= nil, "each owned card shows its rarity gem and tier word")
	expectTrue(panel:FindFirstChild("Join_" .. items[1].id, true) ~= nil and panel:FindFirstChild("JoinHead", true).Text == "Joins your table", "the incoming Patron stands on the left as Joins your table")
	expectTrue(panel:FindFirstChild("Sheet") ~= nil and panel:FindFirstChild("WoodStud1") ~= nil, "wood frame with studs round a parchment sheet")
	cards[2].MouseButton1Click:Fire()
	expectFalse(confirm.Active, "tapping the chosen one again puts it back")
	cards[1].MouseButton1Click:Fire()
	confirm.MouseButton1Click:Fire()
	expectTrue(got ~= nil and #got == 1 and got[1] == owned[1], "Confirm hands the chosen owned id back")
	expectFalse(room.isOpen(), "and closes")
	room.open(view, items, function() got = "again" end)
	back.MouseButton1Click:Fire()
	expectFalse(room.isOpen(), "Back closes without choosing")
	expectTrue(got ~= "again", "Back never confirms")
	-- the pure summary for a two pick overflow
	local PR = require(E.PackRoom)
	local two = PR.summary({ ownedPatrons = owned, recipes = {}, patronLimit = 3, recipeLimit = 2 },
		{ { id = Patrons.Definitions[4].id, name = "A", category = "patron" }, { id = Patrons.Definitions[5].id, name = "B", category = "patron" } }, { owned[1], owned[2] })
	expectTrue(two.ready and #two.lines == 2 and two.refund == PR.sellValue("patron", owned[1]) + PR.sellValue("patron", owned[2]), "two picks into a full table: two lines and the refund of both")
	local joiners = PR.joiners({ ownedPatrons = owned, recipes = {}, patronLimit = 3, recipeLimit = 2 },
		{ { id = Patrons.Definitions[4].id, name = "A", category = "patron" }, { id = Patrons.Definitions[5].id, name = "B", category = "patron" } })
	expectTrue(#joiners == 2 and joiners[1].name == "A" and joiners[2].kind == "patron", "joiners lists the picks that do not fit")
	expectEqual(#PR.joiners({ ownedPatrons = {}, recipes = {}, patronLimit = 3, recipeLimit = 2 }, { { id = Patrons.Definitions[4].id, category = "patron" } }), 0, "nothing joins by force when there is room")
	local source = io.open("src/Client/Shop.lua", "r")
	if source then
		local text = source:read("*a")
		source:close()
		expectTrue(text:find("packMakeRoom.open(view, picked", 1, true) ~= nil and text:find("ResolvePackRemote:FireServer(chosen, replaceIds)", 1, true) ~= nil, "the pack Confirm opens Make room on overflow and sends the replaceIds")
	end
end })

table.insert(tests, { name = "Skip Pack: half the price paid comes back (min 1 from 2 Tips, 0 for a free pack), never more than paid, once, server side", fn = function()
	local Packs = require(script.Parent.Parent.Engine.Packs)
	expectEqual(Packs.skipRefund(0), 0, "a free pack gives nothing back")
	expectEqual(Packs.skipRefund(1), 0, "1 Tip: nothing")
	expectEqual(Packs.skipRefund(2), 1, "2 Tips: 1 back")
	expectEqual(Packs.skipRefund(3), 1, "3 Tips: half rounded down is 1")
	expectEqual(Packs.skipRefund(5), 2, "5 Tips: 2 back")
	expectEqual(Packs.skipRefund(12), 6, "a Mega pack at 12: 6 back")
	expectEqual(Packs.skipRefund(nil), 0, "no record, no refund")
	for paid = 0, 40 do expectTrue(Packs.skipRefund(paid) <= paid, "the refund never exceeds the price paid at " .. paid) end
	-- the real engine
	local state = RunState.new(nil, function(n) return n end)
	state.tips = 100
	local reveal = RunState.openPack(state, "buffoon_pack", function(n) return n end)
	expectEqual(reveal.paidPrice, Packs.getById("buffoon_pack").price, "the price actually paid is stored on the open pack")
	local afterBuy = state.tips
	local ok, msg, refund = RunState.resolvePack(state, {})
	expectTrue(ok, "skipping resolves")
	expectEqual(refund, 3, "6 Tips paid, 3 back")
	expectEqual(state.tips, afterBuy + 3, "the Tips landed")
	expectEqual(msg, "Pack skipped, 3 Tips back.", "and the message says so")
	expectTrue(state.pendingPack == nil, "the pack is closed")
	local ok2 = RunState.resolvePack(state, {})
	expectFalse(ok2, "skipping twice is impossible: there is no open pack")
	expectEqual(state.tips, afterBuy + 3, "so no second refund")
	-- Mega pack
	local mega = RunState.new(nil, function(n) return n end)
	mega.tips = 100
	RunState.openPack(mega, "buffoon_pack_mega", function(n) return n end)
	local before = mega.tips
	local _, _, r2 = RunState.resolvePack(mega, {})
	expectEqual(r2, 6, "a Mega pack at 12 gives 6 back")
	expectEqual(mega.tips, before + 6)
	-- a discounted pack refunds half of what was ACTUALLY paid
	local disc = RunState.new(nil, function(n) return n end)
	disc.tips = 100
	disc.nextShopDiscount = 2
	local expectedPaid = RunState.packPrice(disc, Packs.getById("buffoon_pack"))
	RunState.openPack(disc, "buffoon_pack", function(n) return n end)
	expectEqual(disc.pendingPack.paidPrice, expectedPaid, "the discounted price is the one stored")
	local tipsBefore = disc.tips
	local _, _, r3 = RunState.resolvePack(disc, {})
	expectEqual(r3, Packs.skipRefund(expectedPaid), "half of the discounted price")
	expectEqual(disc.tips, tipsBefore + r3)
	expectTrue(r3 < Packs.skipRefund(Packs.getById("buffoon_pack").price) or expectedPaid == Packs.getById("buffoon_pack").price, "a discount lowers the refund with the price")
	-- a free pack (price floored at 1 Tip by the engine, so force the stored price) gives nothing
	local free = RunState.new(nil, function(n) return n end)
	free.tips = 100
	RunState.openPack(free, "house_pack", function(n) return n end)
	free.pendingPack.paidPrice = 0
	local t0 = free.tips
	local _, m0, r0 = RunState.resolvePack(free, {})
	expectEqual(r0, 0, "a free pack refunds 0")
	expectEqual(free.tips, t0, "no Tips appear")
	expectEqual(m0, "Pack skipped, 0 Tips back.", "the message is still honest")
	-- the client can only send ids, never an amount: the remote takes (chosenIds, replaceIds) and nothing else changes the refund
	local f = io and io.open and io.open("src/Server/init.server.lua", "r")
	if f then
		local src = f:read("*a")
		f:close()
		expectTrue(src:find("Rem.ResolvePack.OnServerEvent:Connect(function(player, chosenIds, replaceIds)", 1, true) ~= nil, "no amount parameter on the remote")
	end
	local g = io and io.open and io.open("src/Client/Shop.lua", "r")
	if g then
		local text = g:read("*a")
		g:close()
		expectTrue(text:find('"Skip Pack (+%d Tips)"', 1, true) ~= nil and text:find("%d Tips back", 1, true) ~= nil, "the button shows the refund and a toast says N Tips back")
	end
end })

table.insert(tests, { name = "SoundFX: pitch ladder, jitter bounds and no repeat, min interval gate, ducking envelope, every cue has an id or layers, stings, coin cascade", fn = function()
	local FX = require(script.Parent.Parent.Engine.SoundFX)
	local S = require(script.Parent.Parent.Engine.SoundIds)
	-- the ladder: a half step per tick, capped at +12 semitones
	expectEqual(FX.ladderSpeed(1), 1, "the first tick is at pitch")
	expectTrue(math.abs(FX.ladderSpeed(2) - 2 ^ (1 / 12)) < 1e-9, "the second is a half step up")
	expectTrue(math.abs(FX.ladderSpeed(13) - 2) < 1e-9, "the thirteenth is an octave up")
	expectTrue(math.abs(FX.ladderSpeed(40) - 2) < 1e-9 and math.abs(FX.ladderSpeed(99) - 2) < 1e-9, "and it stops there")
	local prev = 0
	for n = 1, 20 do expectTrue(FX.ladderSpeed(n) >= prev, "the ladder never falls"); prev = FX.ladderSpeed(n) end
	local c1, c5 = FX.tick("chips", 1), FX.tick("chips", 5)
	expectTrue(c5.speed > c1.speed and c5.volume > c1.volume and c5.volume <= 0.6, "volume rises slightly with the rung, with a cap")
	local m = FX.tick("mult", 3)
	local x = FX.tick("xmult", 1, 3)
	expectTrue(math.abs(x.speed - FX.ladderSpeed(3) * 2) < 1e-9, "an xmult tick is an octave over the last mult tick")
	expectEqual(FX.tick("chips", nil).speed, 1, "a missing count is the first rung")
	expectTrue(m.speed > 1, "mult ticks climb too")
	-- jitter: within bounds and never the same value twice in a row
	local last
	for i = 0, 200 do
		local roll = (i % 21) / 20
		local v = FX.jitter(1, FX.PITCH_JITTER, roll, last)
		expectTrue(v >= 1 - FX.PITCH_JITTER - 1e-9 and v <= 1 + FX.PITCH_JITTER + 1e-9, "pitch stays within 6 percent")
		expectTrue(last == nil or v ~= last, "never the same exact value twice in a row")
		last = v
	end
	local lv
	for i = 0, 100 do
		local v = FX.jitter(0.5, FX.VOLUME_JITTER, (i % 7) / 6, lv)
		expectTrue(v >= 0.5 * (1 - FX.VOLUME_JITTER) - 1e-9 and v <= 0.5 * (1 + FX.VOLUME_JITTER) + 1e-9, "volume stays within 8 percent")
		lv = v
	end
	for _, name in ipairs({ "card_select", "card_play", "card_deal", "button_click", "hover", "chip", "coin" }) do expectTrue(FX.JITTERED[name], name .. " is jittered") end
	-- the gate
	local gate = FX.newGate()
	expectTrue(gate:allow("card_select", 1.000), "the first play is allowed")
	expectFalse(gate:allow("card_select", 1.010), "10 ms later is blocked")
	expectFalse(gate:allow("card_select", 1.040), "40 ms later is still blocked (0.05 s cooldown)")
	expectTrue(gate:allow("card_select", 1.051), "51 ms later is allowed")
	expectEqual(FX.tickSpeed(1), 1, "the first score tick is at normal pitch")
	expectTrue(FX.tickSpeed(5) > FX.tickSpeed(2), "score ticks rise")
	expectEqual(FX.tickSpeed(11), 1.3, "the 11th tick reaches the cap")
	expectEqual(FX.tickSpeed(40), 1.3, "and never goes past 1.3")
	expectTrue(gate:allow("hover", 2.0) and not gate:allow("hover", 2.05) and gate:allow("hover", 2.081), "hover waits 80 ms")
	expectTrue(gate:allow("coin", 1.011), "another cue is independent")
	-- ducking: 4 dB down at once, held 1.2 s, back up over 0.6 s
	local deep = FX.dbToGain(-4)
	expectTrue(math.abs(deep - 0.631) < 0.001, "-4 dB is a gain of 0.631")
	expectEqual(FX.duck(-1), 1, "before the beat nothing is ducked")
	expectEqual(FX.duck(0), deep, "it drops at once")
	expectEqual(FX.duck(1.2), deep, "and holds for 1.2 s")
	expectTrue(FX.duck(1.5) > deep and FX.duck(1.5) < 1, "then eases back")
	expectEqual(FX.duck(1.8), 1, "fully back after 0.6 s")
	local up = 0
	for t = 1.2, 1.8, 0.05 do expectTrue(FX.duck(t) >= up - 1e-9, "the return never dips"); up = FX.duck(t) end
	-- every cue has an id or explicit layers, and the layers only use cues that have ids
	for _, name in ipairs(S.CueOrder) do
		local ok = S.cueId(name) ~= nil or FX.layersFor(name) ~= nil or FX.EMPTY_OK[name]
		expectTrue(ok, name .. " has an id, explicit layers, or is on the silent list")
	end
	expectEqual(table.concat(S.silentCues(), ","), "boss_intro", "boss_intro stays silent (the intro popup is gone); the Backlog 6 cues have ids")
	for name, layers in pairs(FX.Layers) do
		for _, layer in ipairs(layers) do
			expectTrue(S.cueId(layer.cue) ~= nil, name .. " layer plays " .. layer.cue .. " which has a working id")
			expectTrue(layer.semis == nil or math.abs(layer.semis) <= 24, name .. " layer pitch is sane")
		end
	end
	for _, name in ipairs({ "shuffle" }) do expectEqual(S.Cues[name].id, "rbxassetid://9114035457", "shuffle reuses Deck Of Cards 5") end
	expectEqual(S.Cues.shuffle.maxLength, 1.3, "cut to 1.3 s")
	expectTrue(S.Cues.coin.id == "rbxassetid://133292918309565" and #S.CoinAlternates == 2, "the coin default is unchanged, the two alternates are optional")
	-- stings by hand tier
	expectEqual(FX.handSting("High Card"), "quiet", "High Card is quiet")
	expectEqual(FX.handSting("Pair"), "quiet", "Pair is quiet")
	expectEqual(FX.handSting("Two Pair"), "medium", "Two Pair is medium")
	expectEqual(FX.handSting("Three of a Kind"), "medium", "Three of a Kind is medium")
	expectEqual(FX.handSting("Straight"), "loud", "Straight is loud")
	expectEqual(FX.handSting("Flush"), "loud", "Flush is loud")
	for _, name in ipairs({ "Full House", "Four of a Kind", "Straight Flush" }) do expectEqual(FX.handSting(name), "biggest", name .. " is the biggest") end
	expectTrue(#FX.stingLayers("biggest") > #FX.stingLayers("quiet"), "bigger hands layer more")
	-- the coin cascade: 3 coins, 60 ms apart, different pitches
	local cascade = FX.coinCascade(3)
	expectTrue(#cascade == 3 and cascade[2].delay - cascade[1].delay == 0.06 and cascade[3].delay > cascade[2].delay, "three coins 60 ms apart")
	expectTrue(cascade[1].speed ~= cascade[2].speed and cascade[2].speed ~= cascade[3].speed, "at different pitches")
	-- big beats
	expectTrue(FX.isBigBeat("legendary") and FX.isBigBeat("wildcard") and FX.isBigBeat("boss_defeat") and FX.isBigBeat("round_win") and not FX.isBigBeat("pair"), "which beats duck the music")
	-- the Legendary and Wildcard moment layers: win +5, a low thud, chime at +12 and +19, 90 ms apart
	local L = FX.layersFor("legendary_moment")
	expectTrue(L[1].cue == "win" and L[1].semis == 5, "win sting pitched +5")
	local chimes = {}
	for _, l in ipairs(L) do if l.cue == "chip" then chimes[#chimes + 1] = l end end
	expectTrue(#chimes == 2 and chimes[1].semis == 12 and chimes[2].semis == 19 and math.abs(chimes[2].delay - chimes[1].delay - 0.09) < 1e-9, "a two note chime, +12 and +19, 90 ms apart")
end })

table.insert(tests, { name = "Sound pass wiring: Sound.lua gates, jitters and layers cues, ducks the music; ScorePopup climbs the ladder; the Volume slider scales every layer", fn = function()
	if not (io and io.open) then return end
	local function read(path) local f = io.open(path, "r"); if not f then return nil end local t = f:read("*a"); f:close(); return t end
	local snd, pop, cue, dbg, boss = read("src/Client/Sound.lua"), read("src/Client/ScorePopup.lua"), read("src/Client/Cue.lua"), read("src/Client/DebugGoto.lua"), read("src/Client/BossFight.lua")
	if not (snd and pop and cue and dbg and boss) then return end
	expectTrue(snd:find("gate:allow(name, os.clock())", 1, true) ~= nil and snd:find("SoundFX.JITTERED[name]", 1, true) ~= nil, "cues go through the minimum interval gate and the jitter")
	expectTrue(snd:find("SoundFX.layersFor(name)", 1, true) ~= nil and snd:find("getSfxVolume(soundId)", 1, true) ~= nil, "layers play through the one-shot that applies the SFX slider and Mute to every layer")
	expectTrue(snd:find("SoundFX.duck(t)", 1, true) ~= nil and snd:find('ClientSettings.get("musicVolume")', 1, true) ~= nil, "ducking reads the Music slider")
	expectTrue(snd:find("TimeLength == 0", 1, true) ~= nil and snd:find("warn(string.format(\"[Sound] cue %s", 1, true) ~= nil, "a cue that fails to load or has no length is named in a warning")
	expectTrue(pop:find('SoundFX.tick("xmult", 1, multTicks)', 1, true) ~= nil and pop:find("CueBridge.coinCascade", 1, true) ~= nil and pop:find("CueBridge.sting(preview.name)", 1, true) ~= nil, "the tally climbs the ladder, then the coin cascade and the hand sting")
	expectTrue(pop:find('CueBridge.play("legendary_moment")', 1, true) ~= nil, "Legendary and True Wildcard get their own moment")
	expectTrue(cue:find("function Cue.audition", 1, true) ~= nil and dbg:find('target.kind == "sfx"', 1, true) ~= nil, "DebugGoto sfx:<cue> auditions a cue")
	expectTrue(boss:find("Cue).duck()", 1, true) ~= nil, "a boss defeat ducks the music")
	local R = require(script.Parent.Parent.Engine.DebugGotoRules)
	local t = R.parse("sfx:card_play")
	expectTrue(t and t.kind == "sfx" and t.cue == "card_play", "sfx:<cue> parses")
	expectTrue(R.parse("sfx:ladder").cue == "ladder", "sfx:ladder parses")
	expectTrue(R.parse("sfx:roundwin").cue == "roundwin", "sfx:roundwin parses (the whole round win sound set)")
	expectEqual(R.parse("sfx:bad cue!"), nil, "a malformed cue name is refused")
end })

table.insert(tests, { name = "FlashFX: layered glow, vignette, motes and sweep; no full-screen layer above 15 percent; reduced motion is static; the flat overlays are gone", fn = function()
	local FX = require(script.Parent.Parent.Engine.FlashFX)
	for _, kind in ipairs({ "legendary", "wildcard", "showdown", "hit" }) do
		for _, reduced in ipairs({ false, true }) do
			local spec = FX.spec(kind, reduced)
			local tag = kind .. (reduced and " (reduced)" or "")
			expectTrue(FX.maxFullScreenOpacity(spec) <= FX.MAX_FULL_SCREEN_OPACITY + 1e-9, tag .. ": no full-screen layer above 15 percent opacity (" .. FX.maxFullScreenOpacity(spec) .. ")")
			for _, l in ipairs(spec.layers) do
				expectTrue(l.opacity <= 0.6, tag .. ": " .. l.type .. " stays soft")
				if l.type == "glow" then expectTrue(l.coverage < 0.5 and l.size <= 0.55, tag .. ": the glow never covers the whole screen") end
			end
			local c = spec.color
			expectTrue(c[1] <= 255 and c[2] <= 255 and c[3] <= 255 and (c[1] + c[2] + c[3]) / 3 < 235, tag .. ": the colour is muted, not white")
			if reduced then
				expectFalse(spec.motion, tag .. ": reduced motion has no motion")
				for _, l in ipairs(spec.layers) do
					expectTrue(l.type ~= "motes" and l.type ~= "sweep", tag .. ": no motes or sweep")
					expectTrue((l.fadeIn or 0) == 0 and (l.fadeOut or 0) == 0, tag .. ": no animated fade, just on and off")
				end
				expectEqual(FX.moteCount(kind, true), 0, tag .. ": no motes")
				expectEqual(FX.glowPeakAt(spec, 0.1), spec.layers[1].opacity, tag .. ": the glow just stands")
			end
		end
	end
	local leg = FX.spec("legendary", false)
	local glow, vig, motes, sweep
	for _, l in ipairs(leg.layers) do
		if l.type == "glow" then glow = l elseif l.type == "vignette" then vig = l elseif l.type == "motes" then motes = l elseif l.type == "sweep" then sweep = l end
	end
	expectTrue(math.abs(glow.opacity - 0.25) < 1e-9 and glow.fadeIn == 0.5 and glow.fadeOut == 0.8, "glow: peak transparency 0.75, 0.5 s in, 0.8 s out")
	expectTrue(math.abs(vig.opacity - 0.15) < 1e-9, "vignette: 0.85 transparency at its strongest")
	expectTrue(motes.count >= 10 and motes.count <= 16 and FX.moteCount("wildcard", false) >= 10 and FX.moteCount("wildcard", false) <= 16, "10 to 16 motes")
	expectTrue(sweep ~= nil, "Legendary has a light sweep")
	local wild = FX.spec("wildcard", false)
	local hasSweep = false
	for _, l in ipairs(wild.layers) do if l.type == "sweep" then hasSweep = true end end
	expectFalse(hasSweep, "the wildcard has no sweep")
	expectTrue(FX.PALETTE.legendary[1] > FX.PALETTE.legendary[3] and FX.PALETTE.wildcard[3] > FX.PALETTE.wildcard[2], "Legendary is warm gold, Wildcard soft violet")
	-- the envelope: zero, rising, peak, falling, zero; never a strobe
	local prev, peaked = 0, false
	for i = 0, 40 do
		local v = FX.glowPeakAt(leg, i * 0.05)
		if v > 0.2499 then peaked = true end
		expectTrue(v >= 0 and v <= 0.25 + 1e-9, "the glow stays within its peak")
	end
	expectTrue(peaked and FX.glowPeakAt(leg, 0) == 0 and FX.glowPeakAt(leg, leg.duration + 1) == 0, "it rises to the peak and ends at nothing")
	local rises = 0
	local last = 0
	for i = 0, 40 do
		local v = FX.glowPeakAt(leg, i * 0.05)
		if v > last + 1e-9 and last > v - 1e-9 then rises = rises + 1 end
		last = v
	end
	local turns, dir = 0, 0
	local lv = 0
	for i = 0, 60 do
		local v = FX.glowPeakAt(leg, i * 0.03)
		local d = v > lv + 1e-9 and 1 or (v < lv - 1e-9 and -1 or 0)
		if d ~= 0 and dir ~= 0 and d ~= dir then turns = turns + 1 end
		if d ~= 0 then dir = d end
		lv = v
	end
	expectTrue(turns <= 1, "one rise and one fall, no strobe")
	-- the motes are deterministic from their rolls and stay within sane bounds
	local list = FX.motes("legendary", {})
	expectEqual(#list, 16, "one entry per mote")
	for _, m in ipairs(list) do
		expectTrue(m.rise >= 90 and m.rise <= 210 and m.size >= 4 and m.size <= 8 and m.delay <= 0.35, "mote numbers are small and quick")
	end
	-- the old flat overlays are gone from the source
	local function read(path) local f = io and io.open and io.open(path, "r"); if not f then return nil end local t = f:read("*a"); f:close(); return t end
	local pop, pha, sd, bf = read("src/Client/ScorePopup.lua"), read("src/Client/PhaseA.lua"), read("src/Client/Showdown.lua"), read("src/Client/BossFight.lua")
	if pop and pha and sd and bf then
		expectTrue(pop:find("FlashOverlay", 1, true) == nil and pop:find("LEGENDARY_FLASH_COLOR", 1, true) ~= nil and pop:find('FlashFX.play(root, "legendary"', 1, true) ~= nil and pop:find('FlashFX.play(root, "wildcard"', 1, true) ~= nil, "ScorePopup has no flat flash overlay, it plays the layered effect")
		expectTrue(pha:find("flashOverlay", 1, true) == nil, "PhaseA's flat flash overlay is removed")
		expectTrue(sd:find('local dim = Instance.new("Frame")', 1, true) == nil and sd:find("FlashFX.play", 1, true) ~= nil, "Showdown's flat dim is replaced")
		expectTrue(bf:find("Color3.fromRGB(255, 240, 210)", 1, true) == nil or bf:find('FlashFX").play(root, "hit"', 1, true) ~= nil, "the boss screen flash is the soft glow")
	end
end })

table.insert(tests, { name = "Per-set rooms: every Card Set kit piece on the plates under the board is hidden and stays hidden, the felt shade is off in the 14 rooms", fn = function()
	if not (io and io.open) then return end
	local FakeGui = require(script.Parent.FakeGui)
	local E = script.Parent.Parent.Engine
	local map = {}
	for _, n in ipairs({ "PlayTableLayout", "ImageSpace", "PlayBoardLayout", "BoardPanelRows" }) do map[n] = require(E[n]) end
	local stubs = {}
	local env, state = FakeGui.env({ stubs = stubs })
	local folder = FakeGui.folder(map)
	state.services.ReplicatedStorage = { WaitForChild = function() return { WaitForChild = function() return folder end } end }
	stubs.LayoutSwitch = FakeGui.load("src/Client/LayoutSwitch.lua", env)
	local PlayBoardHud = FakeGui.load("src/Client/PlayBoardHud.lua", env)
	local function mk(class, name, parent, order)
		local i = FakeGui.new(class)
		i.Name = name
		if order then i.LayoutOrder = order end
		i.Parent = parent
		return i
	end
	local root = mk("Frame", "Root", nil)
	local sidebar = mk("Frame", "Sidebar", root)
	mk("Frame", "SidebarBoard", root)
	local content = mk("Frame", "BoardContent", sidebar)
	local tips = mk("Frame", "TipsRow", content, 5)
	local hint = mk("Frame", "Hint", content, 10)
	tips.Size = env.UDim2.fromOffset(300, 44)
	hint.Size = env.UDim2.fromOffset(300, 44)
	local pieces = {}
	for _, row in ipairs({ tips, hint }) do
		for _, n in ipairs({ "HudKitPlate", "HudKitPad", "HudKitFrame", "HudKitGlow" }) do
			local p = mk("Frame", n, row)
			p.BackgroundTransparency = 0.12
			pieces[#pieces + 1] = p
		end
	end
	local icon = mk("ImageLabel", "HudKitIcon", tips)
	local rect = map.PlayBoardLayout.placement(1920, 957)
	local called, applied = pcall(PlayBoardHud.apply, root, rect)
	expectTrue(called and applied == true, "applies: " .. tostring(PlayBoardHud.lastError))
	for _, p in ipairs(pieces) do expectFalse(p.Visible, p.Name .. " on a plate is hidden") end
	expectTrue(icon.Visible, "a kit icon a row keeps is not a theme block")
	pieces[2].Visible = true -- the theme paints again when a set is equipped or previewed
	expectFalse(pieces[2].Visible, "a kit piece the theme shows again is hidden again")
	expectTrue(type(PlayBoardHud.reportOverlaps) == "function", "the Studio report exists")
	PlayBoardHud.reportOverlaps(root)
	PlayBoardHud.apply(root, nil)
	local psp = io.open("src/Client/PlayScenePaint.lua", "r")
	if psp then
		local text = psp:read("*a")
		psp:close()
		expectTrue(text:find("if roomDef and roomDef.room then feltClip = nil end", 1, true) ~= nil, "no felt shade over any per-set room")
		expectTrue(text:find("reportOverlaps", 1, true) ~= nil, "the painted table asks for the plate overlap report in Studio")
	end
	local PTL = require(E.PlayTableLayout)
	local PRA = require(E.PlayRoomArt)
	for _, id in ipairs(PRA.ORDER) do
		local def = PTL.SETS[PRA.PREFIX .. id]
		expectTrue(def and def.room == id, id .. " is flagged as a room")
		for _, size in ipairs({ { 1920, 957 }, { 1280, 720 } }) do
			local pl = PTL.placement(size[1], size[2], 260, 150, PRA.PREFIX .. id)
			expectTrue(pl ~= nil, id .. " places at " .. size[1])
		end
	end
end })

table.insert(tests, { name = "ScrollOfferLayout: the Stranger's scroll keeps text inside the measured paper, clear of the rods and the seal, at 1920x1080, 1280x720 and a phone", fn = function()
	local L = require(script.Parent.Parent.Engine.ScrollOfferLayout)
	local function overlap(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	local function inside(r, o) return r.x >= o.x and r.y >= o.y and r.x + r.w <= o.x + o.w and r.y + r.h <= o.y + o.h end
	-- the measured boxes are consistent in the picture
	for key, P in pairs(L.PICTURES) do
		expectTrue(inside(P.safe, P.sheet), key .. ": the safe rect is inside the flat sheet")
		expectFalse(overlap(P.safe, P.seal), key .. ": the safe rect is clear of the seal")
		expectFalse(overlap(P.safe, P.topRoll) or overlap(P.safe, P.bottomRoll), key .. ": and of both rolls")
		local art = L.ART[key]
		expectTrue(inside(P.sheet, { x = art.x, y = art.y, w = art.w, h = art.h }), key .. ": the sheet is inside the opaque art")
	end
	local screens = { { 1920, 1080 }, { 1280, 720 }, { 390, 844 }, { 375, 667 } }
	for _, sc in ipairs(screens) do
		local maxH = math.min(0.8 * sc[2], 760)
		local maxW = sc[1] - 32
		for _, key in ipairs({ "a", "b" }) do
			local r = L.layout(key, maxW, maxH)
			local tag = key .. " at " .. sc[1] .. "x" .. sc[2]
			expectTrue(r ~= nil, "the scroll fits " .. tag)
			if r then
				local card = { x = 0, y = 0, w = r.w, h = r.h }
				expectTrue(r.w <= maxW + 1 and r.h <= maxH + 1, "the card fits the area at " .. tag)
				for _, name in ipairs({ "safe", "medallion", "title", "blessing", "curse", "accept", "decline", "seal" }) do
					expectTrue(inside(r[name], card), name .. " is inside the card at " .. tag)
				end
				for _, name in ipairs({ "medallion", "title", "blessing", "curse", "accept", "decline" }) do
					expectTrue(inside(r[name], r.safe), name .. " is inside the text-safe rect at " .. tag)
					expectFalse(overlap(r[name], r.seal), name .. " never touches the seal at " .. tag)
				end
				local names = { "medallion", "title", "blessing", "curse", "accept", "decline" }
				for i = 1, #names do
					for j = i + 1, #names do
						expectFalse(overlap(r[names[i]], r[names[j]]), names[i] .. " and " .. names[j] .. " do not overlap at " .. tag)
					end
				end
				expectTrue(r.title.h >= L.TEXT_TITLE and r.blessing.h >= L.TEXT_BODY * 2 and r.curse.h >= L.TEXT_BODY * 2, "the text has room for its lines at " .. tag)
				expectTrue(r.accept.h >= 36 and r.accept.w >= 90 and r.decline.w >= 90, "the plates are at least 36 px tall and 90 wide at " .. tag)
				expectTrue(r.accept.y + r.accept.h <= r.seal.y, "the plates sit above the seal at " .. tag)
			end
		end
	end
	expectEqual(L.layout("a", 160, 200), nil, "a tiny window falls back to the flat card")
	expectEqual(L.TEXT_TITLE, 22, "title 22 px")
	expectTrue(L.TEXT_BODY >= 16 and L.TEXT_BUTTON >= 15, "body 16 px, buttons 15 px")
	expectEqual(L.pick({ blessing = "Sharper hands", curse = "Lose all your Tips at the start of every single round" }), "b", "a harsh offer uses the second scroll")
	expectEqual(L.pick({ blessing = "A big bonus this round", curse = "-1 hand" }), "a", "a fair offer uses the first")
	expectEqual(L.pick(nil), "a", "no offer, the first")
end })

table.insert(tests, { name = "Haggle Stranger scroll: the offer is the painted scroll with ink text, a brass medallion and two wooden plates; the flat card is the fallback", fn = function()
	if not (io and io.open) then return end
	local FakeGui = require(script.Parent.FakeGui)
	local E = script.Parent.Parent.Engine
	local SL = require(E.ScrollOfferLayout)
	local stubs = {}
	local env, st = FakeGui.env({ stubs = stubs })
	local Remotes = FakeGui.new("Folder")
	local fired = {}
	for _, n in ipairs({ "Haggle", "Stranger" }) do
		local r = FakeGui.new("Folder")
		r.Name, r.Parent = n, Remotes
		r.FireServer = function(_, ...) fired[#fired + 1] = { n, ... } end
	end
	Remotes.Name = "Remotes"
	st.services.ReplicatedStorage = setmetatable({
		WaitForChild = function() return { WaitForChild = function() return FakeGui.folder({ ShopRefusal = require(E.ShopRefusal), ScrollOfferLayout = SL, ImageSpace = require(E.ImageSpace),
			ContentArt = require(E.ContentArt) }) end } end,
		FindFirstChild = function(_, name) return name == "Remotes" and Remotes or nil end,
	}, {})
	stubs.ClientSettings = { get = function() return false end }
	stubs.ShopTrace = FakeGui.load("src/Client/ShopTrace.lua", env)
	local ShopHaggle = FakeGui.load("src/Client/ShopHaggle.lua", env)
	for _, size in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 390, 844 } }) do
		local shop = FakeGui.new("Frame")
		shop.AbsoluteSize = { X = size[1], Y = size[2] }
		local haggle = ShopHaggle.new({ shopFrame = shop, playClickSfx = function() end, say = function() end })
		haggle.update({ tips = 10, stranger = { id = "purse", name = "The Fat Purse", icon = "P", price = 4, blessing = "A big bonus", curse = "-1 hand" } })
		local scroll = shop:FindFirstChild("StrangerScroll")
		local card = shop:FindFirstChild("StrangerCard")
		local tag = size[1] .. "x" .. size[2]
		expectTrue(scroll ~= nil and scroll.Visible and card ~= nil and not card.Visible, "the scroll shows and the flat card is hidden at " .. tag)
		if scroll and scroll.Visible then
			local pic = scroll:FindFirstChild("ScrollPicture")
			expectTrue(pic ~= nil and pic.Image:find("rbxassetid://", 1, true) ~= nil, "the picture is the scroll art at " .. tag)
			local title, bless, curse = scroll:FindFirstChild("OfferTitle"), scroll:FindFirstChild("OfferBlessing"), scroll:FindFirstChild("OfferCurse")
			expectTrue(title.Text == "The Fat Purse (4 Tips)" and title.TextSize == 22, "the title is 22 px: " .. title.Text)
			expectTrue(bless.TextSize >= 16 and curse.TextSize >= 16 and bless.Text == "Blessing: A big bonus" and curse.Text == "Curse: -1 hand", "the body is 16 px or more")
			expectTrue(scroll:FindFirstChild("StrangerMedallion") ~= nil, "the Stranger sits in a medallion")
			local accept, no = scroll:FindFirstChild("Accept"), scroll:FindFirstChild("NoThanks")
			expectTrue(accept.TextSize >= 15 and no.TextSize >= 15 and accept.Size.Y.Offset >= 36, "the plates are real buttons, 15 px text")
			accept.MouseButton1Click:Fire()
			no.MouseButton1Click:Fire()
			expectTrue(#fired >= 2 and fired[#fired - 1][2] == "accept" and fired[#fired][2] == "decline", "Accept and No thanks still fire the same remote")
			expectTrue(scroll.Size.X.Offset <= size[1] - 16 and scroll.Size.Y.Offset <= size[2], "the scroll fits the window at " .. tag)
		end
		haggle.update({ tips = 1, stranger = { id = "purse", name = "The Fat Purse", icon = "P", price = 4, blessing = "A big bonus", curse = "-1 hand" } })
		expectFalse(scroll:FindFirstChild("Accept").Active, "too few Tips greys Accept at " .. tag)
		haggle.update({ tips = 10 })
		expectFalse(scroll.Visible or card.Visible, "no Stranger, nothing shows at " .. tag)
	end
	local f = io.open("src/Client/ShopHaggle.lua", "r")
	if f then
		local text = f:read("*a")
		f:close()
		expectTrue(text:find("ScrollLayout.layout", 1, true) ~= nil and text:find('ClientSettings.get("reduceShake")', 1, true) ~= nil, "the layout comes from the Engine module and calm mode skips the unroll")
	end
end })

table.insert(tests, { name = "RunOverLayout.scroll: content stays inside the mapped safe rect of the painted scroll, clear of the seal and the rods, or falls back to the plain panel", fn = function()
	local L = require(script.Parent.Parent.Engine.RunOverLayout)
	local function overlap(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	local function inside(r, o) return r.x >= o.x - 1 and r.y >= o.y - 1 and r.x + r.w <= o.x + o.w + 1 and r.y + r.h <= o.y + o.h + 1 end
	for key, S in pairs(L.SCROLLS) do
		expectTrue(inside(S.safe, S.sheet) and inside(S.sheet, S.art), key .. ": safe inside the sheet inside the scroll")
		expectFalse(overlap(S.safe, S.seal), key .. ": the safe rect is clear of the seal")
		expectFalse(overlap(S.safe, S.leftRod) or overlap(S.safe, S.rightRod), key .. ": and of both rods")
	end
	local usedAny = false
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 800, 450 } }) do
		for _, key in ipairs({ "a", "b" }) do
			for _, patrons in ipairs({ 0, 5, 8 }) do
				local C = L.columns(sz[1])
				local factsH = (L.estimateLines("Best hand: Full House, 1280", 300, 17) + L.estimateLines("Final score 604 of 3174  Tips banked 12", 300, 17) + L.estimateLines("Road: Dunes\nHarbor\nMarsh", 300, 15) + 3) * 24
				local r = L.scroll(sz[1], sz[2], { factsH = factsH, patrons = patrons, primary = 3, more = 6 }, key)
				local tag = key .. " " .. patrons .. " Patrons at " .. sz[1] .. "x" .. sz[2]
				if r then
					usedAny = true
					expectTrue(r.card.w <= sz[1] and r.card.h <= sz[2], "the scroll fits the window at " .. tag)
					expectTrue(r.fit >= L.SCROLL_MIN_FIT, "the content is at nearly full size at " .. tag)
					local origin, fit = r.origin, r.fit
					local mapped = function(rc) return { x = origin.x + rc.x * fit, y = origin.y + rc.y * fit, w = rc.w * fit, h = rc.h * fit } end
					local names = { "title", "facts", "patronsLabel", "patrons" }
					for _, name in ipairs(names) do
						local rc = mapped(r.inner[name])
						expectTrue(inside(rc, r.safe), name .. " stays inside the mapped safe rect at " .. tag)
						expectFalse(overlap(rc, r.seal) or overlap(rc, r.leftRod) or overlap(rc, r.rightRod), name .. " clears the seal and the rods at " .. tag)
					end
					for _, group in ipairs({ "primary", "more" }) do
						for i, cell in ipairs(r.inner[group]) do
							local rc = mapped(cell)
							expectTrue(inside(rc, r.safe), group .. " " .. i .. " stays inside the mapped safe rect at " .. tag)
							expectFalse(overlap(rc, r.seal), group .. " " .. i .. " is above the seal at " .. tag)
						end
					end
				else
					expectTrue(sz[1] < 1280 or patrons > 5, "a roomy window uses the scroll at " .. tag)
				end
			end
		end
	end
	expectTrue(usedAny, "the scroll is used at desktop sizes")
	expectEqual(L.scroll(390, 844, { factsH = 200, patrons = 3, primary = 3, more = 6 }, "a"), nil, "a phone keeps the plain one column panel")
end })

table.insert(tests, { name = "RunOverLayout.scroll: about 78 percent of the screen width at 1920x1080, and every text size and button label fits one line", fn = function()
	local L = require(script.Parent.Parent.Engine.RunOverLayout)
	local r = L.scroll(1920, 1080, { factsH = 330, patrons = 3, primary = 3, more = 6 }, "a")
	expectTrue(r ~= nil, "the scroll is used at 1920x1080")
	if r then
		local frac = r.card.w / 1920
		expectTrue(frac > 0.7 and frac < 0.86, "the scroll is near 78 percent of the width, got " .. frac)
	end
	expectTrue(L.Z_LIFT >= 200, "the screen is lifted above the play HUD")
	local E = script.Parent.Parent.Engine
	local primary = L.compute(1920, 1080, { factsH = 330, patrons = 3, primary = 3, more = 6 }).primary
	for i, cell in ipairs(primary) do
		expectTrue(cell.w >= 150, "primary button " .. i .. " is wide enough for a one line 16 px label")
	end
end })

table.insert(tests, { name = "RunOverLayout: every button is wide enough for its label plus a 22 px plate cap each side, on the scroll and the plain panel, and the free paper holds a flavor line", fn = function()
	local L = require(script.Parent.Parent.Engine.RunOverLayout)
	local primaryAll = { { "One More (Free)", "Play Again", "Back to Tavern" }, { "One More Round", "Play Again", "Back to Tavern" }, { "Play Again", "Back to Tavern" } }
	local moreAll = { "Share", "Challenge", "Invite", "Save Badge", "Win Card", "" }
	local narrowMeasure = function(text) return #text * 10 end -- a wider measured font than the estimate: the larger of the two wins
	for _, textW in ipairs({ false, narrowMeasure }) do
		for _, primaryLabels in ipairs(primaryAll) do
			for _, sz in ipairs({ { 1920, 1080 }, { 1600, 900 }, { 1280, 720 }, { 800, 450 }, { 390, 844 } }) do
				local spec = { factsH = 330, patrons = 4, primary = #primaryLabels, more = 6, primaryLabels = primaryLabels, moreLabels = moreAll, textW = textW or nil }
				local rects = { L.compute(sz[1], sz[2], spec) }
				local sc = L.scroll(sz[1], sz[2], spec, "a")
				if sc then rects[#rects + 1] = sc.inner end
				for _, r in ipairs(rects) do
					for i, label in ipairs(primaryLabels) do
						local need = L.buttonWidth(label, textW or nil)
						expectTrue(r.primary[i].w + 0.5 >= need, label .. " fits its plate at " .. sz[1] .. "x" .. sz[2] .. " (" .. r.primary[i].w .. " vs " .. need .. ")")
						expectTrue(need >= L.labelWidth(label, 16) + 2 * L.CAP_PAD, label .. " is measured with 22 px of cap on each side")
					end
					for i, label in ipairs(moreAll) do
						expectTrue(r.more[i].w + 0.5 >= L.buttonWidth(label, textW or nil), label .. " fits its cell at " .. sz[1] .. "x" .. sz[2])
					end
					for i = 2, #primaryLabels do
						local a, b = r.primary[i - 1], r.primary[i]
						expectFalse(a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h, "primary buttons never overlap at " .. sz[1] .. "x" .. sz[2])
					end
				end
				if sc and sc.flavor then
					local f = sc.flavor
					expectTrue(f.h >= L.FLAVOR_MIN_H and f.y >= sc.origin.y and f.y + f.h <= sc.safe.y + sc.safe.h + 1, "the flavor line sits on the paper under the content at " .. sz[1] .. "x" .. sz[2])
					expectFalse(f.y + f.h > sc.seal.y and f.x < sc.seal.x + sc.seal.w and sc.seal.x < f.x + f.w, "and above the seal")
				end
			end
		end
	end
	local sc = L.scroll(1920, 1080, { factsH = 330, patrons = 3, primary = 3, more = 6, primaryLabels = primaryAll[1], moreLabels = moreAll }, "a")
	expectTrue(sc ~= nil and sc.flavor ~= nil, "at 1920x1080 the free paper under the content holds a flavor line")
	expectTrue(L.Z_LIFT >= 1000, "the screen is lifted far above the play HUD")
end })

table.insert(tests, { name = "RunOverLayout: big Play Again, equal 44 px pills, 90 px Patron cards, facts plate contrast and clearance", fn = function()
	local L = require(script.Parent.Parent.Engine.RunOverLayout)
	local function overlap(a, b) return a.x < b.x + b.w - 0.01 and b.x < a.x + a.w - 0.01 and a.y < b.y + b.h - 0.01 and b.y < a.y + a.h - 0.01 end
	local function lin(c) c = c / 255; return c <= 0.03928 and c / 12.92 or ((c + 0.055) / 1.055) ^ 2.4 end
	local function lum(r, g, b) return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b) end
	local plate, cream = lum(34, 24, 16), lum(250, 240, 220)
	expectTrue((cream + 0.05) / (plate + 0.05) >= 4.5, "cream facts on the dark plate are at least 4.5:1")
	expectTrue(L.PLATE_PAD >= 8, "the plate extends past the text")
	for _, sz in ipairs({ { 1920, 1080 }, { 1600, 900 }, { 1280, 720 }, { 800, 450 }, { 390, 844 } }) do
		for _, patrons in ipairs({ 0, 3, 5, 10 }) do
			for _, primary in ipairs({ 2, 3 }) do
				local spec = { factsH = 330, patrons = patrons, primary = primary, more = 5, bigPrimary = true, pills = true, cardSeats = true }
				local r = L.compute(sz[1], sz[2], spec)
				local tag = sz[1] .. "x" .. sz[2] .. " patrons " .. patrons .. " primary " .. primary
				expectTrue(r.primary[1].h >= L.BIG_H and r.primary[1].h > (r.primary[2] and r.primary[2].h or 0), "Play Again is the big primary at " .. tag)
				expectEqual(#r.primary, primary, "one cell per primary at " .. tag)
				local w0 = r.more[1].w
				for i, c in ipairs(r.more) do
					expectTrue(c.h >= 44, "pill " .. i .. " is 44 px tall at " .. tag)
					expectTrue(math.abs(c.w - w0) < 0.01, "pill " .. i .. " matches the others at " .. tag)
				end
				expectTrue(r.patrons.seatW >= 72 and r.patrons.seatH >= 108, "cut cards are 72 px wide or more at " .. tag)
				if patrons > 0 and patrons <= math.floor((r.patrons.w + 8) / (L.CARD_W + 8)) then expectTrue(r.patrons.seatW == L.CARD_W, "up to a row of Patrons gets 90 px cards at " .. tag) end
				local all = { r.title, r.facts, r.patronsLabel, r.patrons }
				for _, c in ipairs(r.primary) do all[#all + 1] = c end
				for _, c in ipairs(r.more) do all[#all + 1] = c end
				for i = 1, #all do
					expectTrue(all[i].x >= 0 and all[i].x + all[i].w <= r.panel.w + 0.01 and all[i].y + all[i].h <= r.panel.h + 0.01, "block " .. i .. " is inside the panel at " .. tag)
					for j = i + 1, #all do expectFalse(overlap(all[i], all[j]), "blocks " .. i .. " and " .. j .. " do not overlap at " .. tag) end
				end
				expectTrue(r.facts.x - L.PLATE_PAD >= 0 and r.facts.y - L.PLATE_PAD >= r.title.y + r.title.h - L.PLATE_PAD, "the facts plate stays inside the panel at " .. tag)
			end
		end
	end
end })

table.insert(tests, { name = "Choice cards are painted parchment: wood frame with brass studs, a slight tilt each, a brass medallion, 16 px ink rule text centred in the gap, green plus and red minus", fn = function()
	local probe = io and io.open and load and io.open("src/Client/ChoicePanel.lua", "r")
	if not probe then return end
	probe:close()
	local FakeGui = require(script.Parent.FakeGui)
	local Engine = script.Parent.Parent.Engine
	local stubs = {
		PatronPlaque = { apply = function() return nil end, applyById = function() return nil end }, ClientSettings = { get = function() return "fast" end },
		ModalStage = { mount = function() return nil end, setKind = function() end },
		SmoothVignette = {}, SoftGlow = {}, PopupDismiss = { attach = function() end },
	}
	local env, st = FakeGui.env({ studio = true, stubs = stubs })
	setmetatable(stubs.SmoothVignette, { __index = function() return function() end end })
	setmetatable(stubs.SoftGlow, { __index = function() return function() return { root = FakeGui.new("Frame") } end end })
	st.services.ReplicatedStorage = { WaitForChild = function()
		return { WaitForChild = function()
			return FakeGui.folder({
				ContentArt = { getImageId = function() return nil end }, ChoiceSceneLayout = require(Engine.ChoiceSceneLayout),
				MenuSceneArt = require(Engine.MenuSceneArt), PopupDismissRules = require(Engine.PopupDismissRules), ChoiceRarity = require(Engine.ChoiceRarity),
				ResponsiveLayout = require(Engine.ResponsiveLayout),
			})
		end }
	end }
	local ChoicePanel = FakeGui.load("src/Client/ChoicePanel.lua", env)
	local gui, menu, root = FakeGui.new("ScreenGui"), FakeGui.new("Frame"), FakeGui.new("Frame")
	menu.Visible, root.Visible = false, true
	gui.AbsoluteSize = { X = 1920, Y = 1080 }
	ChoicePanel.init({ screenGui = gui, menuFrame = menu, root = root, polishButton = function() end, roundCorner = function() end, playClickSfx = function() end, choiceRemote = {} })
	local Patrons = require(Engine.Patrons)
	local function row() return gui:FindFirstChild("ChoiceBackdrop"):FindFirstChild("Row", true) end
	local function cards()
		local out = {}
		for _, slot in ipairs(row():GetChildren()) do
			for _, c in ipairs(slot:GetChildren()) do if c.Name:sub(1, 7) == "Option_" then out[#out + 1] = c end end
		end
		return out
	end
	local tilts = {}
	for _, spec in ipairs({
		{ kind = "modifier", title = "Choose a blessing", options = {
			{ id = "b1", name = "Sharp Eyes", icon = "E", line1 = "+1 hand each round", line2 = "-1 discard each round" },
			{ id = "b2", name = "Generous House", icon = "G", line1 = "+2 Tips per round", line2 = "Shop prices rise by 1" },
			{ id = "b3", name = "Big Recipe Book", icon = "B", line1 = "+1 recipe slot", line2 = "-1 Patron seat" }, { id = "decline", name = "No blessing", icon = "x", line1 = "Play it straight." } } },
		{ kind = "patron", title = "Choose your first Patron", options = {
			{ id = Patrons.Definitions[1].id, name = Patrons.Definitions[1].name, icon = "P", line1 = "A steady hand." },
			{ id = Patrons.Definitions[2].id, name = Patrons.Definitions[2].name, icon = "Q", line1 = "Lucky." } } },
	}) do
		ChoicePanel.update({ choice = spec })
		local list = cards()
		expectTrue(#list == #spec.options, spec.kind .. ": one card per option")
		for i, card in ipairs(list) do
			local isDecline = card.Name == "Option_decline"
			local wood = card:FindFirstChild("WoodFrame")
			expectTrue(wood ~= nil, card.Name .. " has the dark wood frame")
			local studs = 0
			for _, k in ipairs(wood:GetChildren()) do if k.Name:sub(1, 8) == "WoodStud" then studs = studs + 1 end end
			expectEqual(studs, 4, card.Name .. " has four brass studs")
			expectTrue(math.abs(card.Rotation) <= 2 and (isDecline or card.Rotation ~= 0), card.Name .. " has a slight tilt of at most 2 degrees")
			if not isDecline then tilts[#tilts + 1] = card.Rotation end
			expectTrue(card:FindFirstChild("MedalRing") ~= nil, card.Name .. " has a brass ring around the portrait")
			local rule = card:FindFirstChild("Rule")
			expectTrue(rule ~= nil and rule:FindFirstChildOfClass("UIListLayout").VerticalAlignment == env.Enum.VerticalAlignment.Center, card.Name .. " centres the rule text in the gap")
			for _, line in ipairs(rule:GetChildren()) do
				if line.ClassName == "TextLabel" then expectTrue(line.TextSize >= 16, card.Name .. " rule text is 16 px or more") end
			end
			expectTrue(card:FindFirstChild("Pick") ~= nil, card.Name .. " keeps its wooden Choose plate button")
			if spec.kind == "modifier" and not isDecline then
				local plus, minus = rule:FindFirstChild("Line1"), rule:FindFirstChild("Line2")
				expectTrue(plus.TextColor3.G > plus.TextColor3.R and plus.TextColor3.G > plus.TextColor3.B, card.Name .. " plus line is green ink")
				expectTrue(minus.TextColor3.R > minus.TextColor3.G and minus.TextColor3.R > minus.TextColor3.B, card.Name .. " minus line is red ink")
				expectFalse((plus.Text .. minus.Text):find("\226\128\148", 1, true) ~= nil, card.Name .. " text has no em dash")
			end
		end
	end
	expectTrue(#tilts >= 4 and tilts[1] ~= tilts[2], "the cards tilt differently")
	local f = io.open("src/Client/ChoicePanel.lua", "r")
	if f then
		local text = f:read("*a")
		f:close()
		expectTrue(text:find("ChoiceRarity.info", 1, true) ~= nil and text:find("RarityGem", 1, true) ~= nil, "the rarity rim, gem and tier word are the shared ChoiceRarity helper, not a copy")
	end
end })

table.insert(tests, { name = "DebugGoto: haggle, road, runover, packroom, rarity and the wildcard and legendary effects parse, and their synthetic states carry what each screen needs", fn = function()
	local R = require(script.Parent.Parent.Engine.DebugGotoRules)
	local function kind(v) local t = R.parse(v) return t and t.kind, t end
	for _, name in ipairs({ "haggle", "road", "runover", "packroom", "rarity" }) do
		local k, t = kind(name)
		expectTrue(k == "synth" and t.which == name, name .. " is a synth screen")
	end
	local _, t = kind("haggle:bad")
	expectTrue(t.which == "haggle" and t.variant == "bad", "haggle:bad")
	_, t = kind("haggle:good")
	expectTrue(t.which == "haggle" and t.variant == "good", "haggle:good")
	_, t = kind("runover:win")
	expectTrue(t.which == "runover" and t.variant == "win", "runover:win")
	_, t = kind("rarity:2")
	expectTrue(t.which == "rarity" and t.page == 2, "rarity:2 is the second page")
	for _, effect in ipairs({ "wildcard", "legendary" }) do
		local k, e = kind(effect)
		expectTrue(k == "fx" and e.effect == effect, effect .. " plays an effect")
	end
	for _, bad in ipairs({ "haggle:ugly", "runover:lose", "rarity:x", "rarity:0", "packroom:2", "road:1", "Wildcard2" }) do
		expectEqual(R.parse(bad), nil, bad .. " is refused")
	end
	expectTrue(R.parse("HAGGLE:Bad").variant == "bad", "case and spaces are folded")
	-- the synthetic states
	local base = { phase = "playing", night = 1, round = 1, tips = 3, ownedPatrons = {}, patronSlotLimit = 5, hand = { 1, 2 } }
	local Patrons = require(script.Parent.Parent.Engine.Patrons)
	local all = Patrons.Definitions
	local two = { all[1], all[2] }
	local good = R.synth("haggle", base, { patrons = two, variant = "good" })
	local bad = R.synth("haggle", base, { patrons = two, variant = "bad" })
	expectTrue(good.phase == "shop" and good.tips >= 20 and good.stranger ~= nil and #good.shopOffers == 2, "haggle: the Counter with a Stranger and enough Tips")
	expectTrue(#bad.stranger.curse > #bad.stranger.blessing + 8 and #good.stranger.curse <= #good.stranger.blessing + 8, "bad has the long curse (second scroll), good does not")
	local SL = require(script.Parent.Parent.Engine.ScrollOfferLayout)
	expectTrue(SL.pick(bad.stranger) == "b" and SL.pick(good.stranger) == "a", "so the two variants show the two scrolls")
	local road = R.synth("road", base, { roads = { "a", "b", "c" } })
	expectTrue(road.phase == "roundSelect" and #road.worldChoices == 3 and road.night >= 3, "road: three choices on a Night 3 fork")
	local lose = R.synth("runover", base, { patrons = all })
	local win = R.synth("runover", base, { patrons = all, variant = "win" })
	expectTrue(lose.phase == "gameover" and lose.wonRun == false and win.wonRun == true and win.runSummary.won == true, "runover: a loss and a win")
	for _, st in ipairs({ lose, win }) do
		local sm = st.runSummary
		expectTrue(sm.bestHand and #sm.route >= 3 and #sm.patrons >= 1 and sm.blessing and sm.rarity and st.nextUnlock and st.continueOffer == "free", "runover: every field is filled")
	end
	local room = R.synth("packroom", base, { allPatrons = all })
	expectTrue(room.phase == "shop" and room.tips == 20 and #room.ownedPatrons == room.patronSlotLimit and room.pendingPack and #room.pendingPack.items == 3, "packroom: a full table, 20 Tips, a pack of three")
	for _, item in ipairs(room.pendingPack.items) do
		for _, owned in ipairs(room.ownedPatrons) do expectFalse(item.id == owned.id, "a revealed Patron is not already owned") end
	end
	local page1 = R.synth("rarity", base, { tierPatrons = all, page = 1 })
	local page2 = R.synth("rarity", base, { tierPatrons = all, page = 2 })
	expectTrue(page1.choice.kind == "patron" and #page1.choice.options == 3 and #page2.choice.options == 3 and page1.choice.options[1].id ~= page2.choice.options[1].id, "rarity: three per page, the next page shows the next three")
	local f = io and io.open and io.open("src/Client/DebugGoto.lua", "r")
	if f then
		local src = f:read("*a")
		f:close()
		expectTrue(src:find("haggle, haggle:good, haggle:bad", 1, true) ~= nil and src:find("wildcard, legendary", 1, true) ~= nil, "the header comment lists the new values")
	end
end })

table.insert(tests, { name = "LoadProgress: monotonic, clamped 0 to 1, reaches 1 only when the Menu is shown and every phase is done; the bar fill never leaves the frame", fn = function()
	local LP = require(script.Parent.Parent.Engine.LoadProgress)
	local p = LP.new()
	expectEqual(p.value(), 0, "starts at 0")
	p.report("menu", 5, 10)
	expectTrue(math.abs(p.value() - 0.2) < 1e-9, "half of the 40 percent menu phase is 0.2")
	p.report("menu", 2, 10)
	expectTrue(math.abs(p.value() - 0.2) < 1e-9, "a lower report never moves the bar back")
	p.report("menu", 99, 10)
	p.report("gameplay", 10, 10)
	expectTrue(p.value() < 1, "not 1 before the Menu is shown")
	expectFalse(p.isReady(), "not ready before the Menu is shown")
	p.menuShown()
	expectEqual(p.value(), 1, "1 once the Menu is shown and every phase is complete")
	expectTrue(p.isReady(), "ready")
	local q = LP.new()
	q.menuShown()
	expectTrue(q.value() <= 0.2 + 1e-9 and not q.isReady(), "the Menu alone is 20 percent, never 1")
	q.complete("menu"); q.complete("gameplay")
	expectEqual(q.value(), 1, "complete() fills a phase with nothing to load")
	q.report("bogus", 1, 1)
	expectEqual(LP.clamp01(7), 1, "clamped high")
	expectEqual(LP.clamp01(-3), 0, "clamped low")
	local d = 0
	for _ = 1, 600 do
		local nd = LP.ease(d, 0.5, 1 / 60)
		expectTrue(nd >= d and nd <= 0.5, "ease never goes backward or past the target")
		d = nd
	end
	expectTrue(d > 0.49, "ease reaches the target")
	expectEqual(LP.ease(0.8, 0.3, 0.1), 0.8, "a lower target never pulls the bar back")
	for _, v in ipairs({ -1, 0, 0.33, 1, 2 }) do
		for _, w in ipairs({ 0, 100, 345 }) do
			local px = LP.fillWidth(w, v)
			expectTrue(px >= 0 and px <= w, "fill stays inside the frame")
		end
	end
	expectTrue(LP.stalled(10, 1) and not LP.stalled(5, 1), "Almost there after 8 s with no progress")
	expectEqual(LP.status(0.5, true, false), "Almost there...", "stalled text")
	expectEqual(LP.status(0.5, true, true), "Still loading, thanks for waiting", "slow text beats stalled")
	expectTrue(LP.MIN_VISIBLE >= 1.2 and LP.SKIP_AFTER == 25, "timings from the brief")
end })

table.insert(tests, { name = "LoadingTips: 12 tips, plain text with no dashes, short enough for one 15 px line, the shuffle uses each once; the launch screen is wired and uses no tiny text", fn = function()
	local Tips = require(script.Parent.Parent.Engine.LoadingTips)
	local LP = require(script.Parent.Parent.Engine.LoadProgress)
	expectEqual(#Tips.TIPS, 12, "twelve tips")
	for i, tip in ipairs(Tips.TIPS) do
		expectFalse(tip:find("-", 1, true) ~= nil or tip:find("\226\128\148", 1, true) ~= nil or tip:find("\226\128\147", 1, true) ~= nil, "tip " .. i .. " has no dash")
		expectTrue(#tip <= Tips.MAX_LENGTH, "tip " .. i .. " fits one line")
		expectFalse(tip:lower():find("balatro", 1, true) ~= nil, "no banned word")
	end
	for i, text in ipairs({ LP.status(0.1), LP.status(0.5), LP.status(0.9), LP.status(0.5, true), LP.status(0.5, true, true) }) do
		expectFalse(text:find("-", 1, true) ~= nil, "status " .. i .. " has no dash")
	end
	local seen, order = {}, Tips.order(42)
	for _, idx in ipairs(order) do seen[idx] = true end
	local n = 0
	for _ in pairs(seen) do n = n + 1 end
	expectTrue(#order == 12 and n == 12, "every tip exactly once")
	local DG = require(script.Parent.Parent.Engine.DebugGotoRules)
	expectEqual(DG.parse("loading").percent, 60, "loading freezes at 60")
	expectEqual(DG.parse("loading:25").percent, 25, "loading:<n>")
	expectEqual(DG.parse("loading:900").percent, 100, "loading:<n> clamps")
	local f = io and io.open and io.open("default.project.json", "r")
	if f then
		local text = f:read("*a")
		f:close()
		expectTrue(text:find("ReplicatedFirst", 1, true) ~= nil and text:find("src/ReplicatedFirst", 1, true) ~= nil, "ReplicatedFirst is mapped")
	end
	local u = io and io.open and io.open("src/ReplicatedFirst/LoadingScreenUI.lua", "r")
	if u then
		local text = u:read("*a")
		u:close()
		expectTrue(text:find("ScrimGradient", 1, true) ~= nil and not text:find("Vignette", 1, true), "the scrims are two fade frames from ScrimGradient, no stacked vignettes")
		local L = require(script.Parent.Parent.Engine.LoadingLook)
		for _, line in ipairs({ { L.CREAM, L.STATUS_Y }, { L.CREAM, L.TIP_Y } }) do
			expectTrue(L.worstContrast(line[1], L.BOTTOM, line[2]) >= 4.5, "status and tip text read at 4.5:1 even on a white painting")
		end
		expectTrue(L.scrimOpacity(L.BOTTOM, 0.4) == 0 and L.scrimOpacity(L.TOP, 0.5) == 0, "the middle of the painting is not darkened")
		expectTrue(L.scrimOpacity(L.TOP, 0) <= 0.5 and L.scrimOpacity(L.BOTTOM, 1) <= 0.9, "edges darken to a limit")
		expectTrue(text:find("DisplayOrder = 1000", 1, true) ~= nil and text:find("ResetOnSpawn = false", 1, true) ~= nil and text:find("IgnoreGuiInset = true", 1, true) ~= nil, "gui settings")
		expectTrue(text:find("fade.Active = false", 1, true) ~= nil and text:find("gui:Destroy()", 1, true) ~= nil, "it stops blocking clicks and is destroyed")
		expectTrue(text:find("math.max(15, size)", 1, true) ~= nil, "text is never under 15")
		expectTrue(not text:find("gradient(fade,", 1, true) and not text:find("gradient%(fade%s*[,)]"), "no UIGradient is a direct child of the Fade CanvasGroup (it would tint every child)")
	end
end })

table.insert(tests, { name = "BoardDrawer: collapsed board is fully off screen except the handle, the chip and handle stay inside, numbers are whole, phones and forced-open keep it open", fn = function()
	local D = require(script.Parent.Parent.Engine.BoardDrawer)
	local PBL = require(script.Parent.Parent.Engine.PlayBoardLayout)
	expectEqual(D.SLIDE_TIME, 0.2, "settles in 0.2 s")
	expectEqual(D.STRIP, 28, "a 28 px strip stays")
	expectTrue(D.HANDLE == nil and D.CHIP == nil and D.handleRect == nil and D.chipRect == nil and D.chipLines == nil, "no handle tab and no info chip")
	for _, size in ipairs({ { 1920, 957 }, { 1280, 720 }, { 900, 600 } }) do
		local sw, sh = size[1], size[2]
		local p = PBL.placement(sw, sh)
		local boardW = p and p.w or 240
		local dist = D.distance(boardW)
		expectEqual(boardW - dist, D.STRIP, "away, exactly the strip of the board is left on screen at " .. sw .. "x" .. sh)
		local sr = D.stripRect(sh, 40, 600)
		expectTrue(sr.x == 0 and sr.w == 28 and sr.y >= 0 and sr.y + sr.h <= sh, "the strip is on screen")
		expectTrue(sr.w < D.HAND_LEFT_COLLAPSED, "the strip is clear of the hand")
		expectEqual(D.dragDx(0, 50, boardW), 0, "dragging right of open stays open")
		expectEqual(D.dragDx(0, -9999, boardW), -dist, "dragging far left stops at the strip")
		expectEqual(D.dragDx(-dist, 30, boardW), -dist + 30, "dragging the strip back follows the pointer")
		expectTrue(D.settle(false, -math.floor(dist * 0.41), boardW), "open board dragged past 40 percent snaps away")
		expectFalse(D.settle(false, -math.floor(dist * 0.39), boardW), "dragged less than 40 percent snaps back open")
		expectFalse(D.settle(true, -dist + math.floor(dist * 0.41), boardW), "away board dragged back past 40 percent snaps open")
		expectTrue(D.settle(true, -dist + math.floor(dist * 0.39), boardW), "dragged back less than 40 percent stays away")
	end
	expectFalse(D.isDrag(3), "under 4 px is a click")
	expectTrue(D.isDrag(-4), "4 px or more is a drag")
	local g = io and io.open and io.open("src/Client/BoardDrawer.lua", "r")
	if g then
		local src = g:read("*a")
		g:close()
		expectTrue(src:find("BoardDrawerHandle", 1, true) == nil and src:find("BoardDrawerChip", 1, true) == nil, "no handle and no chip are built")
		expectTrue(src:find("BoardDragging", 1, true) ~= nil and src:find("not processed", 1, true) == nil and src:find("processed or", 1, true) ~= nil, "a drag starts only on input no button took")
	end
	expectTrue(D.collapsed(true, false, 1920), "the user's choice collapses it")
	expectFalse(D.collapsed(true, true, 1920), "a tutorial step or tooltip keeps it open")
	expectFalse(D.collapsed(true, false, 800), "under 900 px the compact layout owns the drawer")
	expectEqual(D.handLeft(true, 361), D.HAND_LEFT_COLLAPSED, "the hand uses the free width")
	expectEqual(D.handLeft(false, 361), 385, "open, the hand starts 24 px right of the board")
	local PP = require(script.Parent.Parent.Engine.PlayerProfile)
	expectTrue(PP.SETTING_SPECS.boardCollapsed ~= nil and PP.SETTING_SPECS.boardCollapsed.default == false, "boardCollapsed is a saved setting, default open")
	local R = require(script.Parent.Parent.Engine.DebugGotoRules)
	expectTrue(R.parse("drawer:closed").closed == true and R.parse("drawer:open").closed == false, "DebugGoto drawer:closed and drawer:open")
	local f = io and io.open and io.open("src/Client/BoardDrawer.lua", "r")
	if f then
		local text = f:read("*a")
		f:close()
		expectTrue(text:find("KeyCode.Tab", 1, true) ~= nil and text:find("GetFocusedTextBox", 1, true) ~= nil, "Tab toggles, never while a text box has focus")
		expectTrue(text:find("motionAllowed", 1, true) ~= nil, "reduced motion is instant")
	end
end })

table.insert(tests, { name = "PreviewGuard: every run remote is rejected while PreviewMode is true, a new run ends it, the preview shows a fixed sample hand and numbers and never the real run", fn = function()
	local G = require(script.Parent.Parent.Engine.PreviewGuard)
	local runRemotes = { "PlayHand", "Discard", "BuyPatron", "SellPatron", "Choice", "ChooseRoad", "BuyRecipe", "UseRecipe", "RerollShop", "Haggle", "Stranger", "BuyPack", "ResolvePack", "BuyHousePass", "AdvanceRound", "SelectRound", "SkipRound", "UnlockRoad", "UseCompass", "UseRuleBan", "Minigame", "SideStop", "RequestContinue" }
	for _, name in ipairs(runRemotes) do
		expectTrue(G.blocked("Rem." .. name, true), name .. " is rejected while previewing")
		expectFalse(G.blocked("Rem." .. name, false), name .. " works normally otherwise")
	end
	expectTrue(G.blocked("UseRuleBanRemote", true), "the Rule Ban key is guarded too")
	expectFalse(G.blocked("Rem.SetSetting", true) or G.blocked("Rem.EquipCosmeticSet", true), "settings and cosmetics are not run actions")
	for _, name in ipairs({ "StartRun", "RestartRun", "AbandonRun", "StartTutorial" }) do expectTrue(G.ENDS["Rem." .. name], name .. " ends a preview") end
	local real = { phase = "playing", night = 5, round = 2, roundScore = 812, targetScore = 4000, handsRemaining = 1, discardsRemaining = 0, tips = 31, ownedPatrons = { { id = "x" } }, hand = { { rank = 9, suit = "Hearts" } }, isBossRound = true, bossModifier = { id = "b" } }
	local sample = G.sampleState(real)
	expectEqual(real.night, 5, "the real state is never changed")
	expectEqual(#real.hand, 1, "the real hand is untouched")
	expectTrue(sample.night == 1 and sample.round == 1 and sample.roundScore == 0 and sample.targetScore == 300, "sample Night 1 Round 1, 0 / 300")
	expectTrue(#sample.hand == 8 and #sample.ownedPatrons == 0 and sample.isBossRound == false and sample.bossModifier == nil, "a fixed sample hand, no real Patrons or boss")
	local suits, face, ace = {}, false, false
	for _, c in ipairs(sample.hand) do suits[c.suit] = true if c.rank >= 11 and c.rank <= 13 then face = true end if c.rank == 14 then ace = true end end
