table.insert(tests, { name = "CollectionPreload: the warm list covers every sub-tab and the scenes with no duplicate or empty ids, in batches of 20, and the grids fade art in", fn = function()
	local E = script.Parent.Parent.Engine
	local CP = require(E.CollectionPreload)
	local items = CP.items()
	local seenCat = {}
	for _, it in ipairs(items) do
		expectTrue(type(it[1]) == "string" and it[1] ~= "" and not seenCat[it[1]], "category " .. tostring(it[1]) .. " listed once")
		seenCat[it[1]] = true
	end
	for _, c in ipairs({ "patrons", "recipes", "boss_rounds", "house_passes", "titles", "bonds", "collection_scene" }) do expectTrue(seenCat[c], c .. " is warmed") end
	local fake = {
		collectUrls = function(list)
			local out, seen = {}, {}
			for _, it in ipairs(list) do for i = 1, 45 do local u = it[1] .. i if not seen[u] then seen[u] = true out[#out + 1] = u end end end
			return out
		end,
	}
	local urls = CP.urls(fake)
	local seen = {}
	for _, u in ipairs(urls) do expectTrue(u ~= "" and not seen[u], "no empty or duplicate url " .. u) seen[u] = true end
	local batches = CP.batches(urls, 20)
	local total = 0
	for i, b in ipairs(batches) do expectTrue(#b <= 20 and #b >= 1, "batch " .. i .. " has 1 to 20 urls") total = total + #b end
	expectEqual(total, #urls, "every url is in a batch")
	local ContentArt = require(E.ContentArt)
	local real = CP.urls(ContentArt)
	local rs = {}
	for _, u in ipairs(real) do expectTrue(u ~= "" and not rs[u], "real warm list has no empty or duplicate url") rs[u] = true end
	local f = io and io.open and io.open("src/Client/Collection.lua", "r")
	if f then
		local text = f:read("*a")
		f:close()
		expectTrue(text:find("[Collection] tab=%s ready_ms=%d", 1, true) ~= nil and text:find("collection warm", 1, true) ~= nil, "timing line and warm-up on open")
		expectTrue(text:find("fade = true", 1, true) ~= nil, "Collection art fades in")
	end
	local g = io and io.open and io.open("src/Client/ArtFade.lua", "r")
	if g then
		local text = g:read("*a")
		g:close()
		expectTrue(text:find("DURATION = 0.15", 1, true) ~= nil, "0.15 s fade")
	end
end })

table.insert(tests, { name = "ScrimGradient: a fade is 16+ smooth keypoints, clear at the top, about 8 percent transparent at the bottom (RoundSelect card scrim)", fn = function()
	local ScrimGradient = require(script.Parent.Parent.Engine.ScrimGradient)
	local k = ScrimGradient.keypoints(16, 0.92, 0.8)
	assert(#k >= 16, "needs at least 16 keypoints")
	assert(k[1][1] == 0 and k[1][2] == 1, "transparency 1 at the top")
	assert(k[#k][1] == 1 and math.abs(k[#k][2] - 0.08) < 1e-9, "about 0.08 at the bottom")
	for n = 2, #k do
		assert(k[n][1] > k[n - 1][1], "times strictly increase")
		assert(k[n][2] <= k[n - 1][2], "transparency never rises")
	end
end })


table.insert(tests, { name = "BoardPanelRows: one panel under the board holds Tips, hint, Blessing and Run in order, inside the screen, rows never overlap", fn = function()
	local PB = require(script.Parent.Parent.Engine.PlayBoardLayout)
	local BP = require(script.Parent.Parent.Engine.BoardPanelRows)
	for _, sz in ipairs({ { 1920, 1080 }, { 1506, 751 }, { 1280, 720 }, { 1000, 600 }, { 900, 500 } }) do
		local bw, bh = PB.size(sz[1], sz[2])
		local H = PB.hud(bw, bh)
		local plan = BP.plan({ x = H.target.x - 6, w = H.target.w + 12, top = bh + 2, avail = sz[2] - (bh + 2) - 8,
			want = { tips = true, hint = true, blessing = true, run = true } })
		local tag = sz[1] .. "x" .. sz[2]
		expectTrue(plan.panel.y == bh + 2, "panel hangs right under the board at " .. tag)
		expectTrue(plan.panel.y + plan.panel.h <= sz[2], "panel inside the screen at " .. tag)
		expectTrue(plan.panel.x + plan.panel.w <= bw, "panel no wider than the board at " .. tag)
		local last = plan.panel.y
		for _, k in ipairs(plan.order) do
			local r = plan.rows[k]
			expectTrue(r.y >= last and r.h >= 26, k .. " row below the previous one and tall enough for 15 px text at " .. tag)
			expectTrue(r.x >= plan.panel.x and r.x + r.w <= plan.panel.x + plan.panel.w, k .. " row inside the panel at " .. tag)
			last = r.y + r.h
		end
		expectTrue(last <= plan.panel.y + plan.panel.h, "rows end inside the panel at " .. tag)
		expectTrue(plan.order[1] == "tips" and plan.order[2] == "hint", "Tips then the hint at " .. tag)
		expectTrue(#plan.seps == #plan.order - 1, "one brass line between neighbours at " .. tag)
		expectTrue(plan.fits, "everything fits at " .. tag)
	end
end })

table.insert(tests, { name = "PlayBoardLayout: the tall board is three slices, the band stretches, the cap and extra seats move down, rows fit inside the grown board", fn = function()
	local PB = require(script.Parent.Parent.Engine.PlayBoardLayout)
	local BP = require(script.Parent.Parent.Engine.BoardPanelRows)
	for _, sz in ipairs({ { 1920, 957 }, { 1280, 720 }, { 1000, 600 }, { 900, 500 } }) do
		local bw, bh = PB.size(sz[1], sz[2])
		local H = PB.hud(bw, bh)
		local avail = sz[2] - 8 - bh + math.floor(PB.PANEL_ROOM * bw / PB.IMG_W)
		local plan = BP.plan({ x = H.target.x - 6, w = H.target.w + 12, top = PB.panelTop(bw), avail = avail,
			want = { tips = true, hint = true, blessing = true, run = true } })
		local E = PB.extension(bw, plan.panel.h)
		local tag = sz[1] .. "x" .. sz[2]
		local sl = PB.slices(bw, bh, E)
		expectTrue(#sl == 3 and sl[1].y == 0 and sl[2].y == sl[1].h and sl[3].y == sl[2].y + sl[2].h, "slices stack with no gap at " .. tag)
		expectTrue(sl[3].y + sl[3].h == bh + E, "the grown board ends " .. E .. " px lower at " .. tag)
		expectTrue(sl[1].src.h + sl[2].src.h + sl[3].src.h == PB.IMG_H, "the three source rects cover the picture once at " .. tag)
		expectTrue(sl[2].h >= PB.BAND.h * bh / PB.IMG_H - 1, "the band never shrinks at " .. tag)
		expectTrue(bh + E <= sz[2] - 8 or not plan.fits, "the grown board stays inside the screen with its 8 px margin at " .. tag)
		local rings = PB.map(bw, bh).rings[1]
		expectTrue(PB.panelTop(bw) >= rings.cy + rings.d / 2 - 1, "rows start under the ring bottoms at " .. tag)
		expectTrue(plan.panel.y + plan.panel.h <= bh + E, "every row ends inside the grown board at " .. tag)
		local a, b = PB.seats(bw, bh, 7)[7], PB.seats(bw, bh, 7, E)[7]
		expectTrue(b.y == a.y + E and b.ring.cy == a.ring.cy + E, "an extra seat moves down with the cap at " .. tag)
		expectTrue(PB.seats(bw, bh, 5, E)[5].y == PB.seats(bw, bh, 5)[5].y, "a ring seat does not move at " .. tag)
	end
	expectTrue(PB.extension(460, 0) == 0 and PB.extension(460, 10) == 0, "no rows, no growth")
end })

table.insert(tests, { name = "BoardPanelRows: a missing row collapses, short screens shrink then drop Run and Blessing, an empty plan has no panel", fn = function()
	local BP = require(script.Parent.Parent.Engine.BoardPanelRows)
	local base = { x = 10, w = 240, top = 400 }
	local function plan(avail, want) return BP.plan({ x = base.x, w = base.w, top = base.top, avail = avail, want = want }) end
	local all = { tips = true, hint = true, blessing = true, run = true }
	local roomy = plan(500, all)
	expectTrue(roomy.blessing == "full" and roomy.level == 0, "roomy: full Blessing row")
	local noRun = plan(500, { tips = true, hint = true, blessing = true })
	expectTrue(noRun.rows.run == nil and noRun.panel.h < roomy.panel.h, "no seeded run: the Run row collapses")
	local tight = plan(roomy.panel.h - 10, all)
	expectTrue(tight.blessing == "compact" and tight.fits and tight.rows.run ~= nil, "tight: Blessing goes compact first")
	local tiny = plan(150, all)
	expectTrue(tiny.fits and tiny.panel.h <= 150, "tiny: still fits")
	expectTrue(tiny.rows.run == nil, "tiny: the Run row is dropped before anything else")
	local empty = plan(300, {})
	expectTrue(empty.panel.h == 0 and #empty.order == 0, "no rows, no panel")
end })

