table.insert(tests, { name = "Source audit: no dash characters in player text, no doubled asset prefix, no banned word, the 14 px text count only goes down", fn = function()
	expectEqual(require(script.Parent.Parent.Engine.DebugGotoRules).parse("perf").kind, "perf", "DebugGoto perf prints the [Perf] line")
	local p = io and io.popen and io.popen("ls src/Client/*.lua src/Shared/Engine/*.lua 2>/dev/null")
	if not p then return end
	local files = {}
	for l in p:lines() do files[#files + 1] = l end
	p:close()
	if #files == 0 then return end
	local small = 0
	for _, path in ipairs(files) do
		local n = 0
		for line in io.lines(path) do
			n = n + 1
			local code = line:gsub("%-%-.*$", "") -- comments may use any characters; strings may not
			if code:find("\226\128\148", 1, true) or code:find("\226\128\147", 1, true) then
				expectTrue(false, path .. ":" .. n .. " has an em or en dash in code (player text uses commas and periods)")
			end
			if code:find("rbxassetid://rbxassetid://", 1, true) then
				expectTrue(false, path .. ":" .. n .. " doubles the rbxassetid prefix")
			end
			if code:lower():find("balatro", 1, true) and not code:find("BANNED", 1, true) then -- the filter list itself may name it
				expectTrue(false, path .. ":" .. n .. " has the banned word")
			end
			if path:find("src/Client/", 1, true) then
				local size = code:match("TextSize%s*=%s*(%d+)")
				if size and tonumber(size) == 14 then small = small + 1 end
				if size and tonumber(size) < 14 and not line:find("-- small:", 1, true) then
					expectTrue(false, path .. ":" .. n .. " TextSize " .. size .. " is under the 14 px floor")
				end
			end
		end
	end
	-- the floor is moving to 15: lower this number when a 14 becomes 15, never raise it (Studio check needed for plates that fit 14 only)
	expectTrue(small <= 126, "14 px text literals in src/Client: " .. small .. " (ratchet 126)")
end })

table.insert(tests, { name = "CornerDock: the dock is a function of the open pages, so no open/close order leaves it hidden (tabs, Map, Escape, Round Select, a run starting)", fn = function()
	local DR = require(script.Parent.Parent.Engine.DockRules)
	expectTrue(DR.visible({}), "nothing open: shown")
	expectFalse(DR.visible({ panelOpen = true }), "a page open: hidden")
	expectFalse(DR.visible({ roundSelect = true }), "Round Select: hidden")
	if not (io and io.open and load) then return end
	local probe = io.open("src/Client/CornerDock.lua", "r")
	if not probe then return end
	probe:close()
	local FakeGui = require(script.Parent.FakeGui)
	local env, state = FakeGui.env({})
	state.services.ReplicatedStorage = { WaitForChild = function() return { WaitForChild = function() return FakeGui.folder({ DockRules = DR }) end } end }
	local CornerDock = FakeGui.load("src/Client/CornerDock.lua", env)
	local gui = FakeGui.new("ScreenGui")
	local root = FakeGui.new("Frame")
	root.Parent = gui
	local row = FakeGui.new("Frame")
	row.Name = "CornerIconRow"
	row.Parent = root
	local function backdrop(name)
		local b = FakeGui.new("Frame")
		b.Name = name
		b.Visible = false
		b.Parent = root
		CornerDock.register(b)
		return b
	end
	local collection, badges, map = backdrop("CollectionBackdrop"), backdrop("BadgesBackdrop"), backdrop("TavernMapBackdrop")
	local function expectDock(want, what) expectEqual(row.Visible, want, what) end
	expectDock(true, "start: shown")
	collection.Visible = true
	expectDock(false, "a page open")
	collection.Visible = false
	expectDock(true, "open, close")
	collection.Visible = true
	badges.Visible = true -- the new page shows first ...
	collection.Visible = false -- ... then the old one hides (the order that used to turn the dock back on under an open page)
	expectDock(false, "open, switch tab: still hidden while the new page is up")
	badges.Visible = false
	expectDock(true, "open, switch tab, close")
	collection.Visible = true
	map.Visible = true -- the Tavern Map opens on top of an open page
	collection.Visible = false
	map.Visible = false
	expectDock(true, "page, Map on top, page closes, Map closes: shown (the stale-saved-false bug)")
	collection.Visible = true
	collection.Visible = false -- Escape / dark area / Close X all end as Visible = false
	expectDock(true, "open, Escape")
	root:SetAttribute("BannerAtBottom", true)
	CornerDock.refresh(root)
	expectDock(false, "Round Select up: hidden")
	root:SetAttribute("BannerAtBottom", false)
	CornerDock.refresh(root)
	expectDock(true, "Round Select closed: shown")
	badges.Visible = true
	row.Visible = true -- something else (or a missed signal) leaves the dock in the wrong state
	state.runWaiting() -- the safety loop recomputes within one tick
	expectDock(false, "the safety loop heals a wrong Visible while a page is open")
	badges.Visible = false -- a run starts with every page closed
	row.Visible = false -- a stale hidden dock
	state.runWaiting()
	expectDock(true, "no page open: the safety loop brings the dock back")
end })

table.insert(tests, { name = "Full screen Collection: the layout never writes the windowed size back, the old Shadow stays hidden, the room fills the panel at 1920x1080 and 1280x720", fn = function()
	local scene = collectionBuild({ fullScreen = true })
	if not scene then return end
	local PL = require(script.Parent.Parent.Engine.PanelLayout)
	local top = PL.fullScreenRect(0, 0).y
	local FakeGui = require(script.Parent.FakeGui)
	local shadow = FakeGui.new("Frame") -- the old windowed panel shadow that popIn and SetSkin used to switch back on
	shadow.Name = "Shadow"
	shadow.Parent = scene.panel
	scene.backdrop.Visible = false
	scene.backdrop.Visible = true -- opening runs PanelFullScreen's force(), which flattens the decoration
	expectFalse(shadow.Visible, "opening hides the Shadow")
	for _, vp in ipairs({ { 1920, 1080 }, { 1280, 720 } }) do
		scene.camera.ViewportSize = { X = vp[1], Y = vp[2] }
		scene.panel.AbsoluteSize = { X = vp[1], Y = vp[2] - top } -- what Roblox reports for Size (1, 0, 1, -top)
		scene.panel.AbsoluteSize = { X = vp[1] - 1, Y = vp[2] - top } -- a size change makes the Collection lay out again
		scene.panel.AbsoluteSize = { X = vp[1], Y = vp[2] - top }
		local size = scene.panel.Size
		expectTrue(size.X.Scale == 1 and size.X.Offset == 0 and size.Y.Scale == 1 and size.Y.Offset == -top, vp[1] .. ": the panel keeps the full screen size after the layout ran, not the 66 percent windowed one")
		shadow.Visible = true -- popIn / SetSkin
		expectFalse(shadow.Visible, vp[1] .. ": the Shadow cannot be switched back on")
		scene.open()
		local room, grid = scene.room.AbsoluteSize, scene.panel.AbsoluteSize
		expectTrue(scene.room.Size.X.Scale > 0 or scene.room.Size.X.Offset >= 0, vp[1] .. ": the room has a size")
		expectTrue(room.X <= grid.X and room.Y <= grid.Y, vp[1] .. ": the room fits inside the panel")
	end
end })

table.insert(tests, { name = "beatslow: parses on/freeze/off, slows the Patron beat gap to 2.0 s, holds 1.6 s, off restores", fn = function()
	local R = require(script.Parent.Parent.Engine.DebugGotoRules)
	local PE = require(script.Parent.Parent.Engine.PatronEvents)
	for _, m in ipairs({ "on", "freeze", "off" }) do
		local t = R.parse("beatslow:" .. m)
		expectTrue(t ~= nil and t.kind == "beatslow" and t.mode == m, "beatslow:" .. m .. " parses")
	end
	expectTrue(R.parse("beatslow:maybe") == nil, "junk mode is nil")
	expectEqual(PE.gap(false), 0.18, "normal gap")
	expectTrue(PE.hold() == nil, "no hold normally")
	PE.setSlow("on")
	expectEqual(PE.gap(false), 2.0, "slow gap")
	expectEqual(PE.gap(true), 2.0, "slow gap in fast mode")
	expectEqual(PE.hold(), 1.6, "slow hold")
	expectTrue(PE.slowMode() == "slow", "mode slow")
	PE.setSlow("freeze")
	expectTrue(PE.slowMode() == "freeze", "mode freeze")
	PE.setSlow("off")
	expectEqual(PE.gap(false), 0.18, "off restores the gap")
	expectTrue(PE.slowMode() == nil and PE.hold() == nil, "off clears the mode")
end })

table.insert(tests, { name = "PatronEvents: every rarity has its own pill rim and unknown ones fall back to Common", fn = function()
	local PE = require(script.Parent.Parent.Engine.PatronEvents)
	local seen = {}
	for _, r in ipairs({ "common", "uncommon", "rare", "epic", "legendary" }) do
		local c = PE.rarityRim(r)
		assert(#c == 3, r)
		local k = table.concat(c, ",")
		assert(not seen[k], "rim shared: " .. r)
		seen[k] = true
	end
	assert(PE.rarityRim("Legendary")[1] == 255)
	assert(PE.rarityRim(nil)[1] == PE.rarityRim("common")[1])
end })
table.insert(tests, { name = "PlayMotion.flight: staggered arc to the deck pile, none in calm mode or Fast speed", fn = function()
	local PM = require(script.Parent.Parent.Engine.PlayMotion)
	assert(PM.flight(1, 3, true, false) == nil and PM.flight(1, 3, false, true) == nil)
	local a, b = PM.flight(1, 3, false, false), PM.flight(3, 3, false, false)
	assert(a.delay == 0 and b.delay > a.delay and a.dur > 0.2 and a.dur < 0.5 and a.arc > 0 and a.endScale < 1)
	local x0, y0 = PM.arc(0, 0, 100, 0, 0, a.arc)
	local x1, y1 = PM.arc(0, 0, 100, 0, 1, a.arc)
	local xm, ym = PM.arc(0, 0, 100, 0, 0.5, a.arc)
	assert(x0 == 0 and y0 == 0 and x1 == 100 and y1 == 0 and ym < 0, "starts at the card, ends at the deck, rises in between")
end })
table.insert(tests, { name = "HandFlow: play slide, tick lift, total pop, discard flight and deal flip timing table, nothing in calm mode", fn = function()
	local HF = require(script.Parent.Parent.Engine.HandFlow)
	local PM = require(script.Parent.Parent.Engine.PlayMotion)
	local a, c = HF.playSlide(1, 5, false), HF.playSlide(5, 5, false)
	assert(a.delay == 0 and a.dur == 0.25 and math.abs(c.delay - 0.16) < 1e-9, "0.25 s slide, 0.04 s stagger")
	assert(HF.playSlide(3, 5, true).delay == 0 and HF.playSlide(3, 5, true).dur == 0, "calm: instant")
	assert(HF.tickLift(true, false) == 14 and HF.tickLift(false, false) == 0 and HF.tickLift(true, true) == 0, "14 px lift on the scoring card only")
	assert(HF.totalPop(false).peak == 1.15 and HF.totalPop(true) == nil, "total pops to 1.15, none in calm")
	local d = HF.discardFlight(2, 3, false)
	assert(d.dur == 0.3 and math.abs(d.delay - 0.05) < 1e-9 and HF.discardFlight(1, 3, true) == nil, "discard 0.3 s, 0.05 s apart")
	assert(PM.flight(1, 3, false, false).dur == HF.TABLE.discardDur, "PlayMotion.flight uses the table")
	local f = HF.dealFlip(3, 7, false)
	assert(math.abs(f.delay - 0.12) < 1e-9 and f.flipFrom < 1 and HF.dealFlip(3, 7, true) == nil, "deal 0.06 s stagger with a flip")
	assert(select(1, PM.dealTiming(3, 7)) == f.delay, "deal arc uses the same stagger")
end })
table.insert(tests, { name = "PatronCallout: green Chips and Mult, blue x Mult, rise 24 px over 0.6 s, static 0.4 s in calm, one popup at a time per card", fn = function()
	local PC = require(script.Parent.Parent.Engine.PatronCallout)
	assert(PC.colorKey("chips") == "green" and PC.colorKey("mult") == "green" and PC.colorKey("xmult") == "blue" and PC.colorKey("money") == "gold")
	local s, c = PC.spec(false), PC.spec(true)
	assert(s.rise == 24 and s.dur == 0.6 and s.hop == 0.12 and not s.static, "rise 24 px, 0.6 s, hop 0.12 s")
	assert(c.rise == 0 and c.hop == 0 and c.dur == 0.4 and c.static, "calm: static label for 0.4 s, no motion")
	local a, aEnd = PC.schedule(10, nil, false)
	local b, bEnd = PC.schedule(10.3, aEnd, false)
	assert(a == 10 and aEnd == 10.6 and b == 10.6 and math.abs(bEnd - 11.2) < 1e-9, "a second popup on the same card waits for the first")
	assert(PC.schedule(20, 10.6, false) == 20, "an idle card starts at once")
	local function lum(col) local function f(v) v = v / 255; return v <= 0.03928 and v / 12.92 or ((v + 0.055) / 1.055) ^ 2.4 end return 0.2126 * f(col[1]) + 0.7152 * f(col[2]) + 0.0722 * f(col[3]) end
	local plate = lum({ 28, 18, 10 })
	for _, k in ipairs({ "chips", "xmult", "money" }) do
		local l = lum(PC.color(k))
		assert((l + 0.05) / (plate + 0.05) >= 4.5, k .. " popup colour reads on the dark plate")
	end
end })
table.insert(tests, { name = "Confetti: none in calm mode, fewer on Fast, more for a Boss clear, gold and purple, same seed same pieces", fn = function()
	local C = require(script.Parent.Parent.Engine.Confetti)
	assert(C.count(true, false, true) == 0, "calm: no confetti")
	assert(C.count(false, true, false) < C.count(false, false, false) and C.count(false, false, true) > C.count(false, false, false))
	local a, b = C.pieces(24, 7), C.pieces(24, 7)
	assert(#a == 24)
	local gold, purple = 0, 0
	for i, p in ipairs(a) do
		assert(p.x >= 0.15 and p.x <= 0.85 and p.vy < 0 and p.size >= 6 and p.delay >= 0 and p.delay <= 0.25)
		assert(p.x == b[i].x and p.color[1] == b[i].color[1], "deterministic")
		if p.color[1] > 200 and p.color[3] < 160 then gold = gold + 1 else purple = purple + 1 end
	end
	assert(gold > 0 and purple > 0, "both palettes appear")
end })
table.insert(tests, { name = "RoomLights: the Concept T play room has a fire, candles, a window and a few motes, all inside the picture", fn = function()
	local L = require(script.Parent.Parent.Engine.RoomLights)
	local r = L.ROOMS.concept_t
	assert(r and #r.spots >= 3 and L.moteCount("concept_t") > 0 and L.moteCount("concept_t") <= L.MAX_MOTES)
	local fire = false
	for _, sp in ipairs(r.spots) do
		assert(sp.x > 0 and sp.x < 1 and sp.y > 0 and sp.y < 1 and L.BASE[sp.kind])
		if sp.kind == "fire" then fire = true end
	end
	assert(fire, "the fireplace glows")
	local f = L.flicker("fire", 3.1, 1, false)
	assert(type(f) == "number" and math.abs(f - 1) <= L.LIMIT + 0.001 and L.flicker("fire", 3.1, 1, true) == 1, "flicker stays within the limit and is steady in calm mode")
	assert(r.shaft.x + r.shaft.w <= 1 and r.shaft.y + r.shaft.h <= 1)
end })
table.insert(tests, { name = "Table ambience: table_play and table_boss lights stay within 12 objects and on the picture, steady in Calm mode, run on FxLoop", fn = function()
	local L = require(script.Parent.Parent.Engine.RoomLights)
	for _, key in ipairs({ "table_play", "table_boss" }) do
		local r = L.ROOMS[key]
		assert(r and #r.spots >= 3, key .. " has candles and a fire")
		assert(#r.spots + L.moteCount(key) <= 12, key .. " animates at most 12 objects")
		local fire, candle = false, false
		for _, sp in ipairs(r.spots) do
			assert(sp.x > 0 and sp.x < 1 and sp.y > 0 and sp.y < 1 and L.BASE[sp.kind], key .. " spot on the picture")
			fire = fire or sp.kind == "fire"
			candle = candle or sp.kind == "candle"
			assert(L.flicker(sp.kind, 1.7, 2, true) == 1, "calm mode holds every light still")
		end
		assert(fire and candle, key .. " has a flickering candle and a breathing fire")
		assert(r.shaft.x + r.shaft.w <= 1 and r.shaft.y + r.shaft.h <= 1, key .. " motes stay on the picture")
	end
	local Life = require(script.Parent.Parent.Engine.TavernLife)
	assert(Life.firePulse(0, true) == 1 and Life.firePulse(1.5, false) >= 0.9 and Life.firePulse(1.5, false) <= 1, "fire breathes 0.9 to 1.0, none in Calm mode")
	if not (io and io.open) then return end
	local function read(path) local f = io.open(path, "r"); if not f then return "" end local x = f:read("*a"); f:close(); return x end
	local life = read("src/Client/Gameplay2Life.lua")
	assert(life:find("RoomLights", 1, true) and not life:find("Heartbeat:Connect", 1, true) and not life:find("TweenService", 1, true), "ambience rides RoomLights and the one FxLoop, no tweens of its own")
	assert(read("src/Client/Gameplay2.lua"):find("Gameplay2Life", 1, true), "the table hooks the ambience")
	local C = require(script.Parent.Parent.Engine.Gameplay2Perf)
	local listed = false
	for _, f in ipairs(C.LOOP_FILES) do if f == "src/Client/Gameplay2Life.lua" then listed = true end end
	assert(listed, "the perf lint covers the new file")
end })
table.insert(tests, { name = "ShopSparkle: Rare or better only, more for higher tiers, none in calm mode, one per offer per 30 s", fn = function()
