table.insert(tests, { name = "ConceptTLayout pass 6: stage centre moved right and down and about 5 percent larger, hand moved left and up with smaller cards", fn = function()
	local L = require(script.Parent.Parent.Engine.ConceptTLayout)
	local r = L.rects(1536, 1024)
	local cx, cy = r.stage.x + r.stage.w / 2, r.stage.y + r.stage.h / 2
	assert(math.abs(cx - (768 + 24)) <= 2 and math.abs(cy - (0.588 * 1024 + 27)) <= 2, "stage centre")
	assert(math.abs(r.stage.w / (0.300 * 1536) - 1.05) < 0.02 and math.abs(r.stage.h / (0.116 * 1024) - 1.05) < 0.03, "stage size")
	assert(math.abs(r.hand.x - (0.195 * 1536 - 18)) <= 2 and math.abs(r.hand.y + r.hand.h - (0.851 * 1024 - 3)) <= 2, "hand shift")
	assert(L.HAND_CARD_W < 0.086 and L.STAGE_SCALE == 1.05)
end })
table.insert(tests, { name = "ConceptTLayout small screens: five sizes keep every piece on screen, buttons at least 44 px and clear of the hand, no overlaps, text 15 px", fn = function()
	local L = require(script.Parent.Parent.Engine.ConceptTLayout)
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 800, 450 }, { 844, 390 }, { 1024, 768 } }) do
		local w, h = sz[1], sz[2]
		local tag = w .. "x" .. h
		assert(L.fits(w, h), tag .. " fits")
		local r = L.rects(w, h)
		for name, b in pairs(r) do
			assert(b.x >= 0 and b.y >= 0 and b.x + b.w <= w and b.y + b.h <= h, tag .. " " .. name .. " on screen")
		end
		assert(r.play.h >= 44 and r.discard.h >= 44, tag .. " buttons tall enough")
		assert(r.play.y >= r.hand.y + r.hand.h and r.discard.y >= r.hand.y + r.hand.h, tag .. " hand clear of the buttons")
		assert(#L.overlaps(r) == 0, tag .. " overlaps: " .. table.concat(L.overlaps(r), ","))
		for _, key in ipairs({ "coins", "hands", "round", "deckCount" }) do assert(L.textSize(key, h) >= 15, tag .. " text " .. key) end
	end
end })
table.insert(tests, { name = "Screen audit, play screen: HUD, Patron row (5 and 8 seats), hand, sort pill and buttons stay on screen, never overlap, touch targets 44 px", fn = function()
	local L = require(script.Parent.Parent.Engine.ConceptTLayout)
	local function hit(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	local function inside(b, w, h) return b.x >= 0 and b.y >= 0 and b.x + b.w <= w and b.y + b.h <= h end
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1024, 768 }, { 1024, 600 }, { 800, 450 }, { 844, 390 } }) do
		local w, h = sz[1], sz[2]
		local tag = w .. "x" .. h
		assert(L.fits(w, h), tag .. " fits")
		local r = L.rects(w, h)
		for _, n in ipairs({ 5, 8 }) do
			local row = L.patronRow(w, h, n)
			local hand = L.handFor(r.hand, w, 8)
			for i = 1, n do
				for _, kind in ipairs({ "cards", "labels", "pills" }) do
					local b = row[kind][i]
					assert(inside(b, w, h), tag .. " " .. kind .. i .. " on screen")
					assert(not hit(b, hand), tag .. " Patron " .. kind .. i .. " clear of the hand (n=" .. n .. ")")
					for _, hud in ipairs({ "coins", "hands", "round", "gear" }) do
						assert(not hit(b, r[hud]), tag .. " Patron " .. kind .. i .. " clear of " .. hud)
					end
				end
			end
		end
		local sw = L.sortSize(w, h)
		local sp = L.sortSpot(w, h, sw.w, sw.h, r)
		assert(inside(sp, w, h) and sp.h >= 34, tag .. " sort pill on screen")
		if w < 1000 or h < 600 then assert(sp.h >= 44, tag .. " sort pill is a 44 px touch target") end
		assert(not hit(sp, r.play) and not hit(sp, r.hand), tag .. " sort pill clear of Play Hand and the hand")
		assert(r.play.h >= 44 and r.discard.h >= 44 and r.gear.h >= 28 and r.gear.w >= 28, tag .. " tap targets")
		assert(not hit(r.hand, r.play) and not hit(r.hand, r.discard) and not hit(r.hand, r.deck), tag .. " hand clear of buttons and deck")
	end
	assert(not L.fits(390, 844) and not L.fits(375, 667), "a portrait phone keeps the phone layout, not the painted screen")
end })
table.insert(tests, { name = "Small screens table: 1024x600, 844x390 and 390x844 keep the Patron row clear of the hand; portrait wraps into two rows of up to three", fn = function()
	local PR = require(script.Parent.Parent.Engine.PatronRowLayout)
	local L = require(script.Parent.Parent.Engine.ConceptTLayout)
	local function hit(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	for _, sz in ipairs({ { 1024, 600 }, { 844, 390 }, { 390, 844 } }) do
		local w, h = sz[1], sz[2]
		local tag = w .. "x" .. h
		local hand = { x = 0, y = h - 200 - 10, w = w, h = 200 }
		for _, n in ipairs({ 1, 3, 5, 6, 8 }) do
			local wrap = PR.wrapped(w, h, hand, n)
			if w >= h or n <= 3 then
				assert(wrap == nil, tag .. " n=" .. n .. " does not wrap")
			else
				assert(wrap, tag .. " n=" .. n .. " wraps")
				assert(wrap.rows == 2, tag .. " two rows")
				for i, c in ipairs(wrap.cards) do
					assert(c.x >= 0 and c.y >= PR.TOP_LIMIT and c.x + c.w <= w and c.y + c.h <= hand.y + PR.HAND_TOP_PAD - PR.AIR, tag .. " card " .. i .. " on screen and above the hand cards")
					assert(c.h >= PR.FLOOR_H, tag .. " card " .. i .. " big enough")
					for j = i + 1, #wrap.cards do assert(not hit(c, wrap.cards[j]), tag .. " cards " .. i .. "," .. j .. " do not overlap") end
				end
				local perRow = {}
				for _, c in ipairs(wrap.cards) do perRow[c.y] = (perRow[c.y] or 0) + 1 end
				for _, cnt in pairs(perRow) do assert(cnt <= (n <= 6 and 3 or 4), tag .. " row width") end
			end
		end
		if L.fits(w, h) then
			local r = L.rects(w, h)
			assert(r.play.h >= 44 and r.discard.h >= 44, tag .. " buttons are touch targets")
			assert(r.play.y >= r.hand.y + r.hand.h, tag .. " hand clear of Play Hand")
			assert(#L.overlaps(r) == 0, tag .. " no overlaps")
		else
			assert(w < h, tag .. " only portrait falls back to the phone layout")
		end
	end
end })
table.insert(tests, { name = "Sound polish: every cue volume is 0.05 to 0.7, none over 6 dB above the card flip; ambience bed 0.12, ducked 0.06, muted or hidden is silent", fn = function()
	local S = require(script.Parent.Parent.Engine.SoundIds)
	local A = require(script.Parent.Parent.Engine.Ambience)
	local flip = S.Cues.card_flip.volume
	for name, cue in pairs(S.Cues) do
		assert(cue.volume >= 0.05 and cue.volume <= 0.7, name .. " volume " .. tostring(cue.volume))
		assert(cue.volume <= flip * 2 + 1e-9, name .. " is more than 6 dB above the card flip")
	end
	assert(S.Ambience.tavern.volume == A.BASE and A.DUCKED == 0.06)
	assert(A.volume(false, 1, false, true) == 0.12 and A.volume(false, 1, true, true) == 0.06)
	assert(A.volume(true, 1, false, true) == 0 and A.volume(false, 1, false, false) == 0 and A.volume(false, 0, false, true) == 0)
	assert(math.abs(A.volume(false, 0.5, false, true) - 0.06) < 1e-9)
	assert(not A.shouldPlay("", false, true) and A.shouldPlay("rbxassetid://1", false, true) and not A.shouldPlay("rbxassetid://1", true, true) and not A.shouldPlay("rbxassetid://1", false, false))
end })
table.insert(tests, { name = "GuidedHand: only the first normal run, a fixed starter and no drafts, a two step hint that ends after the first hand, no pulse in calm mode", fn = function()
	local G = require(script.Parent.Parent.Engine.GuidedHand)
	assert(G.isGuided(1, false, false, false) and G.isGuided(0, false, false, false), "first run")
	assert(not G.isGuided(2, false, false, false) and not G.isGuided(1, true, false, false) and not G.isGuided(1, false, true, false) and not G.isGuided(1, false, false, true) and not G.isGuided(nil, false, false, false))
	local RunState = require(script.Parent.Parent.Engine.RunState)
	local state = RunState.new and RunState.new() or nil
	if state then
		assert(G.apply(state) and #state.ownedPatrons == 1 and state.ownedPatrons[1].id == G.STARTER and state.startPatronId == G.STARTER)
		assert(not G.apply(state), "the same Patron cannot be seated twice")
	end
	local a, b = G.hint(true, 0, 0, false), G.hint(true, 0, 2, false)
	assert(a.target == "card" and b.target == "play" and a.pulse and a.line1 ~= "" and a.line2 ~= "" and b.line1 ~= a.line1)
	assert(G.hint(true, 1, 0, false) == nil and G.hint(false, 0, 0, false) == nil and G.hint(nil, 0, 0, false) == nil)
	assert(G.hint(true, 0, 0, true).pulse == false and G.hint(true, 0, 1, true).pulse == false)
	for _, h in ipairs({ a, b }) do assert(not (h.line1 .. h.line2):find("[\226\128\148]") and not (h.line1 .. h.line2):find("%-%-")) end
end })
table.insert(tests, { name = "PatronMotion: entrance by tier, rays only for Legendary, calm mode makes no motion, hover keeps the larger pill", fn = function()
	local PM = require(script.Parent.Parent.Engine.PatronMotion)
	assert(PM.entrance("rare", true) == nil, "calm: no entrance tween")
	local e = PM.entrance("legendary", false)
	assert(e and e.rays == true and e.drop < 0 and e.bounce > 0)
	assert(PM.entrance("common", false).rays == false)
	assert(PM.entrance("epic", false).glow[3] == PM.GLOW.epic[3])
	assert(PM.glowOf("nonsense")[1] == PM.GLOW.common[1])
	local h, hc = PM.hover(false), PM.hover(true)
	assert(h.animate and h.lift > 0 and h.pillScale > 1)
	assert(not hc.animate and hc.lift == 0 and hc.pillScale == h.pillScale, "calm: pill is larger but nothing tweens")
	assert(PM.isNew(nil, "a") and PM.isNew("a", "b") and not PM.isNew("a", "a") and not PM.isNew("a", nil))
end })
table.insert(tests, { name = "PatronTips: content, shared tags, placement clear of HUD and hand, no motion in calm mode", fn = function()
	local PT = require(script.Parent.Parent.Engine.PatronTips)
	local CL = require(script.Parent.Parent.Engine.ConceptTLayout)
	local tagged, sharedFound = 0, false
	local ids = {}
	for _, p in ipairs(Patrons.Definitions) do
		ids[#ids + 1] = p.id
		local t = PT.tagsOf(p.id)
		assert(#t <= 2, p.id .. ": at most two tags")
		for _, x in ipairs(t) do assert(x.tag ~= "flat" and x.word ~= "", p.id .. ": no flat tag") end
		if #t > 0 then tagged = tagged + 1 end
	end
	assert(tagged > 40, "most Patrons show a tag")
	assert(PT.sentence("+4 Mult for each Pair. Grows over time.") == "+4 Mult for each Pair.")
	assert(PT.sentence("  One sentence only ") == "One sentence only")
	local c = PT.content(ids[1], "Name", "+4 Mult. More.", "legendary")
	assert(c.rarity == "Legendary" and c.effect == "+4 Mult." and c.name == "Name", "rarity is text, not colour alone")
	assert(PT.content(ids[1], "N", "x", "bogus").rarity == "Common")
	for i = 1, #ids - 4 do
		local seats = { ids[i], ids[i + 1], ids[i + 2], ids[i + 3], ids[i + 4] }
		local s = PT.sharing(seats, 1)
		assert(not s[1], "a card never highlights itself")
		local mine = {}
		for _, t in ipairs(PT.tagsOf(seats[1])) do mine[t.tag] = true end
		for j in pairs(s) do
			sharedFound = true
			local ok = false
			for _, t in ipairs(PT.tagsOf(seats[j])) do if mine[t.tag] then ok = true end end
			assert(ok, "a highlighted seat shares a shown tag")
		end
	end
	assert(sharedFound, "some seats share tags")
	assert(next(PT.sharing({ ids[1] }, 1)) == nil and next(PT.sharing({}, 1)) == nil)
	-- placement: clear of the HUD pills, the banner, the gear and the hand at five sizes, for all five seats
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1024, 768 }, { 844, 390 }, { 800, 450 } }) do
		local w, h = sz[1], sz[2]
		local r = CL.rects(w, h)
		local avoid = { r.coins, r.hands, r.round, r.gear, r.hand }
		local tip = { X = math.min(280, w * 0.3), Y = math.min(110, h * 0.2) }
		for _, card in ipairs(CL.patronRow(w, h, 5).cards) do
			local x, y = PT.place(card, tip, avoid, { X = w, Y = h })
			assert(x >= 0 and y >= 0 and x + tip.X <= w and y + tip.Y <= h, "tooltip inside the screen at " .. w .. "x" .. h)
			if w >= 1024 then
				for name, a in pairs({ coins = r.coins, hands = r.hands, round = r.round, gear = r.gear, hand = r.hand }) do
					assert(not (x < a.x + a.w and x + tip.X > a.x and y < a.y + a.h and y + tip.Y > a.y),
						"tooltip over " .. name .. " at " .. w .. "x" .. h)
				end
			end
		end
	end
	assert(not PT.motion(true).animate and PT.motion(true).fade == 0 and PT.motion(false).animate)
end })
table.insert(tests, { name = "CollectionCards: count pill, locked glyph, page cue and cut card choice for the Collection book", fn = function()
	local CC = require(script.Parent.Parent.Engine.CollectionCards)
