	assert(CC.countPill(12, 81) == "12 / 81" and CC.countPill(99, 81) == "81 / 81" and CC.countPill(-3, 5) == "0 / 5")
	assert(CC.countPill(3.7, 10.2) == "3 / 10" and CC.countPill(nil, nil) == "0 / 0")
