	local tabs = {}
	for _, tab in ipairs(CB.Tabs) do tabs[tab.id] = true end
	assert(tabs.patrons and tabs.housePasses, "glyph tabs exist in the book")
end })
table.insert(tests, { name = "ScorePacing: 180 ms beats, quicker on repeats, a tap skips, the flourish grows past Target, callouts fit their card", fn = function()
	local P = require(script.Parent.Parent.Engine.ScorePacing)
	local PE = require(script.Parent.Parent.Engine.PatronEvents)
	local G = require(script.Parent.Parent.Engine.Gameplay2Score)
	expectEqual(P.gap(1, false, false), 0.18)
	expectEqual(P.gap(nil, false, false), 0.18)
	expectTrue(P.gap(2, false, false) < P.gap(1, false, false), "a repeat is quicker")
	expectTrue(P.gap(3, false, false) < P.gap(2, false, false))
	expectEqual(P.gap(50, false, false), P.FLOOR, "never under the floor")
	expectEqual(P.gap(1, true, false), 0.12, "fast speed caps the gap")
	expectEqual(P.gap(5, true, false), P.FLOOR)
	expectEqual(P.gap(1, false, true), 0, "calm mode: no wait")
	expectEqual(P.skipGap(), 0)
	expectEqual(PE.gap(false, 1), 0.18)
	expectTrue(PE.gap(false, 4) < 0.18)
	-- repeat counting
	expectEqual(P.nextRepeats(nil, 0, "Pair"), 1)
	expectEqual(P.nextRepeats("Pair", 1, "Pair"), 2)
	expectEqual(P.nextRepeats("Pair", 2, "Pair"), 3)
	expectEqual(P.nextRepeats("Pair", 3, "Flush"), 1)
	-- the flourish grows with the overage
	local last = -1
	for _, ratio in ipairs({ 0.5, 1.0, 1.5, 2.0, 3.0, 10.0 }) do
		local f = P.flourish(ratio * 300, 300)
		expectTrue(f.level >= last, "level never drops as the score grows")
		last = f.level
	end
	expectEqual(P.flourish(100, 300).level, 0)
	expectEqual(P.flourish(300, 300).level, 1)
	expectEqual(P.flourish(450, 300).level, 2)
	expectEqual(P.flourish(600, 300).level, 3)
	expectEqual(P.flourish(900, 300).level, 4)
	expectEqual(P.flourish(900, nil).level, 0)
	expectTrue(P.flourish(900, 300).burst > P.flourish(300, 300).burst and P.flourish(900, 300).peak > P.flourish(300, 300).peak)
	-- the centre score uses it; calm mode still shows only the end value
	local plain = G.plan(0, 300, {})
	local big = G.plan(0, 900, { target = 300 })
	expectTrue(big.slam.peak > plain.slam.peak and big.burst > plain.burst and big.hold > plain.hold, "a big overage slams bigger")
	local calm = G.plan(0, 900, { calm = true, target = 300 })
	expectEqual(calm.slam, nil); expectEqual(#calm.steps, 1); expectEqual(calm.final, 900)
	-- a callout ("+4 Mult", "x1.5 Mult" at 22 px, about 11 px a letter) is never wider than its card, so it never reaches a neighbour
	local CL = require(script.Parent.Parent.Engine.ConceptTLayout)
	for _, size in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 800, 450 }, { 844, 390 }, { 1024, 768 } }) do
		local row = CL.patronRow(size[1], size[2], 5)
		for i = 1, 5 do
			expectTrue(#"x1.5 Mult" * 11 <= row.cards[i].w + 1 or row.cards[i].w < 100, "callout fits card " .. i .. " at " .. size[1])
			if i > 1 then expectTrue(row.cards[i].x >= row.cards[i - 1].x + row.cards[i - 1].w, "cards do not overlap at five seats") end
		end
	end
end })

table.insert(tests, { name = "PatronEvents: the Patron beats come in engine order and the full replay equals the final score", fn = function()
	local PE = require(script.Parent.Parent.Engine.PatronEvents)
	local ids = {}
	for _, p in ipairs(Patrons.Definitions) do ids[#ids + 1] = p.id end
	local checked, withEvents = 0, 0
	for start = 1, #ids, 3 do
		local owned = {}
		for k = 0, 5 do
			owned[#owned + 1] = Patrons.getById(ids[((start + k - 1) % #ids) + 1])
		end
		local samples = {
			{ C(9, "Hearts"), C(9, "Clubs"), C(2, "Spades") },
			{ C(14, "Hearts"), C(13, "Hearts"), C(12, "Hearts"), C(11, "Hearts"), C(9, "Hearts") },
			{ C(5, "Hearts"), C(5, "Clubs"), C(5, "Spades"), C(7, "Hearts"), C(7, "Clubs") },
		}
		for _, cards in ipairs(samples) do
			local hand = HandEvaluator.evaluate(cards)
			local score, chips, mult, extra = Scoring.calculate(hand, owned, {})
			local rc, rm, rs = PE.replay(extra.breakdown)
			expectTrue(math.abs(rc - chips) < 1e-6 and math.abs(rm - mult) < 1e-6 and math.abs(rs - score) < 1e-6, "replay equals Scoring (start " .. start .. ")")
			local ev = PE.fromBreakdown(extra.breakdown)
			local last = 0
			for _, e in ipairs(ev) do
				expectTrue(e.index > last, "events keep engine order")
				last = e.index
				expectTrue(e.kind == "chips" or e.kind == "mult" or e.kind == "xmult" or e.kind == "money", "known kind " .. tostring(e.kind))
				expectTrue(#(PE.text(e)) > 0, "event has pill text")
			end
			if #ev > 0 then withEvents = withEvents + 1 end
			checked = checked + 1
		end
	end
	expectTrue(checked > 0 and withEvents > 0, "some sample hands trigger Patrons")
	expectEqual(PE.gap(false), 0.18, "normal gap")
	expectEqual(PE.gap(true), 0.12, "fast gap")
	expectEqual(PE.text({ kind = "xmult", amount = 1.5 }), "x1.5 Mult", "xmult pill")
	expectEqual(PE.text({ kind = "money", amount = 2 }), "+$2", "money pill")
	expectEqual(#PE.tavernNotes({ chipsMultiplier = 0.5, firstHandMultiplier = 0.5 }, true, -20), 3, "boss chips factor, first hand and bargain")
end })

table.insert(tests, { name = "Journey.lua: the Tavern Map (thousands of instances) is built on first open, not at startup", fn = function()
	local f = io and io.open and io.open("src/Client/Journey.lua", "r")
	if not f then return end
	local src = f:read("*a"); f:close()
	local calls, pos = 0, 1
	while true do
		local a, b = src:find("require(script.Parent.JourneyMapView)", pos, true)
		if not a then break end
		calls = calls + 1
		pos = b + 1
	end
	expectEqual(calls, 1, "JourneyMapView is required once")
	expectTrue(src:find("local function buildMapView%(%)") ~= nil, "the build sits inside buildMapView")
	local open = src:match("local function openJourney%(%).-\n\tend\n")
	expectTrue(open ~= nil and open:find("ensureMapView()", 1, true) ~= nil, "openJourney builds the map before showing it")
	expectTrue(src:find("local mapView = require", 1, true) == nil, "no eager mapView build at startup")
end })

table.insert(tests, { name = "PatronRowLayout: 0 to 8 Patrons never overlap the hand, the board, the dock icons or each other's 60 percent", fn = function()
	local PRL = require(script.Parent.Parent.Engine.PatronRowLayout)
	local PTL = require(script.Parent.Parent.Engine.PlayTableLayout)
	expectEqual(PRL.compute(1920, 957, { x = 100, y = 500, w = 800, h = 200 }, 0), nil, "no Patrons, no row")
	local sizes = { { 1920, 957 }, { 1280, 720 }, { 1506, 751 } }
	for _, sz in ipairs(sizes) do
		local w, h = sz[1], sz[2]
		local left = 340
		local p = PTL.placement(w, h, left, 150)
		expectTrue(p ~= nil, "painted placement at " .. w .. "x" .. h)
		for n = 1, 8 do
			local lay = PRL.compute(w, h, p.hand, n)
			expectTrue(lay ~= nil, n .. " Patrons get a row at " .. w .. "x" .. h)
			local r = lay.rect
			expectTrue(r.y >= PRL.TOP_LIMIT, "row below the dock icons (" .. r.y .. ") at " .. w .. "x" .. h)
			expectTrue(r.y + r.h <= p.hand.y + PRL.HAND_TOP_PAD, "row ends above the hand cards at " .. w .. "x" .. h .. " n=" .. n)
			expectTrue(r.x >= left and r.x + r.w <= w, "row stays right of the board and on screen at " .. w .. "x" .. h .. " n=" .. n)
			expectTrue(lay.cardH >= 100 or h < 800, "cards stay readable (" .. lay.cardW .. "x" .. lay.cardH .. ") at " .. w .. "x" .. h)
			for i = 2, n do
				local a, b = lay.cards[i - 1], lay.cards[i]
				expectTrue(b.x >= a.x + math.floor(a.w * PRL.MIN_VISIBLE) - 1, "each card shows 60 percent at n=" .. n)
				expectTrue(b.x > a.x, "cards run left to right")
			end
			if n <= 5 and not lay.overlap then
				expectTrue(lay.cards[2] == nil or lay.cards[2].x - (lay.cards[1].x + lay.cards[1].w) >= PRL.GAP - 1, "side by side keeps the gap")
			end
		end
	end
	-- phone width: a hand frame in a 390 px wide area
	for n = 1, 8 do
		local hand = { x = 8, y = 520, w = 374, h = 176 }
		local lay = PRL.compute(390, 844, hand, n)
		expectTrue(lay ~= nil and lay.rect.x >= 0 and lay.rect.x + lay.rect.w <= 390, "phone row inside the screen, n=" .. n)
		expectTrue(lay.rect.y + lay.rect.h <= hand.y, "phone row above the hand, n=" .. n)
		expectTrue(lay.cardH >= 100 or lay.overlap, "phone cards keep 72x100 or overlap, n=" .. n)
	end
end })

table.insert(tests, { name = "Patron Nook: panel, ledge, rivets and alcoves stay inside the hand span, below the dock and above the hand at three sizes and a phone", fn = function()
	local PRL = require(script.Parent.Parent.Engine.PatronRowLayout)
	local PTL = require(script.Parent.Parent.Engine.PlayTableLayout)
	local function check(w, h, hand, n, left, tag)
		local lay = PRL.compute(w, h, hand, n)
		local nk = PRL.nook(lay, w, hand)
		expectTrue(nk ~= nil, tag .. " nook exists")
		local b = nk.back
		expectTrue(b.y >= PRL.TOP_LIMIT, tag .. " nook below the dock icons")
		expectTrue(b.y + b.h <= hand.y + (hand.h >= 200 and PRL.HAND_TOP_PAD or 0), tag .. " nook above the hand cards")
		expectTrue(b.x >= left and b.x + b.w <= w, tag .. " nook right of the board and on screen")
		expectTrue(b.x <= lay.rect.x and b.x + b.w >= lay.rect.x + lay.rect.w - 1, tag .. " nook holds the row")
		expectTrue(nk.glow.y == b.y and nk.glow.h <= b.h, tag .. " glow sits on the top edge")
		expectTrue(nk.ledge.y + nk.ledge.h == b.y + b.h, tag .. " ledge ends at the panel bottom")
		expectTrue(nk.ledge.y < lay.rect.y + lay.cardH, tag .. " cards overlap the ledge front")
		expectEqual(#nk.rivets, 2, tag .. " two rivets")
		for _, rv in ipairs(nk.rivets) do
			expectTrue(rv.x >= b.x and rv.x + PRL.RIVET <= b.x + b.w and rv.y >= nk.ledge.y and rv.y + PRL.RIVET <= b.y + b.h, tag .. " rivet on the ledge")
		end
		expectEqual(#nk.alcoves, lay.overlap and 0 or n, tag .. " alcoves only when the cards do not overlap")
		for _, a in ipairs(nk.alcoves) do
			expectTrue(a.x >= b.x and a.x + a.w <= b.x + b.w and a.y >= b.y, tag .. " alcove inside the back panel")
		end
	end
	for _, sz in ipairs({ { 1920, 957 }, { 1280, 720 }, { 1506, 751 } }) do
		local p = PTL.placement(sz[1], sz[2], 340, 150)
		for n = 1, 8 do check(sz[1], sz[2], p.hand, n, 340, sz[1] .. "x" .. sz[2] .. " n=" .. n) end
	end
	for n = 1, 8 do check(390, 844, { x = 8, y = 520, w = 374, h = 176 }, n, 0, "phone n=" .. n) end
	expectEqual(PRL.nook(nil, 100, {}), nil, "no row, no nook")
end })

