		for _, hand in ipairs(hands) do
			for n = 1, 8 do
				local t = sz[1] .. "x" .. sz[2] .. " n=" .. n
				local lay = PRL.compute(sz[1], sz[2], hand, n)
				expectTrue(lay ~= nil, t .. " row is not nil")
				expectTrue(lay.rect.x >= hand.x - 1 and lay.rect.x + lay.rect.w <= hand.x + hand.w + 1, t .. " row inside the hand column")
				local handTop = hand.y + (hand.h >= 200 and PRL.HAND_TOP_PAD or 0)
				if handTop - PRL.AIR - PRL.SMALL_TOP >= PRL.FLOOR_H and not lay.overlap then
					expectTrue(lay.cardH >= PRL.FLOOR_H, t .. " card at least 60 px tall")
				end
				expectTrue(lay.plaqueH == 0 or lay.cardW >= PRL.PLAQUE_MIN_W, t .. " plaque only on wide cards")
				expectTrue(lay.rect.h == lay.cardH + lay.plaqueH, t .. " rect matches cards plus plaque")
			end
		end
	end
end })

table.insert(tests, { name = "PatronRowLayout: leftLimit keeps the row 8 units right of the board, cards 60 px or taller, painted strip yields when cards would be tiny", fn = function()
	local PRL = require(script.Parent.Parent.Engine.PatronRowLayout)
	-- live 1004x500 case: sidebar right edge 160, hand column starts left of the board's right edge
	local hand = { x = 100, y = 190, w = 600, h = 150 }
	local opts = { leftLimit = 160 + 8 }
	for n = 1, 8 do
		local lay = PRL.compute(1004, 500, hand, n, opts)
		expectTrue(lay ~= nil, "n=" .. n .. " row exists")
		expectTrue(lay.rect.x >= 168, "n=" .. n .. " row starts at or after the board edge plus 8")
		expectTrue(lay.rect.x + lay.rect.w <= hand.x + hand.w + 1, "n=" .. n .. " row ends inside the hand column")
		expectTrue(lay.cardH >= PRL.FLOOR_H, "n=" .. n .. " card at least 60 tall")
		local nk = PRL.nook(lay, 1004, hand, opts)
		expectTrue(nk.back.x >= 168, "n=" .. n .. " nook back also clear of the board")
		local pl = PRL.painted(1004, 500, hand, n, opts)
		expectTrue(pl == nil or (pl.cardH >= PRL.FLOOR_H and pl.rect.x >= 168), "n=" .. n .. " painted is nil or 60 px cards clear of the board")
	end
	-- no limit: unchanged behaviour
	local a = PRL.compute(1506, 751, { x = 200, y = 400, w = 800, h = 200 }, 4)
	local b = PRL.compute(1506, 751, { x = 200, y = 400, w = 800, h = 200 }, 4, {})
	expectTrue(a.rect.x == b.rect.x and a.cardW == b.cardW, "no leftLimit changes nothing")
end })

table.insert(tests, { name = "PatronRow: measurements are absolute, so the holder cancels any UIScale on the root (scale:WxH) and logs a [PatronRow] line", fn = function()
	if type(io) ~= "table" or not io.open then return end -- Studio has no io library
	local f = io.open("src/Client/PatronRow.lua", "r")
	if not f then return end -- not run from the repo root
	local src = f:read("*a"); f:close()
	expectTrue(src:find("uiScaleOf(rootRef)", 1, true) ~= nil, "reads the root's UIScale")
	expectTrue(src:find("holderScale.Scale = 1 / k", 1, true) ~= nil, "holder cancels the UIScale")
	expectTrue(src:find("holder.Size = UDim2.fromScale(k, k)", 1, true) ~= nil, "holder keeps covering the root")
	expectTrue(src:find("[PatronRow] scaled root", 1, true) ~= nil, "scaled roots log leftLimit and card 1")
end })

table.insert(tests, { name = "PatronRowLayout.painted: strip keeps its aspect, 1 to 5 cards are centred in their arch, 6 to 8 overlap evenly, at three sizes and a phone", fn = function()
	local PRL = require(script.Parent.Parent.Engine.PatronRowLayout)
	local PTL = require(script.Parent.Parent.Engine.PlayTableLayout)
	expectEqual(PRL.painted(1920, 957, { x = 0, y = 500, w = 800, h = 200 }, 0), nil, "no Patrons, no strip")
	local function check(w, h, hand, left, tag)
		for n = 1, 8 do
			local t = tag .. " n=" .. n
			local lay = PRL.painted(w, h, hand, n)
			expectTrue(lay ~= nil, t .. " has a painted row")
			local st = lay.strip
			expectTrue(math.abs(st.w / st.h - PRL.STRIP_W / PRL.STRIP_H) < 0.02, t .. " strip keeps the picture aspect")
			expectTrue(st.y >= PRL.TOP_LIMIT and st.x >= left and st.x + st.w <= w, t .. " strip below the dock, right of the board, on screen")
			expectTrue(st.y + st.h <= hand.y + (hand.h >= 200 and PRL.HAND_TOP_PAD or 0) + PRL.TUCK, t .. " strip tucks under the hand, no further")
			local floorY = st.y + PRL.ARCH_FLOOR * lay.scale
			for i, c in ipairs(lay.cards) do
				expectTrue(c.y >= PRL.TOP_LIMIT and math.abs(c.y + c.h - 4 - floorY) <= 1, t .. " card " .. i .. " stands on the arch floor")
				expectTrue(c.x >= st.x and c.x + c.w <= st.x + st.w, t .. " card " .. i .. " inside the strip")
			end
			if n <= 5 then
				local arches = PRL.ARCH_SEATS[n]
				expectEqual(#arches, n, t .. " one arch per card")
				for i, a in ipairs(arches) do
					local c = lay.cards[i]
					local cx = c.x + c.w / 2
					local ax = st.x + PRL.ARCH_CX[a] * lay.scale
					local half = PRL.ARCH_W[a] * lay.scale / 2
					expectTrue(math.abs(cx - ax) <= 1.5, t .. " card " .. i .. " centred in its arch")
					expectTrue(c.w <= half * 2, t .. " card " .. i .. " fits the arch opening")
				end
			else
				expectTrue(lay.overlap, t .. " overlaps")
				for i = 2, n do
					expectTrue(lay.cards[i].x - lay.cards[i - 1].x >= math.floor(lay.cardW * PRL.MIN_VISIBLE) - 1, t .. " 60 percent visible")
				end
			end
		end
	end
	for _, sz in ipairs({ { 1920, 957 }, { 1280, 720 }, { 1506, 751 } }) do
		local p = PTL.placement(sz[1], sz[2], 340, 150)
		check(sz[1], sz[2], p.hand, 340, sz[1] .. "x" .. sz[2])
	end
	-- a phone is too narrow for readable arches: the painted layout declines and the code nook (compute) is used
	expectEqual(PRL.painted(390, 844, { x = 8, y = 520, w = 374, h = 176 }, 3), nil, "phone keeps the code nook")
	local src = io and io.open and io.open("src/Client/PatronRow.lua", "r")
	if src then
		local code = src:read("*a"); src:close()
		expectTrue(code:find("play_nook_strip_b", 1, true) ~= nil, "PatronRow reads the painted nook id")
		expectTrue(code:find("and not painted", 1, true) ~= nil, "code alcoves hide under the painting")
	end
end })

table.insert(tests, { name = "BossBubbleLayout: the bubble hangs beside the speaker with a tail at it, stays on screen and 12 px clear of the keep-out rects at three sizes", fn = function()
	local BBL = require(script.Parent.Parent.Engine.BossBubbleLayout)
	local SL = require(script.Parent.Parent.Engine.StageLayout)
	local PTL = require(script.Parent.Parent.Engine.PlayTableLayout)
	local size = { w = 250, h = 104 }
	expectEqual(BBL.place(nil, { x = 0, y = 0, w = 10, h = 10 }, size, {}), nil, "no bounds, no bubble")
	for _, sz in ipairs({ { 1920, 957 }, { 1280, 720 }, { 1506, 751 } }) do
		local w, h = sz[1], sz[2]
		local left = 340
		local fr = SL.bossFrame(w, h)
		expectTrue(fr ~= nil, "boss frame at " .. w .. "x" .. h)
		local cx = w / 2
		local anchor = { x = cx - fr.width / 2, y = fr.top, w = fr.width, h = fr.height }
		local p = PTL.placement(w, h, left, 150)
		local keep = { { x = p.hand.x, y = p.hand.y, w = p.hand.w, h = p.hand.h }, { x = w - 300, y = 0, w = 300, h = 92 } }
		local bounds = { x = left, y = 0, w = w - left, h = h }
		local spot = BBL.place(bounds, anchor, size, keep)
		expectTrue(spot ~= nil, "a spot exists at " .. w .. "x" .. h)
		local r = spot.rect
		expectTrue(r.x >= bounds.x + 8 and r.y >= 8 and r.x + r.w <= w - 8 and r.y + r.h <= h - 8, "on screen at " .. w .. "x" .. h)
		for _, k in ipairs(keep) do
			expectTrue(r.x >= k.x + k.w + 12 or k.x >= r.x + r.w + 12 or r.y >= k.y + k.h + 12 or k.y >= r.y + r.h + 12, "12 px clear of a keep-out rect at " .. w .. "x" .. h)
		end
		expectTrue(r.x >= anchor.x + anchor.w or r.x + r.w <= anchor.x or r.y >= anchor.y + anchor.h or r.y + r.h <= anchor.y, "never covers the speaker")
		-- the tail sits on the bubble's edge that faces the speaker
		local t = spot.tail
		if spot.side == "right" then expectTrue(t.x == r.x and t.y >= r.y and t.y <= r.y + r.h, "tail on the left edge")
		elseif spot.side == "left" then expectTrue(t.x == r.x + r.w, "tail on the right edge")
		elseif spot.side == "below" then expectTrue(t.y == r.y, "tail on the top edge")
		else expectTrue(t.y == r.y + r.h, "tail on the bottom edge") end
	end
	-- nothing fits: the line is skipped, not drawn over something
	local boxed = { { x = 0, y = 0, w = 400, h = 400 } }
	expectEqual(BBL.place({ x = 0, y = 0, w = 400, h = 400 }, { x = 150, y = 150, w = 100, h = 100 }, size, boxed), nil, "no room, no bubble")
end })

table.insert(tests, { name = "BossHomeLayout: the boss medallion and name plate stand in the top strip, clear of the nook, hand, dock and left board at three sizes and a phone", fn = function()
	local BHL = require(script.Parent.Parent.Engine.BossHomeLayout)
	local PRL = require(script.Parent.Parent.Engine.PatronRowLayout)
	local PTL = require(script.Parent.Parent.Engine.PlayTableLayout)
	expectEqual(BHL.place(0, 0, 0), nil, "no screen, no home")
	expectEqual(BHL.place(300, 600, 200), nil, "a strip too narrow for a plate gives no home")
	expectTrue(BHL.BOTTOM_LIMIT < PRL.TOP_LIMIT, "the home ends above the Patron Nook")
	local function apart(a, b, tag)
		expectTrue(a.x >= b.x + b.w or b.x >= a.x + a.w or a.y >= b.y + b.h or b.y >= a.y + a.h, tag)
	end
	local function check(w, h, left, tag)
		local home = BHL.place(w, h, left)
		expectTrue(home ~= nil, tag .. " has a home")
		local m, p = home.medallion, home.plate
		expectTrue(m.w >= 56 and m.w == m.h, tag .. " medallion is a readable circle")
		expectTrue(p.w >= 96 and p.h >= 40, tag .. " plate is readable")
		apart(m, p, tag .. " medallion and plate do not overlap")
		for _, r in ipairs({ m, p }) do
			expectTrue(r.y >= 0 and r.y + r.h <= BHL.BOTTOM_LIMIT, tag .. " inside the top strip")
			expectTrue(r.x >= left + BHL.EDGE, tag .. " clear of the left board")
			expectTrue(r.x + r.w <= w - math.min(300, math.floor(w * 0.35)) - BHL.EDGE, tag .. " clear of the corner dock")
		end
		return home
	end
	for _, sz in ipairs({ { 1920, 957 }, { 1280, 720 }, { 1506, 751 } }) do
		local w, h = sz[1], sz[2]
		local tag = w .. "x" .. h
		local home = check(w, h, 340, tag)
		local p = PTL.placement(w, h, 340, 150)
		local nook = PRL.painted(w, h, p.hand, 5)
		for _, r in ipairs({ home.medallion, home.plate }) do
			apart(r, nook.strip, tag .. " clear of the painted nook")
			apart(r, p.hand, tag .. " clear of the hand")
		end
	end
	check(390, 844, 0, "phone 390x844")
	check(800, 450, 240, "800x450")
	-- the plate source: no name plate is drawn on the nook any more
	local f = io and io.open and io.open("src/Client/BossFight.lua", "r")
	if f then
		local code = f:read("*a"); f:close()
		expectTrue(code:find("BossNamePlate", 1, true) == nil, "no boss name plate hangs on the Patron Nook")
		expectTrue(code:find("BossHomeLayout", 1, true) ~= nil, "BossFight places the boss from BossHomeLayout")
	end
end })

table.insert(tests, { name = "Left board text never cuts: every blessing and curse line fits 3 wrapped lines in the narrowest board text box, boxes end inside the clip edge, no truncation on wrapped board labels", fn = function()
	local Rows = require(script.Parent.Parent.Engine.BoardPanelRows)
	local RM = require(script.Parent.Parent.Engine.RunModifiers)
	-- narrowest plausible row: a 1280x720 board is about 300 px wide, row = target column (about 200) minus padding and the icon
	for _, rowW in ipairs({ 190, 230, 300 }) do
		local textW = math.max(40, rowW - 52)
		for _, d in ipairs(RM.Definitions) do
			for _, t in ipairs({ "+ " .. d.blessing, "- " .. d.curse }) do
				local per = math.floor(textW / 8)
				local need = 1
				local used = 0
				for word in t:gmatch("%S+") do
					if used == 0 then used = #word elseif used + 1 + #word <= per then used = used + 1 + #word else need = need + 1 used = #word end
				end
				expectTrue(need <= Rows.MAX_LINES, d.id .. " '" .. t .. "' needs " .. need .. " lines at row width " .. rowW)
			end
		end
	end
	expectTrue(Rows.CLIP_PAD >= 12, "text boxes end 12 px inside the board edge")
	local function read(path) local f = io and io.open and io.open(path, "r"); if not f then return nil end local x = f:read("*a"); f:close(); return x end
	local chip, hud = read("src/Client/BlessingChip.lua"), read("src/Client/PlayBoardHud.lua")
	if chip and hud then
		expectTrue(chip:find("Rows.CLIP_PAD", 1, true) ~= nil, "BlessingChip caps its text box at the board's clip edge")
		expectTrue(hud:find("BoardPanelRows.CLIP_PAD", 1, true) ~= nil, "the panel plan ends inside the board edge")
		local relayout = chip:match("function BlessingChip.relayout%(%).-\nend") or ""
		expectTrue(relayout:find("TextTruncate = Enum.TextTruncate.None", 1, true) ~= nil and relayout:find("TextWrapped = true", 1, true) ~= nil, "wrapped board effect labels never truncate")
	end
end })

