table.insert(tests, { name = "ConceptTLayout parity: Patron cards, labels and pills stay on screen and clear of the hand, preview pill and sort frame clear of buttons, at five sizes", fn = function()
	local L = require(script.Parent.Parent.Engine.ConceptTLayout)
	local function hit(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 800, 450 }, { 844, 390 }, { 1024, 768 } }) do
		local w, h = sz[1], sz[2]
		local tag = w .. "x" .. h
		local r = L.rects(w, h)
		for _, n in ipairs({ 3, 5, 8 }) do
			local row = L.patronRow(w, h, n)
			assert(#row.cards == n and #row.labels == n and #row.pills == n, tag .. " counts")
			for i = 1, n do
				for _, group in ipairs({ row.cards, row.labels, row.pills }) do
					local b = group[i]
					assert(b.x >= 0 and b.x + b.w <= w and b.y >= 0 and b.y + b.h <= h, tag .. " on screen " .. i)
					assert(not hit(b, r.hand), tag .. " clear of the hand " .. i)
					assert(not hit(b, r.round) and not hit(b, r.gear), tag .. " clear of the HUD " .. i)
				end
				if i > 1 and n <= 5 then assert(row.cards[i].x >= row.cards[i - 1].x + row.cards[i - 1].w - 1, tag .. " cards in order without overlap") end
			end
		end
		local row = L.patronRow(w, h, 5)
		assert(row.cards[1].w / row.cards[1].h <= L.CARD_ASPECT + 0.02, tag .. " card keeps its shape")
		local pv = L.previewRect(w, h)
		assert(pv.h >= 20 and not hit(pv, r.hand) and not hit(pv, r.round), tag .. " preview pill")
		for i = 1, 5 do assert(not hit(pv, row.pills[i]), tag .. " preview clear of the Patron pills " .. i) end
		local box = L.sortSize(w, h)
		local s = L.sortSpot(w, h, box.w, box.h, r)
		assert(s.x >= 0 and s.x + s.w <= r.play.x and s.y >= 0 and s.y + s.h <= h, tag .. " sort frame left of Play Hand")
		assert(not hit(s, r.hand), tag .. " sort frame clear of the hand")
		assert(not hit(s, r.play) and not hit(s, r.discard), tag .. " sort frame clear of both buttons")
		assert(box.w == 120 and box.h >= 34 and ((w >= 1000 and h >= 600) or box.h >= 44), tag .. " sort pill size, 44 px tall on compact")
		assert(math.abs((s.y + s.h / 2) - (r.play.y + r.play.h / 2)) <= 1, tag .. " sort pill shares the Play Hand centre line")
		local h7, h8 = L.handFor(r.hand, w, 7), L.handFor(r.hand, w, 8)
		assert(h7.x == r.hand.x and h8.x < r.hand.x and h8.x + h8.w < 0.80 * w, tag .. " eight cards shift left, seven keep the reference")
	end
end })

table.insert(tests, { name = "TavernLife: fire 0.9 to 1.0 over 3 s, cat 1.5 percent over 4 s, 12 motes rise in 8 s, juice values, nothing in calm mode", fn = function()
	local L = require(script.Parent.Parent.Engine.TavernLife)
	local R = require(script.Parent.Parent.Engine.RoomLights)
	for i = 0, 120 do
		local t = i * 0.05
		local f, c = L.firePulse(t, false), L.catScale(t, false)
		expectTrue(f >= 0.9 - 1e-9 and f <= 1.0 + 1e-9, "fire pulse in range")
		expectTrue(c >= 1 - 1e-9 and c <= 1.015 + 1e-9, "cat breath in range")
	end
	expectTrue(math.abs(L.firePulse(0.4, false) - L.firePulse(3.4, false)) < 1e-9, "fire period is 3 s")
	expectTrue(math.abs(L.catScale(0.7, false) - L.catScale(4.7, false)) < 1e-9, "cat period is 4 s")
	expectEqual(L.firePulse(1, true), 1)
	expectEqual(L.catScale(1, true), 1)
	expectEqual(R.moteCount("concept_t"), 12)
	local shaft = R.ROOMS.concept_t.shaft
	local a, b = R.mote(1, 12, 0, shaft), R.mote(1, 12, 8, shaft)
	expectTrue(math.abs(a.y - b.y) < 1e-9, "a mote returns to its place after 8 s")
	expectEqual(L.coinBurst(5, 5, false), nil)
	expectEqual(L.coinBurst(5, 9, true), nil)
	local cb = L.coinBurst(5, 15, false)
	expectTrue(cb and cb.count >= 4 and cb.count <= 12 and cb.dur > 0, "coin burst on a rise")
	local wf = L.warmFlash(300, 600, false)
	expectTrue(wf and wf.alpha == 0.08 and wf.dur == 0.2, "warm flash 0.08 for 0.2 s")
	expectEqual(L.warmFlash(10, 600, false), nil)
	expectEqual(L.warmFlash(300, 600, true), nil)
	expectEqual(L.patronHop(false), 8)
	expectEqual(L.patronHop(true), nil)
	expectTrue(L.CAT.x + L.CAT.w <= 1536 and L.CAT.y + L.CAT.h <= 1024, "cat crop inside the picture")
end })

-- ===== Patron rarity glow and shine =====
table.insert(tests, { name = "PatronShine: Rare, Epic and Legendary glow in their rarity colour between 0.15 and 0.35 alpha over 3 s, Common and Uncommon do not", fn = function()
	local S = require(script.Parent.Parent.Engine.PatronShine)
	local M = require(script.Parent.Parent.Engine.PatronMotion)
	for _, tier in ipairs({ "common", "uncommon" }) do
		expectEqual(S.glow(tier, false), nil, tier .. " has no glow")
	end
	for _, tier in ipairs({ "rare", "epic", "legendary" }) do
		local g = S.glow(tier, false)
		expectTrue(g ~= nil, tier .. " glows")
		expectEqual(g.period, 3)
		expectEqual(g.alphaMin, 0.15)
		expectEqual(g.alphaMax, 0.35)
		expectTrue(math.abs(g.transMin - 0.65) < 1e-9 and math.abs(g.transMax - 0.85) < 1e-9, "transparency is 1 minus alpha")
		expectEqual(g.rgb[1], M.glowOf(tier)[1], tier .. " uses the entrance glow colour")
	end
	expectTrue(S.glow("RARE", false) ~= nil, "tier names are case blind")
	expectEqual(S.glow(nil, false), nil)
	local blue, purple, gold = S.glow("rare", false).rgb, S.glow("epic", false).rgb, S.glow("legendary", false).rgb
	expectTrue(blue[3] > blue[1], "Rare is blue")
	expectTrue(purple[1] > purple[2] and purple[3] > purple[2], "Epic is purple")
	expectTrue(gold[1] > gold[3] and gold[2] > gold[3], "Legendary is gold")
end })

table.insert(tests, { name = "PatronShine: the diagonal shine is Legendary only, every 6 s, and offsets differ by seat", fn = function()
	local S = require(script.Parent.Parent.Engine.PatronShine)
	for _, tier in ipairs({ "common", "uncommon", "rare", "epic" }) do
		expectEqual(S.shine(tier, false), nil, tier .. " has no shine")
	end
	local s = S.shine("legendary", false)
	expectEqual(s.period, 6)
	expectTrue(s.dur < s.period and s.dur > 0, "sweep is shorter than the gap")
	expectTrue(s.fromX < 0 and s.toX > 1, "the band starts and ends outside the card")
	expectTrue(s.angle ~= 0, "diagonal")
	expectTrue(S.shineOffset(1) ~= S.shineOffset(2), "seats start at different times")
end })

