-- ===== Full run smoke test =====
-- Plays whole runs through the same engine calls the server makes (new, play, Counter, advance, continue) with a
-- scripted bot, and mirrors the server's profile sync, then checks the run state and the save stay valid.
do
	local function smokeWhole(n)
		return type(n) == "number" and n == n and n ~= math.huge and n ~= -math.huge and n == math.floor(n)
	end

	-- every number in the save is finite, no function or userdata sneaks in (what a DataStore write needs)
	local function scanSave(value, path, depth)
		local kind = type(value)
		if kind == "number" then
			expectTrue(value == value and value ~= math.huge and value ~= -math.huge, "save number finite at " .. path)
		elseif kind == "table" then
			expectTrue(depth < 12, "save nests too deep at " .. path)
			for k, v in pairs(value) do
				expectTrue(type(k) == "string" or type(k) == "number", "save key type at " .. path)
				scanSave(v, path .. "." .. tostring(k), depth + 1)
			end
		else
			expectTrue(kind == "string" or kind == "boolean", "save value type " .. kind .. " at " .. path)
		end
	end

	local function smokeCheck(state, label)
		expectTrue(smokeWhole(state.tips) and state.tips >= 0, label .. ": tips whole and not negative, got " .. tostring(state.tips))
		expectTrue(smokeWhole(state.handsRemaining) and state.handsRemaining >= 0, label .. ": hands")
		expectTrue(smokeWhole(state.discardsRemaining) and state.discardsRemaining >= 0, label .. ": discards")
		expectTrue(type(state.roundScore) == "number" and state.roundScore == state.roundScore and state.roundScore >= 0, label .. ": roundScore")
		expectTrue(type(state.targetScore) == "number" and state.targetScore >= 0, label .. ": targetScore")
		local seen, total = {}, 0
		for _, pileName in ipairs({ "deck", "hand", "discardPile" }) do
			for _, card in ipairs(state[pileName]) do
				expectFalse(seen[card], label .. ": a card sits in two piles")
				seen[card] = true
				total = total + 1
			end
		end
		expectTrue(total >= 40, label .. ": the deck kept its cards, got " .. total)
	end

	-- the bot plays the biggest legal group it can (5 down to 1 cards); a boss that wants an exact count is tried in turn
	local function smokePlay(state)
		for count = math.min(5, #state.hand), 1, -1 do
			local pick = {}
			for i = 1, count do
				pick[i] = i
			end
			local ok, result = pcall(RunState.playHand, state, pick)
			if ok then
				return result
			end
		end
		local ok = pcall(RunState.discard, state, { 1 })
		expectTrue(ok or state.runOver, "the bot could neither play nor discard")
		return nil
	end

	-- plays one run. mode "win" lowers every target so all rounds clear, "lose" makes round 1 unwinnable.
	-- Returns the report the checks read.
	local function smokeRun(seed, mode)
		math.randomseed(seed)
		local rng = SeededRng.new(seed)
		local profile = PlayerProfile.new()
		local state = RunState.new({ stakeId = 1, deckVariantId = "standard" }, rng)
		PlayerProfile.recordRunStarted(profile)
		state.strangerSeed = seed * 31 + 7
		smokeCheck(state, "new")
		local report = { rounds = 0, shopVisits = 0, bought = 0, tipsBefore = state.tips, maxNight = 1, handsPlayed = 0, wonSeen = false }
		local steps, lowered = 0, false
		while not state.runOver and steps < 4000 do
			steps = steps + 1
			if not state.roundOver then
				if not lowered then
					lowered = true
					if mode == "win" then
						state.targetScore = 1
					else
						state.targetScore = 1e12
					end
				end
				local handsBefore = state.handsRemaining
				local result = smokePlay(state)
				if result and state.handsRemaining < handsBefore then
					report.handsPlayed = report.handsPlayed + 1
				end
				smokeCheck(state, "play")
			else
				report.rounds = report.rounds + 1
				lowered = false
				PlayerProfile.recordNightReached(profile, state.night)
				report.maxNight = math.max(report.maxNight, state.night)
				if state.wonRun and not report.wonSeen then
					report.wonSeen = true
					PlayerProfile.recordRunWon(profile)
					break
				end
				-- the Counter: roll offers, buy the first Patron the player can pay for, then leave
				local offers = Shop.rollOffers(state)
				report.shopVisits = report.shopVisits + 1
				expectTrue(type(offers) == "table" and type(offers.patrons) == "table", "Counter offers a Patron list")
				local tipsBefore = state.tips
				for _, offer in ipairs(offers.patrons) do
					if #state.ownedPatrons < RunState.patronSlotLimit(state) and state.tips >= RunState.patronPrice(state, offer) then
						local owned = #state.ownedPatrons
						local ok, bought = pcall(RunState.buyPatron, state, offer.id)
						if ok and bought then
							report.bought = report.bought + 1
							expectEqual(#state.ownedPatrons, owned + 1, "a bought Patron is seated")
							expectTrue(state.tips < tipsBefore, "buying a Patron costs Tips")
							break
						end
					end
				end
				smokeCheck(state, "shop")
				RunState.advanceToNextRound(state)
				smokeCheck(state, "advance")
			end
		end
		report.state, report.profile, report.steps = state, profile, steps
		return report
	end

	table.insert(tests, { name = "Smoke run: a full winning run goes from round 1 to the final Night, buys at the Counter and keeps a valid save", fn = function()
		local report = smokeRun(11, "win")
		local state = report.state
		expectTrue(report.steps < 4000, "the run ended on its own")
		expectTrue(state.wonRun, "the run is won")
		expectEqual(report.maxNight, state.config.nightCap, "reached the last Night")
		expectTrue(report.rounds >= state.config.nightCap * state.config.roundsPerNight - 1, "cleared every round, got " .. report.rounds)
		expectTrue(report.shopVisits >= 3, "the Counter opened between rounds")
		expectTrue(report.handsPlayed >= report.rounds, "every round took at least one played hand")
		local profile = report.profile
		expectEqual(profile.stats.runsStarted, 1)
		expectEqual(profile.stats.runsWon, 1)
		expectEqual(profile.stats.bestNightReached, state.config.nightCap)
		scanSave(profile, "profile", 0)
		-- the save loads back the way a new session reads it, and nothing is lost
		local again = PlayerProfile.migrate(profile)
		expectEqual(again.stats.runsWon, 1, "runsWon survives a save and load")
		expectEqual(again.stats.bestNightReached, state.config.nightCap, "best Night survives a save and load")
		scanSave(again, "migrated", 0)
	end })

	table.insert(tests, { name = "Smoke run: round 1 can be lost, the run ends cleanly and the save stays valid", fn = function()
		local report = smokeRun(12, "lose")
		local state = report.state
		expectTrue(state.runOver, "the run is over")
		expectFalse(state.wonRun, "a lost run is not won")
		expectEqual(state.night, 1)
		expectEqual(state.handsRemaining, 0, "every hand was used before the loss")
		expectTrue(report.handsPlayed >= 1, "hands were played")
		expectEqual(report.rounds, 0, "no round was cleared")
		local profile = report.profile
		expectEqual(profile.stats.runsStarted, 1)
		expectEqual(profile.stats.runsWon, 0)
		scanSave(profile, "profile", 0)
		scanSave(PlayerProfile.migrate(profile), "migrated", 0)
	end })

	table.insert(tests, { name = "Smoke run: after losing round 3, One More Round puts the run back at the start of that round with all its hands", fn = function()
		math.randomseed(13)
		local rng = SeededRng.new(13)
		local state = RunState.new({ stakeId = 1, deckVariantId = "standard" }, rng)
		-- clear rounds 1 and 2 the quick way
		for _ = 1, 2 do
			state.targetScore = 1
			expectTrue(smokePlay(state) ~= nil, "a hand played")
			expectTrue(state.roundOver, "round cleared")
			Shop.rollOffers(state)
			RunState.advanceToNextRound(state)
			smokeCheck(state, "advance")
		end
		expectEqual(state.round, 3)
		local hands, discards = state.handsRemaining, state.discardsRemaining
		state.targetScore = 1e12
		local guard = 0
		while not state.runOver and guard < 50 do
			guard = guard + 1
			smokePlay(state)
		end
		expectTrue(state.runOver, "round 3 was lost")
		expectTrue(RunState.canContinue(state), "One More Round is on offer")
		RunState.useContinue(state)
		expectFalse(state.runOver, "the run is alive again")
		expectEqual(state.round, 3, "back in round 3")
		expectEqual(state.handsRemaining, hands, "hands restored")
		expectEqual(state.discardsRemaining, discards, "discards restored")
		expectFalse(RunState.canContinue(state), "only one continue per run")
		smokeCheck(state, "continue")
		-- and the revived round can still be won
		state.targetScore = 1
		expectTrue(smokePlay(state) ~= nil, "a hand played after the continue")
		expectTrue(state.roundOver and not state.runOver, "the revived round is cleared")
	end })

	-- A bot that walks the screens in the server's order (roundSelect, playing, shop, gameover), mirrors the server's phase
	-- changes and checks state at every step: Target, Tips, Patron seats, the Boss Round, Night cleared, Run Over, Try Again.
	table.insert(tests, { name = "Smoke bot: Run Setup, Night 1 table, Counter buy and sell, Boss Round, Night cleared, Run Over and Try Again", fn = function()
		local Gameplay2Moments = require(script.Parent.Parent.Engine.Gameplay2Moments)
		local seed = 21
		math.randomseed(seed)
		local rng = SeededRng.new(seed)
		-- Run Setup: stake and deck variant picked, then the run is built
		local state = RunState.new({ stakeId = 1, deckVariantId = "standard" }, rng)
		local phase = "roundSelect"
		expectEqual(state.night, 1, "setup starts on Night 1")
		expectEqual(state.round, 1, "setup starts on round 1")
		expectEqual(#state.ownedPatrons, 0, "no Patrons before the Counter")
		expectFalse(state.runOver, "a new run is alive")
		expectTrue(RunState.patronSlotLimit(state) >= 1, "there is at least one Patron seat")
		smokeCheck(state, "setup")

		local function enterRound(label)
			phase = "playing"
			expectEqual(state.targetScore, RunState.targetForRound(state, state.round), label .. ": Target is the one Round Select showed")
			expectTrue(state.targetScore > 0, label .. ": Target above zero")
			expectEqual(state.handsRemaining, state.config.handsPerRound, label .. ": full hands")
			expectFalse(state.roundOver, label .. ": round open")
			expectTrue(RunState.phaseAllowsCardActions(phase) and not RunState.phaseAllowsShopActions(phase), label .. ": card actions only")
			smokeCheck(state, label)
		end

		-- Night 1 table: round 1 at its real Target, the bot clears it by lowering the Target after the Target check
		enterRound("n1r1")
		local night1Targets = { state.targetScore }
		local bossSeen = false
		local clearedRounds = 0
		local soldOnce, boughtOnce = false, false
		local guard = 0
		while state.night == 1 and not state.runOver and guard < 20 do
			guard = guard + 1
			local wasBoss = RunState.isBossRound(state)
			state.targetScore = 1 -- the Target check above used the real one; the bot now makes the round easy to clear
			local prev = { phase = "playing", roundScore = 0, tips = state.tips, targetScore = state.targetScore, bossModifier = state.bossModifier,
				round = state.round, night = state.night, nightCap = state.config.nightCap }
			expectTrue(smokePlay(state) ~= nil, "a hand played in round " .. state.round)
			expectTrue(state.roundOver and not state.runOver, "round " .. state.round .. " cleared")
			clearedRounds = clearedRounds + 1
			phase = "shop"
			expectTrue(RunState.phaseAllowsShopActions(phase) and not RunState.phaseAllowsCardActions(phase), "shop actions only at the Counter")
			expectTrue(state.lastRoundReward >= 0, "the round paid a whole, non negative reward")
			expectTrue(smokeWhole(state.lastRoundReward), "reward is whole")
			local now = { phase = phase, roundScore = state.roundScore, tips = state.tips }
			local lines = Gameplay2Moments.clearLines(prev, now)
			expectTrue(lines ~= nil, "a cleared round gives a banner")
			if wasBoss and state.round == state.config.roundsPerNight then
				bossSeen = true
				expectTrue(lines.night ~= nil, "clearing the Boss Round is a Night cleared moment")
				expectEqual(lines.night.title, "Night cleared", "Night 1 is not the run's end")
				expectEqual(lines.night.button, "Continue")
			else
				expectTrue(lines.night == nil, "an ordinary round is not a Night cleared moment")
			end
			smokeCheck(state, "cleared")

			-- the Counter: buy one Patron, sell it back for half, buy again
			local offers = Shop.rollOffers(state)
			expectTrue(type(offers) == "table" and type(offers.patrons) == "table", "Counter offers")
			if not soldOnce then
				for _, offer in ipairs(offers.patrons) do
					local price = RunState.patronPrice(state, offer)
					if state.tips >= price and #state.ownedPatrons < RunState.patronSlotLimit(state) then
						local tips, seats = state.tips, #state.ownedPatrons
						local ok = RunState.buyPatron(state, offer.id)
						expectTrue(ok, "buy " .. offer.id)
						boughtOnce = true
						expectEqual(state.tips, tips - price, "buying takes the price")
						expectEqual(#state.ownedPatrons, seats + 1, "a seat is taken")
						local sold, refund = RunState.sellPatron(state, offer.id)
						expectTrue(sold, "sell " .. offer.id)
						expectEqual(state.tips, tips - price + refund, "selling pays the refund")
						expectEqual(#state.ownedPatrons, seats, "the seat is free again")
						expectFalse(RunState.sellPatron(state, offer.id), "a sold Patron cannot be sold twice")
						soldOnce = true
						break
					end
				end
			end
			smokeCheck(state, "counter")
			RunState.advanceToNextRound(state)
			phase = "playing"
			if state.night == 1 then
				expectTrue(state.round == clearedRounds + 1, "the round counter moved on by one")
				night1Targets[#night1Targets + 1] = RunState.targetForRound(state, state.round)
				enterRound("n1r" .. state.round)
			end
		end
		expectTrue(bossSeen, "Night 1 ended with its Boss Round")
		expectEqual(clearedRounds, state.config.roundsPerNight, "every round of Night 1 was cleared")
		expectTrue(night1Targets[3] > night1Targets[1], "the Boss Round Target is above round 1")
		expectEqual(state.night, 2, "Night 2 follows the Boss Round")
		expectEqual(state.round, 1, "Night 2 starts at round 1")
		expectTrue(boughtOnce and soldOnce, "the bot bought and sold at the Counter")
		smokeCheck(state, "night2")

		-- lose Night 2 round 1: Run Over
		state.targetScore = 1e12
		local loops = 0
		while not state.runOver and loops < 30 do
			loops = loops + 1
			smokePlay(state)
		end
		expectTrue(state.runOver, "the run ends")
		phase = "gameover"
		expectFalse(RunState.phaseAllowsCardActions(phase) or RunState.phaseAllowsShopActions(phase), "no actions on Run Over")
		expectEqual(state.night, 2, "Run Over keeps the Night it ended on")
		expectTrue(Gameplay2Moments.clearLines({ phase = "playing", roundScore = 0, tips = 0, targetScore = 1e12 },
			{ phase = "gameover", roundScore = state.roundScore, tips = state.tips }) == nil, "no clear banner on a loss")
		smokeCheck(state, "gameover")

		-- Try Again: a fresh run from setup, nothing carried over
		local again = RunState.new({ stakeId = 1, deckVariantId = "standard" }, SeededRng.new(seed + 1))
		expectFalse(again.runOver, "the new run is alive")
		expectEqual(again.night, 1)
		expectEqual(again.round, 1)
		expectEqual(#again.ownedPatrons, 0, "no Patrons carried over")
		expectEqual(again.targetScore, RunState.targetForRound(again, 1), "Target back at round 1")
		expectEqual(again.targetScore, night1Targets[1], "same opening Target as the first run")
		smokeCheck(again, "tryagain")
	end })
end

table.insert(tests, { name = "AbilityText: every Patron, Recipe, House Pass and Pack text is short, whole and splits into condition and effect", fn = function()
	local AT = require(script.Parent.Parent.Engine.AbilityText)
	local Recipes = require(script.Parent.Parent.Engine.Recipes)
	local HousePasses = require(script.Parent.Parent.Engine.HousePasses)
	local Packs = require(script.Parent.Parent.Engine.Packs)
	local Patrons = require(script.Parent.Parent.Engine.Patrons)
	-- the split
	local s = AT.split("+15 Chips if the hand contains a Pair.")
	expectEqual(s.effect, "+15 Chips")
	expectEqual(s.trigger, "If the hand contains a Pair")
	local always = AT.split("+4 Mult on every hand.")
	expectEqual(always.trigger, nil, "no condition, no trigger line")
	expectEqual(always.effect, "+4 Mult on every hand")
	expectEqual(AT.split("Earn 1 Tip for each Patron at your table.").trigger, "For each Patron at your table")
	expectEqual(AT.split("").effect, "")
	expectEqual(#AT.card("+4 Mult on every hand."), 1)
	expectEqual(table.concat(AT.card("Adds a Sweet Garnish (+30 Chips) to 1 card (not played)."), " "), "Adds a Sweet Garnish (+30 Chips) to 1 card")
	expectEqual(AT.card("A very long description that cannot fit", "Short one")[1], "Short one", "a short form wins")
	expectEqual(AT.tooltip("+15 Chips if the hand contains a Pair.", "AAAAAA"), '<font color="#AAAAAA">+15</font> Chips\nIf the hand contains a Pair', "effect line, then the condition on its own line, numbers gold")
	-- numbers go gold, the words stay plain, and the markup strips back to the same text
	local rich = AT.gold("+15 Chips, x1.5 Mult, 50% off, 3 Tips")
	expectEqual(AT.plain(rich), "+15 Chips, x1.5 Mult, 50% off, 3 Tips")
	expectTrue(rich:find('<font color="#F6C446">+15</font>', 1, true) ~= nil, "plus number is gold")
	expectTrue(rich:find('<font color="#F6C446">x1.5</font>', 1, true) ~= nil, "times number is gold")
	expectTrue(rich:find('<font color="#F6C446">50%</font>', 1, true) ~= nil, "percent is gold")
	expectEqual(AT.plain(AT.gold("Pairs and Flushes")), "Pairs and Flushes", "no numbers, nothing wrapped")
	-- the registries
	local lists = {
		{ "Patron", Patrons.Definitions },
		{ "House Recipe", Recipes.HouseRecipes },
		{ "Menu Recipe", Recipes.MenuRecipes },
		{ "Secret Recipe", Recipes.SecretRecipes },
		{ "House Pass", HousePasses.Definitions },
		{ "Pack", Packs.Definitions },
	}
	local seen, bad = 0, {}
	for _, entry in ipairs(lists) do
		for _, def in ipairs(entry[2]) do
			if def.description then
				seen = seen + 1
				local problems = AT.check(def.description, def.short)
				if #problems > 0 then
					bad[#bad + 1] = entry[1] .. " " .. tostring(def.id) .. ": " .. table.concat(problems, "; ") .. " -- " .. def.description
				end
			end
		end
	end
	expectEqual(#bad, 0, "\n" .. table.concat(bad, "\n"))
	expectTrue(seen >= 150, "the registries were read, saw " .. seen)
end })

table.insert(tests, { name = "Celebration: coins count up in at most 12 steps, banner 0.4 s, Patron hops in order, 40 suit confetti in 2.5 s, title overshoot, gentle defeat, nothing in calm mode", fn = function()
	local C = require(script.Parent.Parent.Engine.Celebration)
	local s = C.countSteps(7, false)
	assert(#s.values == 7 and s.values[1] == 1 and s.values[7] == 7)
	local b = C.countSteps(100, false)
	assert(#b.values == 12 and b.values[12] == 100 and b.values[1] <= b.values[2])
	assert(C.countSteps(0, false) == nil and C.countSteps(5, true) == nil)
	assert(C.bannerSlide(false).dur == 0.4 and C.bannerSlide(true) == nil)
	assert(C.patronHopDelay(1, false) == 0 and C.patronHopDelay(3, false) > C.patronHopDelay(2, false) and C.patronHopDelay(2, true) == nil)
	local f = C.confetti(123, false)
	assert(#f.pieces == 40 and f.dur == 2.5 and C.confetti(1, true) == nil)
	local gold, red = 0, 0
	for _, p in ipairs(f.pieces) do
		assert(p.delay + p.fall <= f.dur and p.x > 0 and p.x < 1 and p.size >= 18)
		if p.color == C.GOLD then gold = gold + 1 elseif p.color == C.RED then red = red + 1 end
	end
	assert(gold == 20 and red == 20)
	local t = C.titleIn(false)
	assert(t.peak > 1 and t.from < 1 and C.titleIn(true) == nil)
	local d = C.defeat(false)
	assert(d.saturation == 0.6 and d.dur == 0.8 and C.defeat(true) == nil and C.TRY_AGAIN == "Try Again")
end })

