table.insert(tests, { name = "TouchGestures: tap, drag and long press thresholds, reorder maths, 44 px targets with 8 px slack, no motion in calm mode, hand and Patron hooks", fn = function()
	local G = require(script.Parent.Parent.Engine.TouchGestures)
	expectTrue(G.classify(0, 0.1, true) == "tap" and G.classify(5, 0.2, true) == "tap", "a short still press is a tap")
	expectTrue(G.classify(0, 0.2, false) == "pending" and G.classify(2, 0.35, false) == "long", "held 0.35 s is a long press")
	expectTrue(G.classify(0, 0.5, true) == "long", "a long press that ends is not a tap")
	expectTrue(G.classify(12, 0.05, false) == "drag" and G.classify(-30, 1, true) == "drag", "12 px sideways starts a drag, either way")
	expectTrue(G.classify(11, 0.1, true) == "pending", "between the tap and drag limits does nothing yet")
	local o = { "a", "b", "c", "d", "e" }
	local r = G.reorder(o, 1, 3)
	expectTrue(table.concat(r) == "bcade" and table.concat(o) == "abcde", "move right, input untouched")
	expectTrue(table.concat(G.reorder(o, 5, 2)) == "aebcd" and table.concat(G.reorder(o, 3, 3)) == "abcde", "move left, same slot is a no-op")
	expectTrue(table.concat(G.reorder(o, 2, 99)) == "acdeb" and table.concat(G.reorder(o, 2, -4)) == "bacde", "targets clamp")
	expectTrue(#G.reorder({}, 1, 2) == 0, "an empty hand is fine")
	expectTrue(G.slotAt(10, { 0, 50, 100 }) == 1 and G.slotAt(70, { 0, 50, 100 }) == 2 and G.slotAt(500, { 0, 50, 100 }) == 3 and G.slotAt(5, {}) == nil, "nearest slot")
	local w, h = G.hitSize(30, 20)
	expectTrue(w == 44 and h == 44 and G.hitSize(60, 90) == 60, "targets are at least 44 px")
	expectTrue(G.withinTap(30, 0, 40, 60) and not G.withinTap(40, 0, 40, 60), "44 px target plus 8 px slack: 30 px is in, 40 px is out")
	expectTrue(G.withinTap(0, 38, 40, 60) and not G.withinTap(0, 39, 40, 60), "slack on the tall side")
	expectTrue(G.motion(true) == nil, "calm mode: no motion")
	local m = G.motion(false)
	expectTrue(m.slide == 0.12 and m.lift == 24 and G.LONG_PRESS == 0.35 and G.CUE == "card_flip", "tuned numbers")
	local Card = require(script.Parent.Parent.Engine.Card)
	local tip = G.cardTip({ rank = 12, suit = "Hearts" }, Card)
	expectTrue(tip == "Queen of Hearts", "card name: " .. tip)
	expectTrue(G.cardTip({ rank = 14, suit = "Spades", stamp = "gold" }, Card):find("Gold Stamp", 1, true) ~= nil, "stamp line")
	expectTrue(G.cardTip(nil, Card) == "", "no card, no tip")
	if io and io.open then
		local f = io.open("src/Client/HandTouchFX.lua", "r")
		if f then
			local fx = f:read("*a"); f:close()
			expectTrue(fx:find("reduceShake", 1, true) and fx:find("TG.motion(calm())", 1, true), "calm gate on every tween")
			expectTrue(not fx:find("[\128-\255]"), "ASCII only")
			local n = 0
			for _ in fx:gmatch("TweenService:Create") do n = n + 1 end
			local g = 0
			for _ in fx:gmatch("if motion then") do g = g + 1 end
			expectTrue(n == 2 and g == 2, "both tweens sit under 'if motion then'")
			expectTrue(fx:find("Reordering is cosmetic", 1, true) and not fx:find("FireServer", 1, true) and not fx:find("Remote", 1, true), "no server calls")
		end
		local hub = io.open("src/Client/init.client.lua", "r")
		if hub then
			local src = hub:read("*a"); hub:close()
			expectTrue(src:find("HandTouchFX).swallow()", 1, true) and src:find("HandTouchFX).attach(", 1, true), "hand cards hook the gestures")
		end
		local pr = io.open("src/Client/PatronRow.lua", "r")
		if pr then
			local src = pr:read("*a"); pr:close()
			expectTrue(src:find("HandTouchFX).press(", 1, true), "Patron cards use the long press")
		end
	end
end })

table.insert(tests, { name = "FriendlyErrors and InputWatchdog: plain lines under 80 characters, raw errors never shown, toast clear of the HUD and buttons at five sizes, 6 s watchdog releases once", fn = function()
	local FE = require(script.Parent.Parent.Engine.FriendlyErrors)
	local WD = require(script.Parent.Parent.Engine.InputWatchdog)
	local Layout = require(script.Parent.Parent.Engine.ConceptTLayout)
	local n = 0
	for kind, text in pairs(FE.MESSAGES) do
		n = n + 1
		expectTrue(#text < 80, kind .. " is under 80 characters (" .. #text .. ")")
		expectTrue(not text:find("[\128-\255]") and not text:find("--", 1, true), kind .. " is plain ASCII with no dashes")
		expectTrue(not text:lower():find("error") and not text:lower():find("stack") and not text:lower():find("nil"), kind .. " has no technical words")
	end
	expectTrue(n >= 6 and FE.message("nope") == FE.MESSAGES.generic and FE.message(nil) == FE.MESSAGES.generic, "unknown kinds read as generic")
	expectTrue(FE.kindOf("DataStore request was added to queue") == "save" and FE.kindOf("HttpService timed out") == "offline", "raw text maps to a kind")
	expectTrue(FE.kindOf("Server rejected the call") == "rejected" and FE.kindOf("attempt to index nil with 'x' at line 12") == "generic", "a stack trace maps to generic")
	expectTrue(FE.retryable("rejected") and FE.retryable("offline") and not FE.retryable("save") and not FE.retryable("stuck"), "Try again only where it helps")
	expectTrue(FE.HOLD == 3 and FE.shouldShow("save", nil, 10) and not FE.shouldShow("save", 10, 12) and FE.shouldShow("save", 10, 13), "3 s hold, no repeat while up")
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1024, 768 }, { 844, 390 }, { 800, 450 } }) do
		local w, h = sz[1], sz[2]
		local t = FE.rect(w, h)
		local r, f = Layout.rectsIn(w, h)
		expectTrue(t.x >= f.x and t.x + t.w <= f.x + f.w and t.y + t.h <= f.y + f.h, "toast inside the frame at " .. w)
		expectTrue(t.h >= FE.BUTTON.h, "toast tall enough for a 44 px button at " .. w)
		for _, name in ipairs({ "coins", "hands", "round", "gear", "hand", "play", "discard", "deck", "deckCount" }) do
			local o = r[name]
			local hit = t.x < o.x + o.w and o.x < t.x + t.w and t.y < o.y + o.h and o.y < t.y + t.h
			expectTrue(not hit, "toast clear of " .. name .. " at " .. w .. "x" .. h)
		end
	end
	local wd = WD.new()
	wd:arm("fade", 10)
	wd:arm("fade", 14) -- the first start time stays
	wd:arm("guard", 12)
	expectTrue(#wd:expired(15.9) == 0, "not before 6 s")
	local out = wd:expired(16)
	expectTrue(#out == 1 and out[1] == "fade", "fade released at 6 s")
	expectTrue(#wd:expired(17) == 0, "reported once")
	wd:clear("guard")
	expectTrue(#wd:expired(99) == 0 and WD.LIMIT == 6, "a finished thing is never reported")
	if io and io.open then
		local function read(path)
			local f = io.open(path, "r")
			if not f then return nil end
			local src = f:read("*a"); f:close()
			return src
		end
		local fx, wfx = read("src/Client/FriendlyErrorFX.lua"), read("src/Client/InputWatchdogFX.lua")
		if fx then
			expectTrue(not fx:find("TweenService", 1, true) and not wfx:find("TweenService", 1, true), "no tween anywhere")
			expectTrue(fx:find("label.Text = FE.message(kind)", 1, true) and not fx:find("label.Text = raw", 1, true), "the toast shows only the friendly line")
			expectTrue(not fx:find("[\128-\255]") and not wfx:find("[\128-\255]"), "ASCII only")
			expectTrue(wfx:find("Guard.resync()", 1, true) and wfx:find("Fade.forceRelease()", 1, true) and wfx:find("Shield.releaseHidden()", 1, true), "the watchdog releases the fade, InputGuard and PopupShield")
		end
		local hub = read("src/Client/init.client.lua")
		if hub then
			expectTrue(hub:find("InputWatchdogFX).start()", 1, true) and hub:find("fe.watchState(state)", 1, true) and hub:find('expect("play"', 1, true), "the hub starts the watchdog and the save and reply checks")
		end
	end
end })

table.insert(tests, { name = "Click targets: one writer owns the Actions and hand frames while the Concept T screen is up", fn = function()
	if not io then return end
	local function read(path) local fh = io.open(path, "r"); if not fh then return nil end local t = fh:read("*a"); fh:close(); return t end
	local sp, cl, ct = read("src/Client/PlayScenePaint.lua"), read("src/Client/CompactLayout.lua"), read("src/Client/ConceptTPlay.lua")
	if sp then
		local a = sp:find("ConceptTPlay", 1, true)
		local w = sp:find("actionFrame.Position = UDim2.fromOffset(p.actions.x", 1, true)
		expectTrue(a ~= nil and w ~= nil and a < w and sp:find("if not ctOwns then", 1, true) ~= nil, "PlayScenePaint leaves Actions and the hand alone while Concept T is active")
	end
	if cl then expectTrue(cl:find("ConceptTPlay", 1, true) ~= nil and cl:find("ctOwns", 1, true) ~= nil, "CompactLayout leaves them alone too") end
	if ct then expectTrue(ct:find("[ClickCheck]", 1, true) ~= nil and ct:find("IsStudio", 1, true) ~= nil, "Studio self check prints each control against its painted rect") end
end })

table.insert(tests, { name = "Rarity pill: native rounded pill, 4.5:1 text, 22 px at a 130 px card, width is the word plus 28 px, fits under the card", fn = function()
	local S = require(script.Parent.Parent.Engine.RarityPillSpec)
	local Layout = require(script.Parent.Parent.Engine.ConceptTLayout)
	local seen = {}
	for _, tier in ipairs(S.order) do
		local sp = S.spec(tier, 130)
		assert(sp.h == 22, tier .. " is 22 px tall at the reference card")
		assert(sp.w == S.textWidth(sp.word, sp.textSize) + 28, tier .. " width is text plus 28 px")
		assert(S.contrast(S.INK, S.FILL[tier]) >= 4.5, tier .. " text reads at 4.5:1 on its fill")
		assert(sp.textSize >= 14, "text is 14 px or more")
		assert(sp.marker.x + sp.marker.px < sp.text.x, tier .. " marker sits left of the word, inside the pill")
		assert(sp.text.x + sp.text.w <= sp.w, tier .. " word box stays inside the pill")
		local key = table.concat(S.FILL[tier], ",")
		assert(not seen[key], tier .. " has its own fill")
		seen[key] = true
	end
	assert(S.spec("nonsense", 130).word == "Common", "unknown tier falls back to Common")
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 844, 390 }, { 800, 450 } }) do
		local row = Layout.patronRow(sz[1], sz[2], 5)
		local cw = row.cards[1].w
		for _, tier in ipairs(S.order) do
			local sp = S.spec(tier, cw)
			assert(sp.w <= math.max(cw, S.textWidth("Legendary", 14) + 28), tier .. " fits under its card at " .. sz[1] .. " (" .. sp.w .. " vs " .. cw .. ")")
			assert(sp.h >= 18, "pill height readable at " .. sz[1])
		end
	end
	if io then
		local fh = io.open("src/Client/RarityPill.lua", "r")
		if fh then
			local src = fh:read("*a"); fh:close()
			assert(not src:find("ImageLabel", 1, true), "the rarity pill draws no image")
			assert(src:find("UICorner", 1, true) and src:find("UIStroke", 1, true), "rounded with a stroke")
		end
		local pc = io.open("src/Client/ConceptTPatronCard.lua", "r")
		if pc then
			local src = pc:read("*a"); pc:close()
			assert(src:find("RarityPill", 1, true) and not src:find("labelKey", 1, true), "the Patron card draws the native pill, not label art")
		end
	end
end })

table.insert(tests, { name = "TavernStyle and TavernKit: colors from the style sheet, 4.5:1 text, two button kinds, still in Calm mode, no images, no Transparency gradients", fn = function()
	local S = require(script.Parent.Parent.Engine.TavernStyle)
	assert(S.rgb("plateFill")[1] == 40 and S.rgb("green")[1] == 70 and S.rgb("brown")[1] == 90, "plate, green and brown match RoundSelect")
	assert(S.COLORS.goldTrim[1] == 200 and S.STROKE.plate == 2 and S.STROKE.button == 1.5, "gold trim numbers match polishPanel and polishButton")
	for kind, k in pairs(S.BUTTONS) do
		local fill = S.rgb(k.fill)
		local top = { fill[1] + (255 - fill[1]) * 0.06, fill[2] + (255 - fill[2]) * 0.06, fill[3] + (255 - fill[3]) * 0.06 }
		assert(S.contrast(S.rgb(k.text), fill) >= 4.5 and S.contrast(S.rgb(k.text), top) >= 4.5, kind .. " button text reads at 4.5:1, gradient top included")
		assert(k.height >= S.SIZES.minTouch - 4 and k.height >= 40, kind .. " button is a real touch target")
	end
	assert(S.BUTTONS.primary.height >= S.SIZES.minTouch, "the primary button is at least 44 px")
	assert(S.contrast(S.rgb("cream"), S.rgb("plateFill")) >= 4.5, "cream title on the plate")
	assert(S.contrast(S.rgb("gold"), S.rgb("plateDark")) >= 4.5, "gold number on the Target box")
	assert(S.contrast(S.rgb("creamChip"), S.PILLS.wood) >= 4.5, "pill text on wood")
	local calm, live = S.feel(true), S.feel(false)
	assert(calm.lift == 0 and calm.press == 1 and calm.seconds == 0, "Calm mode: no lift, no squeeze, no time")
	assert(live.lift > 0 and live.press < 1 and live.seconds > 0, "live feel moves")
	assert(S.TEXT.min >= 14 and S.TEXT.button >= 14 and S.TEXT.box >= 14, "text sizes of 14 or more")
	local w, h = S.plateSize(1, 1)
	assert(w >= 20 and h >= 20, "a plate never collapses below its corner radius")
	assert(not pcall(S.rgb, "nope"), "unknown color is an error")
	if io then
		local fh = io.open("src/Client/TavernKit.lua", "r")
		if fh then
			local src = fh:read("*a"); fh:close()
			assert(select(2, src:gsub("Instance.new%(\"ImageLabel\"%)", "")) == 2 and not src:find("rbxassetid", 1, true), "the kit draws images only through painted() and icon(), never an id of its own")
			assert(not src:find("%.Transparency%s*=%s*NumberSequence") and not src:find("g%.Transparency"), "gradients are Color only")
			for _, fn in ipairs({ "plate", "primaryButton", "secondaryButton", "pill", "goldBox", "title", "feel" }) do
				assert(src:find("function TavernKit." .. fn, 1, true), "TavernKit." .. fn .. " exists")
			end
			assert(src:find("reduceShake", 1, true) and src:find('"fast"', 1, true), "feel is skipped in Calm mode and Fast speed")
			assert(not src:find("[\128-\255]"), "ASCII only")
		end
	end
end })

table.insert(tests, { name = "FeatureFlags: default flags build no corner icons, each flag brings its own back, LEGACY_V1 brings all", fn = function()
	local F = require(script.Parent.Parent.Engine.FeatureFlags)
	local n = 0
	for icon, flag in pairs(F.CORNER) do
		n = n + 1
		assert(F.FLAGS[flag] == false, flag .. " must default to false")
		assert(not F.cornerIcon(icon), icon .. " icon must not exist by default")
		F.setOverride(flag, true)
		assert(F.cornerIcon(icon), flag .. " must re-create " .. icon)
		for other, oflag in pairs(F.CORNER) do
			if other ~= icon then assert(not F.cornerIcon(other), flag .. " must not bring back " .. other) end
		end
		F.setOverride(flag, nil)
		assert(not F.cornerIcon(icon))
	end
	assert(n == 5, "five corner icons")
	F.LEGACY_V1 = true
	for icon in pairs(F.CORNER) do assert(F.cornerIcon(icon), icon .. " on under LEGACY_V1") end
	F.LEGACY_V1 = false
	assert(not F.cornerIcon("nonsense"))
	if not io then return end
	local f = io.open("src/Client/init.client.lua", "r")
	if not f then return end
	local src = f:read("*a"); f:close()
	for icon in pairs(F.CORNER) do
		assert(src:find('"' .. icon .. '"%)'), "the hub must pass the flag key for " .. icon)
	end
end })

table.insert(tests, { name = "Gameplay v2: one rect function, no overlaps or off-screen rects at three sizes, 44 px buttons, slim bar, every seat reserved, flags pick the table", fn = function()
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	local F = require(script.Parent.Parent.Engine.FeatureFlags)
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 800, 400 }, { 844, 390 }, { 1024, 768 } }) do
		local w, h = sz[1], sz[2]
		assert(L.fits(w, h))
		local r = L.rects(w, h)
		local bad = L.overlaps(r)
		assert(#bad == 0, w .. "x" .. h .. " overlaps: " .. table.concat(bad, ", "))
		local ok, name = L.onScreen(r, w, h)
		assert(ok, w .. "x" .. h .. " off screen: " .. tostring(name))
		assert(r.bar.h <= math.max(30, math.floor(0.09 * h + 0.5)), "round bar at most 9 percent of the height (the reference plates are 85 of 941)")
		assert(r.play.h >= 44 and r.discard.h >= 44 and r.sortRank.h >= 44 and r.sortSuit.h >= 44, "touch targets")
		assert(#r.slots == 5, "five seats reserved")
		for i = 1, 5 do
			assert(r.slots[i].card.w > 0 and r.slots[i].label.h >= 15 and r.slots[i].pill.h >= 17)
			assert(r.slots[i].pill.y + r.slots[i].pill.h <= r.stage.y, "stage clear of Patron pills")
		end
		assert(r.stage.y + r.stage.h <= r.hand.y and r.hand.y + r.hand.h <= r.play.y, "stage, hand and buttons stack without touching")
		assert(r.play.x + r.play.w <= r.discard.x, "Play Hand left of Discard")
		for _, k in ipairs(L.CONTROLS) do assert(r[k], "control rect " .. k) end
		local row = L.patronRow(w, h, 8)
		assert(#row.cards == 8)
	end
	-- the flags: v2 by default, GAMEPLAY_V1 brings the archived table back, neither leaves the hub's own screen
	assert(F.gameplay() == 2)
	F.setOverride("GAMEPLAY_V1", true); assert(F.gameplay() == 1); F.setOverride("GAMEPLAY_V1", nil)
	F.setOverride("GAMEPLAY_V2", false); assert(F.gameplay() == 0); F.setOverride("GAMEPLAY_V2", nil)
	F.LEGACY_V1 = true; assert(F.gameplay() == 1); F.LEGACY_V1 = false
	assert(F.gameplay() == 2)
	if not io then return end
	local f = io.open("src/Client/Gameplay2.lua", "r")
	if not f then return end
	local src = f:read("*a"); f:close()
	assert(src:find("Layout.rects(", 1, true), "the client reads the one rect function")
	assert(not src:find('Instance.new("TextButton")', 1, true) and not src:find('Instance.new("ImageButton")', 1, true), "no separate hit frames: only the real buttons are clickable")
	assert(src:find("TavernKit", 1, true) and src:find("selfCheck", 1, true), "built on TavernKit with a Studio ClickCheck")
	assert(not src:find("[\128-\255]"), "no non ASCII glyph in the new plates")
	local h = io.open("src/Client/init.client.lua", "r")
	if h then
		local hub = h:read("*a"); h:close()
		assert(hub:find("script.Gameplay2", 1, true), "the hub installs Gameplay v2")
	end
end })

table.insert(tests, { name = "Gameplay v2 hand fan: reference span and tilt, clear of the pills, buttons and deck", fn = function()
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	local CT = require(script.Parent.Parent.Engine.ConceptTLayout)
	assert(CT.FAN.deg == 8, "outer cards tilt about 8 degrees")
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1506, 751 }, { 844, 390 } }) do
		local w, h = sz[1], sz[2]
		local r = L.rects(w, h)
		local hd = r.hand
		if w >= 1000 then
			assert(math.abs(hd.w / w - 0.664) < 0.01, "fan spans about 0.664 of the width at " .. w)
			assert(math.abs((hd.x + hd.w / 2) / w - 0.511) < 0.01, "fan centre sits at about 0.511 at " .. w)
		end
		assert(hd.y + hd.h <= math.min(r.playCount.y, r.discardCount.y), "hand ends above the Hands and Discards pills at " .. w)
		assert(hd.x + hd.w <= r.deck.x, "hand ends before the deck at " .. w)
	end
end })

table.insert(tests, { name = "Gameplay v2 live fixes: disc below the name strip, one unit pill, bar order, split sort plates, every plate has text and a z above its parent", fn = function()
	local T = require(script.Parent.Parent.Engine.PatronTierStyle)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	for _, w in ipairs({ 60, 90, 140, 200 }) do
		local h = math.floor(w / 0.712)
		local d = T.discRect(w, h)
		assert(d.w == (w >= 140 and 48 or (w >= 70 and 40 or 28)), "disc scales with the card (w " .. w .. ")")
		assert(d.x + d.w > w and d.y + d.h > h, "the disc sits in the bottom right corner and overhangs the frame")
		assert(math.abs((d.x + d.w - w) / d.w - 0.5) < 0.06 and math.abs((d.y + d.h - h) / d.h - 0.5) < 0.06, "about half of the disc is outside sideways and below")
	end
	assert(T.unitText("+4 Mult") == "Mult" and T.unitText("+30 Chips") == "Chips" and T.unitText("x1.5 Mult") == "Mult")
	assert(T.unitText("Retrigger") == "Retrigger" and T.unitText("") == "")
	assert(T.style("uncommon").gem and not T.style("common").gem and T.style("common").coverGem, "uncommon has a green gem, common hides the cut card's gold one")
	assert(T.style("common").tint[1] < 255 and T.style("common").thickness >= 4, "common is plainer: desaturated portrait, heavy dark frame")
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 800, 400 } }) do
		local w, h = sz[1], sz[2]
		local r = L.rects(w, h)
		for i = 1, 5 do
			local card, label = r.slots[i].card, r.slots[i].label
			local d = T.discRect(card.w, card.h)
			assert(card.y + d.y + d.h <= label.y, "the label starts under the disc at " .. w .. "x" .. h)
		end
		assert(r.target.x < r.round.x and r.round.x < r.tips.x, "Target left, the Night name in the middle, Tips right")
		assert(r.sortSuit.x - (r.sortRank.x + r.sortRank.w) >= 8, "two separate sort plates with an 8 px gap")
		assert(r.discard.x - (r.play.x + r.play.w) >= 10 and r.play.w >= 120 and r.play.h >= 44)
	end
	if not io then return end
	local f = io.open("src/Client/Gameplay2.lua", "r")
	if not f then return end
	local src = f:read("*a"); f:close()
	assert(src:find("local function raise", 1, true) and src:find("raise(target", 1, true), "pill and box children are lifted above their plate (Global ZIndex)")
	assert(src:find("KitLabel", 1, true), "Play Hand and Discard draw their word on a label above the plate")
	assert(src:find("CenterScore", 1, true), "the felt centre shows the round score")
end })

table.insert(tests, { name = "Gameplay v2: count pills ride the top right corner of their button, hand and neighbours stay clear", fn = function()
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 800, 400 }, { 844, 390 }, { 1024, 768 } }) do
		local r = L.rects(sz[1], sz[2])
		for _, p in ipairs({ { r.play, r.playCount }, { r.discard, r.discardCount } }) do
			local b, c = p[1], p[2]
			if sz[1] >= L.REF_MIN_W and sz[2] >= L.REF_MIN_H then
				assert(c.x >= b.x and c.x + c.w <= b.x + b.w, "reference size: the pill sits over the middle of its button, inside its width")
			else
				assert(c.x + c.w >= b.x + b.w and c.x >= b.x, "compact: the pill hangs on the right half of its button")
			end
			assert(c.y + c.h + L.PILL_GAP <= b.y, "pill sits fully above the top edge of the button with a 4 px gap, so its word never shares pixels with the button label at " .. sz[1] .. "x" .. sz[2])
		end
		assert(r.playCount.x + r.playCount.w <= r.discard.x, "the Play pill stays left of Discard")
		assert(r.hand.y + r.hand.h <= r.playCount.y, "the hand ends above the pills")
		assert(#L.overlaps(r) == 0, "no unintended overlap at " .. sz[1] .. "x" .. sz[2] .. ": " .. table.concat(L.overlaps(r), ","))
		assert(L.onScreen(r, sz[1], sz[2]))
	end
end })

table.insert(tests, { name = "Gameplay v2 click rects: the buttons are placed first, opaque, re-asserted when moved, with a real hit test in the Studio check", fn = function()
	if not io then return end
	local f = io.open("src/Client/Gameplay2.lua", "r")
	if not f then return end
	local src = f:read("*a"); f:close()
	local place = src:find("deps.actionFrame.Position = UDim2.fromOffset(r.play.x, r.play.y)", 1, true)
	local rest = src:find("place(bar, r.bar)", 1, true)
	assert(place and rest, "action placement is found")
	assert(src:find("local r = Layout.rects(size.X, size.Y)\n\t\tfanHand(true, size.Y)\n", 1, true))
	local applyAt = src:find("local function apply()", 1, true)
	assert(place > applyAt and place < src:find("place(bar, r.bar)", applyAt, true), "Play Hand and Discard are moved before any piece that could error")
	assert(src:find("flatOpaque(deps.playButton)", 1, true) and src:find("b.BackgroundTransparency = 0", 1, true), "the button is itself the visible plate (opaque flat, or the painted frame behind it)")
	assert(src:find("GetGuiObjectsAtPosition", 1, true), "the Studio check hit tests the painted centre")
	assert(src:find("apply stopped on an error", 1, true), "a failing apply is reported once, not swallowed")
	assert(src:find("SPlate.live(", 1, true) and src:find("scoreCaption.TextSize = 18", 1, true) and src:find("scoreProgress.TextSize = 18", 1, true), "centre score stack: numeral, caption above, progress text under the line")
	assert(src:find("ScoreJuiceBanner", 1, true), "a stale TARGET CLEARED shout is hidden once the screen leaves play")
	assert(src:find('GetPropertyChangedSignal("Position")', 1, true), "another module moving the controls is undone at once")
end })

table.insert(tests, { name = "Gameplay2 wall banners: two banners at the reference spots, on screen, touching no table piece at six sizes, none on compact screens, art recorded, still (no tween)", fn = function()
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	local Kit = require(script.Parent.Parent.Engine.PaintedKitArt)
	assert(Kit.pk_banner_l and Kit.pk_banner_l:find("rbxassetid://%d+"), "left banner art recorded")
	assert(Kit.pk_banner_r and Kit.pk_banner_r:find("rbxassetid://%d+"), "right banner art recorded")
	assert(L.banners(1024, 768) == nil and L.banners(844, 390) == nil and L.banners(800, 450) == nil, "compact screens keep the wall bare")
	for _, sz in ipairs({ { 1920, 1080 }, { 1920, 957 }, { 1672, 941 }, { 1506, 751 }, { 1280, 720 }, { 2380, 957 } }) do
		local w, h = sz[1], sz[2]
		local b = L.banners(w, h)
		assert(b and b.right, w .. "x" .. h .. " has the right banner")
		assert(not b.left or b.left.x + b.left.w < b.right.x, "left banner is left of the right banner")
		if w >= 1672 then assert(b.left, w .. "x" .. h .. " has room for the left banner") end
		local flat = L.flat(L.rects(w, h))
		for side, rc in pairs(b) do
			assert(rc.x >= 0 and rc.y >= 0 and rc.x + rc.w <= w and rc.y + rc.h <= h, side .. " banner on screen at " .. w .. "x" .. h)
			for name, o in pairs(flat) do
				local hit = rc.x < o.x + o.w and o.x < rc.x + rc.w and rc.y < o.y + o.h and o.y < rc.y + rc.h
				assert(not hit, side .. " banner overlaps " .. name .. " at " .. w .. "x" .. h)
			end
		end
	end
	local ref = L.banners(1672, 941)
	assert(math.abs(ref.left.x - 285) <= 2 and math.abs(ref.left.w - 95) <= 2, "left banner at the reference spot")
	assert(math.abs(ref.right.x - 1430) <= 2 and math.abs(ref.right.w - 120) <= 2, "right banner at the reference spot")
	if io then
		local f = io.open("src/Client/Gameplay2.lua", "r")
		if f then
			local src = f:read("*a"); f:close()
			local i = src:find("wall banners:", 1, true)
			local j = src:find("local wallBanners", 1, true)
			assert(i and j, "banner block present")
			assert(not src:sub(i, j + 900):find("TweenService", 1, true), "banners are still pictures")
		end
	end
end })

