table.insert(tests, { name = "Counter fixes: bright Next Round with gold edge, packs as big as offers, banner under the preview pill and clear of the Patron rows", fn = function()
	local E = script.Parent.Parent.Engine
	local S, SL, L = require(E.TavernScreens), require(E.ShopSceneLayout), require(E.Gameplay2Layout)
	local Style = require(E.TavernStyle)
	local N = S.NEXT_ROUND
	assert(N.fill[1] == 77 and N.fill[2] == 158 and N.fill[3] == 77, "bright warm green (0.30, 0.62, 0.30)")
	assert(N.text[1] == 250 and N.text[2] == 240 and N.text[3] == 220, "cream label")
	assert(N.edge and N.edge[1] > 200 and N.edge[3] < 100, "thin gold edge")
	assert(N.hover[2] > N.fill[2], "hover brightens")
	assert(Style.contrast(N.text, N.stroke) >= 4.5, "the label's dark outline gives 4.5:1")
	-- layers: the scene sits under every control
	assert(S.LAYERS.scene < S.LAYERS.decor and S.LAYERS.decor < S.LAYERS.controls)
	-- offer cards and packs at 1920x1080 with three or four offers: offers 170 px or more, packs not tiny (at least 70 percent of an offer)
	for n = 3, 4 do
		local r = SL.rects(1920, 1080, { offers = n, packs = 2 })
		assert(r.offers[1].w >= 170, "offer card 170 px wide with " .. n .. " offers")
		assert(r.packs[1].w >= 0.7 * r.offers[1].w - 1, "pack is at least 70 percent of an offer card")
	end
	local r3 = SL.rects(1920, 1080, { offers = 3, packs = 2 })
	assert(r3.packs[1].w >= 170, "with three offers the packs are 170 px too")
	-- banner: under the 26 px preview pill, inside the stage, below every Patron pill
	for _, sz in ipairs({ { 1920, 957 }, { 1920, 1080 }, { 1280, 720 } }) do
		local r = L.rects(sz[1], sz[2])
		local cy = L.bannerY(sz[1], sz[2])
		local top = cy - L.BANNER_H / 2
		assert(top >= r.stage.y + 26, "banner under the preview pill at " .. sz[1])
		for _, s in ipairs(r.slots) do
			assert(top >= s.pill.y + s.pill.h and top >= s.label.y + s.label.h, "banner clear of the Patron label and pill rows at " .. sz[1])
		end
		assert(cy < r.hand.y + r.hand.h, "banner above the bottom of the hand")
	end
end })

table.insert(tests, { name = "Gameplay v2 and shop polish round three: corner disc, Next Round contrast, banner spot, score stack, bigger offer cards, no overlaps", fn = function()
	local E = script.Parent.Parent.Engine
	local T, S, RB, L = require(E.PatronTierStyle), require(E.TavernScreens), require(E.RewardBanner), require(E.Gameplay2Layout)
	local Style = require(E.TavernStyle)
	-- 1. the disc: 40 px, bottom right corner, 40 percent outside the frame, label clear of its overhang
	local d = T.discRect(150, 210)
	assert(d.w == 48 and d.x + d.w == 150 + 24 and d.y + d.h == 210 + 24, "48 px disc on a roomy card, 24 px sideways and 24 px below the corner")
	assert(T.discBand(150) >= 16, "the label starts under the disc overhang")
	-- 2. Next Round: bright green, cream text at 24 px, at least 3:1 (large text) with a solid dark outline
	assert(S.NEXT_ROUND.textSize == 24 and Style.contrast({ 250, 240, 220 }, S.NEXT_ROUND.stroke) >= 4.5, "cream on its dark outline (the plate itself is bright green)")
	assert(S.NEXT_ROUND.fill[2] > Style.rgb("greenDeep")[2], "brighter than the kit primary")
	-- 3. the Round Complete plate stands right of the merchant: top right, clear of the right-hand column
	for _, w in ipairs({ 1920, 1280, 1024, 844 }) do
		local sp = RB.spot(w)
		assert(sp.right <= w - 120 and sp.right - sp.width >= w * 0.4, "plate in the right half, clear of the right column at " .. w)
	end
	assert(RB.clearedLine() == "Target cleared" and RB.clearedLine(120, 65) == "Target cleared  120 of 65")
	-- 4. offer cards at 1920x1080 are at least 170 px wide for up to four offers
	local SL = require(E.ShopSceneLayout)
	for n = 2, 4 do
		local r = SL.rects(1920, 1080, { offers = n, packs = 2 })
		assert(r.offers[1].w >= 170, "offer card at least 170 px wide with " .. n .. " offers")
	end
	-- 5. the centre score stack: 72 px font (56 px digits), line directly under, progress text under the line, all inside the stage
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 } }) do
		local r = L.rects(sz[1], sz[2])
		local st = L.scoreStack(r.stage.h, 20, 22)
		if st.roomy then
			assert(st.textSize == math.min(72, r.stage.h - 52) and st.lineY <= st.numTop + st.numH and st.progressY > st.lineY and st.bottom <= r.stage.h, "score stack fits the stage at " .. sz[1])
		end
	end
	assert(L.scoreStack(400, 20, 22).roomy and L.scoreStack(400, 20, 22).textSize == 72 and not L.scoreStack(60, 20, 22).roomy)
	assert(L.scoreStack(113, 20, 22).roomy and L.scoreStack(113, 20, 22).textSize >= 44, "1280x720 keeps the caption and the line with a smaller numeral")
end })

table.insert(tests, { name = "Gameplay v2 scoring: centre score counts up in 12 steps, slams in with a burst and a hold, Fast halves it, Calm is instant, a client module reads the settings", fn = function()
	local S = require(script.Parent.Parent.Engine.Gameplay2Score)
	assert(S.plan(100, 100) == nil and S.plan(100, 50) == nil, "no plan when the score does not rise")
	local p = S.plan(0, 310)
	assert(#p.steps == 12 and p.steps[12] == 310 and p.final == 310 and p.burst > 0 and p.hold == 1.0)
	for i = 2, #p.steps do assert(p.steps[i] >= p.steps[i - 1], "steps never go down") end
	assert(p.slam.peak > 1.2 and p.slam.peak <= 1.3, "slam scales up about 1.25")
	assert(math.abs(p.total - (12 * 0.07 + 0.12 + 0.18 + 1.0)) < 1e-9)
	local f = S.plan(0, 310, { fast = true })
	assert(math.abs(f.total - p.total / 2) < 1e-9 and f.hold == 0.5, "Fast halves every time")
	local c = S.plan(0, 310, { calm = true })
	assert(#c.steps == 1 and c.steps[1] == 310 and c.slam == nil and c.burst == 0 and c.total == 0, "Calm mode: the end value, no motion")
	assert(S.skipTo(p) == 310 and S.skipTo(nil) == nil)
	assert(S.pitch(1, 12) == 1.0 and math.abs(S.pitch(12, 12) - 1.3) < 1e-9 and S.pitch(1, 1) == 1.0)
	if not io then return end
	local fh = assert(io.open("src/Client/Gameplay2ScoreFX.lua", "r")); local src = fh:read("*a"); fh:close()
	assert(src:find("reduceShake", 1, true) and src:find("calm = calm()", 1, true), "the FX asks Calm mode first")
	local g = assert(io.open("src/Client/Gameplay2.lua", "r")); local gs = g:read("*a"); g:close()
	assert(gs:find("Gameplay2ScoreFX", 1, true), "Gameplay2 plays the centre score FX")
end })

table.insert(tests, { name = "Gameplay v2 feel: hover 10, select 28, neighbours 6, deal 0.06 s apart and done by 0.6 s, Play ring pulses 1.6 s only on a legal hand, press 3 px, shake, none in Calm mode", fn = function()
	local F = require(script.Parent.Parent.Engine.Gameplay2Feel)
	local T = require(script.Parent.Parent.Engine.FeelTuning)
	local PM = require(script.Parent.Parent.Engine.PlayMotion)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	assert(T.HOVER_LIFT == 10 and T.SELECTED_LIFT == 28 and T.NEIGHBOUR_SPREAD == 6)
	for n = 1, 8 do
		local lastDelay, lastDur = PM.dealTiming(n, n)
		assert(lastDelay + lastDur <= 0.6 + 1e-9, "the last of " .. n .. " cards lands by 0.6 s")
	end
	assert(math.abs(select(1, PM.dealTiming(2, 8)) - 0.06) < 1e-9, "0.06 s stagger")
	assert(F.legalPlay(1) and F.legalPlay(5) and not F.legalPlay(0) and not F.legalPlay(6) and not F.legalPlay(1, 2, 5), "legal means 1 to 5 cards and the round's minimum")
	assert(math.abs(F.glow(0) - F.GLOW_MIN) < 1e-9 and math.abs(F.glow(0.8) - F.GLOW_MAX) < 1e-9 and math.abs(F.glow(1.6) - F.GLOW_MIN) < 1e-9, "period 1.6 s")
	for i = 0, 32 do local g = F.glow(i * 0.05); assert(g >= F.GLOW_MIN - 1e-9 and g <= F.GLOW_MAX + 1e-9) end
	assert(F.glow(0.3, true) == F.CALM_GLOW and F.glow(1.1, true) == F.CALM_GLOW, "Calm mode: a steady ring")
	assert(F.press(false).px == 3 and F.press(true) == nil and F.shake(true) == nil and F.shake(false).count >= 2)
	assert(F.pillTick("Hands 3", "Hands 2", false) ~= nil and F.pillTick("Hands 3", "Hands 3", false) == nil and F.pillTick("Hands 3", "Hands 2", true) == nil)
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 800, 400 } }) do
		local r = L.rects(sz[1], sz[2])
		local x, y = F.discardPoint(r, sz[1], sz[2])
		assert(x > sz[1] / 2 and x <= sz[1] and y <= sz[2] and y >= r.deckCount.y, "the discard pile is at the bottom right at " .. sz[1])
	end
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local c = f:read("a"); f:close(); return c end
	local fx = read("src/Client/Gameplay2FeelFX.lua")
	assert(fx:find("reduceShake", 1, true) and fx:find("Rules.press(calm())", 1, true) and fx:find("FxLoop.add", 1, true), "Calm mode checked, the glow loop goes through FxLoop")
	assert(read("src/Client/Gameplay2.lua"):find("Gameplay2FeelFX", 1, true) and read("src/Client/CardFlights.lua"):find("point", 1, true), "wired")
end })

table.insert(tests, { name = "Gameplay v2 moments: Target cleared plate lines and rect, boss banner clear of the Patron row or left out, red tint, Out of hands line, Calm mode shows without motion", fn = function()
	local M = require(script.Parent.Parent.Engine.Gameplay2Moments)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	local won = M.clearLines({ phase = "playing", targetScore = 300, roundScore = 280, tips = 5 }, { phase = "shop", targetScore = 300, roundScore = 340, tips = 12 })
	assert(won and won.title == "Target cleared" and won.score == "Score 340 of 300" and won.tips == "Tips +7" and won.tipsEarned == 7)
	assert(M.clearLines({ phase = "playing", targetScore = 300, roundScore = 100, tips = 5 }, { phase = "shop", targetScore = 300, roundScore = 100, tips = 5 }) == nil, "a round that was not cleared gets no plate")
	assert(M.clearLines({ phase = "playing", targetScore = 300, roundScore = 400, tips = 5 }, { phase = "gameover", targetScore = 300, roundScore = 400, tips = 5 }) == nil, "no plate over Run Over")
	assert(M.clearLines(nil, {}) == nil and M.clearLines({ phase = "shop" }, { phase = "shop" }) == nil)
	local t, tc, tf = M.clearTiming(false, false), M.clearTiming(true, false), M.clearTiming(false, true)
	assert(t.slide == 0.4 and t.count and tc.slide == 0 and tc.fade == 0 and not tc.count and math.abs(tf.slide - 0.2) < 1e-9, "0.4 s slide, Calm none, Fast half")
	local boss = M.bossText({ round = 3, bossModifier = { name = "The Tax Man", description = "Hearts score nothing." } })
	assert(boss == "The Tax Man" and select(2, M.bossText({ round = 3, bossModifier = { name = "The Tax Man", description = "Hearts score nothing." } })) == "Hearts score nothing.")
	assert(M.bossText({ round = 1, bossModifier = { name = "x" } }) == nil and M.bossText({ round = 3 }) == nil)
	assert(M.bossGlow(false).color[1] > M.bossGlow(false).color[3], "a redder glow")
	assert(M.defeatLine({ roundScore = 120, targetScore = 300 }) == "Out of hands. Score 120 of 300.")
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 800, 400 } }) do
		local w, h = sz[1], sz[2]
		local p = M.clearPlate(w, h)
		assert(p.x >= 0 and p.y >= 0 and p.x + p.w <= w and p.y + p.h <= h and math.abs(p.x + p.w / 2 - w / 2) <= 1, "plate centred and on screen at " .. w)
		local r = L.rects(w, h)
		local b = M.bossBanner(r, w, h)
		if b then
			assert(b.h >= 18 and b.y >= r.bar.y + r.bar.h, "banner under the top bar at " .. w)
			for i = 1, 5 do
				local c = r.slots[i].card
				assert(b.y + b.h <= c.y, "banner clear of Patron seat " .. i .. " at " .. w)
			end
			assert(b.x + b.w <= w and b.x >= 0)
		elseif w >= 1280 then
			error("a banner fits at " .. w)
		end
	end
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local c = f:read("a"); f:close(); return c end
	local fx = read("src/Client/Gameplay2MomentsFX.lua")
	assert(fx:find("reduceShake", 1, true) and fx:find("timing.slide == 0", 1, true), "Calm mode checked before any tween")
	assert(not fx:find("Backdrop", 1, true), "the plate is not a Backdrop and takes no input")
	assert(read("src/Client/Gameplay2.lua"):find("Gameplay2MomentsFX", 1, true) and read("src/Client/GameOver.lua"):find("defeatLine", 1, true), "wired")
end })

table.insert(tests, { name = "Gameplay v2 boss entrance: icon per rule family, 0.4 s slide and 1.2 s hold, none in Calm mode, once per boss round", fn = function()
	local M = require(script.Parent.Parent.Engine.Gameplay2Moments)
	local BR = require(script.Parent.Parent.Engine.BossRounds)
	for _, boss in ipairs(BR.Definitions) do
		local ic = M.bossIcon(boss.rules)
		assert(#ic >= 1 and #ic <= 2 and not ic:find("[\128-\255]"), "ASCII icon for " .. boss.id)
	end
	for _, tag in ipairs(BR.RuleTagIds) do assert(M.ICONS[tag], "icon for tag " .. tag) end
	local n = M.bossEntrance(false, false)
	assert(n.slide == 0.4 and n.hold == 1.2)
	local f = M.bossEntrance(false, true)
	assert(f.slide == 0.2 and f.hold == 0.6)
	local c = M.bossEntrance(true, false)
	assert(c.slide == 0 and c.hold == 0, "no motion in Calm mode")
	assert(M.bossEntranceKey({ night = 2, round = 3, bossModifier = { id = "bouncer" } }) ~= M.bossEntranceKey({ night = 3, round = 3, bossModifier = { id = "bouncer" } }))
	assert(M.bossEntranceKey({ night = 1, round = 1 }) == nil)
end })

table.insert(tests, { name = "Shop buy UX: Buy plate says Need N when Tips are short, the shake is small and absent in Calm mode and on Fast", fn = function()
	local M = require(script.Parent.Parent.Engine.ShopBuyUX)
	assert(M.shortBy(8, 5) == 3 and M.shortBy(5, 8) == 0 and M.shortBy(nil, nil) == 0)
