end })

table.insert(tests, { name = "Gameplay v2 Night cleared and Run complete: only a cleared Boss Round, Run complete on the last Night, plates inside the screen with a 48 px Continue", fn = function()
	local M = require(script.Parent.Parent.Engine.Gameplay2Moments)
	local boss = { phase = "playing", targetScore = 100, roundScore = 120, tips = 5, round = 3, night = 2, nightCap = 8, bossModifier = { id = "bouncer" } }
	local now = { phase = "shop", roundScore = 120, tips = 12 }
	local l = M.clearLines(boss, now)
	assert(l and l.night and l.night.title == "Night cleared" and l.night.sub == "Night 2 of 8" and not l.night.runComplete and l.night.button == "Continue")
	boss.night = 8
	assert(M.clearLines(boss, now).night.title == "Run complete" and M.clearLines(boss, now).night.runComplete)
	boss.endless = true
	assert(M.clearLines(boss, now).night.title == "Night cleared", "Endless Nights keep going")
	local plain = { phase = "playing", targetScore = 100, roundScore = 120, tips = 5, round = 1, night = 2, nightCap = 8 }
	assert(M.clearLines(plain, now) and M.clearLines(plain, now).night == nil, "an ordinary round has no Night plate")
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1024, 600 }, { 800, 400 } }) do
		for _, big in ipairs({ false, true }) do
			local p = M.nightPlate(sz[1], sz[2], big)
			assert(p.x >= 0 and p.y >= 0 and p.x + p.w <= sz[1] and p.y + p.h <= sz[2], "plate on screen at " .. sz[1])
			local c = M.continueRect(p)
			assert(c.h >= 44 and c.x >= 0 and c.x + c.w <= p.w and c.y + c.h <= p.h, "Continue inside the plate at " .. sz[1])
			assert(c.y >= (big and 146 or 134) + 4, "Continue below the four text lines at " .. sz[1])
		end
	end
	assert(M.nightPlate(1920, 1080, true).w > M.nightPlate(1920, 1080, false).w, "Run complete is the bigger plate")
	if not io then return end
	local f = assert(io.open("src/Client/Gameplay2MomentsFX.lua", "r")); local src = f:read("a"); f:close()
	assert(src:find("ConfettiFX", 1, true) and src:find("CrownGlow", 1, true) and src:find("calm()", 1, true), "confetti and glow, Calm mode checked")
end })

table.insert(tests, { name = "Gameplay v2 Patron tooltip: 0.25 s delay, 320 px wide scaling down, portrait column, plate clear of the bar, hand, buttons, sort control and deck for all five seats at three sizes", fn = function()
	local T = require(script.Parent.Parent.Engine.Gameplay2Tip)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	assert(T.DELAY == 0.25)
	assert(T.width(1920) == 320 and T.width(1280) == 320 and T.width(800) == 220 and T.width(640) == 220, "320 wide, scaling down to 220")
	local p = T.portrait(320)
	assert(math.abs(p.w / p.h - 0.712) < 0.02 and T.textWidth(320) > 150, "portrait left, text right")
	assert(T.height(320, 10) == p.h + 24 and T.height(320, 400) == 424)
	local function hit(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 800, 400 } }) do
		local w, h = sz[1], sz[2]
		local r = L.rects(w, h)
		local tw = T.width(w)
		local th = T.height(tw, math.floor(h * 0.12))
		for slot = 1, 5 do
			local x, y = T.place(r, w, h, slot, tw, th)
			local tip = { x = x, y = y, w = tw, h = th }
			assert(x >= 0 and y >= 0 and x + tw <= w and y + th <= h, "inside the screen, seat " .. slot .. " at " .. w)
			for _, a in ipairs(T.avoid(r)) do
				assert(not hit(tip, a), "plate clear of the bar, hand, buttons, sort control and deck, seat " .. slot .. " at " .. w .. "x" .. h)
			end
		end
	end
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local c = f:read("a"); f:close(); return c end
	local fx = read("src/Client/PatronTipFX.lua")
	assert(fx:find("Gameplay2Tip", 1, true) and fx:find("Tip.DELAY", 1, true), "the plate waits the delay")
end })

table.insert(tests, { name = "Gameplay v2 audit: 1920x1080, 1280x720, 1024x600, 800x400 and 844x390 have no warnings (hand cards 56 px or wider, 44 px touch targets, nothing overlaps), portrait and tiny windows keep the older screen", fn = function()
	local A = require(script.Parent.Parent.Engine.Gameplay2Audit)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	assert(#A.SIZES == 5)
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1024, 600 }, { 800, 400 }, { 844, 390 }, { 1024, 768 } }) do
		local a = A.audit(sz[1], sz[2])
		assert(a.fits, sz[1] .. "x" .. sz[2] .. " runs the v2 table")
		assert(#a.warnings == 0, sz[1] .. "x" .. sz[2] .. ": " .. table.concat(a.warnings, "; "))
		assert(a.handCard.w >= 56, "hand cards at least 56 px wide at " .. sz[1])
		local r = L.rects(sz[1], sz[2])
		assert(r.play.h >= 44 and r.discard.h >= 44 and r.sortRank.h >= 44 and r.sortSuit.h >= 44 and r.sortRank.w >= 44, "44 px touch targets at " .. sz[1])
	end
	local portrait = A.audit(390, 844)
	assert(not portrait.fits and #portrait.warnings == 0 and not L.fits(390, 844) and not L.fits(640, 360) and L.fits(720, 360), "portrait and tiny windows keep the older screen")
	local lines = A.report(800, 400)
	assert(lines[1]:find("800x400: ok", 1, true) and #lines > 20, "the report prints the size line and every rect")
	assert(A.report(390, 844)[1]:find("older play screen", 1, true))
	local D = require(script.Parent.Parent.Engine.DebugGotoRules)
	local t = D.parse("audit:v2")
	assert(t and t.kind == "audit", "DebugGoto audit:v2 parses")
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local c = f:read("a"); f:close(); return c end
	local studio = read("src/Client/AuditV2.lua")
	assert(studio:find("IsStudio", 1, true) and read("src/Client/DebugGoto.lua"):find("AuditV2", 1, true), "Studio only, reachable from DebugGoto")
end })

table.insert(tests, { name = "Patron power disc: only the figure (at most 5 characters, never the unit), 48 px disc on a roomy card, text 20 px unscaled and clipped, Studio warning when text is wider than the disc", fn = function()
	local T = require(script.Parent.Parent.Engine.PatronTierStyle)
	local V = require(script.Parent.Parent.Engine.PatronValueText)
	for _, pair in ipairs({ { "+1 Chips", "+1" }, { "+4 Mult", "+4" }, { "x1.1 Mult", "x1.1" }, { "+3 Mult", "+3" }, { "+15 Chips", "+15" }, { "x1.5 Mult", "x1.5" }, { "+100 Chips", "+100" } }) do
		assert(T.numeral(pair[1]) == pair[2], pair[1] .. " shows as " .. pair[2] .. ", got " .. T.numeral(pair[1]))
	end
	assert(T.numeral("+1 Tip") == "+1" and T.numeral("") == "" and T.numeral(nil) == "" and T.numeral("Retrigger") == "Retri", "no figure: cut to five characters")
	for _, d in ipairs({ "+1 Chips and more", "Earn 4 Tips at the end", "Draw 1 more card each hand", "x2.25 Mult for pairs", "+4 Mult per Heart" }) do
		local v = V.of(d)
		if v then assert(#T.numeral(v) <= T.NUMERAL_MAX, "the figure of '" .. v .. "' is at most five characters") end
	end
	assert(T.discDiameter(157) == 48 and T.discDiameter(105) == 40 and T.discDiameter(58) == 28, "48 px at 1920x1080 card width, scales down")
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local c = f:read("a"); f:close(); return c end
	local fx = read("src/Client/PatronTierFX.lua")
	assert(fx:find("num.TextScaled = false", 1, true) and fx:find("disc.ClipsDescendants = true", 1, true) and fx:find("TextTruncate.None", 1, true), "fixed size, clipped, no truncation marks")
	assert(fx:find("TextBounds.X > disc.AbsoluteSize.X", 1, true) and fx:find("IsStudio", 1, true), "Studio only warning when the text is wider than the disc")
end })

table.insert(tests, { name = "Gameplay v2 synergy hints: a gold thread joins neighbouring Patrons that share a theme, label only in a wide gap, the shop outlines offers that work with an owned Patron", fn = function()
	local S = require(script.Parent.Parent.Engine.Gameplay2Synergy)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	local links = S.links({ "lucky_dice", "regulars_round", "suit_yourself", "all_matching" })
	assert(#links == 2, "pairs link seats 1 and 2, flush links seats 3 and 4, got " .. #links)
	assert(links[1].a == 1 and links[1].b == 2 and links[1].tag == "pairs" and links[1].word ~= "")
	assert(links[2].a == 3 and links[2].b == 4 and links[2].tag == "flush")
	assert(#S.links({ "lucky_dice", "suit_yourself" }) == 0, "different themes do not link")
	assert(#S.links({ "the_regular", "curtain_call" }) == 0, "the flat tag never counts")
	assert(#S.links({ "lucky_dice", nil, "regulars_round" }) == 0 and #S.links({}) == 0 and #S.links({ "lucky_dice" }) == 0, "only neighbours, gaps and single seats give nothing")
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 800, 400 } }) do
		local r = L.rects(sz[1], sz[2])
		local t = S.thread(r, links[1])
		assert(t, "a thread at " .. sz[1])
		local a, b = r.slots[1].card, r.slots[2].card
		assert(t.x == a.x + a.w and t.x + t.w == b.x, "the thread spans exactly the gap")
		assert(t.y >= a.y and t.y + t.h <= a.y + a.h, "at mid height of the cards")
		local gap = b.x - (a.x + a.w)
		assert((t.label ~= nil) == (gap >= 26), "label only in a gap of 26 px or more at " .. sz[1] .. " (gap " .. gap .. ")")
		if t.label then assert(t.label.x >= t.x and t.label.x + t.label.w <= t.x + t.w, "label inside the gap") end
	end
	assert(S.completes({ { tag = "pairs", reason = "Works with a Patron you own." } }) and S.completes({ { reason = "Works with 2 Patrons you own." } }))
	assert(not S.completes({ { reason = "Fits the hand you play most." } }) and not S.completes({}) and not S.completes(nil), "only a real match outlines the offer")
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local c = f:read("a"); f:close(); return c end
	assert(read("src/Client/ShopCards.lua"):find("SynergyGlow", 1, true) and read("src/Client/Gameplay2.lua"):find("Gameplay2SynergyFX", 1, true), "wired")
	assert(not read("src/Client/Gameplay2SynergyFX.lua"):find("TweenService", 1, true), "static, so Calm mode is the same")
end })

table.insert(tests, { name = "Gameplay v2 hand preview: name, level, chips and mult from the real preview, No score when a rule zeroes it, pill on top of the stage clear of the Patron pills", fn = function()
	local P = require(script.Parent.Parent.Engine.Gameplay2Preview)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	assert(P.line({ name = "Flush", chips = 50.4, mult = 6 }, 2) == "Flush Lv 2  |  50 Chips x 6 Mult", "numbers are floored, level shown")
	assert(P.line({ name = "Pair", chips = 10, mult = 2 }, nil) == "Pair Lv 1  |  10 Chips x 2 Mult" and P.line({ name = "Pair", chips = 0, mult = 0 }, 3) == "Pair Lv 3  |  No score")
	assert(P.line(nil, 1) == nil and P.line({}, 1) == nil)
	assert(P.levelOf({ Flush = 4 }, "Flush") == 4 and P.levelOf({}, "Flush") == 1 and P.levelOf(nil, "Flush") == 1)
	local HP = require(script.Parent.Parent.Engine.HandPreview)
	assert(HP.compute(nil, { 1 }) == nil, "no view, no preview (the line follows the real preview only)")
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 800, 400 } }) do
		local r = L.rects(sz[1], sz[2])
		local text = P.line({ name = "Straight Flush", chips = 150, mult = 12 }, 12)
		local pr = P.rect(r.stage, text)
		assert(pr.w <= r.stage.w and pr.x >= r.stage.x and pr.x + pr.w <= r.stage.x + r.stage.w and pr.y == r.stage.y and pr.h == 26, "pill inside the stage top at " .. sz[1])
		for i = 1, 5 do
			local pill = r.slots[i].pill
			assert(pr.y >= pill.y + pill.h, "pill under Patron pill " .. i .. " at " .. sz[1])
		end
		assert(pr.y + pr.h <= r.hand.y, "pill above the hand at " .. sz[1])
	end
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local c = f:read("a"); f:close(); return c end
	assert(read("src/Client/Gameplay2.lua"):find("PreviewPill", 1, true) and read("src/Client/init.client.lua"):find("Gameplay2).setPreview", 1, true), "wired to the hub's preview")
	-- one preview only: the older Concept T box ("<chips> Chips x <mult> Mult") stays hidden while the v2 table is up
	local pr = read("src/Client/PatronRow.lua")
	local fn = pr:match("function M%.placePill%(%).-\nend\n") or ""
	assert(fn:find("Gameplay2", 1, true) and fn:find("not v2", 1, true), "PatronRow.placePill hides the old preview box on the v2 table")
	assert(read("src/Client/Gameplay2.lua"):find("PreviewRules.H", 1, true), "the caption row is as tall as the preview pill")
end })

table.insert(tests, { name = "Gameplay v2 centre: the preview pill never touches the score numeral, line or progress text at three sizes", fn = function()
	local P = require(script.Parent.Parent.Engine.Gameplay2Preview)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 800, 400 } }) do
