table.insert(tests, { name = "Gameplay v2 sound pass: every moment plays an existing cue with an id from a real call site, volumes stay in 0..1 at every slider step, Mute and a zero slider are silent", fn = function()
	local G = require(script.Parent.Parent.Engine.Gameplay2Sound)
	local S = require(script.Parent.Parent.Engine.SoundIds)
	local SFX = require(script.Parent.Parent.Engine.SoundFX)
	assert(#G.MOMENTS >= 11)
	for _, m in ipairs(G.MOMENTS) do
		local cue = S.Cues[m.cue]
		assert(cue, m.moment .. ": the cue " .. m.cue .. " exists in SoundIds")
		assert(cue.id ~= "" and cue.id:find("^rbxassetid://%d+$"), m.moment .. ": the cue has a real id")
		assert(cue.volume > 0 and cue.volume <= 1, m.moment .. ": cue volume in range")
		for _, step in ipairs(G.SLIDER_STEPS) do
			local v = G.effective(cue.volume, 3, step, false)
			assert(v >= 0 and v <= 1, m.moment .. ": volume stays in 0..1 at slider " .. step)
			if step == 0 then assert(v == 0, "slider at zero is silent") end
		end
		assert(G.effective(cue.volume, 1, 1, true) == 0, m.moment .. ": Mute is silent")
	end
	assert(G.effective(0.5, 1, 0.5, false) == 0.25 and G.effective(0.9, 3, 1, false) == 1)
	-- the score tick rises 1.0 to 1.3 and no cue repeats faster than its cooldown
	assert(math.abs(SFX.tickSpeed(1) - 1.0) < 1e-9 and math.abs(SFX.tickSpeed(11) - 1.3) < 1e-9, "score_tick pitch ladder 1.0 to 1.3")
	assert(SFX.minInterval("hover") >= 0.05 and SFX.minInterval("score_tick") >= 0.03, "per cue cooldowns")
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local c = f:read("a"); f:close(); return c end
	for _, m in ipairs(G.MOMENTS) do
		assert(read(m.file):find(m.marker, 1, true), m.moment .. ": " .. m.file .. " has the call site " .. m.marker)
	end
end })

table.insert(tests, { name = "Gameplay v2 pass 21 to 23: GuiObject count under 1,500, every table effect on FxLoop, text 12 px or more, silent cues keep their call site", fn = function()
	local P = require(script.Parent.Parent.Engine.Gameplay2Perf)
	local G = require(script.Parent.Parent.Engine.Gameplay2Sound)
	local S = require(script.Parent.Parent.Engine.SoundIds)
	local FX = require(script.Parent.Parent.Engine.SoundFX)
	assert(P.LIMIT == 1500 and P.verdict(100) == "ok" and P.verdict(1200) == "warn" and P.verdict(1500) == "over")
	local tree = { Children = { { ClassName = "Frame", Visible = true, Children = { { ClassName = "TextLabel", Visible = true, Children = {} }, { ClassName = "UICorner", Children = {} } } },
		{ ClassName = "Frame", Visible = false, Children = { { ClassName = "TextLabel", Visible = true, Children = {} } } } } }
	assert(P.count(tree, false) == 4 and P.count(tree, true) == 3, "invisible branches are not counted on screen")
	for _, m in ipairs(G.SILENT_OK) do
		assert(S.Cues[m.cue] and FX.EMPTY_OK[m.cue], m.moment .. ": a real cue that is allowed to stay silent")
	end
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local c = f:read("a"); f:close(); return c end
	for _, m in ipairs(G.SILENT_OK) do assert(read(m.file):find(m.marker, 1, true), m.moment .. ": call site") end
	for _, path in ipairs(P.LOOP_FILES) do
		local src = read(path)
		local bad = P.forbiddenLoop(src)
		assert(not bad, path .. " starts a repeating effect outside FxLoop: " .. tostring(bad))
		for size in src:gmatch("TextSize = (%d+)") do assert(tonumber(size) >= P.MIN_TEXT, path .. ": text under 12 px") end
	end
	assert(read("src/Client/GuidedHint.lua"):find("FxLoop.add", 1, true), "the guide pulse runs on FxLoop")
	assert(read("src/Client/AuditV2.lua"):find("Gameplay2Perf", 1, true), "AuditV2 prints the GuiObject count")
end })

table.insert(tests, { name = "Gameplay v2 quick controls: Quick view and writes stay pure, the loose Mute and Calm plates are gone and one 44 px gear sits top right", fn = function()
	local Q = require(script.Parent.Parent.Engine.Gameplay2Quick)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	local off = Q.view({})
	assert(off.mute.text == "Mute" and off.mute.kind == "secondary" and not off.mute.on and off.calm.text == "Calm" and off.calm.kind == "secondary")
	local on = Q.view({ muted = true, reduceMotion = true, reduceFlashing = true, reduceShake = true })
	assert(on.mute.text == "Muted" and on.mute.kind == "primary" and on.calm.text == "Calm On" and on.calm.kind == "primary", "state is a word and a green plate, never colour alone")
	assert(Q.view({ reduceMotion = true }).calm.on == false, "one of the three is not Calm Mode")
	assert(Q.muteWrites({}).muted == true and Q.muteWrites({ muted = true }).muted == false)
	local w1 = Q.calmWrites({})
	assert(w1.reduceMotion == true and w1.reduceFlashing == true and w1.reduceShake == true, "Calm turns the three on together")
	local w2 = Q.calmWrites({ reduceMotion = true, reduceFlashing = true, reduceShake = true })
	assert(w2.reduceMotion == false and w2.reduceFlashing == false and w2.reduceShake == false, "and off together")
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1024, 600 }, { 800, 400 }, { 844, 390 } }) do
		local r = L.rects(sz[1], sz[2])
		assert(r.mute == nil and r.calm == nil, "no loose Mute or Calm plates at " .. sz[1])
		assert(r.gear and r.gear.h >= 44 and r.gear.w >= 44, "44 px gear at " .. sz[1])
		assert(r.gear.y >= 60 and r.gear.x + r.gear.w <= sz[1], "gear below Roblox's top bar and on screen at " .. sz[1])
		assert(#L.overlaps(r) == 0, "no overlaps with the table at " .. sz[1] .. ": " .. table.concat(L.overlaps(r), ","))
		local ok = L.onScreen(r, sz[1], sz[2])
		assert(ok, "on screen at " .. sz[1])
	end
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local c = f:read("a"); f:close(); return c end
	local g = read("src/Client/Gameplay2.lua")
	assert(not g:find("MuteButton", 1, true) and not g:find("CalmButton", 1, true) and g:find("GearMenu", 1, true), "the table has no loose plates, the gear module is installed")
end })

table.insert(tests, { name = "Boss round table: one boss plate after the intro, clear of Patrons, hints, score and hand, hints dodge it and wait for the intro", fn = function()
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	local M = require(script.Parent.Parent.Engine.Gameplay2Moments)
	local H = require(script.Parent.Parent.Engine.RoundHints)
	local function hit(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1506, 751 } }) do
		local w, h = sz[1], sz[2]
		local r = L.rects(w, h)
		local rp = M.rulePlate(r)
		expectTrue(rp ~= nil, "the one boss plate fits at " .. w .. "x" .. h)
		for i, sl in ipairs(r.slots) do
			for _, part in ipairs({ "card", "label", "pill" }) do expectTrue(not hit(rp, sl[part]), "boss plate clear of Patron seat " .. i .. " " .. part .. " at " .. w) end
		end
		for _, k in ipairs({ "stage", "hand", "bar", "gear", "sortRank", "sortSuit", "deck" }) do expectTrue(not hit(rp, r[k]), "boss plate clear of " .. k .. " at " .. w) end
		local spot = H.place(r, w, h, { rp })
		if spot then
			expectTrue(not hit(spot.plate, rp) and not hit(spot.button, rp), "the hint plate and its button never touch the boss plate at " .. w)
			for i, sl in ipairs(r.slots) do expectTrue(not hit(spot.plate, sl.card) and not hit(spot.plate, sl.pill), "hint clear of Patron seat " .. i .. " at " .. w) end
			expectTrue(not hit(spot.plate, r.hand) and not hit(spot.plate, r.stage), "hint clear of hand and stage at " .. w)
		end
	end
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local c = f:read("a"); f:close(); return c end
	local fx = read("src/Client/Gameplay2MomentsFX.lua")
	expectTrue(fx:find('Instance.new("Frame")\n\t\tbanner.Name = "BossBanner"', 1, true) == nil and fx:find("banner:Destroy()", 1, true), "the BossBanner strip is never built, an old one is removed")
	expectTrue(read("src/Client/BossFight.lua"):find('root:FindFirstChild("Gameplay2")', 1, true), "the old top bar boss plate and medallion stay hidden on the v2 table")
	local hints = read("src/Client/RoundHintsFX.lua")
	expectTrue(hints:find('FindFirstChild("BossIntro")', 1, true) and hints:find('FindFirstChild("BossRulePlate")', 1, true), "hints wait for the boss intro and dodge the rule plate")
end })

