table.insert(tests, { name = "Gear toggles: Calm, Reduce motion, Sound, Music and Hints take effect at once and persist through the profile, looping FX re-check Calm every tick", fn = function()
	local G = require(script.Parent.Parent.Engine.GearMenu)
	local A = require(script.Parent.Parent.Engine.Accessibility)
	local PP = require(script.Parent.Parent.Engine.PlayerProfile)
	local prof = PP.new()
	local function apply(id)
		-- what the client does: read the live settings, take the writes, set each key (the server stores the same through setSetting)
		local cur = {}
		for k, v in pairs(prof.settings) do cur[k] = v end
		for k, v in pairs(G.writes(id, cur)) do
			local ok, msg = PP.setSetting(prof, k, v)
			expectTrue(ok or msg == "Unchanged", "setting " .. k .. " accepted by the profile: " .. tostring(msg))
		end
	end
	expectTrue(not A.calm(prof.settings), "calm is off at the start")
	apply("calm")
	expectTrue(A.calm(prof.settings) and G.view(prof.settings).calm.on and G.duration(A.calm(prof.settings)) == 0, "Calm on: motion off at once, drop down has no slide")
	expectTrue(prof.settings.reduceMotion and prof.settings.reduceFlashing and prof.settings.reduceShake, "Calm sets all three")
	apply("calm")
	expectTrue(not A.calm(prof.settings) and G.duration(false) > 0, "Calm off: motion is back")
	apply("reduceMotion")
	expectTrue(A.calm(prof.settings) and G.view(prof.settings).reduceMotion.state == "On", "Reduce motion alone also reads as calm for every loop")
	apply("reduceMotion")
	expectTrue(not A.calm(prof.settings), "Reduce motion off: back")
	apply("sound"); expectTrue(prof.settings.sfxVolume == 0 and not G.view(prof.settings).sound.on, "Sound off writes sfxVolume 0")
	apply("sound"); expectTrue(prof.settings.sfxVolume == 1 and G.view(prof.settings).sound.on, "Sound on writes 1")
	apply("music"); expectTrue(prof.settings.musicVolume == 0 and not G.view(prof.settings).music.on, "Music off writes musicVolume 0")
	apply("music"); expectTrue(prof.settings.musicVolume == G.MUSIC_DEFAULT, "Music on restores the default")
	apply("hints"); expectTrue(prof.settings.roundHints == false, "Hints off")
	apply("hints"); expectTrue(prof.settings.roundHints == true, "Hints on")
	-- persistence: the saved profile comes back with the toggles as left
	apply("calm"); apply("music")
	local back = PP.migrate(prof)
	expectTrue(back.settings.reduceMotion == true and back.settings.reduceShake == true and back.settings.musicVolume == 0, "saved toggles survive a reload")
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local c = f:read("a"); f:close(); return c end
	expectTrue(read("src/Client/Gameplay2FeelFX.lua"):find("switched on mid run", 1, true), "the legal move glow loop stops itself when Calm switches on")
	expectTrue(read("src/Client/GuidedHint.lua"):find("Calm mode switched on: a steady outline", 1, true), "the guided pulse stops itself")
	expectTrue(read("src/Client/RoomLights.lua"):find("wasCalm", 1, true), "room glows settle to still values at once")
	expectTrue(read("src/Client/GearMenu.lua"):find("G.duration(calm())", 1, true), "the drop down reads Calm live each time it opens")
end })

table.insert(tests, { name = "Gear menu: one 44 px gear top right, a 280 px menu that stays on screen and clear of other plates, toggles flip real settings, one menu at a time, Calm skips the slide", fn = function()
	local G = require(script.Parent.Parent.Engine.GearMenu)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	local P = require(script.Parent.Parent.Engine.PlayerProfile)
	local function hit(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1024, 600 }, { 844, 390 }, { 800, 400 }, { 720, 360 } }) do
		local w, h = sz[1], sz[2]
		local g, m = G.gearRect(w, h), G.menuRect(w, h)
		expectTrue(g.w >= 44 and g.h >= 44 and g.y >= 60 and g.x + g.w <= w, "gear is 44 px, under the top bar, on screen at " .. w)
		expectTrue(m.x >= 0 and m.y >= g.y + g.h and m.x + m.w <= w and m.y + m.h <= h, "menu fully on screen below the gear at " .. w .. "x" .. h)
		expectTrue(m.w <= 280 and m.w >= 200, "menu about 280 wide at " .. w)
		for _, rr in ipairs(G.rowRects(m)) do expectTrue(rr.h >= 44 and rr.x >= 0 and rr.x + rr.w <= m.w, rr.id .. " row is 44 px and inside the menu at " .. w) end
		local r = L.rects(w, h)
		if L.fits(w, h) then
			expectTrue(not hit(g, r.bar), "gear clear of the top bar at " .. w)
			for i, sl in ipairs(r.slots) do expectTrue(not hit(g, sl.card) and not hit(g, sl.label) and not hit(g, sl.pill), "gear clear of Patron seat " .. i .. " at " .. w) end
			expectTrue(not hit(g, r.stage) and not hit(g, r.hand) and not hit(g, r.deck), "gear clear of stage, hand and deck at " .. w)
		end
	end
	local ids = {}
	for _, row in ipairs(G.ROWS) do ids[row.id] = row.kind end
	expectTrue(ids.sound == "toggle" and ids.music == "toggle" and ids.calm == "toggle" and ids.reduceMotion == "toggle" and ids.hints == "toggle", "five toggles")
	expectTrue(ids.pause == "action" and ids.howTo == "action" and ids.quit == "action", "three actions")
	local s = P.defaultSettings()
	local v = G.view(s)
	expectTrue(v.sound.state == "On" and v.music.state == "On" and v.calm.state == "Off" and v.reduceMotion.state == "Off" and v.hints.state == "On", "defaults read as words")
	local function apply(id) for k, val in pairs(G.writes(id, s)) do expectTrue(P.SETTING_SPECS[k] ~= nil, k .. " is a real setting"); s[k] = val end end
	apply("sound"); expectTrue(G.view(s).sound.state == "Off" and s.sfxVolume == 0, "Sound off"); apply("sound"); expectTrue(G.view(s).sound.on and s.sfxVolume == 1, "Sound back on")
	apply("music"); expectTrue(G.view(s).music.state == "Off" and s.musicVolume == 0, "Music off"); apply("music"); expectTrue(G.view(s).music.on and s.musicVolume > 0, "Music back on")
	apply("calm"); expectTrue(G.view(s).calm.on and s.reduceMotion and s.reduceFlashing and s.reduceShake, "Calm flips the three together"); apply("calm"); expectTrue(not G.view(s).calm.on and not s.reduceMotion, "and back")
	apply("reduceMotion"); expectTrue(s.reduceMotion == true and G.view(s).reduceMotion.state == "On", "Reduce motion"); apply("reduceMotion")
	apply("hints"); expectTrue(s.roundHints == false and G.view(s).hints.state == "Off", "Hints off"); apply("hints"); expectTrue(s.roundHints == true, "Hints on")
	expectTrue(next(G.writes("pause", s)) == nil and next(G.writes("quit", s)) == nil, "actions write no setting")
	expectTrue(G.duration(true) == 0 and G.duration(false) == 0.15, "Calm mode and Reduce motion slide in at once")
	expectTrue(G.visibleOn({ root = true, table = true }) and G.visibleOn({ root = true, counter = true }) and G.visibleOn({ root = true, map = true }), "table, Counter and Night map show the gear")
	expectTrue(not G.visibleOn({ root = false, table = true }) and not G.visibleOn({ root = true }) and not G.visibleOn({ root = true, table = true, popup = true }), "never on the Menu, a bare root or under a popup")
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local c = f:read("a"); f:close(); return c end
	local c = read("src/Client/GearMenu.lua")
	expectTrue(c:find("OverlayManager.open(\"settings\")", 1, true) and c:find("ClientSettings.set(k, val)", 1, true), "the menu reuses the real settings and pause backends")
	expectTrue(c:find("KeyCode.Escape", 1, true) == nil and c:find("PopupDismiss", 1, true), "Escape goes through PopupDismiss")
	expectTrue(c:find("G.duration(calm())", 1, true), "the slide is skipped in Calm mode")
	expectTrue(read("src/Client/Gameplay2.lua"):find("GearMenu", 1, true), "installed by the table, shared by the Counter and Night map through the root")
end })

table.insert(tests, { name = "Gameplay v2 polish run: every whole-picture plate keeps its art's shape (within 45 percent), nothing overlaps its neighbours, text size fits the inner height at six sizes", fn = function()
	local E = script.Parent.Parent.Engine
	local L, S = require(E.Gameplay2Layout), require(E.TavernStyle)
	local plates = { { "target", "wh_target" }, { "tips", "wh_target" }, { "round", "wh_scroll" }, { "playCount", "wh_small" }, { "discardCount", "wh_small" }, { "deckCount", "wh_count" }, { "sortRank", "wh_btn_sq" }, { "sortSuit", "wh_btn_sq" } }
	local function hit(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1506, 751 }, { 1024, 600 }, { 844, 390 }, { 800, 400 } }) do
		local w, h = sz[1], sz[2]
		local r = L.rects(w, h)
		local seen = {}
		for _, pr in ipairs(plates) do
			local rc, def = r[pr[1]], S.PAINTED[pr[2]]
			if rc and def then
				local want, got = def.src[1] / def.src[2], rc.w / rc.h
				-- Rank and Suit are square buttons drawn from a wide picture; they only have to be a sane button, the rest keep the art's shape
				if pr[1] ~= "sortRank" and pr[1] ~= "sortSuit" then
					expectTrue(got / want > 0.55 and got / want < 1.45, pr[1] .. " stays near its art shape at " .. w .. "x" .. h .. " (" .. string.format("%.2f vs %.2f", got, want) .. ")")
				end
				-- (the slim bar is at most 8 percent of the height, so on a 390 px phone a plate is 18 px: 14 px text with 2 px above and below)
				expectTrue(rc.h >= 14 + 2 * 2, pr[1] .. " is tall enough for 14 px text with 2 px padding at " .. w)
				seen[#seen + 1] = { pr[1], rc }
			end
		end
		for i = 1, #seen do for j = i + 1, #seen do
			expectTrue(not hit(seen[i][2], seen[j][2]), seen[i][1] .. " and " .. seen[j][1] .. " overlap at " .. w .. "x" .. h)
		end end
	end
end })

table.insert(tests, { name = "Gear menu quick buttons: speaker and Pause sit at the top left, 44 px, on screen, apart from the gear and the menu and the Gameplay v2 pieces at six sizes", fn = function()
	local E = script.Parent.Parent.Engine
	local G, L = require(E.GearMenu), require(E.Gameplay2Layout)
	local function hit(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1506, 751 }, { 1024, 600 }, { 844, 390 }, { 800, 400 } }) do
		local w, h = sz[1], sz[2]
		local q, g, m = G.quickRects(w, h), G.gearRect(w, h), G.menuRect(w, h)
		expectTrue(q.speaker.x >= 0 and q.pause.x + q.pause.w < g.x and q.speaker.x + q.speaker.w + G.QUICK_GAP <= q.pause.x and q.speaker.y == g.y, "row order and gap, top left " .. w)
		expectTrue(q.speaker.w >= 44 and q.speaker.h >= 44 and q.pause.h >= 44, "44 px targets " .. w)
		expectTrue(not hit(q.speaker, g) and not hit(q.pause, g) and not hit(q.speaker, m) and not hit(q.pause, m), "clear of gear and menu " .. w)
		local r = L.rects(w, h)
		for _, k in ipairs({ "target", "round", "tips", "traySlot1", "traySlot2", "trayUse", "traySell" }) do
			if r[k] then
				expectTrue(not hit(q.speaker, r[k]) and not hit(q.pause, r[k]), "quick buttons clear of " .. k .. " at " .. w)
			end
		end
	end
	if not io then return end
	local f = assert(io.open("src/Client/GearMenu.lua", "r")); local c = f:read("a"); f:close()
	expectTrue(c:find("pk_w_icon_speaker", 1, true) and c:find("pk_w_icon_pause", 1, true) and c:find('G.writes("sound"', 1, true), "speaker toggles Sound, both use the painted icons")
end })

table.insert(tests, { name = "Gameplay v2 consumables tray: two Recipe slots at the top left, Use and Sell plates, 44 px targets, no overlaps at six sizes, names fit in two lines, use flow and sell rules", fn = function()
	local E = script.Parent.Parent.Engine
	local T, L, Recipes, RS = require(E.Gameplay2Tray), require(E.Gameplay2Layout), require(E.Recipes), require(E.RunState)
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1024, 600 }, { 844, 390 }, { 800, 400 }, { 720, 360 } }) do
		local r = L.rects(sz[1], sz[2])
		if sz[2] > 360 then for _, k in ipairs(L.TRAY_CONTROLS) do assert(r[k], k .. " exists at " .. sz[1] .. "x" .. sz[2]) end end
		if not r.traySlot1 then assert(sz[2] <= 360, "only the shortest screen goes without the tray")end
		if r.traySlot1 then
			for _, k in ipairs(L.TRAY_CONTROLS) do
				assert(r[k], k .. " exists at " .. sz[1] .. "x" .. sz[2])
				assert(r[k].h >= 44 and r[k].w >= 44, k .. " is a 44 px target at " .. sz[1])
			end
			assert(r.traySlot1.y >= 60 and r.traySlot2.x + r.traySlot2.w < r.gear.x, "tray starts under the top bar and is clear of the gear at " .. sz[1])
			assert(r.traySlot2.x + r.traySlot2.w < r.slots[1].card.x, "tray is clear of the first Patron at " .. sz[1])
			assert(r.trayUse.y + r.trayUse.h < r.sortRank.y, "tray is above Rank and Suit at " .. sz[1])
			assert(#L.overlaps(r) == 0, "no overlaps at " .. sz[1] .. ": " .. table.concat(L.overlaps(r), ","))
			assert(L.onScreen(r, sz[1], sz[2]), "on screen at " .. sz[1])
			if r.trayPrompt then assert(r.trayPrompt.h >= 44 and r.trayPrompt.y > r.trayUse.y, "prompt plate is the third row") end
			local inner = r.traySlot1.w - 8
			local all = {}
			for _, list in ipairs({ Recipes.HouseRecipes, Recipes.MenuRecipes, Recipes.SecretRecipes }) do
				for _, def in ipairs(list) do
					assert(T.lines(T.label(def.name), inner) <= 2, def.name .. " fits two lines in a " .. r.traySlot1.w .. " px slot at " .. sz[1])
				end
			end
		end
	end
	-- held view: first two of the three boxes, a faint empty slot, the extra count
	local st = { houseRecipeInventory = { "suit_swap" }, menuRecipeInventory = {}, secretRecipeInventory = {} }
	local h = T.held(st)
	assert(h.slots[1].id == "suit_swap" and h.slots[1].needsSuit and h.slots[1].need.max == 3 and h.slots[1].tier == "Common" and h.slots[2].empty and h.more == 0)
	assert(h.slots[1].sell == math.floor(Recipes.getHouseRecipeById("suit_swap").price / 2), "sell value is half the price")
	assert(T.held({ houseRecipeInventory = { "suit_swap", "suit_swap", "suit_swap" } }).more == 1, "a third is counted, not drawn")
	-- the use flow
	local slot = h.slots[1]
	assert(T.flow({ empty = true }, 0, nil, false).phase == "empty" and T.flow(slot, 0, nil, false).phase == "idle")
	local f0 = T.flow(slot, 0, "Hearts", true)
	assert(f0.phase == "pick" and not f0.canUse and f0.prompt == "Pick 1 to 3 cards", "asks for cards first: " .. f0.prompt)
	local f2 = T.flow(slot, 2, "Clubs", true)
	assert(f2.phase == "ready" and f2.canUse and f2.useText == "Use Clubs" and f2.prompt:find("Suit: Clubs", 1, true), "a suit recipe shows its suit")
	assert(not T.flow(slot, 4, "Clubs", true).canUse, "too many cards")
	assert(T.label("Double Trouble Recipe") == "Double Trouble" and T.label("Recipe") == "Recipe")
	assert(T.nextSuit("Spades") == "Hearts" and T.nextSuit("Diamonds") == "Spades" and T.nextSuit(nil) == "Spades")
	local cat, id, idx, suit = T.useArgs(slot, { 2, 5 }, "Clubs")
	assert(cat == "house" and id == "suit_swap" and idx[2] == 5 and suit == "Clubs")
	local menuSlot = T.held({ menuRecipeInventory = { Recipes.MenuRecipes[1].id } }).slots[1]
	assert(T.flow(menuSlot, 0, nil, true).canUse and not menuSlot.need, "a Menu Recipe needs no cards")
	local _, _, i2, s2 = T.useArgs(menuSlot, { 1 }, "Clubs")
	assert(i2 == nil and s2 == nil, "no cards or suit are sent when the recipe wants none")
	-- engine rules: use at the table while playing, sell any time a recipe may be used
	assert(RS.phaseAllowsRecipeUse("playing") and RS.phaseAllowsRecipeUse("shop") and not RS.phaseAllowsRecipeUse("roundSelect") and not RS.phaseAllowsRecipeUse("gameover"))
	local run = { tips = 3, houseRecipeInventory = { "suit_swap" }, menuRecipeInventory = {}, secretRecipeInventory = {} }
	assert(not RS.sellRecipe(run, "house", "nope") and not RS.sellRecipe(run, "bad", "suit_swap") and run.tips == 3)
	local ok, refund = RS.sellRecipe(run, "house", "suit_swap")
	assert(ok and refund == slot.sell and run.tips == 3 + refund and #run.houseRecipeInventory == 0, "sold once")
	assert(not RS.sellRecipe(run, "house", "suit_swap"), "never twice")
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local c = f:read("a"); f:close(); return c end
	local server = read("src/Server/init.server.lua")
	assert(server:find("Rem.SellRecipe.OnServerEvent", 1, true) and server:find("phaseAllowsRecipeUse", 1, true), "the server sells and uses by the table rule")
	assert(read("src/Server/Remotes.lua"):find('"SellRecipe"', 1, true) and read("src/Shared/Engine/PreviewGuard.lua"):find("Rem.SellRecipe", 1, true))
	local c = read("src/Client/Gameplay2Tray.lua")
	assert(not c:find("TweenService", 1, true) and not c:find(":Tween", 1, true), "the tray never tweens")
	assert(c:find("TextTruncate.None", 1, true), "names are never cut")
	local bad = (c .. read("src/Shared/Engine/Gameplay2Tray.lua")):lower()
	assert(not bad:find("\u{2014}", 1, true) and not bad:find("balatro", 1, true))
end })

table.insert(tests, { name = "Night intro: shown once per Night and Round while playing, 1.2 s, none in Calm mode, a Boss round keeps its own intro, a tap skips, plate fits every size", fn = function()
	local R = require(script.Parent.Parent.Engine.Gameplay2Moments)
	local J = require(script.Parent.Parent.Engine.JourneyMap)
	local st = { phase = "playing", night = 3, round = 2, targetScore = 1200, handsRemaining = 4 }
	assert(R.nightIntroKey(st) == "3:2" and R.nightIntroKey({ phase = "roundSelect", night = 3, round = 2 }) == nil and R.nightIntroKey({ phase = "shop" }) == nil)
	assert(R.nightIntroKey({ phase = "playing", night = 3, round = 3, bossModifier = { id = "x" } }) == nil, "a Boss round has the boss intro")
	assert(R.nightIntroKey({ phase = "playing", night = 1, round = 1, tutorialStage = 1 }) == nil, "not over the tutorial")
	assert(R.nightIntroKey(st) ~= R.nightIntroKey({ phase = "playing", night = 3, round = 1 }), "each round has its own key")
	assert(R.nightIntro(true, false) == nil and R.nightIntro(true, true) == nil, "none in Calm mode")
	local t = R.nightIntro(false, false)
	assert(math.abs(t.fadeIn + t.hold + t.fade - 1.2) < 1e-9 and t.total == 1.2 and t.dim > 0 and t.dim < 1)
	local f = R.nightIntro(false, true)
	assert(math.abs(f.fadeIn + f.hold + f.fade - 0.6) < 1e-9, "Fast halves it")
	local l = R.nightIntroLines(st, J.getNight(3).name)
	assert(l.title == "Night 3" and l.room == "The Lantern Garden" and l.rule == "Score 1200 in 4 hands.")
	assert(R.nightIntroLines({ night = 1, targetScore = 300, handsRemaining = 1 }, "x").rule == "Score 300 in 1 hand.")
	for _, text in ipairs({ l.title, l.room, l.rule }) do
		assert(not text:find("\u{2014}", 1, true) and not text:find("--", 1, true) and not text:lower():find("balatro", 1, true))
	end
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 844, 390 }, { 720, 360 } }) do
		local p = R.nightIntroPlate(sz[1], sz[2])
		assert(p.x >= 0 and p.y >= 0 and p.x + p.w <= sz[1] and p.y + p.h <= sz[2] and p.h >= 96, "plate on screen at " .. sz[1])
	end
	if not io then return end
	local function read(path) local f2 = assert(io.open(path, "r")); local c = f2:read("a"); f2:close(); return c end
	local fx = read("src/Client/NightIntroFX.lua")
	assert(fx:find("MouseButton1Click", 1, true) and fx:find("Rules.nightIntro(calm()", 1, true), "a tap skips and Calm asks the rules")
	assert(fx:find("TextTruncate.None", 1, true) and fx:find("reduceMotion", 1, true))
	local g = read("src/Client/Gameplay2.lua")
	assert(g:find("NightIntroFX).update", 1, true) and g:find("NightIntroFX).reset", 1, true), "the table drives the intro")
end })

table.insert(tests, { name = "Menu Daily Challenge entry: a Notice Board note with the native green TavernKit Play Daily plate, same start function as the Daily action row, dropped first when the board is crowded", fn = function()
