table.insert(tests, { name = "Patron name strip: every Patron name fits beside the power disc at the card widths of 1920x1080 and 1280x720", fn = function()
	local Fit = require(script.Parent.Parent.Engine.PatronNameFit)
	local Style = require(script.Parent.Parent.Engine.PatronTierStyle)
	local Patrons = require(script.Parent.Parent.Engine.Patrons)
	assert(Fit.MIN_SIZE == 11 and Fit.MAX_SIZE == 16, "11 to 16 px")
	for _, w in ipairs({ 157, 140, 120, 105 }) do
		local r = Fit.rect(w)
		local d = Style.discDiameter(w)
		local discLeft = w - (d - math.floor(d * Style.DISC_OVERLAP_X + 0.5)) -- where the disc starts over the strip
		assert(r.x + r.w <= discLeft, "name ends before the disc at card width " .. w)
		for _, p in ipairs(Patrons.Definitions) do
			if w >= 157 then -- 1920x1080 cards: every name shows in full
				assert(Fit.fits(p.name, w), string.format("'%s' (%d px at 11) does not fit %d px at card width %d", p.name, math.floor(Fit.textWidth(p.name, Fit.MIN_SIZE)), r.w, w))
			else -- narrower cards: the label ends with a mark (TextTruncate.AtEnd) and shows at least 10 letters; the tooltip has the full name
				assert(r.w >= Fit.textWidth(string.rep("m", 10), Fit.MIN_SIZE) * 0.9, "room for ten letters at card width " .. w)
			end
		end
	end
	if not io then return end
	local f = assert(io.open("src/Client/PatronRow.lua", "r")); local src = f:read("a"); f:close()
	assert(src:find("NameFit.rect(r.w)", 1, true) and src:find("TextScaled = true", 1, true) and src:find("IsStudio", 1, true), "row sizes the name by its card width and warns in Studio")
end })

table.insert(tests, { name = "Patron parchment seat: every cut card has a portrait window inside its picture, ribbon and portrait never overlap, ink is 4.5:1", fn = function()
	local P = require(script.Parent.Parent.Engine.PatronParchment)
	local Crop = require(script.Parent.Parent.Engine.PatronCardCrop)
	local CardArt = require(script.Parent.Parent.Engine.ConceptTPatronArt)
	local Fit = require(script.Parent.Parent.Engine.PatronNameFit)
	local n = 0
	for key, id in pairs(CardArt) do
		if type(id) == "string" and id ~= "" and key:sub(1, 4) == "ctp_" then
			local r = P.imageRect(key:sub(5))
			assert(r, "no portrait crop for " .. key)
			assert(r.x >= 0 and r.y >= 0 and r.x + r.w <= 1024 and r.y + r.h <= 1536, key .. " crop leaves the picture")
			local aspect = r.w / r.h
			assert(aspect > 0.6 and aspect < 1.0, key .. " crop aspect " .. aspect)
			assert(r.y + r.h <= 1536 * 0.86, key .. " crop reaches the baked name plate")
			n = n + 1
		end
	end
	assert(n >= 81, "all 81 cut cards are covered, got " .. n)
	local c = 0
	for _ in pairs(Crop) do c = c + 1 end
	assert(c >= 81, "crop table has every card")
	local L = P.layout()
	assert(L.portrait.x >= 0 and L.portrait.x + L.portrait.w <= 1 and L.ribbon.x + L.ribbon.w <= 1, "inside the seat")
	assert(L.portrait.h >= 0.9 and L.portrait.y + L.portrait.h >= 0.94, "the portrait runs to the seat bottom inside a thin border")
	assert(L.portrait.y + L.portrait.h > L.ribbon.y and L.portrait.y + L.portrait.h - L.ribbon.y <= 0.2, "the ribbon overlaps the portrait's bottom")
	assert(L.ribbon.y >= 0.8 - 1e-9 and L.ribbon.h <= 0.18, "the ribbon sits in the bottom 20 percent of the seat")
	local TS = require(script.Parent.Parent.Engine.PatronTierStyle)
	for _, w in ipairs({ 157, 105, 58 }) do
		local d = TS.discRect(w, 200)
		assert(d.x + d.w > w and d.x < w and d.y + d.h > 200 and d.y < 200, "the disc overlaps the bottom right corner")
		assert(math.abs((d.x + d.w - w) - d.w / 2) <= 1 and math.abs((d.y + d.h - 200) - d.h / 2) <= 1, "by half")
	end
	assert(L.ribbon.y + L.ribbon.h <= 1, "ribbon inside the seat")
	assert(P.contrast() >= 4.5, "ink on the ribbon: " .. P.contrast())
	for _, w in ipairs({ 157, 140, 120, 105 }) do
		local nr = P.nameRect(w)
		assert(nr.w >= Fit.textWidth(string.rep("m", 9), Fit.MIN_SIZE) * 0.9, "room for nine letters on the ribbon at seat width " .. w)
	end
	if not io then return end
	local f = assert(io.open("src/Client/PatronRow.lua", "r")); local src = f:read("a"); f:close()
	assert(src:find("PatronParchmentCard", 1, true), "the row draws the parchment seat")
	local g = assert(io.open("src/Client/PatronParchmentCard.lua", "r")); local cl = g:read("a"); g:close()
	assert(not cl:find("TweenService", 1, true) and not cl:lower():find("balatro", 1, true), "static, clean")
end })

table.insert(tests, { name = "PatronJuice: each tier adds an effect, Calm mode keeps only the pill text, order and pill text, one FxLoop job, no per particle tween", fn = function()
	local J = require(script.Parent.Parent.Engine.PatronJuice)
	local PE = require(script.Parent.Parent.Engine.PatronEvents)
	local c, u, r, e, l = J.spec("common"), J.spec("uncommon"), J.spec("rare"), J.spec("epic"), J.spec("legendary")
	assert(c.hop == 6 and c.ring == 0 and c.sweep == 0 and c.sparks == 0 and c.rays == 0, "common: a 6 px hop and the pill")
	assert(u.ring > 0 and u.sweep == 0, "uncommon adds the ring")
	assert(r.ring > 0 and r.sweep > 0 and r.sparks == 0, "rare adds the sweep")
	assert(e.sparks == 6 and e.crown > 0 and e.rays == 0, "epic: 6 sparks and a crown flash")
	assert(l.rays == 0.5 and l.edge > 0 and l.sparks == 6, "legendary: rays for 0.5 s and the edge glow")
	assert(l.pill.rise == 24 and l.pill.dur == 0.7, "the pill rises 24 px over 0.7 s")
	for _, tier in ipairs({ "common", "uncommon", "rare", "epic", "legendary" }) do
		local k = J.spec(tier, true)
		assert(k.static and k.hop == 0 and k.ring == 0 and k.sweep == 0 and k.sparks == 0 and k.crown == 0 and k.rays == 0 and k.edge == 0 and k.pill.rise == 0, "calm: text only " .. tier)
		assert(J.spec(tier, false, true).pill.dur < J.spec(tier).pill.dur, "fast halves " .. tier)
	end
	assert(J.tierOf("mythical") == "legendary" and J.tierOf("nonsense") == "common" and J.tierOf("EPIC") == "epic", "tier names")
	assert(J.pillText("chips", 30) == "+30 Chips" and J.pillText("mult", 4) == "+4 Mult" and J.pillText("xmult", 1.5) == "x1.5" and J.pillText("money", 3) == "" and J.pillText("mult", nil) == "", "pill text")
	local o = J.order({ "a", "b", "c", "d" }, { "d", "b" })
	assert(#o == 2 and o[1] == "b" and o[2] == "d", "row order, left to right")
	assert(J.delayOf(1) == 0 and math.abs(J.delayOf(3) - 0.24) < 1e-9, "0.12 s apart")
	assert(PE.gap(false) >= J.SPACING and PE.gap(true) >= J.SPACING, "the scoring beats are at least 0.12 s apart")
	for i = 1, 6 do
		for _, p in ipairs({ 0, 0.5, 1 }) do
			local x, y = J.particle(i, 6, p)
			assert(x > 0 and x < 1.1 and y >= 0.05 and y <= 0.85, "spark stays near the card")
		end
	end
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local src = f:read("a"); f:close(); return src end
	local fx = read("src/Client/PatronJuiceFX.lua")
	assert(fx:find("FxLoop.add", 1, true) and not fx:find("TweenService", 1, true), "one FxLoop job, no tween")
	assert(fx:find("Kit.still()", 1, true), "Calm mode, Reduce motion and Fast are still")
	assert(not fx:find("Active = true", 1, true), "takes no clicks")
	assert(read("src/Client/PatronRow.lua"):find("PatronJuiceFX", 1, true), "the row plays it on the v2 table")
	assert(read("src/Shared/Engine/Gameplay2Perf.lua"):find("PatronJuiceFX.lua", 1, true), "listed in the FxLoop lint")
end })

table.insert(tests, { name = "Gameplay2Flair: better hands get more flair, under 1.2 s, OVERKILL on a one hand kill, name clear of the Patron row, numeral and hand at three sizes, Calm mode text only", fn = function()
	local F = require(script.Parent.Parent.Engine.Gameplay2Flair)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	assert(F.tierOf("Pair") == "plain" and F.tierOf("High Card") == "plain" and F.tierOf("Three of a Kind") == "plain", "pairs plain")
	assert(F.tierOf("Flush") == "wipe" and F.tierOf("Straight") == "wipe", "Flush and Straight")
	assert(F.tierOf("Full House") == "burst" and F.tierOf("Four of a Kind") == "burst", "Full House and Four of a Kind")
	assert(F.tierOf("Straight Flush") == "vignette" and F.tierOf("Royal Flush") == "vignette", "Straight Flush and Royal")
	assert(F.tierOf("Something New") == "plain" and F.tierOf(nil) == "plain", "unknown reads plain")
	local p, w, b, v = F.spec("Pair"), F.spec("Flush"), F.spec("Full House"), F.spec("Straight Flush")
	assert(p.underline == 0 and p.burst == 0 and p.vignette == 0, "plain has only the slam and sweep")
	assert(w.underline > 0 and w.burst == 0 and w.vignette == 0, "wipe adds the underline")
	assert(b.underline > 0 and b.burst > 0 and b.vignette == 0, "burst adds the burst")
	assert(v.underline > 0 and v.burst > b.burst and v.vignette > 0, "vignette adds the gold vignette")
	assert(p.slam.down + p.slam.settle < 0.31, "the slam is 0.3 s")
	for _, n in ipairs({ "Pair", "Flush", "Full House", "Royal Flush" }) do
		assert(F.spec(n).total <= 1.2 and F.spec(n, false, true).total < F.spec(n).total, "under 1.2 s, Fast shorter " .. n)
		local k = F.spec(n, true, false, true)
		assert(k.static and k.slam == nil and k.sweep == 0 and k.underline == 0 and k.burst == 0 and k.vignette == 0 and k.overkill, "calm: text only " .. n)
	end
	assert(F.overkill(900, 600) and F.overkill(600, 600) and not F.overkill(599, 600) and not F.overkill(100, 0) and not F.overkill(nil, 5), "overkill: one hand reaches the Target")
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 800, 400 } }) do
		local r = L.rects(sz[1], sz[2])
		local avoid = 0
		for _, s in ipairs(r.slots) do avoid = math.max(avoid, s.pill.y + s.pill.h, s.label.y + s.label.h) end
		local size = F.fontSize(r.stage, avoid)
		if sz[1] == 1920 then assert(size and size >= 32 and size <= 40, "32 to 40 px at 1920x1080 (the seats sit at the reference height, so the stage is shorter), got " .. tostring(size)) end
		if size then
			assert(size >= F.MIN_FONT and size <= 40, "font range")
			local n = F.nameRect(r.stage, avoid, size)
			assert(n.y >= avoid, string.format("name below the Patron row at %dx%d (%d vs %d)", sz[1], sz[2], n.y, avoid))
			assert(n.y + n.h <= r.stage.y + F.CAPTION + F.OVERLAP, "name stays above the numeral digits")
			assert(n.x >= r.stage.x and n.x + n.w <= r.stage.x + r.stage.w, "inside the stage width")
			assert(n.y + n.h <= r.hand.y and n.y + n.h <= r.play.y, string.format("clear of the hand and Play Hand at %dx%d: name bottom %d, hand %d, play %d, stage %d,%d,%d,%d", sz[1], sz[2], n.y + n.h, r.hand.y, r.play.y, r.stage.x, r.stage.y, r.stage.w, r.stage.h))
			local pr = F.overkillRect(n, r.stage, "Straight Flush", size)
			if pr then
				assert(pr.x >= r.stage.x and pr.x + pr.w <= r.stage.x + r.stage.w and pr.y >= n.y and pr.y + pr.h <= n.y + n.h + 1, "OVERKILL plate inside the name row")
				assert(pr.x >= r.stage.x + r.stage.w / 2 + #"Straight Flush" * size * 0.58 / 2, "plate right of the name")
			end
		end
	end
	assert(F.fontSize({ x = 0, y = 100, w = 400, h = 20 }, 100) == nil, "no room: no flair")
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local src = f:read("a"); f:close(); return src end
	local fx = read("src/Client/Gameplay2FlairFX.lua")
	assert(fx:find("FxLoop.add", 1, true) and not fx:find("TweenService", 1, true) and fx:find("Kit.still()", 1, true), "one FxLoop job, no tween, still in Calm mode")
	assert(fx:find("InputBegan", 1, true) and fx:find("Active = false", 1, true), "a tap skips it, it takes no clicks")
	assert(read("src/Client/ScorePopup.lua"):find("Gameplay2).flair(preview)", 1, true), "played hands call the flair")
	assert(read("src/Shared/Engine/Gameplay2Perf.lua"):find("Gameplay2FlairFX.lua", 1, true), "listed in the FxLoop lint")
end })

table.insert(tests, { name = "Gameplay2Flair: the name sits on a dark banner inside the stage, Chips and Mult plates flank it on the same row when they fit, never over the hand or Patron row, at five sizes", fn = function()
	local F = require(script.Parent.Parent.Engine.Gameplay2Flair)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	local plated = 0
	for _, sz in ipairs({ { 1920, 1080 }, { 1506, 751 }, { 1280, 720 }, { 1024, 600 }, { 800, 450 } }) do
		local r = L.rects(sz[1], sz[2])
		local avoid = 0
		for _, s in ipairs(r.slots) do avoid = math.max(avoid, s.pill.y + s.pill.h, s.label.y + s.label.h) end
		local size = F.fontSize(r.stage, avoid)
		if size then
			local n = F.nameRect(r.stage, avoid, size)
			local b = F.bannerRect(n, r.stage, "Straight Flush", size)
			assert(b.x >= r.stage.x and b.x + b.w <= r.stage.x + r.stage.w and b.y == n.y and b.h == n.h, "banner inside the stage and the name row")
			assert(b.y >= avoid and b.y + b.h <= r.hand.y and b.y + b.h <= r.play.y, "banner clear of the Patron row, hand and Play Hand")
			local p = F.sidePlates(b, r.stage)
			if p then
				plated = plated + 1
				assert(p.chips.x + p.chips.w + F.SIDE_GAP <= b.x and p.mult.x >= b.x + b.w + F.SIDE_GAP, "plates beside the banner, not over it")
				assert(p.chips.x >= r.stage.x and p.mult.x + p.mult.w <= r.stage.x + r.stage.w, "plates inside the stage")
				assert(p.chips.y >= n.y and p.chips.y + p.chips.h <= n.y + n.h and p.mult.y == p.chips.y, "plates on the name row")
			end
		end
	end
	assert(plated >= 1, "at least one size has room for the plates")
	local c, m = F.sideText(126.4, 3.6)
	assert(c == "126 Chips" and m == "x 4 Mult", "whole numbers")
	assert(F.sidePlates({ x = 10, y = 0, w = 300, h = 30 }, { x = 0, y = 0, w = 320, h = 30 }) == nil, "no room, no plates")
	if not io then return end
	local f = assert(io.open("src/Client/Gameplay2FlairFX.lua", "r")); local fx = f:read("a"); f:close()
	assert(fx:find("NameBanner", 1, true) and fx:find("ChipsPlate", 1, true) and fx:find("MultPlate", 1, true), "banner and both plates are drawn")
	assert(not fx:find("Transparency = ColorSequence", 1, true) and not fx:find("TweenService", 1, true), "no tween, Color-only gradient")
end })

table.insert(tests, { name = "CardLook: selected cards wear a thin warm gold edge (no cyan or white), the corner rank is at least 18 px at 1280x720 and never under the 15 px floor", fn = function()
	local C = require(script.Parent.Parent.Engine.CardLook)
	local A = require(script.Parent.Parent.Engine.Gameplay2Audit)
	assert(not C.isCoolGlow(C.EDGE_RGB), "the edge is warm gold")
	assert(C.isCoolGlow({ 120, 220, 255 }) and C.isCoolGlow({ 250, 250, 250 }) and not C.isCoolGlow({ 255, 214, 130 }), "cool and white glows are detected")
	local sel, both, hov, rest = C.edge(true, false), C.edge(true, true), C.edge(false, true), C.edge(false, false)
	assert(sel.thickness == 2 and sel.transparency == 0, "selected: a 2 px solid edge")
	assert(both.thickness == 3 and both.thickness <= 3, "selected and hovered: at most 3 px")
	assert(hov.thickness < sel.thickness and hov.transparency >= 0.5, "hover is fainter than selected")
	assert(rest.transparency == 1, "a resting card has no edge")
	for _, e in ipairs({ sel, both, hov, rest }) do assert(e.rgb == C.EDGE_RGB and e.thickness <= 3, "gold and thin") end
	for _, sz in ipairs(A.SIZES) do
		local a = A.audit(sz[1], sz[2])
		if a.fits then
			local px = C.rankPx(a.handCard.w, a.handCard.h)
			assert(px >= C.RANK_FLOOR, "rank floor at " .. sz[1])
			if sz[1] >= 1280 then assert(px >= C.MIN_RANK_1280, string.format("rank %d px at %dx%d, under 18", px, sz[1], sz[2])) end
		end
	end
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local src = f:read("a"); f:close(); return src end
	local face = read("src/Client/CardFace.lua")
	assert(face:find("UDim2.fromScale(0.36, 0.18)", 1, true) and face:find("MinTextSize = 18", 1, true), "CardLook mirrors the CardFace index box and floor")
	assert(read("src/Client/init.client.lua"):find('WaitForChild("CardLook")', 1, true), "the hub draws the selection edge from CardLook")
	local pal = read("src/Client/Palette.lua")
	assert(pal:find("cardSelected", 1, true), "palette unchanged")
end })

table.insert(tests, { name = "Counter summary plate: top right under the corner buttons, inside the screen, quest toasts start 8 px under it, wired once", fn = function()
	local S = require(script.Parent.Parent.Engine.ShopSummary)
	local T = require(script.Parent.Parent.Engine.CornerToastRules)
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1024, 600 }, { 844, 390 } }) do
		local r = S.rect(sz[1], sz[2])
		assert(r.x >= 0 and r.x + r.w <= sz[1] - S.EDGE + 0.5 and r.y >= 66 and r.w <= 300, "plate inside the corner at " .. sz[1])
		local plan = T.plan("shop")
		T.below(plan, sz[1], S.keepOut(sz[1], sz[2]))
		assert(T.slot(sz[1], sz[2], plan, 1).y >= r.y + r.h + S.TOAST_GAP, "toasts start under the plate at " .. sz[1])
	end
	local l = S.lines({ title = "Target cleared", score = "Score 900 of 600", tips = "Tips +7" })
	assert(l.score == "Score 900 of 600" and l.tips == "Tips +7" and S.lines(nil) == nil)
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local c = f:read("a"); f:close(); return c end
	assert(read("src/Client/Gameplay2.lua"):find("ShopSummaryPlate", 1, true) and read("src/Client/Shop.lua"):find("ShopSummaryPlate", 1, true), "wired")
	assert(not read("src/Client/ShopSummaryPlate.lua"):find("TweenService", 1, true), "no tweens")
end })

