table.insert(tests, { name = "Gameplay v2 Night 2 and 3 tables: boss rule plate clear of Patrons, score and hand, a tint per rule family, synergy thread visible when narrow, deck click covers the count plate", fn = function()
	local M = require(script.Parent.Parent.Engine.Gameplay2Moments)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	local S = require(script.Parent.Parent.Engine.Gameplay2Synergy)
	local BR = require(script.Parent.Parent.Engine.BossRounds)
	for _, tag in ipairs(BR.RuleTagIds) do assert(M.TINTS[tag], "tint for rule " .. tag) end
	local t = M.bossTint({ "suitDebuff" })
	assert(t.fill[1] < t.edge[1] and t.fill[3] < t.edge[3], "fill is the darker version of the edge")
	assert(M.bossTint(nil).edge[1] > 100 and M.bossTint({ "suitDebuff" }).edge[3] ~= M.bossTint({ "fewerHands" }).edge[3], "default red, families differ")
	local function hit(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1024, 768 } }) do
		local w, h = sz[1], sz[2]
		local r = L.rects(w, h)
		local p = M.rulePlate(r)
		assert(p and p.h >= 20 and p.w >= 140, "a rule plate fits at " .. w)
		assert(p.x >= 0 and p.x + p.w <= w and p.y + p.h <= h, "on screen at " .. w)
		for i = 1, 5 do
			local s = r.slots[i]
			assert(not hit(p, s.card) and not hit(p, s.label) and not hit(p, s.pill), "clear of Patron seat " .. i .. " at " .. w)
		end
		assert(not hit(p, r.stage), "clear of the preview pill and score block at " .. w)
		assert(not hit(p, r.hand) and not hit(p, r.sortRank) and not hit(p, r.sortSuit) and not hit(p, r.gear), "clear of hand and controls at " .. w)
		local d = L.deckHit(r)
		assert(d.y == r.deck.y and d.y + d.h == r.deckCount.y + r.deckCount.h and d.h >= 44, "deck click covers book and count plate at " .. w)
		assert(d.x <= r.deck.x and d.x + d.w >= r.deckCount.x + r.deckCount.w and d.x + d.w <= w, "deck click inside the screen at " .. w)
		-- every thread at this size is visible: thick and bright when there is no room for the tag label
		for a = 1, 4 do
			local th = S.thread(r, { a = a, b = a + 1 })
			assert(th and th.h >= S.THREAD_H and th.alpha >= S.THREAD_ALPHA, "thread drawn at " .. w)
			if not th.label then assert(th.h == S.THREAD_H_NARROW and th.alpha == S.THREAD_ALPHA_NARROW, "narrow thread is bolder at " .. w) end
		end
	end
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local c = f:read("a"); f:close(); return c end
	local fx = read("src/Client/Gameplay2MomentsFX.lua")
	assert(fx:find("BossRulePlate", 1, true) and fx:find("Rules.rulePlate", 1, true) and fx:find("Rules.bossTint", 1, true), "rule plate wired")
	assert(read("src/Client/Gameplay2.lua"):find("Layout.deckHit", 1, true), "deck hit wired")
	local dt = read("src/Client/DeckTracker.lua")
	assert(not dt:find("fromOffset(150, 34)", 1, true) and not dt:find("fromOffset(140, 34)", 1, true) and not dt:find("or 96, 34)", 1, true), "deck viewer controls are 44 px")
end })

table.insert(tests, { name = "Gameplay v2 end moments: Run complete lists unlocks above a 48 px Continue, plates fit at four sizes, Night cleared keeps tips, old champion button is 44 px", fn = function()
	local M = require(script.Parent.Parent.Engine.Gameplay2Moments)
	local prev = { phase = "playing", round = 3, night = 8, nightCap = 8, bossModifier = { name = "B" }, targetScore = 300, roundScore = 200, tips = 5 }
	local now = { phase = "shop", roundScore = 400, tips = 15, unlockNotice = { items = { { kind = "patron", id = "x" } } } }
	local lines = M.clearLines(prev, now)
	assert(lines.night.runComplete and lines.unlockItems and #lines.unlockItems == 1 and lines.tipsEarned == 10, "unlock items and tips carried")
	local mid = M.clearLines({ phase = "playing", round = 3, night = 2, nightCap = 8, bossModifier = { name = "B" }, targetScore = 300, roundScore = 200, tips = 5 }, now)
	assert(not mid.night.runComplete and mid.night.title == "Night cleared" and mid.tipsEarned == 10 and mid.night.button == "Continue")
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 800, 400 }, { 844, 390 } }) do
		local w, h = sz[1], sz[2]
		for _, complete in ipairs({ false, true }) do
			local p = M.nightPlate(w, h, complete)
			assert(p.x >= 0 and p.y >= 0 and p.x + p.w <= w and p.y + p.h <= h, "plate on screen at " .. w)
			local cr = M.continueRect({ w = p.w, h = p.h })
			assert(cr.h >= 44 and cr.x >= 0 and cr.x + cr.w <= p.w and cr.y + cr.h <= p.h, "Continue inside the plate and 44 px tall at " .. w)
			local tipsBottom = (complete and 120 or 108) + 26
			assert(cr.y >= tipsBottom + 4, "Continue below the Tips line at " .. w .. " complete=" .. tostring(complete))
			if complete then
				local u = M.unlockRow({ w = p.w, h = p.h })
				assert(u and u.y >= tipsBottom and u.y + u.h + 8 <= cr.y, "unlock line between Tips and Continue at " .. w)
			end
		end
	end
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local c = f:read("a"); f:close(); return c end
	assert(read("src/Client/Gameplay2MomentsFX.lua"):find("Rules.unlockRow", 1, true), "unlock line wired")
	assert(not read("src/Client/NightVictory.lua"):find("fromOffset(220, 38)", 1, true), "Enter Endless Nights plate is 44 px or more")
end })

table.insert(tests, { name = "Gameplay v2 touch pass: table and Counter controls are 44 px targets with no overlap at 1280x720, 1024x768 and 844x390; a Patron tap opens the plate, a second tap or a tap away closes it", fn = function()
	local T = require(script.Parent.Parent.Engine.Gameplay2Touch)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	assert(#T.SIZES == 3)
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1024, 768 }, { 844, 390 } }) do
		local bad = T.table(sz[1], sz[2])
		assert(#bad == 0, sz[1] .. "x" .. sz[2] .. " table: " .. table.concat(bad, "; "))
		for _, counts in ipairs({ { offers = 2, packs = 0 }, { offers = 3, packs = 2 }, { offers = 5, packs = 2 } }) do
			local shop = T.shop(sz[1], sz[2], counts)
			assert(#shop == 0, sz[1] .. "x" .. sz[2] .. " Counter with " .. counts.offers .. " offers: " .. table.concat(shop, "; "))
		end
	end
	assert(#T.table(390, 844) == 0 and not L.fits(390, 844), "a portrait phone keeps the older screens and is not audited here")
	-- a failing layout is reported: a 30 px tall Mute would be caught
	local TT = require(script.Parent.Parent.Engine.TipTap)
	local st = TT.new()
	assert(TT.tapCard(st, 2) == "open" and st.open == 2, "a tap opens the plate")
	assert(TT.tapCard(st, 2) == "close" and st.open == nil, "a second tap on the same card closes it")
	assert(TT.tapCard(st, 1) == "open" and TT.tapCard(st, 3) == "open" and st.open == 3, "tapping another card moves the plate")
	local card = { x = 100, y = 100, w = 80, h = 110 }
	assert(TT.tapAway(st, 120, 130, card) == false and st.open == 3, "a tap on the card itself is left to tapCard")
	assert(TT.tapAway(st, 600, 400, card) == true and st.open == nil, "a tap away closes it")
	assert(TT.tapAway(st, 600, 400, card) == false, "nothing open, nothing to close")
	assert(TT.longPress(st, 4) == "open" and st.open == 4, "a long press leaves the plate open")
	assert(TT.isTap(3, 0.1) and not TT.isTap(3, 0.6) and not TT.isTap(20, 0.1), "tap needs a short press that barely moved")
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local c = f:read("a"); f:close(); return c end
	local row = read("src/Client/PatronRow.lua")
	assert(row:find("TipTap.tapCard", 1, true) and row:find("TipTap.tapAway", 1, true) and row:find("TipTap.longPress", 1, true), "PatronRow uses TipTap")
end })

table.insert(tests, { name = "Counter offers at 1920x957 and 1920x1080: a lone offer is 190 x 260 or more, three offers with two packs keep 190 wide, four stay 150 wide, Reroll directly under the row, nothing covers the bell, Next Round or the tabs", fn = function()
	local S = require(script.Parent.Parent.Engine.ShopSceneLayout)
	local function hit(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	for _, sz in ipairs({ { 1920, 957 }, { 1920, 1080 } }) do
		local function rects(o, k) return S.rects(sz[1], sz[2], { offers = o, packs = k, room = true }) end
		local one = rects(1, 0).offers[1]
		assert(one.w >= 190 and one.h >= 260 and one.w <= S.OFFER_MAX_W, "a lone offer is 190 x 260 or more at " .. sz[2] .. ": " .. one.w .. "x" .. one.h)
		assert(rects(1, 2).offers[1].w >= 190 and rects(3, 0).offers[1].w >= 190, "one offer with packs, and three offers, keep 190 wide")
		local three = rects(3, 2)
		assert(three.offers[1].w >= 190 and three.offers[1].h >= 250, "three offers with two packs keep 190 x 250: " .. three.offers[1].w .. "x" .. three.offers[1].h)
		assert(rects(4, 2).offers[1].w >= 150 and rects(4, 0).offers[1].w >= 150, "four offers stay 150 wide")
		for _, counts in ipairs({ { 1, 0 }, { 1, 2 }, { 3, 0 }, { 3, 2 }, { 4, 2 } }) do
			local r = rects(counts[1], counts[2])
			local plate = S.rerollPlate(r)
			assert(plate and plate.h >= 44 and plate.x == r.offers[1].x, "Reroll is 44 px tall, left aligned with the row")
			for i, o in ipairs(r.offers) do
				for _, k in ipairs(r.keepOut) do assert(not hit(o, k), "offer " .. i .. " clear of the bell, ledger, arch, wall, Next Round and tabs") end
				assert(not hit(o, plate), "offer " .. i .. " clear of Reroll")
				if r.offers[i + 1] then assert(not hit(o, r.offers[i + 1]), "offers do not overlap") end
			end
			for _, pk in ipairs(r.packs) do
				for _, o in ipairs(r.offers) do assert(not hit(pk, o), "packs clear of offers") end
			end
		end
	end
end })

table.insert(tests, { name = "Patron library: '23 of 81 found' count line, synergy line on the detail card, 44 px tier filter plates, locked tiles keep their hint, no overlap at 1920x1080 and 1280x720", fn = function()
	local C = require(script.Parent.Parent.Engine.CollectionCards)
	local B = require(script.Parent.Parent.Engine.CollectionBook)
	local R = require(script.Parent.Parent.Engine.CollectionRoomLayout)
	assert(C.foundText(23, 81) == "23 of 81 found" and C.foundText(99, 81) == "81 of 81 found" and C.foundText(-3, 81) == "0 of 81 found", "count line is clamped")
	assert(C.CHIP_H == 44, "filter plates are 44 px")
	local withTags, none = 0, 0
	for _, item in ipairs(B.itemsFor("patrons")) do
		local line = C.synergyLine(item.id)
		if line == "" then none = none + 1 else withTags = withTags + 1; assert(line:find("^Works with: "), "line starts with Works with") end
	end
	assert(withTags > 0, "some Patrons name their synergies (" .. none .. " have none)")
	assert(#B.RarityOrder >= 5, "a filter plate for every tier")
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 } }) do
		local w, h = sz[1], sz[2]
		local P = R.panel(w, h, C.CHIP_H, nil, "section")
		assert(P.filter.h >= C.CHIP_H, "the filter plate holds a 44 px chip at " .. w)
		assert(P.filter.y >= P.tabs.y + P.tabs.h and P.filter.y + P.filter.h <= h - R.FOOTER, "filter plate under the tabs and above Close at " .. w)
		assert(P.area.y + P.area.h <= P.tabs.y, "the grid ends above the tab strip at " .. w)
	end
	local grid = B.displayItems("patrons", { common = true })
	assert(#grid < #B.itemsFor("patrons") and #grid > 0, "hiding a tier leaves the others")
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local c = f:read("a"); f:close(); return c end
	local src = read("src/Client/Collection.lua")
	assert(src:find("foundText", 1, true) and src:find("synergyLine", 1, true) and src:find("CHIP_H", 1, true), "Collection draws the count line, the synergy line and 44 px chips")
	assert(src:find("Locked\\n", 1, true) and src:find("undiscoveredHint", 1, true), "locked tiles keep the hint")
end })

table.insert(tests, { name = "RoundHints: three plates, show once, Night 1 rounds 1 to 3 only, off in Calm mode and with the toggle, clear of the table at four sizes", fn = function()
	local RH = require(script.Parent.Parent.Engine.RoundHints)
	local Hints = require(script.Parent.Parent.Engine.Hints)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	expectEqual(#RH.ORDER, 3, "three plates")
	for _, e in ipairs(RH.ORDER) do
		expectTrue(Hints.getById(e.id) ~= nil, e.id .. " is stored in hintsSeen")
		expectTrue(Hints.wordCount(e.body) <= 12 and not (e.title .. e.body):find("%-%-"), e.id .. " is short and has no dashes")
		expectTrue(not Hints.dueFor({ phase = "playing", round = 1 }, {}, {}) or Hints.dueFor({ phase = "playing", round = 1 }, {}, {}).id:sub(1, 11) ~= "round_hint_", "no bubble ever shows a table plate")
	end
	local profile = {}
	expectTrue(Hints.markSeen(profile, "round_hint_select") and not Hints.markSeen(profile, "round_hint_select"), "stored once")
	expectTrue(Hints.cleanSaved({ round_hint_target = true }).round_hint_target == true, "survives a save and load")
	local function st(t) local s = { phase = "playing", night = 1, round = 1, ownedPatrons = {}, profileStats = { bestNightReached = 0 } }; for k, v in pairs(t or {}) do s[k] = v end; return s end
	local on = { enabled = true, calm = false }
	expectEqual(RH.next(st(), {}, on).id, "round_hint_select", "round 1 starts with picking cards")
	expectEqual(RH.next(st(), { round_hint_select = true }, on), nil, "no Patron owned yet, no Target plate in round 1")
	expectEqual(RH.next(st({ ownedPatrons = { { id = "the_regular" } } }), { round_hint_select = true }, on).id, "round_hint_tiers", "a Patron brings the power plate")
	expectEqual(RH.next(st({ round = 2 }), { round_hint_select = true, round_hint_tiers = true }, on).id, "round_hint_target", "round 2 explains Target")
	expectEqual(RH.next(st({ round = 3 }), { round_hint_select = true, round_hint_tiers = true, round_hint_target = true }, on), nil, "all seen, nothing more")
	expectEqual(RH.next(st({ round = 2 }), { round_hint_select = true }, on).id, "round_hint_target", "a plate that is not due does not block the next")
	expectEqual(RH.next(st({ round = 4 }), {}, on), nil, "round 4 is past the layer")
	expectEqual(RH.next(st({ night = 2 }), {}, on), nil, "Night 2 is past the layer")
	expectEqual(RH.next(st({ profileStats = { bestNightReached = 2 } }), {}, on), nil, "Night 1 cleared before")
	expectEqual(RH.next(st({ isTutorial = true }), {}, on), nil, "not in the tutorial")
	expectEqual(RH.next(st({ phase = "shop" }), {}, on), nil, "only on the table")
	expectEqual(RH.next(st({ guidedFirstHand = true, handsPlayedTotal = 0 }), {}, on), nil, "the guided first hand hint owns the screen first")
	local after = RH.next(st({ guidedFirstHand = true, handsPlayedTotal = 1 }), {}, on)
	expectTrue(after == nil or after.id ~= "round_hint_select", "after the guided hand Pick your cards is spent; a later plate may show")
	expectEqual(RH.next(st(), {}, { enabled = true, calm = true }), nil, "skipped in Calm mode")
	expectEqual(RH.next(st(), {}, { enabled = false, calm = false }), nil, "skipped with the Hints toggle off")
	do -- Got it plate: cream label at least 4.5:1 on the green fill and on its hover, plate and button level and 44 px or more
		local TS = require(script.Parent.Parent.Engine.TavernStyle)
		expectTrue(TS.contrast(RH.GOT_IT.text, RH.GOT_IT.fill) >= 4.5, "Got it label contrast on the fill")
		expectTrue(TS.contrast(RH.GOT_IT.text, RH.GOT_IT.hover) >= 4.5, "Got it label contrast on hover")
		local f = RH.GOT_IT.fill
		expectTrue(f[1] < 90 and f[2] < 90 and f[3] < 90, "Got it fill is dark wood, not green")
		expectTrue(RH.GOT_IT.text[1] > 200 and RH.GOT_IT.text[2] > 150, "Got it text is gold")
		local spot = RH.place(L.rects(1920, 1080), 1920, 1080)
		expectTrue(spot and spot.button.y >= spot.plate.y + spot.plate.h and spot.button.h >= 44 and spot.button.x >= spot.plate.x and spot.button.x + spot.button.w <= spot.plate.x + spot.plate.w, "Got it sits under the plate, inside its width, 44 px or more")
	end
	expectTrue(RH.satisfied("round_hint_select", 1) and not RH.satisfied("round_hint_select", 0) and not RH.satisfied("round_hint_tiers", 5), "picking a card finishes the first plate only")
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1024, 768 }, { 844, 390 } }) do
		local w, h = sz[1], sz[2]
		if L.fits(w, h) then
			local r = L.rects(w, h)
			local spot = RH.place(r, w, h)
			if w >= 1280 then expectTrue(spot ~= nil, w .. "x" .. h .. ": the plate fits") end
			if spot then
				expectTrue(spot.button.h >= 44, "Got it is 44 px tall at " .. w .. "x" .. h)
				for _, rect in pairs({ spot.plate, spot.button }) do
					expectTrue(rect.x >= 0 and rect.y >= 0 and rect.x + rect.w <= w and rect.y + rect.h <= h, "on screen at " .. w .. "x" .. h)
					for name, other in pairs(L.flat(r)) do
						local hit = rect.x < other.x + other.w and other.x < rect.x + rect.w and rect.y < other.y + other.h and other.y < rect.y + rect.h
						expectTrue(not hit, w .. "x" .. h .. ": hint overlaps " .. name)
					end
				end
				expectTrue(spot.plate.y + spot.plate.h <= r.hand.y, "above the hand at " .. w .. "x" .. h)
			end
		end
	end
	if not io then return end
	local f = io.open("src/Client/Settings.lua", "r")
	if f then
		local src = f:read("*a"); f:close()
		expectTrue(src:find('makeChoiceRow("roundHints"', 1, true) ~= nil, "Settings has a Round Hints toggle")
	end
end })

table.insert(tests, { name = "Night clear Patron reward: 3 unowned Patrons, rarer with the Night, Skip, full table, fixed boards and picks", fn = function()
	local RunChoice = require(script.Parent.Parent.Engine.RunChoice)
	local CollectionBook = require(script.Parent.Parent.Engine.CollectionBook)
	local Patrons = require(script.Parent.Parent.Engine.Patrons)
	local function fresh(night)
		local state = RunState.new({}, function(n) return math.random(n) end)
		state.night = night or 2
		state.round = 1
		return state
	end
	local function rankOf(id)
		local def = Patrons.getById(id)
		local rarity = CollectionBook.rarityOf({ tab = "patrons", id = id, def = def })
		for i, r in ipairs(CollectionBook.RarityOrder) do if r == rarity then return i end end
		return 99
	end
	expectEqual(RunChoice.rewardMaxRarity(2), 2, "Night 2 up to Uncommon")
	expectEqual(RunChoice.rewardMaxRarity(3), 2); expectEqual(RunChoice.rewardMaxRarity(4), 3, "one tier more every two Nights")
	expectTrue(RunChoice.rewardMaxRarity(99) <= #CollectionBook.RarityOrder - 1, "never the top tier")
	for night = 2, 6 do
		local state = fresh(night)
		for _ = 1, 20 do
			local choice = RunChoice.rewardDraft(state, true)
			expectTrue(choice ~= nil and choice.kind == "reward" and choice.skip == true, "a reward at Night " .. night)
			expectEqual(#choice.options, 3, "three cards")
			local seen = {}
			for _, o in ipairs(choice.options) do
				expectTrue(not seen[o.id], "no repeats"); seen[o.id] = true
				expectTrue(rankOf(o.id) <= RunChoice.rewardMaxRarity(night), o.id .. " is not above the Night's cap")
				expectTrue(not o.name:lower():find("balatro"), "kid safe names")
			end
		end
	end
	expectEqual(RunChoice.rewardDraft(fresh(2), false), nil, "no reward on Daily, Weekly, Seed or the tutorial")
	-- Skip changes nothing
	local state = fresh(2)
	local choice = RunChoice.rewardDraft(state, true)
	local ok, msg, nextChoice = RunChoice.pick(state, choice, "decline")
	expectTrue(ok and msg == "" and nextChoice == nil and #state.ownedPatrons == 0, "Skip seats nobody")
	-- a pick seats exactly that Patron; a made-up id is refused and changes nothing
	expectTrue(not (RunChoice.pick(state, choice, "not_offered")), "not an offered id")
	local id = choice.options[2].id
	local ok2 = RunChoice.pick(state, choice, id)
	expectTrue(ok2 and #state.ownedPatrons == 1 and state.ownedPatrons[1].id == id, "the picked Patron joins")
	-- a Patron already owned is never offered again
	for _ = 1, 30 do
		local again = RunChoice.rewardDraft(state, true)
		for _, o in ipairs(again.options) do expectTrue(o.id ~= id, "owned Patrons are left out") end
	end
	-- a full table gets no reward
	local full = fresh(3)
	for _, p in ipairs(Patrons.Definitions) do
		if #full.ownedPatrons >= RunState.patronSlotLimit(full) then break end
		RunState.grantPatron(full, p.id)
	end
	expectEqual(RunChoice.rewardDraft(full, true), nil, "full table, no reward")
	-- the reward kind is wired to the stage and rarity tables, and cannot be abandoned (it is Skip, not Back)
	expectEqual(require(script.Parent.Parent.Engine.ChoiceRarity).tabFor("reward"), "patrons")
	expectEqual(require(script.Parent.Parent.Engine.ModalGate).stageFor("reward"), "draft")
	expectTrue(not require(script.Parent.Parent.Engine.PopupDismissRules).canAbandonChoice("reward"))
	if not io then return end
	local f = io.open("src/Server/init.server.lua", "r")
	if f then
		local src = f:read("*a"); f:close()
		expectTrue(src:find("RunChoice.rewardDraft(session.state, not fixedRun)", 1, true) ~= nil, "the server opens the reward on a new Night")
	end
	local g = io.open("src/Client/ChoicePanel.lua", "r")
	if g then
		local src = g:read("*a"); g:close()
		expectTrue(src:find("RewardSkip", 1, true) and src:find('"decline"', 1, true), "the panel has a Skip plate")
	end
end })

table.insert(tests, { name = "Boss intro cinematic: 2.5 s slide and hold, none in Calm mode, Fast halves, plate inside the screen with room for the portrait, victory reward line", fn = function()
	local M = require(script.Parent.Parent.Engine.Gameplay2Moments)
