table.insert(tests, { name = "SortGlide: cards that changed place slide from their old spot, unmoved and new cards stay, none in Calm mode, the whole glide ends within 0.5 s, wired into the sort handler", fn = function()
	local G = require(script.Parent.Parent.Engine.SortGlide)
	local offs = G.offsets({ [1] = 100, [2] = 200, [3] = 300 }, { [1] = 300, [2] = 200, [3] = 100, [4] = 400 })
	expectTrue(offs[1] == -200, "card 1 started 200 px left of its new place")
	expectTrue(offs[3] == 200, "card 3 started 200 px right of its new place")
	expectTrue(offs[2] == nil and offs[4] == nil, "an unmoved card and a new card do not glide")
	expectTrue(G.offsets({ [1] = 100 }, { [1] = 101 })[1] == nil, "under 2 px counts as unmoved")
	expectTrue(G.timing(true, false) == nil, "Calm mode and Reduce motion: no tween")
	expectTrue(G.timing(false, true).time < G.timing(false, false).time, "Fast is quicker")
	for _, n in ipairs({ 1, 5, 8, 12 }) do
		for _, fast in ipairs({ false, true }) do
			local t = G.timing(false, fast)
			expectTrue(G.delay(n, n, fast) + t.time <= G.TOTAL_CAP + 1e-9, n .. " cards: the last one lands by " .. G.TOTAL_CAP .. " s")
		end
	end
	if not io then return end
	local f = assert(io.open("src/Client/init.client.lua", "r")); local hub = f:read("a"); f:close()
	expectTrue(hub:find("SortGlideFX", 1, true) ~= nil, "the sort handler calls SortGlideFX")
	f = assert(io.open("src/Client/SortGlideFX.lua", "r")); local fx = f:read("a"); f:close()
	expectTrue(fx:find("if calm() or", 1, true) ~= nil, "calm mode returns before any tween")
end })

table.insert(tests, { name = "Button labels: the word draws above every skin plate and rim child (Run Over buttons were dimmed)", fn = function()
	if not (io and io.open) then return end
	local FakeGui = require(script.Parent.FakeGui)
	local env = FakeGui.env({ stubs = {} })
	local B = FakeGui.load("src/Client/ButtonLabelTop.lua", env)
	expectTrue(B.zFor(5024, { 5024, 5024 }) > 5024, "label z is above equal-z siblings")
	expectTrue(B.zFor(10, { 40 }) > 40, "label z is above a higher sibling")
	for _, z in ipairs({ 1, 24, 5024 }) do
		local b = FakeGui.new("TextButton")
		b.ZIndex, b.Text = z, "Try Again"
		local plate, rim = FakeGui.new("ImageLabel"), FakeGui.new("Frame")
		plate.Name, rim.Name = "SetSkinPlate", "InnerRim"
		plate.ZIndex, rim.ZIndex = z, z
		plate.Parent, rim.Parent = b, b
		local label = B.attach(b)
		expectTrue(label ~= nil and label.Name == "KitLabel" and label.Text == "Try Again", "label mirrors the text")
		for _, c in ipairs(b:GetChildren()) do
			if c ~= label and c:IsA("GuiObject") then expectTrue(c.ZIndex < label.ZIndex, c.Name .. " draws under the label at z " .. z) end
		end
		b.Text = "Play Again"
		expectTrue(label.Text == "Play Again", "text change follows")
		b.ZIndex = z + 5000
		plate.ZIndex, rim.ZIndex = z + 5000, z + 5000
		b.ZIndex = z + 5001
		expectTrue(label.ZIndex > plate.ZIndex and label.ZIndex > rim.ZIndex, "a lifted screen keeps the label on top")
	end
	local function has(file, text)
		local f = io.open("src/Client/" .. file, "r"); local src = f:read("a"); f:close()
		return src:find(text, 1, true) ~= nil
	end
	expectTrue(has("SetSkin.lua", "ButtonLabelTop") and has("VisualHelpers.lua", "ButtonLabelTop"), "the two helpers that add plate and rim attach the label")
	expectTrue(has("HudTheme.lua", "ButtonLabelTop"), "HUD action buttons attach the label")
	expectTrue(has("InputWatchdogFX.lua", "ButtonLabelTop"), "the sweep runs as a safety net on every screen")
	expectTrue(B.needs(5, "Play", { 5 }) and B.needs(5, "Play", { 9, 1 }) and not B.needs(5, "Play", { 4 }) and not B.needs(5, "", { 9 }) and not B.needs(5, "Play", {}), "needs rule")
	local root = FakeGui.new("Frame")
	local tb, plain = FakeGui.new("TextButton"), FakeGui.new("TextButton")
	tb.Text, plain.Text, tb.ZIndex, plain.ZIndex = "Go", "Stay", 7, 7
	local art = FakeGui.new("ImageLabel"); art.ZIndex = 8; art.Parent = tb
	tb.Parent, plain.Parent = root, root
	expectTrue(B.sweep(root) == 1, "sweep fixes only the button with a plate over its word")
	expectTrue(tb:FindFirstChild("KitLabel").ZIndex > art.ZIndex and plain:FindFirstChild("KitLabel") == nil, "label above the art, clean button untouched")
	expectTrue(B.sweep(root) == 0, "sweep is idempotent")
	expectTrue(has("TavernScreens.lua", "NEXT_ROUND") and has("TavernScreens.lua", 'name == "PlayAgain"'), "Run Over Play Again uses the bright green")
end })

table.insert(tests, { name = "Button labels: a button and its KitLabel never draw the same word twice, a scaled word keeps 12 px padding and a 26 cap, the self check flags a double draw", fn = function()
	if not (io and io.open) then return end
	local FakeGui = require(script.Parent.FakeGui)
	local B = FakeGui.load("src/Client/ButtonLabelTop.lua", FakeGui.env({ stubs = {} }))
	local b = FakeGui.new("TextButton")
	b.Text, b.TextScaled = "Next Round", true
	local label = B.attach(b)
	expectTrue(label.Text == "Next Round" and label.TextTransparency == 0, "the label draws the word")
	expectTrue(b.TextTransparency == 1 and b.TextStrokeTransparency == 1 and b.Text == "Next Round", "the button hides its own copy and keeps its Text")
	b.TextTransparency = 0.4 -- an owner dims the button: the label takes the dim, the button stays hidden
	expectTrue(label.TextTransparency == 0.4 and b.TextTransparency == 1, "a dim is drawn once, on the label")
	expectTrue(label:FindFirstChildOfClass("UITextSizeConstraint").MaxTextSize == 26 and label:FindFirstChildOfClass("UIPadding").PaddingLeft.Offset == 12, "scaled word: cap 26, 12 px side padding")
	local root = FakeGui.new("Frame")
	b.Parent = root
	b.TextTransparency, b.TextStrokeTransparency = 0, 0 -- a writer shows the own copy again
	expectTrue(#B.doubled(root, false) >= 0, "doubled() lists without fixing")
	b.TextTransparency, b.TextStrokeTransparency = 0, 0
	local before = #B.doubled(root, true)
	expectTrue(b.TextTransparency == 1 and b.TextStrokeTransparency == 1 and #B.doubled(root, false) == 0, "doubled(root, true) hides every own copy (" .. before .. " found first)")
	local f = io.open("src/Client/TavernScreens.lua", "r"); local ts = f:read("a"); f:close()
	expectTrue(ts:find('b:FindFirstChild("KitLabel") and 1 or 0', 1, true) ~= nil, "the Next Round settle keeps the own copy hidden while a KitLabel exists")
	local S = require(script.Parent.Parent.Engine.SelfCheck)
	local twice = S.check({
		{ path = "G.Shop.NextRound", text = "Next Round", textTransparency = 0 },
		{ path = "G.Shop.NextRound.KitLabel", text = "Next Round", textTransparency = 0 },
	})
	local found = false
	for _, w in ipairs(twice) do if w:find("shows twice", 1, true) then found = true end end
	expectTrue(found, "self check warns on a doubled word")
	local once = S.check({
		{ path = "G.Shop.NextRound", text = "Next Round", textTransparency = 1 },
		{ path = "G.Shop.NextRound.KitLabel", text = "Next Round", textTransparency = 0 },
	})
	for _, w in ipairs(once) do expectFalse(w:find("shows twice", 1, true) ~= nil, "no warning when only the label draws") end
end })

table.insert(tests, { name = "Music mix: one bed per screen on existing ids, stepped crossfade without a pop, tension layer only on the last hand under half the Target, at most 3 voices, Mute and the slider win, no tweens", fn = function()
	local M = require(script.Parent.Parent.Engine.MusicMix)
	local SoundIds = require(script.Parent.Parent.Engine.SoundIds)
	expectEqual(M.screenOf({}, true), "menu")
	expectEqual(M.screenOf({ phase = "shop" }), "shop")
	expectEqual(M.screenOf({ phase = "playing", bossModifier = {} }), "boss")
	expectEqual(M.screenOf({ phase = "playing" }), "table")
	expectEqual(M.screenOf({ phase = "roundSelect" }), "map")
	expectEqual(M.screenOf({ phase = "playing", runOver = true }), "runover")
	for screen, bed in pairs(M.BEDS) do
		local id = bed.key == "title" and SoundIds.Music.menu or SoundIds.Music[bed.key]
		expectTrue(SoundIds.isValidId(id), screen .. " bed uses an existing id")
		expectTrue(bed.gain > 0 and bed.gain <= 1, screen .. " gain")
	end
	expectEqual(M.bedFor("table", "region_snow").key, "region_snow")
	expectEqual(M.bedFor("boss", "region_snow").key, "boss", "a region never replaces the boss bed")
	-- tension
	local base = { phase = "playing", targetScore = 1000, roundScore = 400, handsRemaining = 1 }
	expectTrue(M.tension(base), "last hand, under half")
	expectFalse(M.tension({ phase = "playing", targetScore = 1000, roundScore = 600, handsRemaining = 1 }), "over half")
	expectFalse(M.tension({ phase = "playing", targetScore = 1000, roundScore = 400, handsRemaining = 2 }), "not the last hand")
	expectFalse(M.tension({ phase = "shop", targetScore = 1000, roundScore = 0, handsRemaining = 1 }), "not on the table")
	expectFalse(M.tension({ phase = "playing", targetScore = 1000, roundScore = 0, handsRemaining = 1, roundOver = true }), "round already over")
	expectEqual(M.tensionGain("shop"), 0); expectEqual(M.tensionGain("boss"), 0); expectTrue(M.tensionGain("table") > 0)
	-- voices
	expectEqual(#M.voices({ bed = true, outgoing = true, sting = true, tension = true }), 3, "never more than 3 voices")
	expectEqual(table.concat(M.voices({ bed = true, outgoing = true, sting = true, tension = true }), ","), "bed,sting,outgoing", "tension is the one dropped")
	expectEqual(table.concat(M.voices({ bed = true, tension = true }), ","), "bed,tension")
	-- fades: gradual, monotonic, no pop, Calm still steps (fewer, never a jump from 0 to 1)
	for _, calm in ipairs({ false, true }) do
		local f = M.fade(calm)
		expectTrue(#f >= 4, "at least 4 steps")
		local prevOut, prevIn = 1, 0
		for i, pair in ipairs(f) do
			expectTrue(pair[1] <= prevOut + 1e-9 and pair[2] >= prevIn - 1e-9, "monotonic at " .. i)
			expectTrue(pair[2] - prevIn <= 0.5, "no pop at step " .. i)
			prevOut, prevIn = pair[1], pair[2]
		end
		expectTrue(f[#f][1] == 0 and f[#f][2] == 1, "ends fully on the new bed")
	end
	expectTrue(M.stepTime(true) > M.stepTime(false), "Calm steps are longer")
	expectEqual(M.volume(0.8, true, 1, 1), 0, "Mute wins")
	expectEqual(M.volume(0, false, 1, 1), 0, "slider at 0 is silent")
	expectTrue(math.abs(M.volume(0.8, false, 0.5, 0.5) - 0.2) < 1e-9, "slider x gain x fraction")
	expectTrue(M.shouldFade("title", "gameplay") and not M.shouldFade("shop", "shop") and not M.shouldFade(nil, "shop"))
	if io and io.open then
		for _, file in ipairs({ "MusicMixFX.lua" }) do
			local f = io.open("src/Client/" .. file, "r"); local src = f:read("a"); f:close()
			expectFalse(src:find("TweenService", 1, true) ~= nil, file .. " makes no tweens")
		end
		local f = io.open("src/Client/Sound.lua", "r"); local src = f:read("a"); f:close()
		local a, b = src:find("local function stepFade", 1, true), src:find("-- JUKEBOX AUTOPLAY/SHUFFLE: drops", 1, true)
		expectFalse(src:sub(a, b):find("TweenService", 1, true) ~= nil, "the bed crossfade makes no tweens")
		f = io.open("src/Client/init.client.lua", "r"); src = f:read("a"); f:close()
		expectTrue(src:find("MusicMixFX", 1, true) ~= nil, "the hub hands the bed choice to MusicMixFX")
	end
end })

table.insert(tests, { name = "Sound and music pass: 1 s bed crossfade, every action has a cue with a call site, Sound and Music groups obey Mute and their sliders", fn = function()
	local M = require(script.Parent.Parent.Engine.MusicMix)
	local G = require(script.Parent.Parent.Engine.Gameplay2Sound)
	local SoundIds = require(script.Parent.Parent.Engine.SoundIds)
	expectEqual(M.FADE_TIME, 1, "beds crossfade over 1 s")
	expectTrue(math.abs(M.stepTime(false) * M.STEPS - 1) < 1e-9 and math.abs(M.stepTime(true) * M.STEPS_CALM - 1) < 1e-9, "Calm and normal both span 1 s")
	local have = {}
	for _, m in ipairs(G.MOMENTS) do have[m.cue] = true end
	for _, cue in ipairs({ "card_deal", "card_select", "card_deselect", "card_play", "score_tick", "score_total", "patron_trigger",
		"round_clear", "defeat", "shop_buy", "shop_reroll", "shop_sell", "coin" }) do
		expectTrue(have[cue], "a call site is listed for " .. cue)
	end
	for _, step in ipairs(G.SLIDER_STEPS) do
		expectEqual(G.effective(0.8, 1, step, true), 0, "Mute silences the Sound group at slider " .. step)
		expectTrue(G.effective(0.8, 1, step, false) <= step + 1e-9, "the SFX slider caps the cue at " .. step)
		expectEqual(M.volume(step, true, 1, 1), 0, "Mute silences the Music group at slider " .. step)
		expectTrue(math.abs(M.volume(step, false, 1, 1) - step) < 1e-9, "the Music slider sets the bed at " .. step)
	end
	for _, screen in ipairs({ "menu", "map", "table", "boss", "shop", "runover" }) do
		expectTrue(type(M.bedFor(screen).key) == "string", screen .. " has one bed")
	end
	expectEqual(#M.voices({ bed = true, outgoing = true, sting = true, tension = true }), 3, "no more than 3 voices at once")
	expectTrue(SoundIds.isValidId(SoundIds.Music.shop) and SoundIds.isValidId(SoundIds.Music.boss), "shop and boss beds use existing ids")
end })

table.insert(tests, { name = "First five minutes: hint sequence card then Play Hand then spent, first shop outlines the cheapest affordable Patron once, hint plates are painted", fn = function()
	local GH = require(script.Parent.Parent.Engine.GuidedHand)
	local RH = require(script.Parent.Parent.Engine.RoundHints)
	local FB = require(script.Parent.Parent.Engine.FirstBuy)
	local a = GH.hint(true, 0, 0, false)
	expectTrue(a and a.target == "card", "no card picked: the hint points at a card")
	local b = GH.hint(true, 0, 1, false)
	expectTrue(b and b.target == "play", "one card picked: the hint points at Play Hand")
	expectEqual(GH.hint(true, 1, 0, false), nil, "after the first hand the guided hint is gone")
	expectEqual(GH.hint(false, 0, 0, false), nil, "not a guided run: no hint")
	for _, h in ipairs({ a, b }) do
		expectTrue(#h.line1 <= 40 and #h.line2 <= 40, "each hint line is short (two lines, one glance)")
	end
	expectTrue(RH.expired("round_hint_select", { handsPlayedTotal = 1 }), "Pick your cards is spent after the first hand")
	-- first buy
	local offers = { { id = "a", price = 8 }, { id = "b", price = 4 }, { id = "c", price = 4 }, { id = "d", price = 30 } }
	expectEqual(FB.pick(offers, 10), 2, "cheapest affordable, first on a tie")
	expectEqual(FB.pick(offers, 3), nil, "nothing affordable: no outline")
	expectEqual(FB.pick({}, 10), nil)
	expectEqual(FB.pick(nil, 10), nil)
	expectTrue(FB.enabled({ night = 1, ownedPatrons = { "the_regular" }, patronLimit = 5 }), "Night 1 with the starter: on")
	expectFalse(FB.enabled({ night = 1, ownedPatrons = { "x", "y" }, patronLimit = 5 }), "a second Patron was bought: off")
	expectFalse(FB.enabled({ night = 2, ownedPatrons = {} }), "Night 2: off")
	expectFalse(FB.enabled({ night = 1, ownedPatrons = { "x" }, patronLimit = 1 }), "no free seat: off")
	if io and io.open then
		local function src(p) local f = io.open(p, "r"); local s = f:read("a"); f:close(); return s end
		expectTrue(src("src/Client/RoundHintsFX.lua"):find('painted(plate, "wh_hint")', 1, true) ~= nil, "Round hint plate is painted")
		expectTrue(src("src/Client/RoundHintsFX.lua"):find('painted(button, "wh_btn_green")', 1, true) == nil, "Got it is a dark plate, not the green picture")
		expectTrue(src("src/Client/GuidedHint.lua"):find('painted(plate, "wh_target")', 1, true) ~= nil, "guided hint plate is painted")
		expectTrue(src("src/Client/Shop.lua"):find("FirstBuy.pick", 1, true) ~= nil and src("src/Client/ShopCards.lua"):find("spec.highlight", 1, true) ~= nil, "the Counter outlines the first buy")
	end
end })

