table.insert(tests, { name = "Gameplay2Tier: quiet, pulse, burst and OVERKILL by hand total versus Target, Combo pill from 3 triggers, Calm mode one static label, everything inside the centre block", fn = function()
	local T = require(script.Parent.Parent.Engine.Gameplay2Tier)
	expectEqual(T.tierOf(99, 100), 0, "under 1x is quiet")
	expectEqual(T.tierOf(100, 100), 1, "1x pulses")
	expectEqual(T.tierOf(199, 100), 1)
	expectEqual(T.tierOf(200, 100), 2, "2x bursts")
	expectEqual(T.tierOf(499, 100), 2)
	expectEqual(T.tierOf(500, 100), 3, "5x is OVERKILL")
	expectEqual(T.tierOf(50, nil), 0)
	expectEqual(T.tierOf(50, 0), 0)
	expectEqual(T.comboOf(2), nil)
	expectEqual(T.comboOf(3), 3)
	expectEqual(T.comboOf(5), 5)
	local q = T.spec(0, 0, false, false)
	expectTrue(q.label == nil and q.comboText == nil and q.pulse == 0 and q.burst == 0 and q.coins == 0, "quiet shows nothing extra")
	local p1, p2, p3 = T.spec(1, 0, false, false), T.spec(2, 0, false, false), T.spec(3, 0, false, false)
	expectTrue(p1.pulse > 0 and p1.burst == 0 and p1.shake == 0, "tier 1: pulse only")
	expectTrue(p2.burst > 0 and p2.shake > 0 and p2.coins == 0 and not p2.banner, "tier 2: burst and a small shake")
	expectTrue(p3.banner and p3.coins > 0 and p3.label == "OVERKILL", "tier 3: banner and coin shower")
	expectEqual(T.spec(1, 4, false, false).comboText, "Combo x 4", "combo pill text")
	expectEqual(T.spec(1, 2, false, false).comboText, nil, "two triggers is no combo")
	for tier = 0, 3 do
		local c = T.spec(tier, 5, true, false)
		expectTrue(c.static and c.pulse == 0 and c.burst == 0 and c.shake == 0 and c.coins == 0 and c.combo == nil, "Calm mode tier " .. tier .. ": no motion")
		expectTrue(c.label == nil or type(c.label) == "string", "one label")
	end
	expectEqual(T.spec(0, 5, true, false).label, "Combo x 5", "Calm, quiet tier: the combo word is the one label")
	expectTrue(T.spec(3, 0, false, true).hold < T.spec(3, 0, false, false).hold, "Fast halves the time")
	for _, sz in ipairs({ { 200, 130 }, { 160, 90 }, { 320, 180 } }) do
		local box = { x = 0, y = 0, w = sz[1], h = sz[2] }
		for _, r in ipairs({ T.labelRect(box), T.comboRect(box) }) do
			expectTrue(r.x >= 0 and r.y >= 0 and r.x + r.w <= box.w and r.y + r.h <= box.h, "pill inside the block at " .. sz[1] .. "x" .. sz[2])
		end
		for i = 1, 14 do
			local c = T.coinPath(i, 14, box)
			expectTrue(c.x0 >= 0 and c.x0 <= box.w and c.y0 >= 0 and c.y1 <= box.h, "coin " .. i .. " stays inside the block")
		end
	end
	local sf = io and io.open and io.open("src/Client/Gameplay2TierFX.lua", "r")
	if sf then
		local src = sf:read("*a"); sf:close()
		expectFalse(src:find("TweenService", 1, true) ~= nil, "no tweens in the tier flourish")
		expectTrue(src:find("static", 1, true) ~= nil and src:find("Kit.still", 1, true) ~= nil, "Calm mode takes the static path")
	end
end })

table.insert(tests, { name = "Self check cleanup: count pills clear of button words, skip noise frames and hidden banners, empty text, Sort halves use the layout rect", fn = function()
	local S = require(script.Parent.Parent.Engine.SelfCheck)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	-- (1) the Hands and Discards pill words never overlap the Play Hand and Discard labels
	for _, sz in ipairs({ { 1920, 957 }, { 1280, 720 }, { 844, 390 } }) do
		local r = L.rects(sz[1], sz[2])
		local nodes = {
			{ path = "A.Play.KitLabel", text = "Play Hand", textTransparency = 0, rect = r.play },
			{ path = "A.Discard.KitLabel", text = "Discard", textTransparency = 0, rect = r.discard },
			{ path = "B.HandsPill.Word", text = "Hands 4", textTransparency = 0, rect = r.playCount },
			{ path = "B.DiscardsPill.Word", text = "Discards 3", textTransparency = 0, rect = r.discardCount },
		}
		local out = S.check(nodes)
		expectEqual(#out, 0, "no label overlap at " .. sz[1] .. "x" .. sz[2] .. ": " .. table.concat(out, "; "))
		expectTrue(r.hand.y + r.hand.h <= r.playCount.y, "the hand still ends above the pills")
	end
	-- (2) the Sort halves are 44 px tall and side by side in the layout
	for _, sz in ipairs({ { 1920, 957 }, { 1280, 720 }, { 844, 390 } }) do
		local r = L.rects(sz[1], sz[2])
		expectTrue(r.sortRank.h >= 44 and r.sortSuit.h >= 44 and r.sortRank.x + r.sortRank.w < r.sortSuit.x, "Sort halves are touch targets at " .. sz[1])
	end
	local f = io and io.open and io.open("src/Client/Gameplay2.lua", "r")
	if f then
		local src = f:read("*a"); f:close()
		expectTrue(src:find("splitSort(k, r)", 1, true) ~= nil, "the live Sort control is sized by its layout rects")
	end
	-- (3) noise frames
	expectTrue(S.ignoreFrame("Glow", 0.95, 3, {}), "a nearly clear frame is noise")
	expectTrue(S.ignoreFrame("Ring", 0.5, 0, {}), "Z 0 is noise")
	expectTrue(S.ignoreFrame("Dot", 0.5, 3, { "Root", "CandleGlow" }), "inside an effect folder is noise")
	expectTrue(S.ignoreFrame("Vignette", 0.5, 3, {}), "a named effect frame is noise")
	expectFalse(S.ignoreFrame("Panel", 0.2, 3, { "Root" }), "a real plate stays checked")
	-- (4) hidden banners and empty text
	expectTrue(S.ignoreLabel("", "Anything", 0) and S.ignoreLabel("   ", "Anything", 0), "empty text is skipped")
	expectTrue(S.ignoreLabel("Enraged", "BossEnrageBanner", 1) and S.ignoreLabel("x", "LegendaryBanner", 1), "hidden banners are skipped")
	expectFalse(S.ignoreLabel("Play Hand", "KitLabel", 1), "a blank Play Hand word is still caught")
	local warns = S.check({ { path = "G.BossEnrageBanner", text = "Enraged", textTransparency = 1 }, { path = "G.A.KitLabel", text = "Play Hand", textTransparency = 1 } })
	expectEqual(#warns, 1, "only the real unreadable label warns")
end })

table.insert(tests, { name = "Daily strip: shows on the Night map and Run Over only, streak, first open goal and chest from the real views, old saves safe, day rollover and double claim", fn = function()
	local D = require(script.Parent.Parent.Engine.DailyStrip)
	local LS = require(script.Parent.Parent.Engine.LoginStreak)
	local Q = require(script.Parent.Parent.Engine.Quests)
	assert(D.visible("roundSelect") and D.visible("gameover"), "map and Run Over")
	assert(not D.visible("playing") and not D.visible("shop") and not D.visible("menu"), "never on the table, Counter or menu")
	-- old save: nothing at all
	local old = D.view(nil, nil)
	expectEqual(old.chest, "none", "no login view, no chest")
	expectEqual(old.streakText, "Streak: starts today", "safe default")
	-- real rules: day 1 check in, chest ready, claim once, opened, same day claim refused
	local profile = {}
	local day = 20000
	assert(LS.checkIn(profile, day), "first check in")
	local v = D.view(LS.view(profile), Q.view(profile, day, 100))
	expectEqual(v.streakText, "Streak: 1 day", "singular")
	expectEqual(v.chest, "ready", "chest waits")
	expectEqual(v.claimDay, 1, "slot 1")
	assert(v.goalText:find("0/", 1, true), "goal progress shown: " .. v.goalText)
	local ok = LS.claim(profile, v.claimDay, nil)
	assert(ok, "first claim works")
	local again = LS.claim(profile, v.claimDay, nil)
	assert(not again, "double claim refused")
	expectEqual(D.view(LS.view(profile), nil).chest, "opened", "after the claim the chest is opened")
	-- same day again: no change; next UTC day: streak 2 and the chest is ready again
	assert(not LS.checkIn(profile, day), "same day is no new check in")
	assert(LS.checkIn(profile, day + 1), "next day")
	local v2 = D.view(LS.view(profile), nil)
	expectEqual(v2.streakText, "Streak: 2 days", "plural")
	expectEqual(v2.chest, "ready", "new day, new chest")
	expectEqual(v2.claimDay, 2, "slot 2")
	-- a finished goal moves to the next open one; all done says so
	local qs = { quests = { { desc = "A", progress = 3, goal = 3, done = true }, { desc = "Play 10 hands.", progress = 4, goal = 10, done = false } } }
	expectEqual(D.view(nil, qs).goalText, "Play 10 hands. 4/10", "first unfinished goal")
	qs.quests[2].done = true
	expectEqual(D.view(nil, qs).goalText, "All daily goals done", "all done")
	assert(D.view(nil, qs).goalDone, "goalDone flag")
end })

table.insert(tests, { name = "Daily strip layout: inside the screen, 44 px touch targets, chest inside the strip at six sizes, Calm mode reveal has no motion", fn = function()
	local D = require(script.Parent.Parent.Engine.DailyStrip)
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1024, 600 }, { 1024, 768 }, { 844, 390 }, { 390, 844 } }) do
