	end
end })

table.insert(tests, { name = "Invite Tips bonus: paid once per UTC day, the invite and titles still count, junk day and old saves safe, the saved day survives a load", fn = function()
	local Invites = require(script.Parent.Parent.Engine.Invites)
	local PlayerProfile = require(script.Parent.Parent.Engine.PlayerProfile)
	local host = PlayerProfile.new()
	local ok, _, tips = Invites.creditInviter(host, 1, 2, 20000)
	expectTrue(ok); expectEqual(tips, Invites.INVITER_TIPS, "first invite of the day pays")
	local before = host.pendingStartTips
	local ok2, _, tips2 = Invites.creditInviter(host, 1, 3, 20000)
	expectTrue(ok2, "the second friend still counts"); expectEqual(tips2, 0, "no second Tips bonus the same day")
	expectEqual(host.pendingStartTips, before, "Tips unchanged")
	expectEqual(host.invitesAccepted, 2, "both counted toward the titles")
	local _, _, tips3 = Invites.creditInviter(host, 1, 4, 20001)
	expectEqual(tips3, Invites.INVITER_TIPS, "next UTC day pays again")
	expectFalse((Invites.creditInviter(host, 1, 4, 20001)), "the same friend never pays twice")
	-- an inbox drained after a long offline spell pays one bonus per day, not one per friend
	local later = PlayerProfile.new()
	local credited, _, paid = Invites.drainInbox(later, 1, { 11, 12, 13 }, 20005)
	expectEqual(credited, 3); expectEqual(paid, Invites.INVITER_TIPS, "one bonus for the whole inbox")
	-- no day given: the old behaviour, no cap
	local plain = PlayerProfile.new()
	Invites.creditInviter(plain, 1, 2); Invites.creditInviter(plain, 1, 3)
	expectEqual(plain.pendingStartTips, 2 * Invites.INVITER_TIPS, "no day, no cap")
	-- junk and old saves
	local fresh = PlayerProfile.new()
	Invites.cleanSaved(fresh, { inviteTipsDay = "x" }); expectEqual(fresh.inviteTipsDay, nil, "junk day dropped")
	Invites.cleanSaved(fresh, { inviteTipsDay = 1.5 }); expectEqual(fresh.inviteTipsDay, nil, "fraction dropped")
	Invites.cleanSaved(fresh, {}); expectEqual(fresh.inviteTipsDay, nil, "old save")
	Invites.cleanSaved(fresh, { inviteTipsDay = 20000 }); expectEqual(fresh.inviteTipsDay, 20000, "saved day kept")
	local _, _, tips4 = Invites.creditInviter(fresh, 1, 9, 20000)
	expectEqual(tips4, 0, "a reload on the same day does not reopen the bonus")
end })

table.insert(tests, { name = "Fair monetization audit: every Robux item is cosmetic or convenience, nothing sells Tips, XP, slots or power, the paid Season row gives no Tips", fn = function()
	local Store = require(script.Parent.Parent.Engine.Store)
	local GamePasses = require(script.Parent.Parent.Engine.GamePasses)
	local problems = Store.audit()
	expectEqual(#problems, 0, "audit: " .. table.concat(problems, "; "))
	for _, item in ipairs(Store.Items) do
		assert(item.category == "cosmetic" or item.category == "convenience", item.id)
		assert(not (item.contents and (item.contents.tips or item.contents.xp or item.contents.patrons)), item.id .. " sells power")
	end
	-- the audit catches a bad item
	table.insert(Store.Items, { id = "bad", kind = "product", description = "Get +5 Tips every run", perks = {} })
	assert(#Store.audit() >= 1, "a missing category is reported")
	Store.Items[#Store.Items] = { id = "bad2", category = "cosmetic", kind = "product", description = "x", perks = { "+5 Tips" } }
	assert(#Store.audit() >= 1, "a cosmetic that mentions Tips is reported")
	Store.Items[#Store.Items] = { id = "bad3", category = "cosmetic", kind = "product", description = "x", perks = {}, contents = { tips = 9 } }
	assert(#Store.audit() >= 1, "Tips contents are reported")
	table.remove(Store.Items)
	expectEqual(#Store.audit(), 0, "clean again")
	-- Fast Forward is the only convenience pass (it only speeds the reveal, same numbers); the retry is also free once a day
	expectEqual(Store.PASS_CATEGORY.fast_forward, "convenience")
	expectEqual(Store.DEV_PRODUCT_CATEGORY.continue, "convenience")
	expectTrue(#GamePasses.Definitions >= 3)
end })

table.insert(tests, { name = "Table polish: the Pick your cards plate is spent once any hand was played, and the Patron voice stays quiet while the finale banner is up", fn = function()
	local H = require(script.Parent.Parent.Engine.RoundHints)
	local V = require(script.Parent.Parent.Engine.PatronVoiceLayout)
	local state = { phase = "playing", night = 1, round = 1, handsPlayedTotal = 0, ownedPatrons = {}, profileStats = {} }
	expectEqual(H.next(state, {}, { enabled = true }).id, "round_hint_select", "due before any hand")
	expectFalse(H.expired("round_hint_select", state), "not spent yet")
	state.handsPlayedTotal = 1
	assert(H.expired("round_hint_select", state), "spent after the first hand")
	local nxt = H.next(state, {}, { enabled = true })
	assert(nxt == nil or nxt.id ~= "round_hint_select", "never offered after a hand")
	expectFalse(H.expired("round_hint_tiers", state), "only the pick cards plate expires")
	expectFalse(H.expired("round_hint_select", nil), "junk state is safe")
	-- voice
	assert(V.suppressed(10, 12.5), "quiet while the banner is up")
	expectFalse(V.suppressed(13, 12.5), "speaks again after")
	expectFalse(V.suppressed(10, nil), "no banner, no quiet")
	assert(V.BANNER_QUIET >= 2, "covers the banner's life")
	if not io then return end
	local function read(p) local f = io.open(p, "r"); if not f then return nil end local s = f:read("*a"); f:close(); return s end
	local fx = read("src/Client/RoundHintsFX.lua")
	local voice = read("src/Client/PatronVoice.lua")
	local pop = read("src/Client/ScorePopup.lua")
	if fx and voice and pop then
		assert(fx:find("Rules.expired", 1, true), "the client hides an expired plate")
		assert(voice:find("PatronVoice.suppress", 1, true) and voice:find("os.clock() < quietUntil", 1, true), "say() honours the quiet time")
		assert(pop:find("PatronVoice).suppress", 1, true), "the finale banner silences the bubble")
	end
end })


table.insert(tests, { name = "Gameplay v2 reference proportions: top bar x 0.245 to 0.834, Patron seats span half the width, buttons at 0.861 of the height, at 1920x1080, 1280x720 and 1506x751", fn = function()
