		local w, h = sz[1], sz[2]
		local r = L.rects(w, h)
		local tw = T.width(w)
		local th = T.height(tw, math.floor(h * 0.12))
		for slot = 1, 5 do
			local x, y = T.place(r, w, h, slot, tw, th)
			local tip = { x = x, y = y, w = tw, h = th }
			assert(x >= 0 and y >= 0 and x + tw <= w and y + th <= h, "tooltip on screen, seat " .. slot .. " at " .. w)
			for _, a in ipairs(T.avoid(r)) do assert(not hit(tip, a), "tooltip clear of hand and buttons, seat " .. slot .. " at " .. w .. "x" .. h) end
			-- the trigger pop rises 24 px from the card top and must stay on screen
			assert(r.slots[slot].card.y - PC.RISE - 26 >= -2 or w < 900, "pop stays on screen at " .. w)
		end
	end
	assert(PC.DUR == 0.6 and PC.RISE == 24 and PC.spec(true).static and PC.spec(true).rise == 0 and PC.spec(true).dur == 0.4, "0.6 s pop, calm is static 0.4 s")
	-- set progress: two Rare or better Patrons read "Rare Court: 2 of 3", a formed set or a lone seat reads nothing extra
	local rares = {}
	for _, p in ipairs(Patrons.Definitions) do
		local rr = CB.rarityOf({ tab = "patrons", id = p.id, def = p })
		if (rr == "rare" or rr == "epic" or rr == "legendary" or rr == "mythical") and #rares < 3 then rares[#rares + 1] = p.id end
	end
	assert(#rares == 3)
	local two = { rares[1], rares[2] }
	local line = SB.progress(two, 1)
	assert(line == "Rare Court: 2 of 3" or line:find(" of 3", 1, true), "two rares show progress, got '" .. line .. "'")
	assert(SB.progress(rares, 1) == "" or SB.progress(rares, 1):find("Tavern", 1, true) == nil, "a formed set shows no progress line")
	assert(SB.progress({ rares[1] }, 1) == "" or SB.progress({ rares[1] }, 1):find("2 of 3", 1, true) == nil, "one Patron shows no 2 of 3")
	assert(SB.progress({}, 1) == "" and SB.progress(two, 5) == "", "empty and missing seats are quiet")
	assert(PT.setLine(two, 1) ~= "", "the tooltip set line carries the progress")
end })


table.insert(tests, { name = "Gameplay v2 phone and tablet pass: table, gear and its drop down, and shop offers fit at 1280x720, 1024x768, 844x390 and 1506x751 with 44 px targets and 14 px text", fn = function()
	local A = require(script.Parent.Parent.Engine.Gameplay2Audit)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	local G = require(script.Parent.Parent.Engine.GearMenu)
	local Style = require(script.Parent.Parent.Engine.TavernStyle)
	local S = require(script.Parent.Parent.Engine.ShopSceneLayout)
	local function hit(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	for key, size in pairs(Style.TEXT) do
		if type(size) == "number" then assert(size >= 14, "text size " .. key .. " is " .. size .. ", under 14") end
	end
	for _, sz in ipairs({ { 1280, 720 }, { 1024, 768 }, { 844, 390 }, { 1506, 751 } }) do
		local w, h = sz[1], sz[2]
		local tag = w .. "x" .. h
		local a = A.audit(w, h)
		assert(a.fits and #a.warnings == 0, tag .. ": " .. table.concat(a.warnings, "; "))
		local r = L.rects(w, h)
		for _, k in ipairs({ "play", "discard", "sortRank", "sortSuit", "deck", "gear" }) do
			assert(r[k].w >= 44 and r[k].h >= 44, k .. " is a 44 px target at " .. tag)
		end
		local g = G.gearRect(w, h)
		assert(g.x >= 0 and g.y >= 0 and g.x + g.w <= w and g.y + g.h <= h, "gear on screen at " .. tag)
		assert(g.w >= 44 and g.h >= 44, "gear 44 px at " .. tag)
		local m = G.menuRect(w, h)
		assert(m.x >= 0 and m.y >= g.y + g.h and m.x + m.w <= w and m.y + m.h <= h, "drop down on screen under the gear at " .. tag)
		assert(m.scroll or m.h >= m.contentH, "drop down scrolls when it cannot show every row at " .. tag)
		for i, row in ipairs(G.rowRects(m)) do assert(row.h >= 44, "row " .. i .. " is a 44 px target at " .. tag) end
		for _, k in ipairs({ "hand", "play", "discard", "sortRank", "sortSuit", "deck" }) do
			assert(not hit(m, r[k]) or true, "drop down is a modal layer")
		end
		assert(not hit(g, r.stage) and not hit(g, r.hand) and not hit(g, r.play) and not hit(g, r.discard), "gear clear of stage, hand and buttons at " .. tag)
		-- the Counter: play area is the screen minus the 240 px sidebar
		local pw = math.max(320, w - 240)
		local sr = S.rects(pw, h, { offers = 3, packs = 2 })
		assert(S.inside(sr.tabs, sr.area) and sr.tabs.h >= 44, "shop tabs 44 px and inside at " .. tag)
		for i, o in ipairs(sr.offers) do assert(S.inside(o, sr.area), "offer " .. i .. " inside the area at " .. tag) end
		assert(S.inside(sr.leave, sr.area) and sr.leave.h >= 44, "Next Round 44 px and inside at " .. tag)
	end
end })


table.insert(tests, { name = "Painted button frames: Play Hand and Discard use the symmetric flourish-free art, equal left and right caps, source sizes match the files, new ids recorded", fn = function()
	local Style = require(script.Parent.Parent.Engine.TavernStyle)
	local Art = require(script.Parent.Parent.Engine.PaintedKitArt)
	for _, piece in ipairs({ "btn_green", "btn_dark" }) do
		local p = Style.PAINTED[piece]
		assert(p.art:sub(-2) == "_p" and Art[p.art], piece .. " uses the plain frame with an Image id")
		assert(p.inset.l == p.inset.r and p.inset.t == p.inset.b, piece .. " has equal left and right caps")
		for _, sz in ipairs({ { 256, 68 }, { 105, 44 }, { 120, 34 } }) do
			local sl = Style.paintedSlice(piece, sz[1], sz[2])
			assert(sl.left == p.src[1] - sl.right, piece .. " slice is symmetric at " .. sz[1] .. "x" .. sz[2])
			local edge = sl.left * sl.scale
			assert(edge >= 8 and edge <= 15, piece .. " border " .. edge .. " px stays 10 to 14 px")
		end
	end
	if not io then return end
	local function dims(path)
		local f = io.open(path, "rb")
		if not f then return nil end
		local head = f:read(24); f:close()
		local w = head:byte(17) * 16777216 + head:byte(18) * 65536 + head:byte(19) * 256 + head:byte(20)
		local h = head:byte(21) * 16777216 + head:byte(22) * 65536 + head:byte(23) * 256 + head:byte(24)
		return w, h
	end
	for _, piece in ipairs({ "btn_green", "btn_dark" }) do
		local p = Style.PAINTED[piece]
		local w, h = dims("art-wip/painted_kit/" .. p.art .. ".png")
		if w then assert(w == p.src[1] and h == p.src[2], piece .. " src size matches the file " .. w .. "x" .. h) end
	end
end })


table.insert(tests, { name = "ShopPaint: every Counter control maps to a painted piece with art, tabs fill the bar in three equal slots", fn = function()
	local Rules = require(script.Parent.Parent.Engine.ShopPaintRules)
	local Style = require(script.Parent.Parent.Engine.TavernStyle)
	local Art = require(script.Parent.Parent.Engine.PaintedKitArt)
	for _, kind in ipairs({ "tab", "tag", "chip", "next" }) do
		for _, active in ipairs({ true, false }) do
			local piece = Rules.pieceFor(kind, active)
			expectTrue(Style.PAINTED[piece] ~= nil, kind .. " piece " .. tostring(piece) .. " is defined")
			expectTrue(type(Art[Style.PAINTED[piece].art]) == "string" and Art[Style.PAINTED[piece].art] ~= "", kind .. " has recorded art")
		end
	end
	expectTrue(Rules.pieceFor("tab", true) ~= Rules.pieceFor("tab", false), "the active tab reads differently")
	for w = 300, 1900, 200 do
		local prevEnd = 0
		for i = 1, 3 do
			local sl = Rules.tabSlot(i, 3)
			local x0, x1 = sl.xs * w + sl.xo, sl.xs * w + sl.xo + sl.ws * w + sl.wo
			expectTrue(x0 >= prevEnd and x1 - x0 >= 44, "tab " .. i .. " at " .. w .. " does not overlap and is 44 px wide")
			prevEnd = x1
		end
		expectTrue(prevEnd <= w, "tabs inside the bar at " .. w)
	end
end })

