table.insert(tests, { name = "Ornate button family: buttonPiece picks the whole picture near its aspect and the ornate nine-slice elsewhere; every screen uses it", fn = function()
	local Style = require(script.Parent.Parent.Engine.TavernStyle)
	local Art = require(script.Parent.Parent.Engine.PaintedKitArt)
	expectEqual(Style.buttonPiece("primary", 310, 80), "wh_btn_green", "a 310x80 primary is the whole green picture")
	expectEqual(Style.buttonPiece("secondary", 310, 80), "wh_btn_dark", "a 310x80 secondary is the whole dark picture")
	expectEqual(Style.buttonPiece("primary", 900, 44), "orn_btn_green", "a wide Select bar is the ornate nine-slice")
	expectEqual(Style.buttonPiece("secondary", 60, 60), "orn_btn_dark", "a square button is the ornate nine-slice")
	expectEqual(Style.buttonPiece("secondary", 0, 0), "wh_btn_dark", "an unmeasured plate is the whole picture, never the thin nine-slice")
	-- Counter after a win: every plate wears the ornate family; summary, Reroll and Next Round keep clear of the screen edges
	local PR = require(script.Parent.Parent.Engine.ShopPaintRules)
	expectEqual(PR.pieceFor("tab", true), "wh_btn_green", "selected tab is the green whole picture")
	expectEqual(PR.pieceFor("tab", false), "wh_btn_dark", "other tabs are the dark whole picture")
	expectEqual(PR.pieceFor("tag"), "wh_btn_dark", "Reroll tag is ornate")
	expectEqual(PR.pieceFor("chip"), "orn_wide", "boss notice is the ornate wide plate")
	expectEqual(PR.pieceFor("summary"), "orn_target", "summary plate is the symmetric ornate Target frame")
	expectEqual(PR.TAB_Z, 8, "tab pictures sit above the Counter dim layer (Z 5)")
	local sl = require(script.Parent.Parent.Engine.TavernStyle).paintedSlice("orn_target", 300, 124)
	expectTrue(sl and sl.left == 200 and sl.right == 1470 - 200 and sl.top == 130 and sl.bottom == 348 - 130, "summary slice keeps all four corners alike")
	expectTrue(sl.scale * 200 * 2 <= 300 * 0.9 + 1e-9, "both corner columns fit inside the 300 px summary plate")
	-- Roblox keeps a picture at 1024 px on its longer side: the slice rect TavernKit draws with lies inside that texture for every piece
	-- (the 1470 px summary plate lost its right edge when SliceCenter sat past the texture), and looks the same size on screen
	do
		local TS = require(script.Parent.Parent.Engine.TavernStyle)
		for piece, def in pairs(TS.PAINTED) do
			local tw = TS.paintedTexSlice(piece, 300, 124)
			local sw = TS.paintedSlice(piece, 300, 124)
			if def.inset then
				local k = math.min(1, TS.TEX_MAX / math.max(def.src[1], def.src[2]))
				expectTrue(tw.right <= def.src[1] * k + 1e-9 and tw.bottom <= def.src[2] * k + 1e-9, piece .. " slice rect inside the clamped texture")
				expectTrue(math.abs(tw.scale * tw.left - sw.scale * sw.left) < 1e-6, piece .. " corner keeps its on screen size")
			else
				expectTrue(tw == nil, piece .. " whole picture has no slice")
			end
		end
		local t = TS.paintedTexSlice("orn_target", 300, 124)
		expectTrue(t.right <= 1024 and t.left < t.right, "summary right slice line inside the 1024 texture")
	end
	local Sum = require(script.Parent.Parent.Engine.ShopSummary)
	local SL = require(script.Parent.Parent.Engine.ShopSceneLayout)
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1506, 751 } }) do
		local W, H = sz[1], sz[2]
		local r = Sum.rect(W, H)
		assert(r.x >= 0 and r.x + r.w <= W - Sum.GEAR_CLEAR, "summary plate clear of the gear at " .. W)
		local rows = Sum.rows(r.w)
		assert(rows.tips.y + rows.tips.h <= Sum.HEIGHT - Sum.BORDER, "summary text inside the border at " .. W)
		assert(rows.title.x >= Sum.BORDER and rows.title.x + rows.title.w <= r.w - Sum.BORDER, "summary text inside side border at " .. W)
		assert(rows.score.size >= 15, "summary text size at " .. W)
		-- picture aspect: the sliced picture (both corner columns and its scaled height) fits the rect, so all four corners show
		local ps = require(script.Parent.Parent.Engine.TavernStyle).paintedSlice("orn_target", r.w, r.h)
		assert(ps.scale * 400 <= r.w, "both corner columns inside the summary rect at " .. W)
		assert(ps.scale * 348 <= r.h + 1e-9, "scaled picture height inside the summary rect at " .. W)
		local rect = SL.rects(W, H, { offers = 3, packs = 2 })
		local rp = SL.rerollPlate(rect)
		if rp and rect.area then
			assert(rp.x >= 0, "Reroll fully on screen at " .. W)
			assert(rp.y + rp.h <= rect.area.h - 12, "Reroll 12 px above the bottom at " .. W)
		end
	end
	for _, kind in ipairs({ "primary", "secondary" }) do
		for _, sz in ipairs({ { 310, 80 }, { 900, 44 }, { 44, 44 }, { 0, 0 } }) do
			local piece = Style.buttonPiece(kind, sz[1], sz[2])
			expectTrue(Style.PAINTED[piece] ~= nil and type(Art[Style.PAINTED[piece].art]) == "string", piece .. " is defined with art")
		end
	end
	if not io then return end
	local function read(p) local f = io.open(p, "rb"); if not f then return "" end local t = f:read("*a"); f:close(); return t end
	for file, needle in pairs({ ["src/Client/RoundSelect.lua"] = 'paintedButton(selectButton, "primary")', ["src/Client/GameOver.lua"] = 'paintedButton(b, "primary")',
		["src/Client/Shop.lua"] = 'paintedButton(rerollButton, "secondary")', ["src/Client/GearMenu.lua"] = 'Kit.paintedButton, b, "secondary"',
		["src/Client/TavernScreens.lua"] = 'paintedButton(b, "primary")', ["src/Client/ShopHaggle.lua"] = 'paintedButton(haggleButton, "secondary")' }) do
		expectTrue(read(file):find(needle, 1, true) ~= nil, file .. " wears the ornate button family")
	end
	for _, file in ipairs({ "src/Client/RoundSelect.lua", "src/Client/GameOver.lua", "src/Client/Shop.lua" }) do
		local t = read(file)
		expectTrue(t:find('"btn_green"', 1, true) == nil and t:find('"btn_dark"', 1, true) == nil, file .. " has no old flat button piece left")
	end
end })

table.insert(tests, { name = "Round 7 live fixes: Rank and Suit icon and word never touch (6 px gap, word left aligned), the wide hint body ends 8 px above its frame, Got it is a wide 44 px plate centred on the hint", fn = function()
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	local RH = require(script.Parent.Parent.Engine.RoundHints)
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1506, 751 } }) do
		local r = L.rects(sz[1], sz[2])
		for _, nm in ipairs({ "sortRank", "sortSuit" }) do
			local b = r[nm]
			local iconW = math.max(8, math.floor(b.h * 0.53 + 0.5)) -- TavernKit.icon
			local iconRight = math.floor(b.w * 0.06) + iconW
			local textLeft = math.floor(b.w * 0.06 + iconW + 10) -- its padding; the word is left aligned, so it starts here
			expectTrue(textLeft - iconRight >= 6, nm .. " icon and word gap at " .. sz[1] .. "x" .. sz[2])
			expectTrue(b.w - textLeft >= 36, nm .. " leaves room for the word at " .. sz[1] .. "x" .. sz[2])
		end
	end
	do -- tall plate: Got it under the plate with an 8 px gap, left on the text column, clear of the table candle (x 285 to 365, y 490 to 620 of 1672 x 941) and the left candle (x 150 to 215, y 140 to 330)
		for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1506, 751 } }) do
			local w, h = sz[1], sz[2]
			local sp = RH.place(L.rects(w, h), w, h, {})
			if sp and sp.kind == "tall" then
				expectEqual(sp.button.y - (sp.plate.y + sp.plate.h), 8, "Got it is 8 px under the plate at " .. w)
				local k = w / 1672
				for _, c in ipairs({ { 285, 490, 80, 130 }, { 150, 140, 65, 190 } }) do
					local cx, cy, cw, ch = c[1] * k, c[2] * k, c[3] * k, c[4] * k
					local hit = sp.button.x < cx + cw and cx < sp.button.x + sp.button.w and sp.button.y < cy + ch and cy < sp.button.y + sp.button.h
					expectTrue(not hit, "Got it clear of a candle at " .. w .. "x" .. h)
				end
			end
		end
	end
	-- wide plate: body y 38, two 15 px lines (36 px box) must end 8 px above the frame bottom
	expectTrue(RH.WIDE_H - (38 + 36) >= 8, "the wide frame is tall enough for its two body lines")
	expectTrue(RH.WIDE_BUTTON_W > RH.WIDE_BUTTON_H and RH.WIDE_BUTTON_H >= 44, "Got it is wide, not square, and a 44 px touch target")
	local r = L.rects(1920, 957)
	local spot = RH.place(r, 1920, 957, {})
	if spot and spot.kind == "wide" then
		expectEqual(spot.button.y + spot.button.h / 2, spot.plate.y + spot.plate.h / 2, "Got it is centred on the plate")
	end
	if io then
		local function read(p) local f = io.open(p, "r"); if not f then return nil end local t = f:read("*a"); f:close(); return t end
		local kit = read("src/Client/TavernKit.lua")
		if kit then expectTrue(kit:find("host.TextXAlignment = Enum.TextXAlignment.Left", 1, true) ~= nil, "icon plates left align the word") end
	end
end })

table.insert(tests, { name = "TableCheck: pieces convert to the 1672 x 941 reference, 25 px off passes, 30 px warns, a missing piece is only reported, DebugGoto tablecheck parses", fn = function()
	local T = require(script.Parent.Parent.Engine.TableCheck)
	local D = require(script.Parent.Parent.Engine.DebugGotoRules)
	local k = 1506 / T.REF_W
	local live = {}
	for _, t in ipairs(T.TARGETS) do -- a GUI 1506 wide, every piece exactly on its target
		live[t.key] = { x = t.x0 * k, y = (t.y0 or 100) * k, w = (t.x1 - t.x0) * k, h = ((t.y1 or 140) - (t.y0 or 100)) * k }
	end
	local lines, warns = T.compare(live, 1506)
	expectEqual(#warns, 0, "on target")
	expectEqual(#lines, #T.TARGETS)
	live.PlayHand.x = live.PlayHand.x + 24 * k
	expectEqual(#select(2, T.compare(live, 1506)), 0, "24 px off passes")
	live.PlayHand.x = live.PlayHand.x + 6 * k
	expectEqual(#select(2, T.compare(live, 1506)), 1, "30 px off warns")
	live.Discard = nil
	local l4, w4 = T.compare(live, 1506)
	expectEqual(#l4, #T.TARGETS, "a missing piece still gets a line")
	expectEqual(#w4, 1, "and no warning of its own")
	-- a 1506 x 751 viewport with a 58 px top inset: AbsolutePosition y is 58 less than the layout y, and y scales by height, not width
	local kx, ky = T.scales(1506, 751)
	expectTrue(math.abs(kx - 1672 / 1506) < 1e-9 and math.abs(ky - 941 / 751) < 1e-9, "each axis has its own scale")
	local ph = T.TARGETS[9] -- PlayHand
	expectEqual(ph.key, "PlayHand")
	local abs = { x = ph.x0 / kx, y = ph.y0 / ky - 58, w = (ph.x1 - ph.x0) / kx, h = (ph.y1 - ph.y0) / ky }
	local r2 = T.toReference(abs, 1506, 751, 58)
	expectTrue(math.abs(r2.y - ph.y0) < 1e-6 and math.abs(r2.x - ph.x0) < 1e-6 and math.abs(r2.h - (ph.y1 - ph.y0)) < 1e-6, "inset added back, y and height scale by the viewport height")
	local _, w2 = T.compare({ PlayHand = abs }, 1506, 751, 58)
	expectEqual(#w2, 0, "Play Hand on target with the inset")
	local _, w3 = T.compare({ PlayHand = abs }, 1506, 751, 0)
	expectEqual(#w3, 1, "without the inset the same piece is 58 px high and warns")
	local t = D.parse("tablecheck")
	expectTrue(t and t.kind == "tablecheck", "DebugGoto tablecheck parses")
end })

table.insert(tests, { name = "Plate audit: painted plates keep text 8 px inside the 14 px carved border (Counter summary, Night map bar), and the summary plate, boss banner and Run Over plates overlap nothing at 1920x1080, 1280x720 and 1506x751", fn = function()
	local S = require(script.Parent.Parent.Engine.ShopSummary)
	local SL = require(script.Parent.Parent.Engine.ShopSceneLayout)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	local M = require(script.Parent.Parent.Engine.Gameplay2Moments)
	local function hit(a, b) return a.x < b.x + b.w and b.x < a.x + a.w and a.y < b.y + b.h and b.y < a.y + a.h end
	-- the summary rows: 22 px (14 border plus 8 air) from every edge, stacked, none overlapping, text 15 px or more
	for _, pw in ipairs({ 300, 253 }) do
		local rows = S.rows(pw)
		local order = { rows.title, rows.score, rows.tips }
		for i, rw in ipairs(order) do
			assert(rw.x >= S.BORDER + S.PAD and rw.x + rw.w <= pw - S.BORDER - S.PAD, "row " .. i .. " 8 px inside the border at width " .. pw)
			assert(rw.y >= S.BORDER + S.PAD and rw.y + rw.h <= S.HEIGHT - S.BORDER - S.PAD, "row " .. i .. " inside vertically")
			assert(rw.size >= 15 and rw.size + 2 <= rw.h, "row " .. i .. " text fits its row")
			if i > 1 then assert(rw.y >= order[i - 1].y + order[i - 1].h, "rows do not overlap") end
		end
	end
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1506, 751 } }) do
		local w, h = sz[1], sz[2]
		local sum = S.rect(w, h)
		local shop = SL.rects(w, h)
		for _, key in ipairs({ "tabs", "nextBoss", "leave" }) do
			assert(not hit(sum, shop[key]), "summary plate clear of the Counter " .. key .. " at " .. w)
		end
		assert(sum.x >= 0 and sum.x + sum.w <= w and sum.y + sum.h <= h, "summary plate on screen at " .. w)
		-- boss round: the rule banner sits between the top bar and the Patron seats
		local r = L.rects(w, h)
		local b = M.bossBanner(r, w, h)
		assert(b, "a boss banner fits at " .. w)
		assert(b.y >= r.bar.y + r.bar.h and b.y + b.h <= r.slots[1].card.y, "boss banner between the bar and the seats at " .. w)
		for i = 1, 5 do assert(not hit(b, r.slots[i].card), "boss banner clear of seat " .. i) end
		for _, complete in ipairs({ false, true }) do
			local np = M.nightPlate(w, h, complete)
			assert(np.x >= 0 and np.y >= 0 and np.x + np.w <= w and np.y + np.h <= h, "night plate on screen at " .. w)
		end
	end
	if not io then return end
	local function read(path) local f = assert(io.open(path, "r")); local c = f:read("a"); f:close(); return c end
	assert(read("src/Client/Journey.lua"):find("journeyBossInfoLabel.Position = UDim2.new(0, 22, 0, 22)", 1, true), "Night map bar text starts 22 px in (14 border plus 8)")
	assert(read("src/Client/ShopSummaryPlate.lua"):find("Summary.rows", 1, true), "the summary plate takes its rows from the tested numbers")
end })

table.insert(tests, { name = "TableCheck by tests: every table piece of Gameplay2Layout.rects is within 25 reference px of the 1672 x 941 mockup at 1920x1080 and 1280x720", fn = function()
	local T = require(script.Parent.Parent.Engine.TableCheck)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	local SP = require(script.Parent.Parent.Engine.Gameplay2ScorePlate)
	local RH = require(script.Parent.Parent.Engine.RoundHints)
	for _, size in ipairs({ { 1920, 1080 }, { 1280, 720 } }) do
		local w, h = size[1], size[2]
		-- the live check converts GUI pixels to the reference by width alone, so the reference y is read at the same scale (a 16:9 window against a 16:9 mockup)
		local r = L.rects(w, h)
		local live = { TargetBox = r.target, RoundName = r.round, TipsPill = r.tips, SortRank = r.sortRank, SortSuit = r.sortSuit,
			PlayHand = r.play, Discard = r.discard, DeckCountPill = r.deckCount, ScorePlate = SP.plate(w, h) }
		local x0, y0, x1, y1
		for _, s in ipairs(r.slots) do
			local c = s.card
			x0 = x0 and math.min(x0, c.x) or c.x; y0 = y0 and math.min(y0, c.y) or c.y
			x1 = x1 and math.max(x1, c.x + c.w) or c.x + c.w; y1 = y1 and math.max(y1, c.y + c.h) or c.y + c.h
		end
		live.PatronSlots = { x = x0, y = y0, w = x1 - x0, h = y1 - y0 }
		local hint = RH.place(r, w, h, {})
		if hint then -- the plate and its Got it button are one piece in the mockup (x 18 to 335, y 345 to 485)
			local p, b = hint.plate, hint.button
			local hx0, hy0 = math.min(p.x, b.x), math.min(p.y, b.y)
			local hx1, hy1 = math.max(p.x + p.w, b.x + b.w), math.max(p.y + p.h, b.y + b.h)
			if p.w <= RH.PLATE_MIN_W then hx1 = math.min(hx1, hx0 + (335 - 18) / T.REF_W * w); hy1 = math.min(hy1, hy0 + (485 - 345) / T.REF_W * w) end -- held at its readable minimum size on small screens: only its top left corner is compared
			live.RoundHint = { x = hx0, y = hy0, w = hx1 - hx0, h = hy1 - hy0 }
		end
		local lines, warns = T.compare(live, w)
		for _, l in ipairs(lines) do print(w .. " " .. l) end
		expectEqual(#warns, 0, w .. "x" .. h .. ": " .. table.concat(warns, "; "))
	end
end })

table.insert(tests, { name = "Score plate: caption, numeral and progress line stand 8 px inside the carved border, a long total shrinks to fit", fn = function()
	local P = require(script.Parent.Parent.Engine.Gameplay2ScorePlate)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1506, 751 }, { 1920, 957 } }) do
		local w, h = sz[1], sz[2]
		local st = L.rects(w, h).stage
		for _, compact in ipairs({ false, true }) do
			local lv = P.live(st, w, 20, 22, compact)
			local tag = w .. "x" .. h .. (compact and " scoring" or " idle")
			expectTrue(lv.plate.x >= st.x and lv.plate.y >= st.y and lv.plate.x + lv.plate.w <= st.x + st.w and lv.plate.y + lv.plate.h <= st.y + st.h, tag .. ": plate inside the stage")
			expectTrue(lv.inner.x - lv.plate.x == P.PAD and lv.inner.y - lv.plate.y == P.PAD, tag .. ": 8 px inner padding")
			-- the stack runs from the box top (numeral row, caption above) down to contentBottom: all of it inside the inner area
			local top = lv.box.y + (lv.N.roomy and not lv.N.compact and 0 or lv.N.numTop)
			expectTrue(top >= lv.inner.y, tag .. ": stack top " .. top .. " inside inner top " .. lv.inner.y)
			expectTrue(lv.contentBottom <= lv.inner.y + lv.inner.h, tag .. ": stack bottom " .. lv.contentBottom .. " inside inner bottom " .. (lv.inner.y + lv.inner.h))
			expectTrue(lv.N.numH >= 14, tag .. ": numeral readable")
			-- a 9 digit total fits the inner width, a short one keeps its full size
			local big = P.fitSize(lv.N.textSize, 9, lv.inner.w)
			expectTrue(big * 0.62 * 9 <= lv.inner.w or big == P.MIN_FONT, tag .. ": long total fits")
			expectTrue(P.fitSize(lv.N.textSize, 1, lv.inner.w) == lv.N.textSize, tag .. ": short total keeps its size")
		end
	end
	if not io then return end
	local f = assert(io.open("src/Client/Gameplay2.lua", "r")); local src = f:read("a"); f:close()
	expectTrue(src:find("SPlate.live(", 1, true) ~= nil and src:find("fitSize", 1, true) ~= nil, "the live plate uses the tested rects")
	expectTrue(src:find("scoreNum.Font = Enum.Font.GothamBold", 1, true) ~= nil and src:find("scoreNum.TextColor3 = Color3.fromRGB(255, 255, 255)", 1, true) ~= nil, "bold white digits with a gold outline")
end })

table.insert(tests, { name = "Gameplay v2: Rank, Suit, Play Hand and Discard share one bottom row, even gaps, clear of the count pills", fn = function()
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1506, 751 } }) do
		local w, h = sz[1], sz[2]
		local r = L.rects(w, h)
		local row = { r.sortRank, r.sortSuit, r.play, r.discard }
		local tag = w .. "x" .. h
		for i = 2, 4 do
			expectTrue(math.abs(row[i].y - row[1].y) <= 4, tag .. ": same top, control " .. i)
			expectTrue(math.abs(row[i].h - row[1].h) <= 4, tag .. ": same height, control " .. i)
		end
		-- left to right order, no overlap, gaps at least 8 px
		local gaps = {}
		for i = 1, 3 do
			gaps[i] = row[i + 1].x - (row[i].x + row[i].w)
			expectTrue(gaps[i] >= 8, tag .. ": gap " .. i .. " is " .. gaps[i])
		end
		-- the two gaps inside each pair are even: Rank to Suit and Play to Discard differ by at most 12 px
		expectTrue(math.abs(gaps[1] - gaps[3]) <= 12, tag .. ": pair gaps " .. gaps[1] .. " and " .. gaps[3])
		expectTrue(math.abs(r.sortRank.w - r.sortSuit.w) <= 2, tag .. ": Rank and Suit equal width")
		expectTrue(math.abs(r.play.w - r.discard.w) <= 2, tag .. ": Play Hand and Discard equal width")
		-- the Hands and Discards pills hang above their button, touching neither it nor the sort plates
		for _, pk in ipairs({ "playCount", "discardCount" }) do
			local p = r[pk]
			expectTrue(p.y + p.h < row[3].y, tag .. ": " .. pk .. " above the buttons")
			for _, k in ipairs({ "sortRank", "sortSuit" }) do
				local b = r[k]
				local hit = p.x < b.x + b.w and b.x < p.x + p.w and p.y < b.y + b.h and b.y < p.y + p.h
				expectTrue(not hit, tag .. ": " .. pk .. " clear of " .. k)
			end
		end
		-- every control is a plain rect with a positive size inside the screen (the live instance is moved onto this one rect, so hit box == plate)
		for _, k in ipairs({ "sortRank", "sortSuit", "play", "discard" }) do
			local b = r[k]
			expectTrue(b.x >= 0 and b.y >= 0 and b.x + b.w <= w and b.y + b.h <= h, tag .. ": " .. k .. " on screen")
		end
	end
end })

table.insert(tests, { name = "IconLabelLayout: the icon stands at the left, the word starts 6 px right of it, both centred, never overlapping (Rank and Suit at three sizes)", fn = function()
	local I = require(script.Parent.Parent.Engine.IconLabelLayout)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	for _, sz in ipairs({ { 1920, 1080 }, { 1280, 720 }, { 1506, 751 }, { 800, 450 } }) do
		local r = L.rects(sz[1], sz[2])
		for _, k in ipairs({ "sortRank", "sortSuit" }) do
			local b = r[k]
			local p = I.place(b.w, b.h)
			local tag = sz[1] .. "x" .. sz[2] .. " " .. k
			expectEqual(p.icon.x, 14, tag .. ": icon 14 px from the left")
			expectEqual(p.label.x - (p.icon.x + p.icon.w), 6, tag .. ": 6 px between icon and word")
			expectTrue(p.icon.x + p.icon.w <= p.label.x, tag .. ": icon and word do not overlap")
			expectTrue(p.icon.y >= 0 and p.icon.y + p.icon.h <= b.h, tag .. ": icon inside the plate height")
			expectTrue(math.abs((p.icon.y + p.icon.h / 2) - b.h / 2) <= 1, tag .. ": icon centred vertically")
			expectEqual(p.label.h, b.h, tag .. ": word row is the full height, centred by the label")
			expectTrue(p.label.x + p.label.w <= b.w - I.RIGHT + 0.001, tag .. ": word ends inside the plate")
		end
	end
end })

table.insert(tests, { name = "TableCheck inset: GetGuiInset 0 falls back to viewport minus GUI height, then the root offset; 1506 x 751 with a 58 px inset puts Play Hand on target", fn = function()
	local T = require(script.Parent.Parent.Engine.TableCheck)
	expectEqual(T.insetFrom(58, 751, 693, 0), 58, "a reported inset wins")
	expectEqual(T.insetFrom(0, 751, 693, 0), 58, "viewport 751 minus GUI 693")
	expectEqual(T.insetFrom(0, nil, nil, -58), 58, "root sits 58 above 0")
	expectEqual(T.insetFrom(0, 751, 751, 0), 0, "nothing hidden, nothing added")
	local inset = T.insetFrom(0, 751, 693, 0)
