table.insert(tests, { name = "IconLabelLayout.anchored: the group hangs from the plate centre, so it lies inside a 144 x 68 plate even when the width measured was 300 or 600 (stale), and TavernKit wires cloned plates", fn = function()
	local I = require(script.Parent.Parent.Engine.IconLabelLayout)
	for _, measured in ipairs({ 144, 160, 300, 600 }) do
		for _, word in ipairs({ 4, 9 }) do
			local a = I.anchored(measured, 68, word * 18 * 0.56, 18, 14)
			local r = I.resolve(144, a) -- drawn in the real plate
			if measured >= 144 or word == 4 then
				expectTrue(r.icon.x >= 0 and r.icon.x + r.icon.w <= 144, measured .. "/" .. word .. ": icon inside the plate")
				expectTrue(r.label.x >= r.icon.x + r.icon.w and r.label.x + r.label.w <= 144, measured .. "/" .. word .. ": word right of the icon, inside the plate")
			end
		end
	end
	local a = I.anchored(144, 68, 4 * 18 * 0.56, 18, 14)
	local r = I.resolve(144, a)
	expectTrue(math.abs((r.icon.x + (r.label.x + r.label.w)) / 2 - 72) <= 2, "the icon plus word group is centred")
	if not io then return end
	local fh = io.open("src/Client/TavernKit.lua", "r")
	if fh then
		local src = fh:read("*a"); fh:close()
		expectTrue(src:find("Layout.anchored", 1, true) and src:find("UDim2.new(0.5, a.icon.dx", 1, true), "TavernKit hangs the icon from the plate centre")
		expectTrue(src:find("TavernKit._wired[host]", 1, true), "hooks go on every host, also a Cloned one that already has a KitIcon")
	end
end })

table.insert(tests, { name = "IconLabelLayout: Rank and Suit at 144 x 68 keep 14 px clear on both sides with the width pad, group centred, the word box centred text never reaches the border", fn = function()
	local I = require(script.Parent.Parent.Engine.IconLabelLayout)
	for _, word in ipairs({ "Rank", "Suit" }) do
		for _, perChar in ipairs({ 0.5, 0.6, 0.7 }) do -- real metrics are not available offline: three plausible glyph widths
			local a = I.anchored(144, 68, #word * 20 * perChar, 20, 14)
			local r = I.resolve(144, a)
			expectTrue(r.icon.x >= I.SIDE, word .. ": 14 px clear left")
			expectTrue(144 - (r.label.x + r.label.w) >= I.SIDE - 1, word .. ": 14 px clear right")
			expectTrue(math.abs(r.icon.x - (144 - (r.label.x + r.label.w))) <= 2, word .. ": equal margins")
		end
	end
	local g0 = I.group(144, 68, 0, 18, 14)
	expectEqual(g0.label.w, 0, "no word, no pad")
end })

table.insert(tests, { name = "IconLabelLayout.childX: with the KitIconPad at 0 (TavernKit.icon) the Rank and Suit group lands inside a 144 px plate with 14 px margins; the old half-plate padding pushed the word to the border", fn = function()
	local I = require(script.Parent.Parent.Engine.IconLabelLayout)
	for _, word in ipairs({ "Rank", "Suit" }) do
		local a = I.anchored(144, 68, 40, 18, 14)
		local ix, lx = I.childX(144, 0, 0.5, a.icon.dx), I.childX(144, 0, 0.5, a.label.dx)
		expectTrue(ix >= I.SIDE and 144 - (lx + a.label.w) >= I.SIDE - 1, word .. ": inside with margins")
		local badPad = 144 / 2 + a.label.dx -- the old padding
		expectTrue(I.childX(144, badPad, 0.5, a.label.dx) + a.label.w > 144 - I.SIDE, word .. ": the old padding pushed the word to the border")
	end
	if not io then return end
	local f = io.open("src/Client/TavernKit.lua", "r")
	if not f then return end
	local src = f:read("a"); f:close()
	expectTrue(src:find("up.PaddingLeft = UDim.new(0, 0)", 1, true) ~= nil, "TavernKit.icon zeroes KitIconPad when a KitLabel draws the word")
	expectTrue(src:find("p.icon.x - up.PaddingLeft.Offset", 1, true) ~= nil, "the no-word branch compensates the icon for the padding")
end })

table.insert(tests, { name = "PatronParchment.storedRect: the 81 crops are scaled 2/3 into the stored 683 x 1024 texture, inside it, window ends above the baked name plate", fn = function()
	local P = require(script.Parent.Parent.Engine.PatronParchment)
	local Crop = require(script.Parent.Parent.Engine.PatronCardCrop)
	local n = 0
	for id, r in pairs(Crop) do
		local s = P.storedRect(id)
		expectTrue(math.abs(s.x - r.x * 1024 / 1536) < 0.001 and math.abs(s.h - r.h * 1024 / 1536) < 0.001, id .. ": scaled by 2/3")
		expectTrue(s.x >= 0 and s.y >= 0 and s.x + s.w <= 683.4 and s.y + s.h <= 1024.1, id .. ": inside the stored texture")
		expectTrue(r.y + r.h <= 1536 * 0.82, id .. ": window ends above the baked name plate")
		n = n + 1
	end
	expectEqual(n, 81, "one crop per Patron")
	expectTrue(P.storedRect("no_such_patron") == nil, "no crop, no rect")
end })


table.insert(tests, { name = "Hand v2: cards grow toward the reference size and 8 cards stay clear of the buttons and deck at 1920x1080, 1920x957, 1506x751, 1280x720", fn = function()
	local HS = require(script.Parent.Parent.Engine.HandSizing)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	local CT = require(script.Parent.Parent.Engine.ConceptTLayout)
	local want = { ["1920x1080"] = 137, ["1920x957"] = 137 }
	for _, sz in ipairs({ { 1920, 1080 }, { 1920, 957 }, { 1506, 751 }, { 1280, 720 } }) do
		local key = sz[1] .. "x" .. sz[2]
		local r = L.rects(sz[1], sz[2])
		for _, n in ipairs({ 8, 9, 10 }) do
			local hf = CT.handFor(r.hand, sz[1], n)
			local cw = HS.cardSize(sz[1], hf.w, hf.h, n)
			expectTrue(cw >= 44, "touch size " .. key)
			expectTrue(hf.y + hf.h <= r.play.y, "hand ends above Play Hand at " .. key)
			expectTrue(hf.x + hf.w <= r.deck.x, "hand ends left of the deck at " .. key)
		end
		local cw = HS.cardSize(sz[1], r.hand.w, r.hand.h, 8)
		if want[key] then expectTrue(cw >= 130, "card at least 130 wide at " .. key .. ", got " .. cw) end
	end
end })

table.insert(tests, { name = "Live hand path: roomy windows overlap cards, 8 cards reach about 0.084 of the width at 1506, 1920 and 1280", fn = function()
	local HS = require(script.Parent.Parent.Engine.HandSizing)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	for _, sz in ipairs({ { 1920, 957, 140 }, { 1506, 751, 120 }, { 1280, 720, 105 } }) do
		local r = L.rects(sz[1], sz[2])
		local hf = HS.frameFor(sz[1], r.hand, 8)
		expectEqual(hf.y + hf.h, r.hand.y + r.hand.h, "the frame only grows upward at " .. sz[1])
		local cw = HS.cardSize(sz[1], hf.w, hf.h, 8)
		expectTrue(cw >= sz[3], "8 cards at least " .. sz[3] .. " wide at " .. sz[1] .. ", got " .. cw)
		local gap = HS.gap(sz[1], cw)
		expectTrue(gap < 0, "neighbours overlap at " .. sz[1])
		expectTrue(8 * cw + 7 * gap + 2 * HS.PAD <= r.hand.w, "the overlapped row fits the frame at " .. sz[1])
	end
	expectEqual(HS.gap(1000, 100), HS.GAP, "narrow windows keep the 6 px gap")
end })

table.insert(tests, { name = "Idle Score plate and its line stay 12 px above the tallest hand card at 8, 9 and 10 cards, 1920x1080, 1920x957, 1506x751, 1280x720", fn = function()
	local HS = require(script.Parent.Parent.Engine.HandSizing)
	local L = require(script.Parent.Parent.Engine.Gameplay2Layout)
	local CT = require(script.Parent.Parent.Engine.ConceptTLayout)
	local SP = require(script.Parent.Parent.Engine.Gameplay2ScorePlate)
	for _, sz in ipairs({ { 1920, 1080 }, { 1920, 957 }, { 1506, 751 }, { 1280, 720 } }) do
		local r = L.rects(sz[1], sz[2])
		for _, n in ipairs({ 8, 9, 10 }) do
			local hf = HS.frameFor(sz[1], CT.handFor(r.hand, sz[1], n), math.max(n, 8))
			local st = SP.idleStage(r.stage, hf.y)
			local live = SP.live(st, sz[1], 26, 22, false)
			local plateBottom = live.plate.y + live.plate.h
			expectTrue(st.h <= r.stage.h, "the idle stage never grows at " .. sz[1] .. " x " .. sz[2])
			-- 1280 wide has only 80 px between the Patron pills and the card tops: the full stack needs SP.MIN_H, so the gap may shrink to 0 there (never overlap)
			expectTrue(plateBottom + (sz[1] >= 1400 and SP.HAND_GAP or 0) <= hf.y, "plate bottom " .. plateBottom .. " clear of the card tops " .. hf.y .. " at " .. sz[1] .. " x " .. sz[2] .. " with " .. n .. " cards")
			expectTrue(live.contentBottom <= plateBottom, "the 0 of N line is inside the plate at " .. sz[1] .. " x " .. sz[2])
			expectTrue(live.N.roomy and not live.N.noProgress, "idle plate keeps the Score caption and the 0 of N line at " .. sz[1] .. " x " .. sz[2] .. " with " .. n .. " cards")
			expectTrue(live.N.numTop >= 26, "caption row present at " .. sz[1] .. " x " .. sz[2])
			if n == 8 then print(("[TableRects] %dx%d plate y=%d bottom=%d handTop=%d stage=%d..%d"):format(sz[1], sz[2], live.plate.y, plateBottom, hf.y, st.y, st.y + st.h)) end
		end
	end
	expectEqual(SP.idleStage({ x = 1, y = 2, w = 3, h = 99 }, nil).h, 99, "no hand rect keeps the stage")
end })

table.insert(tests, { name = "PlayRoomArt.backdrop: Classic Tavern draws table_play_ref, sets with a room keep theirs, PlayScenePaint prints [PlayTableBg]", fn = function()
	local PRA = require(script.Parent.Parent.Engine.PlayRoomArt)
	local TA = require(script.Parent.Parent.Engine.TableSceneArt)
	local PA = require(script.Parent.Parent.Engine.PlaySceneArt)
	local key, id = PRA.backdrop("classic_tavern", PA, TA)
	expectEqual(key, "table_play_ref", "classic key")
	expectEqual(id, TA.table_play_ref, "classic id")
	key = PRA.backdrop(nil, PA, TA)
	expectEqual(key, "table_play_ref", "no set")
	local k2 = PRA.backdrop("winter_evening", PA, TA)
	expectTrue(k2 == "play_table_bg_b" or k2 == "play_room_winter_evening_bg", "a set room is not replaced: " .. tostring(k2))
	local k3 = PRA.backdrop("classic_tavern", PA, {})
	expectEqual(k3, "play_table_bg_b", "missing reference id falls back")
	if not io then return end
	local f = io.open("src/Client/PlayScenePaint.lua", "r")
	if f then
		local src = f:read("a"); f:close()
		expectTrue(src:find("PlayRoomArt.backdrop(sid, art, TableSceneArt)", 1, true) ~= nil and src:find("[PlayTableBg] key=", 1, true) ~= nil, "PlayScenePaint draws and prints the backdrop key")
	end
end })

table.insert(tests, { name = "RoundHints: the heading is gold with 4.5:1 on the plate, the Patron Power heading is capitalised", fn = function()
	local RH = require(script.Parent.Parent.Engine.RoundHints)
	local function lum(c)
		local function f(v) v = v / 255; return v <= 0.03928 and v / 12.92 or ((v + 0.055) / 1.055) ^ 2.4 end
		return 0.2126 * f(c[1]) + 0.7152 * f(c[2]) + 0.0722 * f(c[3])
	end
	local a, b = lum(RH.TITLE_COLOR), lum(RH.PLATE_COLOR)
	expectTrue((a + 0.05) / (b + 0.05) >= 4.5, "gold on the dark plate")
	expectTrue(RH.TITLE_COLOR[1] > 200 and RH.TITLE_COLOR[2] > 160 and RH.TITLE_COLOR[3] < 120, "the heading is gold")
	local found = false
	for _, h in ipairs(RH.ORDER) do if h.title == "Patron Power" then found = true end end
	expectTrue(found, "Patron Power heading")
end })

table.insert(tests, { name = "Play table background: the reference tavern scene has a recorded id and its light spots sit on the picture", fn = function()
	local A = require(script.Parent.Parent.Engine.TableSceneArt)
	local RL = require(script.Parent.Parent.Engine.RoomLights)
	expectTrue(type(A.table_play_ref) == "string" and A.table_play_ref:find("rbxassetid://", 1, true) == 1, "table_play_ref id")
	expectTrue(type(A.table_play) == "string", "the older scene stays as the fallback")
	for _, sp in ipairs(RL.ROOMS.table_play.spots) do
		expectTrue(sp.x > 0 and sp.x < 1 and sp.y > 0 and sp.y < 0.6, "spot on the room part of the picture")
	end
end })

return tests
